/// A scripted response for [`ScriptedLlm`]: either a plain text end-turn
/// reply or a tool-use response that keeps the loop running. (No `Clone`:
/// the gated variant holds a one-shot receiver.)
#[derive(Debug)]
enum ScriptedResponse {
    /// Plain text reply that ends the turn.
    Text(String),
    /// A chat call that fails outright with a provider error.
    Error(String),
    /// Tool calls that keep the loop running.
    ToolUse(Vec<LlmToolCall>),
    /// A text reply held back until a one-shot gate opens — the chat call
    /// parks inside the stream, letting tests race a cancellation against
    /// an in-flight LLM call deterministically.
    Gated {
        release: tokio::sync::oneshot::Receiver<()>,
        text: String,
    },
    /// A gated text response whose park ALSO observes the request's
    /// cancel token — a cancelled turn unblocks the park and the stream
    /// ends without a Done, so the engine's cooperative-cancellation
    /// settle (not the hard drop) closes the turn. The watchdog-kill
    /// shape for settle-path reason tests.
    GatedCancelAware {
        release: tokio::sync::oneshot::Receiver<()>,
        text: String,
    },
    /// A tool-use response held back until a one-shot gate opens — the
    /// chat call parks inside the stream with a tool call pending, letting
    /// tests switch the model between a turn's LLM steps deterministically
    /// (the mid-turn step-level switch tests).
    GatedToolUse {
        release: tokio::sync::oneshot::Receiver<()>,
        tool_calls: Vec<LlmToolCall>,
    },
    /// A chat call that parks on a one-shot gate and then FAILS with a
    /// stream-level provider error — lets a test hold a side call in
    /// flight past the turn's settle and only then fail it.
    GatedError {
        release: tokio::sync::oneshot::Receiver<()>,
        message: String,
    },
}

/// A scripted [`Llm`] for crate-local tests: replays canned responses in
/// FIFO order, one `chat()` per response, streaming one `TextDelta` per
/// character before the block-level tail.
#[derive(Debug, Default)]
pub(super) struct ScriptedLlm {
    calls: AtomicU64,
    responses: Mutex<VecDeque<ScriptedResponse>>,
    /// Every chat call's serialized messages, in call order — lets tests
    /// assert on what the engine loop fed back (e.g. tool results).
    recorded_messages: Mutex<Vec<serde_json::Value>>,
    /// Every chat call's full `LlmChatParams`, in call order — lets tests
    /// assert on the request's non-message faces (e.g. the serialized tool
    /// list offered to the model).
    captured: Mutex<Vec<LlmChatParams>>,
    /// The token usage every response's `Usage` event reports (defaults to
    /// all zeros; tests that assert usage accumulation set real values).
    usage: Mutex<(u64, u64, u64, u64)>,
}

impl ScriptedLlm {
    pub(super) fn new() -> Self {
        Self::default()
    }

    /// Report these four-bucket values on every subsequent `Usage` event.
    fn set_usage(&self, input: u64, output: u64, cache_read: u64, cache_creation: u64) {
        *self.usage.lock().unwrap_or_else(|e| e.into_inner()) =
            (input, output, cache_read, cache_creation);
    }

    /// Push the (possibly overridden) `Usage` event.
    fn push_usage_event(&self, events: &mut VecDeque<LlmEvent>) {
        let (input, output, cache_read, cache_creation) =
            *self.usage.lock().unwrap_or_else(|e| e.into_inner());
        events.push_back(LlmEvent::Usage {
            input_tokens: input,
            output_tokens: output,
            cache_read_tokens: cache_read,
            cache_creation_tokens: cache_creation,
        });
    }

    /// The serialized messages of the n-th chat call (0-based).
    fn messages_of_call(&self, call: usize) -> serde_json::Value {
        self.recorded_messages
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .get(call)
            .cloned()
            .unwrap_or(serde_json::Value::Null)
    }

    pub(super) fn push_text(&self, text: &str) {
        self.responses
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .push_back(ScriptedResponse::Text(text.to_string()));
    }

    pub(super) fn push_tool_use(&self, tool_calls: Vec<LlmToolCall>) {
        self.responses
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .push_back(ScriptedResponse::ToolUse(tool_calls));
    }

    /// Queue a chat call that fails outright with a provider error.
    fn push_error(&self, message: &str) {
        self.responses
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .push_back(ScriptedResponse::Error(message.to_string()));
    }

    /// Queue a gated text reply and return the release handle — the reply
    /// is held back until the test sends on (or drops) it.
    fn push_gated(&self, text: &str) -> tokio::sync::oneshot::Sender<()> {
        let (release, gate) = tokio::sync::oneshot::channel();
        self.responses
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .push_back(ScriptedResponse::Gated {
                release: gate,
                text: text.to_string(),
            });
        release
    }

    /// [`Self::push_gated`] with cancel-aware parking: the parked stream
    /// unblocks on the request's cancel token (ending without a Done), so
    /// a watchdog kill settles through the cooperative-cancellation path.
    fn push_gated_cancel_aware(&self, text: &str) -> tokio::sync::oneshot::Sender<()> {
        let (release, gate) = tokio::sync::oneshot::channel();
        self.responses
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .push_back(ScriptedResponse::GatedCancelAware {
                release: gate,
                text: text.to_string(),
            });
        release
    }

    /// Queue a gated tool-use reply and return the release handle — the
    /// tool calls are held back until the test sends on (or drops) it, so
    /// the turn parks mid-step with a tool round pending.
    fn push_gated_tool_use(
        &self,
        tool_calls: Vec<LlmToolCall>,
    ) -> tokio::sync::oneshot::Sender<()> {
        let (release, gate) = tokio::sync::oneshot::channel();
        self.responses
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .push_back(ScriptedResponse::GatedToolUse {
                release: gate,
                tool_calls,
            });
        release
    }

    /// Queue a gated FAILING reply and return the release handle — the
    /// chat call parks on the gate, then yields a stream-level provider
    /// error. Lets a test keep a side call in flight until after the
    /// turn's settle and only then fail it.
    fn push_gated_error(&self, message: &str) -> tokio::sync::oneshot::Sender<()> {
        let (release, gate) = tokio::sync::oneshot::channel();
        self.responses
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .push_back(ScriptedResponse::GatedError {
                release: gate,
                message: message.to_string(),
            });
        release
    }

    /// The captured `LlmChatParams` of every chat call so far, in call
    /// order — a snapshot clone of what the engine passed to the provider
    /// (messages, tools, and the rest of the request shape).
    fn captured_params(&self) -> Vec<LlmChatParams> {
        self.captured
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .clone()
    }

    pub(super) fn chat_call_count(&self) -> u64 {
        self.calls.load(Ordering::Relaxed)
    }
}

impl Llm for ScriptedLlm {
    fn system_prompt(&self) -> &str {
        "You are a scripted test assistant."
    }

    fn model_name(&self) -> &str {
        "scripted-llm"
    }

    fn capability(&self) -> &ModelCapability {
        static CAPABILITY: ModelCapability = ModelCapability {
            image_in: false,
            video_in: false,
            audio_in: false,
            dynamically_loaded_tools: false,
        };
        &CAPABILITY
    }

    fn chat(&self, params: LlmChatParams) -> EngineResult<LlmEventStream> {
        self.captured
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .push(params.clone());
        self.recorded_messages
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .push(serde_json::to_value(&params.messages).unwrap_or_default());
        // Exhausted queue: a placeholder reply, never an empty response —
        // the empty-response guard (turn-scheduling SDR-002/ADR-002) fails
        // empty-but-completed turns, so silently draining to "" would turn
        // every un-scripted turn (side calls, notification turns, extra
        // turns the test didn't plan) into a step-retry storm. Tests that
        // genuinely want an empty response must script `push_text("")`.
        let response = self
            .responses
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .pop_front()
            .unwrap_or(ScriptedResponse::Text(
                "(no more scripted replies)".to_string(),
            ));
        // Counted after the pop: `chat_call_count` then means "responses
        // consumed", so a caller waiting for N calls knows the N-th
        // queued response has actually been taken by its round (the
        // count and the pop share this critical section's ordering).
        self.calls.fetch_add(1, Ordering::Relaxed);
        if let ScriptedResponse::Error(message) = &response {
            return Err(mirri_core::error::EngineError::ProviderError(
                message.clone(),
            ));
        }
        let mut events = VecDeque::new();
        match response {
            // The error arm returns above; this arm exists so the match
            // stays exhaustive when a new variant is added.
            ScriptedResponse::Error(_) => unreachable!("errors return before the stream"),
            ScriptedResponse::Text(text) => {
                for ch in text.chars() {
                    events.push_back(LlmEvent::TextDelta {
                        text: ch.to_string(),
                    });
                }
                if !text.is_empty() {
                    events.push_back(LlmEvent::TextPart { text });
                }
                self.push_usage_event(&mut events);
                events.push_back(LlmEvent::Done {
                    stop_reason: "completed".to_string(),
                });
            }
            ScriptedResponse::ToolUse(tool_calls) => {
                for tc in &tool_calls {
                    // Stream the tool-call arguments as two live fragments
                    // before the block-level ToolCall — mirrors what a real
                    // OpenAI-style provider does and exercises the
                    // `event.tool.call.delta` relay path end to end.
                    let args_text = serde_json::to_string(&tc.args).unwrap_or_default();
                    if args_text.len() > 4 {
                        let (head, tail) = args_text.split_at(args_text.len() / 2);
                        for fragment in [head, tail] {
                            events.push_back(LlmEvent::ToolCallPart {
                                index: 0,
                                arguments_part: fragment.to_string(),
                                call_id: Some(tc.id.clone()),
                                tool_name: Some(tc.name.clone()),
                            });
                        }
                    }
                    events.push_back(LlmEvent::ToolCall {
                        tool: tc.name.clone(),
                        args: tc.args.clone(),
                        call_id: tc.id.clone(),
                    });
                }
                self.push_usage_event(&mut events);
                events.push_back(LlmEvent::Done {
                    stop_reason: "tool_calls".to_string(),
                });
            }
            ScriptedResponse::Gated { release, text } => {
                // Build the same event sequence the Text arm produces,
                // then park on the gate before the first event flows —
                // the caller observes an in-flight, not-yet-answered LLM
                // call for as long as it holds the gate.
                let text = text.clone();
                for ch in text.chars() {
                    events.push_back(LlmEvent::TextDelta {
                        text: ch.to_string(),
                    });
                }
                if !text.is_empty() {
                    events.push_back(LlmEvent::TextPart { text });
                }
                self.push_usage_event(&mut events);
                events.push_back(LlmEvent::Done {
                    stop_reason: "completed".to_string(),
                });
                let first = events.pop_front();
                let gated = futures::stream::once(async move {
                    let _ = release.await;
                    first
                })
                .filter_map(|event| async move { event })
                .chain(futures::stream::iter(events));
                return Ok(Box::pin(gated));
            }
            ScriptedResponse::GatedCancelAware { release, text } => {
                // The same parked-on-gate shape as `Gated`, but the park
                // ALSO observes the request's cancel token: a cancelled
                // turn unblocks here and the stream ends without a Done,
                // so the engine's cooperative-cancellation path (not the
                // hard drop) settles the turn — the watchdog-kill shape
                // the settle-path reason tests need.
                let text = text.clone();
                for ch in text.chars() {
                    events.push_back(LlmEvent::TextDelta {
                        text: ch.to_string(),
                    });
                }
                if !text.is_empty() {
                    events.push_back(LlmEvent::TextPart { text });
                }
                self.push_usage_event(&mut events);
                events.push_back(LlmEvent::Done {
                    stop_reason: "completed".to_string(),
                });
                let first = events.pop_front();
                let cancel = params.cancel.clone();
                let gated = futures::stream::once(async move {
                    tokio::select! {
                        _ = release => first,
                        _ = cancel.cancelled() => None,
                    }
                })
                .filter_map(|event| async move { event })
                .chain(futures::stream::iter(events));
                return Ok(Box::pin(gated));
            }
            ScriptedResponse::GatedToolUse {
                release,
                tool_calls,
            } => {
                // The same gated spelling as the text arm, but the parked
                // response is a tool call — the turn continues to a second
                // LLM step once the gate opens.
                let mut events = VecDeque::new();
                for tc in &tool_calls {
                    events.push_back(LlmEvent::ToolCall {
                        tool: tc.name.clone(),
                        args: tc.args.clone(),
                        call_id: tc.id.clone(),
                    });
                }
                self.push_usage_event(&mut events);
                events.push_back(LlmEvent::Done {
                    stop_reason: "tool_calls".to_string(),
                });
                let first = events.pop_front();
                let gated = futures::stream::once(async move {
                    let _ = release.await;
                    first
                })
                .filter_map(|event| async move { event })
                .chain(futures::stream::iter(events));
                return Ok(Box::pin(gated));
            }
            ScriptedResponse::GatedError { release, message } => {
                // Parks on the gate, then fails — the in-flight side call
                // whose failure lands after the turn already settled.
                let message = message.clone();
                let gated = futures::stream::once(async move {
                    let _ = release.await;
                    LlmEvent::Error { message }
                });
                return Ok(Box::pin(gated));
            }
        }
        Ok(Box::pin(futures::stream::iter(events)))
    }
}

/// An [`LlmFactory`] serving one shared [`ScriptedLlm`].
#[derive(Debug, Clone)]
pub(super) struct ScriptedLlmFactory {
    llm: Arc<ScriptedLlm>,
}

impl ScriptedLlmFactory {
    pub(super) fn new(llm: Arc<ScriptedLlm>) -> Self {
        Self { llm }
    }
}

impl LlmFactory for ScriptedLlmFactory {
    fn create_llm(&self, _config: &AgentScopeConfig) -> Result<Arc<dyn Llm>, String> {
        Ok(Arc::clone(&self.llm) as Arc<dyn Llm>)
    }
}

/// An [`LlmFactory`] recording the model id each `create_llm` call saw
/// while answering a shared scripted LLM — the seam for the per-prompt
/// model-override tests.
#[derive(Debug, Clone)]
struct RecordingLlmFactory {
    llm: Arc<ScriptedLlm>,
    seen: Arc<std::sync::Mutex<Vec<String>>>,
}

impl LlmFactory for RecordingLlmFactory {
    fn create_llm(&self, config: &AgentScopeConfig) -> Result<Arc<dyn Llm>, String> {
        self.seen
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .push(config.model_id.clone());
        Ok(Arc::clone(&self.llm) as Arc<dyn Llm>)
    }
}

/// A server on a throwaway tempdir workspace, with an optional factory.
///
/// The bare test servers' config carries an explicit `default_model` seed:
/// the embedded create chain requires a resolvable model (spec 11 R4 — no
/// built-in fallback), so tests that don't care about the model still need
/// SOME default configured, exactly like a real user's config.toml would.
/// Tests that DO care about the model resolution use
/// [`test_server_with_config_toml`] with their own TOML.
const TEST_DEFAULT_MODEL: &str = "test-default-model";

/// The seeded config snapshot shared by the bare test-server helpers.
fn test_server_config() -> Arc<RwLock<ServerConfig>> {
    let config = ServerConfig {
        default_model: Some(TEST_DEFAULT_MODEL.to_string()),
        ..ServerConfig::default()
    };
    Arc::new(RwLock::new(config))
}

fn test_server(llm_factory: Option<Arc<dyn LlmFactory>>) -> (EmbeddedServer, tempfile::TempDir) {
    let tmp = tempfile::tempdir().expect("tempdir must be creatable");
    let workspace = Arc::new(WorkspaceScope::new(
        WorkspaceId::new("test-ws"),
        tmp.path().to_path_buf(),
        WorkspaceScopeConfig::default(),
    ));
    let manager = Arc::new(SessionManager::new(workspace));
    (
        EmbeddedServer::with_providers(
            manager,
            llm_factory,
            None,
            None,
            None,
            test_server_config(),
            None,
        ),
        tmp,
    )
}

/// Converse once with the session — SDR-004's materialization trigger (W5).
/// Best-effort on purpose: a turn that fails (most of these tests configure
/// no LLM provider) still materializes the session and stamps its
/// `last_prompt` — "the conversation failed" is not empty.
async fn converse_once(server: &EmbeddedServer, session_id: &str) {
    let _ = server
        .call_method(
            "message.send",
            json!({ "session_id": session_id, "text": "hello" }),
        )
        .await;
}

#[test]
fn should_attach_engine_providers_when_server_is_built_for_a_workspace_root() {
    // Given a throwaway workspace root
    let tmp = tempfile::tempdir().expect("tempdir must be creatable");

    // When the fully-wired server is constructed for it
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("wired-ws"),
        tmp.path().to_path_buf(),
        None,
        Vec::new(),
    );

    // Then every engine-loop provider is attached: the LLM factory (turns
    // run when credentials are in the environment), the profile manager
    // (Agent/AgentSwarm tool registration), and the local fetch provider
    // (FetchURL tool registration).
    assert!(server.llm_factory.is_some(), "llm factory must be wired");
    assert!(
        server.profile_manager.is_some(),
        "profile manager must be wired"
    );
    assert!(
        server.fetch_url_provider.is_some(),
        "fetch url provider must be wired"
    );
}

#[test]
fn should_load_config_toml_from_the_injected_home_when_one_is_provided() {
    // Given an injected Mirri home carrying a config.toml
    let home = tempfile::tempdir().expect("home tempdir");
    std::fs::write(home.path().join("config.toml"), "[test]\n").expect("write config");

    // And a throwaway workspace root
    let workspace = tempfile::tempdir().expect("workspace tempdir");

    // When the fully-wired server is constructed with the injected home
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("injected-home"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );

    // Then the configuration was loaded from the injected home's
    // config.toml — not from the ambient environment's Mirri home
    assert_eq!(
        server.config_path().as_deref(),
        Some(home.path().join("config.toml").as_path()),
        "config.toml must resolve under the injected home"
    );
    // And the server records the injected home for RPC-time consumers
    assert_eq!(server.home_dir(), Some(home.path()));
}

#[tokio::test]
async fn should_isolate_session_persistence_under_the_injected_home_when_one_is_provided() {
    // Given a workspace root carrying a stray persisted session — the
    // workspace-local layout `<workspace>/.mirri/v3_sessions` that
    // accumulated across runs and made `session.list` environment-dependent
    let workspace = tempfile::tempdir().expect("workspace tempdir");
    let stray_dir = workspace
        .path()
        .join(".mirri")
        .join("v3_sessions")
        .join("session-stray");
    std::fs::create_dir_all(&stray_dir).expect("create stray session dir");
    std::fs::write(stray_dir.join("state.json"), r#"{"title": "stray"}"#)
        .expect("write stray state");

    // And an empty injected Mirri home
    let home = tempfile::tempdir().expect("home tempdir");
    seed_home_default_model(home.path());

    // When the server is built with the injected home and sessions are listed
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("injected-home"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );
    let listed = server
        .call_method("session.list", json!({}))
        .await
        .expect("session.list must succeed");

    // Then the stray workspace-local session is invisible — the listing
    // reads the injected home's sessions root, which is empty
    assert_eq!(
        listed["items"]
            .as_array()
            .expect("session.list returns an array")
            .len(),
        0,
        "the stray workspace-local session must not leak into the listing"
    );

    // And a newly created session persists under the injected home — not
    // under the workspace-local `.mirri` root — nested in the workspace
    // bucket derived from the workspace cwd (the TS per-workspace layout)
    let created = server
        .call_method("session.create", json!({ "title": "isolated" }))
        .await
        .expect("session.create must succeed");
    let session_id = created["id"].as_str().expect("session id");
    converse_once(&server, session_id).await;
    let bucket = mirri_core::encode_work_dir_key(workspace.path());
    let persisted_state = home
        .path()
        .join("v3_sessions")
        .join(&bucket)
        .join(session_id)
        .join("state.json");
    assert!(
        persisted_state.exists(),
        "the new session's state must live under the injected home (bucket {bucket})"
    );
    assert!(
        !workspace
            .path()
            .join(".mirri")
            .join("v3_sessions")
            .join(session_id)
            .exists(),
        "the new session must not write into the workspace-local sessions root"
    );
}

#[tokio::test]
async fn should_migrate_a_legacy_flat_session_at_startup_when_one_is_in_the_home() {
    // Given an injected Mirri home whose sessions root carries a LEGACY
    // flat session (the pre-Phase-2 rust layout: state.json directly under
    // <home>/v3_sessions/<id>/) with a minimal resumable wire log
    let workspace = tempfile::tempdir().expect("workspace tempdir");
    let home = tempfile::tempdir().expect("home tempdir");
    seed_home_default_model(home.path());
    let flat_dir = home.path().join("v3_sessions").join("session-legacy");
    std::fs::create_dir_all(&flat_dir).expect("create flat session dir");
    std::fs::write(
        flat_dir.join("state.json"),
        r#"{"title":"Legacy flat","createdAt":"2024-01-01T00:00:00Z","updatedAt":"2024-01-01T00:00:00Z","tags":[]}"#,
    )
    .expect("write flat state");
    std::fs::write(
        flat_dir.join("wire.jsonl"),
        "{\"op\":\"metadata\",\"protocolVersion\":null,\"createdAt\":null}\n",
    )
    .expect("write flat wire log");
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("legacy-migration"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );

    // When the first RPC call is dispatched (the seam the one-time
    // migration runs on — the same lazy pattern as the MCP connect)
    let listed = server
        .call_method("session.list", json!({}))
        .await
        .expect("session.list must succeed");

    // Then the legacy session was migrated into the workspace bucket (the
    // flat session carried no workDir, so the current workspace cwd is the
    // backfilled attribution) and the flat directory is gone
    assert!(!flat_dir.exists(), "the flat directory must be gone");
    let bucket = mirri_core::encode_work_dir_key(workspace.path());
    let moved = home
        .path()
        .join("v3_sessions")
        .join(&bucket)
        .join("session-legacy");
    assert!(moved.join("state.json").exists());
    assert!(moved.join("wire.jsonl").exists());

    // And the listing still sees the migrated session
    assert_eq!(
        listed["items"]
            .as_array()
            .expect("session.list returns an array")
            .len(),
        1,
        "the migrated session must remain visible to session.list"
    );

    // And the session is resumable through its new bucketed location
    let resumed = server
        .call_method("session.resume", json!({ "session_id": "session-legacy" }))
        .await
        .expect("session.resume must succeed after the migration");
    assert_eq!(resumed["id"].as_str(), Some("session-legacy"));
}

// ---------------------------------------------------------------------------
// Phase 3 — the SQLite session index (`<home>/session-index.db`)
// ---------------------------------------------------------------------------

/// Given an injected home, When a session is created and closed, Then its
/// index row is written through (create + close), the listing resolves the
/// persisted session with the same wire fields as the disk scan, and the
/// workspace's `sessionCount` is served from the index.
#[tokio::test]
async fn should_serve_persisted_listings_through_the_session_index_when_a_home_is_injected() {
    // Given a server with an injected home and one created session
    let workspace = tempfile::tempdir().expect("workspace tempdir");
    let home = tempfile::tempdir().expect("home tempdir");
    seed_home_default_model(home.path());
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("index-list"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );
    let created = server
        .call_method("session.create", json!({ "title": "Indexed" }))
        .await
        .expect("session.create must succeed");
    let session_id = created["id"].as_str().expect("session id").to_string();
    converse_once(&server, &session_id).await;

    // When the session is closed (persisted-only from here on)
    server
        .call_method("session.close", json!({ "sessionId": session_id }))
        .await
        .expect("session.close must succeed");

    // Then the close-time write-through left the row in the index
    let index = server.session_index().expect("the index is open");
    let row = index
        .get_session(&session_id)
        .expect("the session row was written through");
    assert_eq!(row.title.as_deref(), Some("Indexed"));
    assert_eq!(
        row.workspace_id,
        mirri_core::encode_work_dir_key(workspace.path()),
        "the row is attributed to the bound workspace's bucket"
    );

    // And the listing resolves the persisted session with the same wire
    // fields the disk scan serves
    let listed = server
        .call_method("session.list", json!({}))
        .await
        .expect("session.list must succeed");
    let entry = listed["items"]
        .as_array()
        .expect("session.list returns the page envelope's items")
        .iter()
        .find(|row| row["id"] == json!(session_id))
        .expect("the closed session is listed");
    assert_eq!(entry["title"], json!("Indexed"));
    assert_eq!(entry["status"], json!("closed"));
    assert_eq!(
        entry["cwd"],
        json!(workspace.path().to_string_lossy().to_string()),
        "the persisted row echoes the workspace root as cwd"
    );

    // And the workspace listing counts the session from the index
    let workspaces = server
        .call_method("workspace.list", json!({}))
        .await
        .expect("workspace.list must succeed");
    assert_eq!(workspaces[0]["sessionCount"], json!(1));
}

/// Given an archived and a plain persisted session in an injected home,
/// When listings run, Then the archived row drops out of the default listing
/// and returns with `includeArchive` — the row carrying the flag.
#[tokio::test]
async fn should_filter_archived_sessions_out_of_index_backed_listings() {
    // Given a server with an injected home and two closed sessions
    let workspace = tempfile::tempdir().expect("workspace tempdir");
    let home = tempfile::tempdir().expect("home tempdir");
    seed_home_default_model(home.path());
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("index-archive"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );
    let mut ids = Vec::new();
    for title in ["Plain", "Archived"] {
        let created = server
            .call_method("session.create", json!({ "title": title }))
            .await
            .expect("session.create must succeed");
        let id = created["id"].as_str().expect("session id").to_string();
        converse_once(&server, &id).await;
        server
            .call_method("session.close", json!({ "sessionId": id }))
            .await
            .expect("session.close must succeed");
        ids.push(id);
    }

    // When one of them is archived (the persisted-only branch of the flag
    // write — the session is no longer live)
    server
        .call_method("session.archive", json!({ "sessionId": ids[1] }))
        .await
        .expect("session.archive must succeed");

    // Then the row carries the flag
    let index = server.session_index().expect("the index is open");
    assert!(
        index
            .get_session(&ids[1])
            .expect("the archived row exists")
            .archived
    );
    assert!(
        !index
            .get_session(&ids[0])
            .expect("the plain row exists")
            .archived
    );

    // And the default listing excludes it while the opt-in keeps it
    let default = server
        .call_method("session.list", json!({}))
        .await
        .expect("session.list must succeed");
    let listed_ids: Vec<&str> = default["items"]
        .as_array()
        .unwrap()
        .iter()
        .filter_map(|row| row["id"].as_str())
        .collect();
    assert_eq!(listed_ids, vec![ids[0].as_str()]);
    let opted_in = server
        .call_method("session.list", json!({ "includeArchive": true }))
        .await
        .expect("session.list must succeed");
    assert_eq!(opted_in["items"].as_array().unwrap().len(), 2);
}

/// Given an indexed session whose directory later disappears from disk,
/// When a fresh engine on the same home lists sessions, Then the orphaned
/// row is dropped by the startup reconcile and the listing is empty.
#[tokio::test]
async fn should_drop_index_rows_when_the_session_directory_disappears() {
    // Given a server with an injected home, one closed session, and its
    // row in the index
    let workspace = tempfile::tempdir().expect("workspace tempdir");
    let home = tempfile::tempdir().expect("home tempdir");
    seed_home_default_model(home.path());
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("index-orphan"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );
    let created = server
        .call_method("session.create", json!({ "title": "Doomed" }))
        .await
        .expect("session.create must succeed");
    let session_id = created["id"].as_str().expect("session id").to_string();
    converse_once(&server, &session_id).await;
    server
        .call_method("session.close", json!({ "sessionId": session_id }))
        .await
        .expect("session.close must succeed");
    assert!(
        server
            .session_index()
            .expect("the index is open")
            .get_session(&session_id)
            .is_some(),
        "the row exists before the directory is removed"
    );

    // When the session directory disappears (deleted out-of-band) and a
    // fresh engine on the same home runs its first RPC
    let bucket = mirri_core::encode_work_dir_key(workspace.path());
    std::fs::remove_dir_all(
        home.path()
            .join("v3_sessions")
            .join(&bucket)
            .join(&session_id),
    )
    .expect("remove the session directory");
    let restart = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("index-orphan"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );
    let listed = restart
        .call_method("session.list", json!({}))
        .await
        .expect("session.list must succeed");

    // Then the orphan pass deleted the row and the listing is empty
    assert!(
        restart
            .session_index()
            .expect("the index is open")
            .get_session(&session_id)
            .is_none(),
        "the orphaned row is deleted"
    );
    assert_eq!(
        listed["items"]
            .as_array()
            .expect("session.list returns an array")
            .len(),
        0
    );
}

/// Given an injected home, When the engine boots and registers its bound
/// workspace, Then the row lands in the index AND writes through to the
/// cross-engine `workspaces.json` registry with the TS on-disk shape.
#[tokio::test]
async fn should_register_the_bound_workspace_in_the_index_and_the_registry() {
    // Given a server with an injected home
    let workspace = tempfile::tempdir().expect("workspace tempdir");
    let home = tempfile::tempdir().expect("home tempdir");
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("index-workspace"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );

    // When the first RPC runs (the seam the one-time reconcile runs on)
    server
        .call_method("workspace.list", json!({}))
        .await
        .expect("workspace.list must succeed");

    // Then the bound workspace's row is registered in the index under the
    // workdir key, with the root's basename as its name
    let key = mirri_core::encode_work_dir_key(workspace.path());
    let index = server.session_index().expect("the index is open");
    let row = index
        .get_workspace(&key)
        .expect("the bound workspace is registered");
    assert_eq!(
        row.root.as_deref(),
        Some(workspace.path().to_str().unwrap())
    );
    assert_eq!(
        row.name.as_deref(),
        Some(
            workspace
                .path()
                .file_name()
                .unwrap()
                .to_string_lossy()
                .as_ref()
        )
    );

    // And the registration wrote through to the cross-engine registry in
    // the TS on-disk shape
    let registry: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(home.path().join("workspaces.json"))
            .expect("workspaces.json was written"),
    )
    .expect("workspaces.json parses");
    assert_eq!(
        registry["workspaces"][key.as_str()]["root"],
        json!(workspace.path().to_string_lossy().to_string())
    );
}

/// A server with a profile manager and mock LLM factory, registering a
/// `"coder"` profile so Agent/AgentSwarm tools can spawn subagents.
fn test_server_with_profiles(
    llm_factory: Arc<dyn LlmFactory>,
) -> (EmbeddedServer, tempfile::TempDir) {
    use mirri_core::{AgentProfile, PermissionMode, ProfileManager};
    let tmp = tempfile::tempdir().expect("tempdir must be creatable");
    let workspace = Arc::new(WorkspaceScope::new(
        WorkspaceId::new("test-ws"),
        tmp.path().to_path_buf(),
        WorkspaceScopeConfig::default(),
    ));
    let manager = Arc::new(SessionManager::new(workspace));
    let profile_manager = Arc::new(ProfileManager::new());
    profile_manager
        .register(AgentProfile {
            name: "coder".to_string(),
            model: "mock-llm".to_string(),
            permission_mode: Some(PermissionMode::Yolo),
            ..Default::default()
        })
        .unwrap();
    let server = EmbeddedServer::with_providers(
        manager,
        Some(llm_factory),
        Some(profile_manager),
        None,
        None,
        test_server_config(),
        None,
    );
    (server, tmp)
}

/// Seed `config.toml` for the config write-path tests: one provider
