const CONFIG_WRITE_SEED_TOML: &str = r#"
default_provider = "kimi"
default_model = "kimi/alpha"

[providers.kimi]
type = "openai"
api_key = "sk-test"

[models."kimi/alpha"]
provider = "kimi"
model = "alpha"
max_context_size = 128000

[models."kimi/beta"]
provider = "kimi"
model = "beta"
max_context_size = 200000
"#;

/// A server whose config.toml lives in a tempdir, seeded with the given
/// TOML contents. The in-memory snapshot is loaded exactly like a real
/// boot, and `config_path` points at the file so the `config.set` /
/// `removeProvider` / `removeModel` write path works. Returns the
/// server, the tempdir, and the config file path.
fn test_server_with_config_toml(
    toml_contents: &str,
) -> (EmbeddedServer, tempfile::TempDir, std::path::PathBuf) {
    let tmp = tempfile::tempdir().expect("tempdir must be creatable");
    let config_path = tmp.path().join("config.toml");
    std::fs::write(&config_path, toml_contents).expect("config.toml write should succeed");
    let workspace = Arc::new(WorkspaceScope::new(
        WorkspaceId::new("test-ws"),
        tmp.path().to_path_buf(),
        WorkspaceScopeConfig::default(),
    ));
    let manager = Arc::new(SessionManager::new(workspace));
    let config = Arc::new(RwLock::new(
        ServerConfig::load(&config_path, &mirri_os::LocalSyncFs).expect("seed config should load"),
    ));
    let server = EmbeddedServer::with_providers(
        manager,
        None,
        None,
        None,
        None,
        config,
        Some(config_path.clone()),
    );
    (server, tmp, config_path)
}

