/// Given a server with the profile catalog, when a session is created, then
/// the main agent runs under the essential `agent` profile's tool whitelist
/// (the explicit list with the MCP glob, not the unrestricted default) and
/// the template-rendered system prompt.
#[tokio::test]
async fn should_apply_the_essential_profile_whitelist_when_the_main_agent_is_created() {
    let (server, _tmp) = test_server_with_profile_catalog();

    let result = server
        .call_method("session.create", json!({ "modelId": "mock-model" }))
        .await
        .expect("session created");
    let session_id = result["id"].as_str().unwrap().to_string();

    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .expect("session is live");
    let agent = session
        .get_agent(&mirri_core::AgentId::new(DEFAULT_MAIN_AGENT_ID))
        .await
        .expect("main agent is live");
    let enabled: Vec<String> = agent.tool_manager().read().enabled_tools().to_vec();
    assert!(
        enabled.contains(&"mcp__*".to_string()),
        "the main agent carries the profile whitelist with the MCP glob: {enabled:?}"
    );
    assert!(
        enabled.contains(&"Read".to_string()) && enabled.contains(&"Bash".to_string()),
        "the main agent carries the profile's core tools: {enabled:?}"
    );
    let prompt = agent
        .config()
        .read()
        .unwrap_or_else(|e| e.into_inner())
        .system_prompt
        .clone()
        .expect("the main agent's prompt is assembled");
    assert!(
        prompt.contains("# Prompt and Tool Use"),
        "the main agent's prompt is the base template: {prompt}"
    );
}

/// Given a closed session, when it is resumed, then the rebuilt main agent
/// carries the same essential-profile whitelist as the create path — no
/// create/resume divergence.
#[tokio::test]
async fn should_apply_the_essential_profile_whitelist_when_the_session_is_resumed() {
    let (server, _tmp) = test_server_with_profile_catalog();
    let created = server
        .call_method("session.create", json!({ "modelId": "mock-model" }))
        .await
        .expect("session created");
    let session_id = created["id"].as_str().unwrap().to_string();
    // Materialize the session on disk (a turn stamps the wire log even when
    // no LLM is configured — the resume path needs the persisted bucket).
    converse_once(&server, &session_id).await;
    server
        .call_method("session.close", json!({ "session_id": &session_id }))
        .await
        .expect("session closed");

    server
        .call_method("session.resume", json!({ "session_id": &session_id }))
        .await
        .expect("session resumed");

    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .expect("resumed session is live");
    let agent = session
        .get_agent(&mirri_core::AgentId::new(DEFAULT_MAIN_AGENT_ID))
        .await
        .expect("main agent is live after resume");
    let enabled: Vec<String> = agent.tool_manager().read().enabled_tools().to_vec();
    assert!(
        enabled.contains(&"mcp__*".to_string()),
        "the resumed main agent carries the profile whitelist: {enabled:?}"
    );
    let prompt = agent
        .config()
        .read()
        .unwrap_or_else(|e| e.into_inner())
        .system_prompt
        .clone()
        .expect("the resumed main agent's prompt is assembled");
    assert!(
        prompt.contains("# Prompt and Tool Use"),
        "the resumed main agent's prompt is the base template: {prompt}"
    );
}

