/// Given a server whose config declares a default model alias, when a
/// session is created with an explicit-but-empty `modelId` (`""` — the
/// wire's "no preference" spelling some clients send instead of omitting
/// the field), then the create falls through to the configured default
/// exactly like an omitted `modelId` — the empty string is filtered
/// before resolution, symmetric with the resume path's empty-record
/// filter (spec 11 R9), never bound as a half-empty model id.
#[tokio::test]
async fn should_fall_back_to_the_config_default_when_session_create_model_id_is_an_empty_string() {
    // Given a server whose config declares a default model alias
    let (server, _tmp, _config_path) = test_server_with_config_toml(
        r#"
default_model = "kimi/alpha"

[providers.kimi]
type = "openai"
api_key = "sk-test"

[models."kimi/alpha"]
provider = "kimi"
model = "alpha"
max_context_size = 128000
"#,
    );

    // When a session is created with modelId: "" instead of omitting it
    let result = server
        .call_method(
            "session.create",
            json!({ "title": "Empty modelId", "modelId": "" }),
        )
        .await
        .expect("session created on the config default");

    // Then the wire view and the addressed agent carry the configured
    // default, exactly like an omitted modelId
    let session_id = result["id"].as_str().expect("session id");
    assert_eq!(result["model"], json!("kimi/alpha"));
    let model = server
        .call_method("agent.getModel", json!({ "sessionId": session_id }))
        .await
        .expect("get model");
    assert_eq!(model.as_str(), Some("kimi/alpha"));
}

/// Given a server whose config declares no default model, when a session
/// is created without an explicit `modelId`, then the create is rejected
/// with an actionable `request.invalid` error naming the two remediation
/// paths (set `default_model` in config.toml, or pass `modelId`) — no
/// built-in model is silently bound (spec 11 R4), and no half-created
/// session lingers in the workspace.
#[tokio::test]
async fn should_reject_session_creation_with_actionable_error_when_no_model_resolvable() {
    let (server, _tmp, _config_path) = test_server_with_config_toml(
        r#"
[providers.kimi]
type = "openai"
api_key = "sk-test"

[models."kimi/alpha"]
provider = "kimi"
model = "alpha"
max_context_size = 128000
"#,
    );

    // When a session is created without an explicit model id
    let error = server
        .call_method("session.create", json!({}))
        .await
        .expect_err("session.create must fail when no model is resolvable");

    // Then the error is a client error (request.invalid) whose message
    // points at both remediation paths and never names a built-in model
    assert!(
        matches!(&error, EngineError::Rpc { code, .. } if *code == mirri_proto::rpc::JSON_RPC_INVALID_PARAMS),
        "expected an invalid-params error, got: {error}"
    );
    let message = error.to_string();
    assert!(message.contains("no model configured"), "{message}");
    assert!(message.contains("default_model"), "{message}");
    assert!(message.contains("modelId"), "{message}");
    assert!(
        !message.contains("claude-"),
        "the error must not name any built-in model: {message}"
    );

    // And the workspace keeps no half-created session behind
    let listed = server
        .call_method("session.list", json!({}))
        .await
        .expect("session.list must succeed");
    let items = listed["items"].as_array().expect("session.list items");
    assert!(
        items.is_empty(),
        "a rejected create must not leave a session behind"
    );
}

