/// Given a session created on "first-model", when `message.send` carries a
/// model, then the LLM factory resolves the prompt's model, and the switch
/// is sticky: the agent's live scope config carries it for the session's
/// next prompt too (one param-carrying send is one standard switch — the
/// same mutation `session.updateMeta` applies; spec 11 A9).
#[tokio::test]
async fn should_apply_the_model_override_when_message_send_carries_a_model() {
    // Given a server with a recording mock LLM and a session on "first-model"
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("first");
    let seen = Arc::new(std::sync::Mutex::new(Vec::new()));
    let (server, _tmp, _config_path) =
        test_server_with_two_models_and_factory(Arc::new(RecordingLlmFactory {
            llm: Arc::clone(&mock),
            seen: Arc::clone(&seen),
        }));
    let created = server
        .call_method(
            "session.create",
            json!({ "title": "send-model", "modelId": "first-model" }),
        )
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    // When a message is sent carrying a model (a registered alias — the
    // shared switch path validates it exactly like `agent.setModel`)
    server
        .call_method(
            "message.send",
            json!({ "session_id": session_id, "text": "hi", "mode": "wait", "model": "second-model" }),
        )
        .await
        .unwrap();

    // Then the factory resolved the sent model (never the create-time one)
    assert_eq!(
        *seen.lock().unwrap_or_else(|e| e.into_inner()),
        vec!["second-model".to_string()],
        "the prompt's model must reach the LLM factory"
    );

    // And the next prompt without a model inherits the switch (the
    // sticky semantics, mirroring session.updateMeta)
    mock.push_text("second");
    server
        .call_method(
            "message.send",
            json!({ "session_id": session_id, "text": "again", "mode": "wait" }),
        )
        .await
        .unwrap();
    assert_eq!(
        seen.lock().unwrap_or_else(|e| e.into_inner()).last(),
        Some(&"second-model".to_string()),
        "the override must stick on the agent's live scope config"
    );
}

/// Given a session created through the REAL embedded create chain while the
/// main agent runs "model-a", when the main agent switches to "model-b" and
/// a child is spawned through the production host (the one the create path
/// wired into the main agent's config and bound to the main agent's live
/// config handle), then the child's LLM construction sees "model-b" — the
/// production binding point's regression (spec 11 A3; review R1 I1: deleting
/// the create-path binding in `session_handlers.rs` makes this test go red).
#[tokio::test]
async fn should_inherit_live_parent_model_through_production_host_when_main_switches_model() {
    // Given a server whose profile manager resolves a model-less "coder"
    // profile (Tier 3 is then the only resolvable face) and a recording mock
    // LLM — the same assembly shape as `test_server_with_profiles`, with the
    // profile declared model-less on purpose
    use mirri_core::subagent::SpawnRequest;
    let tmp = tempfile::tempdir().expect("tempdir must be creatable");
    let workspace = Arc::new(WorkspaceScope::new(
        WorkspaceId::new("test-ws"),
        tmp.path().to_path_buf(),
        WorkspaceScopeConfig::default(),
    ));
    let manager = Arc::new(SessionManager::new(workspace));
    let profile_manager = Arc::new(mirri_core::ProfileManager::new());
    profile_manager
        .register(mirri_core::AgentProfile {
            name: "coder-nomodel".to_string(),
            ..Default::default()
        })
        .unwrap();
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("child reply");
    let seen = Arc::new(Mutex::new(Vec::new()));
    let server = EmbeddedServer::with_providers(
        manager,
        Some(Arc::new(RecordingLlmFactory {
            llm: Arc::clone(&mock),
            seen: Arc::clone(&seen),
        })),
        Some(profile_manager),
        None,
        None,
        test_server_config(),
        None,
    );

    // When a session is created on "model-a" through the real create chain,
    // the main agent switches to "model-b", and a child is spawned without
    // a model through the production host
    let created = server
        .call_method("session.create", json!({ "modelId": "model-a" }))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .expect("session stays live");
    let main = session
        .get_agent(&AgentId::new(DEFAULT_MAIN_AGENT_ID))
        .await
        .expect("main agent");
    main.set_model("model-b".to_string());
    let host = {
        let config = main.config();
        let guard = config.read().unwrap_or_else(|e| e.into_inner());
        guard
            .subagent_host
            .clone()
            .expect("the create chain wires the production host into the main agent's config")
    };
    let mut handle = host
        .spawn(SpawnRequest {
            profile_name: "coder-nomodel".to_string(),
            prompt: "do the thing".to_string(),
            description: "production-binding regression".to_string(),
            model: None,
            cancel: mirri_core::CancelToken::new(),
            run_in_background: false,
            parent_tool_call_id: None,
            swarm_index: None,
            swarm_item: None,
            suppress_rate_limit_failure_event: false,
        })
        .expect("spawn resolves through the production host");
    let completion = tokio::time::timeout(Duration::from_secs(10), &mut handle.completion)
        .await
        .expect("child turn completes without deadlock")
        .expect("child turn succeeds");

    // Then the child's LLM construction saw the parent's NEW model — the
    // create-path binding made the live "model-b" reachable (the production
    // host reads the shared live handle, not the create-time snapshot)
    assert_eq!(completion.result, "child reply");
    let seen_models: Vec<String> = seen.lock().unwrap_or_else(|e| e.into_inner()).clone();
    assert!(
        seen_models.iter().any(|model| model == "model-b"),
        "the child LLM must be built on the parent's live model through the production host, got: {seen_models:?}"
    );
}

#[tokio::test]
async fn should_stream_message_received_and_agent_message_chunk_when_turn_runs_with_mock_llm() {
    // Given a server with a scripted mock LLM (titled session — the test
    // counts the mock's calls, and an untitled session's settle would
    // spawn the side title call too)
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("chunked");
    let (server, _tmp) = test_server(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))));
    let created = server
        .call_method("session.create", json!({ "title": "chunked" }))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    // When a subscriber listens and a wait-mode message runs its turn
    let mut events = server.subscribe_events().await.unwrap();
    server
        .call_method(
            "message.send",
            json!({ "session_id": session_id, "text": "hi" }),
        )
        .await
        .unwrap();

    // Then the subscriber observes event.message.received then one
    // event.assistant.delta per assistant character
    let mut saw_received = false;
    let mut chunk_text = String::new();
    for _ in 0..100 {
        match tokio::time::timeout(Duration::from_secs(5), events.recv())
            .await
            .expect("event must arrive within 5s")
            .expect("event channel stays open")
        {
            notification if notification.method == "event.message.received" => {
                assert_eq!(notification.params["sessionId"], session_id);
                assert_eq!(notification.params["role"], "user");
                saw_received = true;
            }
            notification if notification.method == "event.assistant.delta" => {
                chunk_text.push_str(
                    notification.params["delta"]
                        .as_str()
                        .expect("chunk params carry the delta text"),
                );
                if chunk_text == "chunked" {
                    break;
                }
            }
            _ => {}
        }
    }
    assert!(
        saw_received,
        "event.message.received must precede the chunks"
    );
    assert_eq!(chunk_text, "chunked");
    assert_eq!(mock.chat_call_count(), 1);
}

#[tokio::test]
async fn should_emit_turn_started_and_ended_when_message_send_succeeds() {
    // Given a server with a scripted mock LLM and a created session
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("hello");
    let (server, _tmp) = test_server(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))));
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    // When a subscriber listens and a wait-mode message runs its turn
    let mut events = server.subscribe_events().await.unwrap();
    server
        .call_method(
            "message.send",
            json!({ "session_id": session_id, "text": "hello" }),
        )
        .await
        .unwrap();

    // Then the subscriber observes event.turn.started followed by
    // event.turn.ended, both carrying the same client-facing turn id and
    // the session's id, with the wire stop reason on the ended event
    let mut started_turn_id: Option<String> = None;
    for _ in 0..100 {
        let notification = tokio::time::timeout(Duration::from_secs(5), events.recv())
            .await
            .expect("turn event must arrive within 5s")
            .expect("event channel stays open");
        match notification.method.as_str() {
            "event.turn.started" => {
                assert_eq!(notification.params["sessionId"], session_id);
                // The bracket is attributed to the agent that runs the
                // turn — the main agent's string identity here.
                assert_eq!(notification.params["agentId"], json!("main"));
                let turn_id = notification.params["turnId"]
                    .as_str()
                    .expect("turn id is a string")
                    .to_string();
                assert!(
                    turn_id.starts_with("turn-"),
                    "event.turn.started carries the client-facing turn-<uuid> id"
                );
                started_turn_id = Some(turn_id);
            }
            "event.turn.ended" => {
                assert!(
                    started_turn_id.is_some(),
                    "event.turn.ended must be preceded by event.turn.started"
                );
                assert_eq!(notification.params["sessionId"], session_id);
                // The closing half of the bracket carries the same
                // attribution as the opening half.
                assert_eq!(notification.params["agentId"], json!("main"));
                assert_eq!(
                    notification.params["turnId"],
                    started_turn_id.as_deref().expect("started turn id"),
                    "event.turn.ended closes the turn event.turn.started opened"
                );
                assert_eq!(
                    notification.params["reason"], "completed",
                    "the scripted EndTurn maps to the wire reason 'completed'"
                );
                return; // both events observed in order
            }
            _ => {}
        }
    }
    panic!("event.turn.started/event.turn.ended never both observed");
}

/// should emit structured agent.status frames when a message turn runs (CR4)
///
/// The frames are published by the `AgentStatusPublisher` wired at the
/// message-send dispatch, on every activity phase transition the turn's
/// tracker folds. The config declares the default model with a 500k
/// context window so the publisher's max-context handle is positive and
/// the contextTokens/maxContextTokens pair is present on every frame.
#[tokio::test]
async fn should_emit_structured_agent_status_when_a_message_turn_runs() {
    // Given a server whose config declares the default model with a 500k
    // context window, and a scripted one-shot LLM
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("hello");
    let (server, _tmp, _config_path) = test_server_with_config_toml_and_llm(
        "default_model = \"expert\"\n\
         \n\
         [models.expert]\n\
         provider = \"rakuten\"\n\
         model = \"GLM-5.3-Coding\"\n\
         max_context_size = 500000\n",
        Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock))),
    );
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    // When a subscriber listens and a wait-mode message runs its turn
    let mut events = server.subscribe_events().await.unwrap();
    server
        .call_method(
            "message.send",
            json!({ "session_id": session_id, "text": "hello" }),
        )
        .await
        .unwrap();

    // Then the subscriber observes structured agent.status frames: at
    // least one mid-turn frame (a running/streaming phase) before the
    // closing `ended` frame, every frame attributed to the main agent,
    // every frame carrying the positive token pair (the 500k window from
    // the config) and the usage object with numeric totals.
    let mut saw_mid_turn_phase = false;
    let mut status_frames = 0u32;
    for _ in 0..300 {
        let notification = tokio::time::timeout(Duration::from_secs(5), events.recv())
            .await
            .expect("event must arrive within 5s")
            .expect("event channel stays open");
        if notification.method != "event.agent.status.updated" {
            continue;
        }
        status_frames += 1;
        let params = &notification.params;
        assert_eq!(
            params["agentId"],
            json!("main"),
            "the main agent's turn attributes its status frames to \"main\": {params}"
        );
        // The token pair is present on every frame — the publisher only
        // emits the pair when the effective max is > 0 (the inf-ratio
        // guard), and this config's window is 500k. contextTokens starts
        // at 0 (the first frame fires before the user message lands in
        // memory) and grows as the turn records.
        let context_tokens = params["contextTokens"]
            .as_u64()
            .expect("contextTokens is a number");
        let max_context_tokens = params["maxContextTokens"]
            .as_u64()
            .expect("maxContextTokens is a number");
        assert!(
            max_context_tokens > 0,
            "the configured window makes maxContextTokens positive: {params}"
        );
        assert_eq!(max_context_tokens, 500000);
        assert!(
            params["contextUsage"].as_f64().is_some(),
            "the usage ratio derives from the token pair: {params}"
        );
        // The usage snapshot rides every frame (TS TokenUsage spelling:
        // inputOther/output/inputCacheRead/inputCacheCreation).
        assert!(
            params["usage"]["total"].is_object(),
            "the usage object with its total bucket: {params}"
        );
        assert!(
            params["usage"]["total"]["inputOther"].is_u64(),
            "numeric token totals: {params}"
        );
        match params["phase"].as_str().expect("phase is a string") {
            "running" | "streaming" => saw_mid_turn_phase = true,
            "ended" => {
                assert!(
                    saw_mid_turn_phase,
                    "a mid-turn status frame must precede the ended frame"
                );
                assert!(
                    status_frames >= 2,
                    "the turn publishes at least the started and ended frames"
                );
                assert!(
                    context_tokens > 0,
                    "the recorded conversation keeps the settled frame's \
                     contextTokens positive: {params}"
                );
                return; // mid-turn + closing frame observed in order
            }
            other => panic!("unexpected agent status phase: {other}"),
        }
    }
    panic!("no ended agent status frame observed for the main agent's turn");
}

/// should emit agent.status frames for a subagent member when dispatched
///
/// The member's frames carry the child's `agent-<uuid>` identity — the
/// same wire vocabulary every other agent-scoped event uses, so the web
/// can attribute member status apart from the parent's.
#[tokio::test(flavor = "multi_thread")]
async fn should_emit_agent_status_for_a_subagent_member_when_dispatched() {
    // Given a profile-backed server whose scripted LLM first calls the
    // Agent tool, then finishes the parent turn (the child consumes the
    // middle response) — the same shape the subagent-lifecycle test uses
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_tool_use(vec![LlmToolCall {
        id: "call-agent-1".to_string(),
        name: "Agent".to_string(),
        args: json!({
            "prompt": "do the delegated thing",
            "description": "delegate work",
        }),
    }]);
    mock.push_text("child result");
    mock.push_text("parent done");
    let (server, _tmp) =
        test_server_with_profiles(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock))));
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    // When a subscriber listens and the parent turn delegates to a child
    let mut events = server.subscribe_events().await.unwrap();
    server
        .call_method(
            "message.send",
            json!({ "session_id": session_id, "text": "delegate please" }),
        )
        .await
        .unwrap();

    // Then some agent.status frames carry the member's agent-<uuid> id
    // (the subagent host wires the publisher on the child's flow at
    // spawn), and those frames carry the same structured payload shape.
    let mut saw_member_frame = false;
    for _ in 0..400 {
        let notification = tokio::time::timeout(Duration::from_secs(5), events.recv())
            .await
            .expect("event must arrive within 5s")
            .expect("event channel stays open");
        if notification.method != "event.agent.status.updated" {
            continue;
        }
        let params = &notification.params;
        let agent_id = params["agentId"].as_str().expect("agentId is a string");
        if agent_id.starts_with("agent-") {
            saw_member_frame = true;
            assert!(
                params["phase"].is_string(),
                "the member frame carries a phase: {params}"
            );
            assert!(
                params["usage"]["total"].is_object(),
                "the member frame carries the usage object: {params}"
            );
        } else {
            assert_eq!(
                agent_id, "main",
                "the parent's frames stay attributed to \"main\": {params}"
            );
            // The parent's closing frame means the delegation is over —
            // the member's frames have all been observed by then.
            if params["phase"] == "ended" {
                assert!(
                    saw_member_frame,
                    "the dispatched member must publish at least one status \
                     frame under its agent-<uuid> id before the parent ends"
                );
                return;
            }
        }
    }
    panic!("the parent's turn never published its ended status frame");
}

/// Given a session that also holds a child agent (the `agent-<uuid>`
/// string vocabulary), when `message.send` addresses the child in both
/// wait and fire modes, then every `event.turn.started` /
/// `event.turn.ended` frame carries the CHILD's id in `agentId` — the
/// turn bracket is attributed to the agent that actually runs the turn,
/// never a blanket "main".
#[tokio::test(flavor = "multi_thread")]
async fn should_attribute_turn_events_to_the_child_agent_when_message_send_addresses_it() {
    // Given a scripted mock LLM with one reply per send and a session
    // holding the main agent plus a freshly created child agent
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("child wait reply");
    mock.push_text("child fire reply");
    let (server, _tmp) = test_server(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))));
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .expect("session is live");
    let child_id = format!("agent-{}", uuid::Uuid::new_v4());
    session
        .create_agent(
            AgentId::new(child_id.clone()),
            AgentScopeConfig {
                model_id: TEST_DEFAULT_MODEL.to_string(),
                ..Default::default()
            },
        )
        .await
        .expect("child agent created");

    // When the child is addressed in wait mode (the bracket runs inline)
    // and then in fire mode (the bracket closes from the spawned task)
    let mut events = server.subscribe_events().await.unwrap();
    server
        .call_method(
            "message.send",
            json!({ "session_id": &session_id, "agent_id": &child_id, "text": "wait please" }),
        )
        .await
        .unwrap();
    server
        .call_method(
            "message.send",
            json!({
                "session_id": &session_id,
                "agent_id": &child_id,
                "text": "fire please",
                "mode": "fire",
            }),
        )
        .await
        .unwrap();

    // Then every turn bracket frame names the child, in both modes —
    // two started + two ended, each with the child's `agent-<uuid>`.
    let mut started_count = 0;
    let mut ended_count = 0;
    let deadline = tokio::time::Instant::now() + Duration::from_secs(10);
    while (started_count < 2 || ended_count < 2) && tokio::time::Instant::now() < deadline {
        let notification = match tokio::time::timeout_at(deadline, events.recv()).await {
            Ok(Some(notification)) => notification,
            _ => break,
        };
        match notification.method.as_str() {
            "event.turn.started" => {
                assert_eq!(
                    notification.params["agentId"], child_id,
                    "the wait- and fire-arm TurnStarted must attribute to the addressed child"
                );
                started_count += 1;
            }
            "event.turn.ended" => {
                assert_eq!(
                    notification.params["agentId"], child_id,
                    "the wait- and fire-arm TurnCompleted must attribute to the addressed child"
                );
                ended_count += 1;
            }
            _ => {}
        }
    }
    assert_eq!(
        started_count, 2,
        "both the wait and fire arm must announce a child-attributed turn.started"
    );
    assert_eq!(
        ended_count, 2,
        "both the wait and fire arm must close with a child-attributed turn.ended"
    );
}

#[tokio::test]
async fn should_return_turn_id_immediately_when_fire_message_sent_with_mock_llm() {
    // Given a server with a scripted mock LLM and a created session
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("fire and forget");
    let (server, _tmp) = test_server(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))));
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    // When a message is sent in fire mode with a subscriber attached
    let mut events = server.subscribe_events().await.unwrap();
    let result = server
        .call_method(
            "message.send",
            json!({ "session_id": session_id, "text": "hi", "mode": "fire" }),
        )
        .await
        .unwrap();

    // Then the response returns immediately with the turn id — the full
    // snake envelope, and nothing else (no wait-mode `turn` leaks in)
    let mut envelope_keys: Vec<&str> = result
        .as_object()
        .expect("fire result is an object")
        .keys()
        .map(String::as_str)
        .collect();
    envelope_keys.sort_unstable();
    assert_eq!(
        envelope_keys,
        vec!["agent_id", "ok", "session_id", "turn_id"],
        "fire envelope key set must stay exactly ok/session_id/agent_id/turn_id"
    );
    assert_eq!(result["ok"], true);
    assert_eq!(result["session_id"], session_id);
    let turn_id = result["turn_id"]
        .as_str()
        .expect("fire mode returns turn_id");
    assert!(turn_id.starts_with("turn-"));

    // And the assistant chunks stream to the subscriber afterwards
    let mut chunk_text = String::new();
    while chunk_text.len() < "fire and forget".len() {
        let notification = tokio::time::timeout(Duration::from_secs(5), events.recv())
            .await
            .expect("chunk must arrive within 5s")
            .expect("event channel stays open");
        if notification.method == "event.assistant.delta" {
            chunk_text.push_str(notification.params["delta"].as_str().unwrap());
        }
    }
    assert_eq!(chunk_text, "fire and forget");
    assert_eq!(mock.chat_call_count(), 1);
}

