/// Given a session with a live-event callback wired to its bus, when a
/// tool-call part fragment arrives without a call id (a fragment preceding
/// its identity header — only possible in malformed provider streams), then
/// nothing reaches the subscriber: the wire `event.tool.call.delta` requires
/// a `toolCallId`, and the relay drops identity-less fragments rather than
/// forwarding an unusable event (the documented divergence from the TS
/// buffer-until-header approach, which does not translate because the rust
/// block-level ToolCall only flushes at stream end).
#[tokio::test]
async fn should_not_relay_a_tool_call_part_that_carries_no_call_id() {
    // Given a server with a created session and an event subscriber
    let (server, _tmp) = test_server(None);
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    let mut events = server.subscribe_events().await.unwrap();
    let artifacts = server
        .session_manager()
        .session_artifacts(&SessionId::new(&session_id))
        .expect("created session has artifacts");

    // When the live chunk callback carries an identity-less tool-call part
    let callback =
        super::event_relay::live_chunk_callback(&artifacts.event_bus, "agent-1", &session_id, None);
    callback(mirri_core::LiveEvent::ToolCallPart {
        index: 0,
        arguments_part: "{\"q\":".to_string(),
        call_id: None,
        tool_name: None,
    });

    // Then no notification arrives — the fragment is dropped, not projected
    let received = tokio::time::timeout(Duration::from_millis(200), events.recv()).await;
    assert!(
        received.is_err(),
        "identity-less tool-call parts must not surface on the event bus"
    );
}

