#[tokio::test]
async fn should_relay_the_background_task_lifecycle_with_a_durable_envelope_when_a_task_runs() {
    // Given a server with a created session (session.create wires the task
    // manager onto the session's bus), an event subscriber, and the
    // session's task manager
    let (server, _tmp) = test_server(None);
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    let mut events = server.subscribe_events().await.unwrap();
    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .expect("created session is live");
    let tasks = session.tasks();

    // When a background task is registered and completes
    let task_id = tasks.register(
        TaskKind::Process {
            command: Some("cargo test".to_string()),
            dispatcher: None,
        },
        "test run".to_string(),
        session_id.clone(),
    );
    tasks.complete(&task_id, 0);

    // Then the subscriber observes event.background.task.started followed
    // by event.background.task.terminated, both durable (seq/epoch stamped)
    // with the envelope session id, the info snapshot nested verbatim, and
    // the exit code only on the terminated frame
    let mut saw_started = false;
    for _ in 0..100 {
        let notification = tokio::time::timeout(Duration::from_secs(5), events.recv())
            .await
            .expect("background task event must arrive within 5s")
            .expect("event channel stays open");
        match notification.method.as_str() {
            "event.background.task.started" => {
                assert_eq!(notification.params["sessionId"], session_id);
                assert_eq!(notification.params["volatile"], false);
                assert!(
                    notification.params.get("seq").is_some()
                        && notification.params.get("epoch").is_some(),
                    "durable background task events carry seq/epoch"
                );
                assert_eq!(notification.params["info"]["taskId"], task_id);
                assert_eq!(notification.params["info"]["kind"], "process");
                assert_eq!(notification.params["info"]["command"], "cargo test");
                assert_eq!(notification.params["info"]["status"], "running");
                assert!(
                    notification.params["info"].get("exitCode").is_none(),
                    "the started spelling carries no exit code"
                );
                saw_started = true;
            }
            "event.background.task.terminated" => {
                assert!(
                    saw_started,
                    "event.background.task.terminated must be preceded by started"
                );
                assert_eq!(notification.params["sessionId"], session_id);
                assert_eq!(notification.params["info"]["taskId"], task_id);
                assert_eq!(notification.params["info"]["status"], "completed");
                assert_eq!(notification.params["info"]["exitCode"], 0);
                assert!(
                    notification.params["info"].get("endedAt").is_some(),
                    "the terminated spelling stamps endedAt"
                );
                return; // both events observed in order
            }
            _ => {}
        }
    }
    panic!("event.background.task.started/terminated never both observed");
}

#[tokio::test]
async fn should_stamp_durable_events_with_monotonic_seq_and_constant_epoch_when_relaying() {
    // Given a server with a created session and an event subscriber
    let (server, _tmp) = test_server(None);
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    let mut events = server.subscribe_events().await.unwrap();
    let artifacts = server
        .session_manager()
        .session_artifacts(&SessionId::new(&session_id))
        .expect("created session has artifacts");

    // When the session's bus carries an interleaving of durable, volatile,
    // and Unknown events
    artifacts.event_bus.publish(SessionEvent::TurnStarted {
        agent_id: "main".to_string(),
        session_id: session_id.clone(),
        turn_id: "turn-1".to_string(),
    });
    artifacts
        .event_bus
        .publish(SessionEvent::AgentMessageChunk {
            agent_id: "main".to_string(),
            text: "delta".to_string(),
        });
    artifacts.event_bus.publish(SessionEvent::Unknown);
    artifacts.event_bus.publish(SessionEvent::TurnCompleted {
        agent_id: "main".to_string(),
        session_id,
        turn_id: "turn-1".to_string(),
        stop_reason: "completed".to_string(),
        wire_turn_id: 1,
        duration_ms: None,
    });

    // Then the relay forwards the turn bracket and the volatile delta in
    // bus order, with the Unknown event dropped: the notification after the
    // delta is the turn ending itself
    let mut received: Vec<JsonRpcNotification> = Vec::new();
    let deadline = tokio::time::Instant::now() + Duration::from_secs(5);
    while let Ok(Some(notification)) = tokio::time::timeout_at(deadline, events.recv()).await {
        let ended = notification.method == "event.turn.ended";
        received.push(notification);
        if ended {
            break;
        }
    }
    let delta_index = received
        .iter()
        .position(|notification| notification.method == "event.assistant.delta")
        .expect("the relay forwards the volatile delta");
    assert_eq!(
        received[delta_index + 1].method,
        "event.turn.ended",
        "the Unknown event between the delta and the ending is not forwarded"
    );

    // And the volatile delta carries no seq/epoch
    let delta_params = &received[delta_index].params;
    assert!(
        delta_params.get("seq").is_none() && delta_params.get("epoch").is_none(),
        "volatile events must not carry a seq or an epoch: {delta_params}"
    );

    // And the durable events carry strictly increasing seqs under one
    // constant, non-empty epoch (the server instance's)
    let mut last_seq: u64 = 0;
    let mut epochs: Vec<String> = Vec::new();
    for notification in &received {
        let Some(seq) = notification.params.get("seq").and_then(Value::as_u64) else {
            continue;
        };
        assert!(
            seq > last_seq,
            "durable seqs must be monotonically increasing per session, got {seq} after {last_seq}"
        );
        last_seq = seq;
        epochs.push(
            notification.params["epoch"]
                .as_str()
                .expect("durable events carry an epoch")
                .to_string(),
        );
    }
    assert!(
        last_seq > 0,
        "at least one durable event must have been forwarded"
    );
    assert!(
        epochs
            .iter()
            .all(|epoch| epoch == &epochs[0] && !epoch.is_empty()),
        "every durable event carries the same non-empty epoch: {epochs:?}"
    );
}

/// Given a subscriber attached before a closed session is resumed, when
/// `session.resume` is dispatched, then the subscriber receives the
/// `event.session.updated` resumed announcement — the publish must land
/// after the relay is installed, not on the fresh bus inside the resume
/// itself (where zero subscribers can ever observe it).
#[tokio::test]
async fn should_deliver_the_session_updated_resumed_event_when_session_resume_is_dispatched() {
    // Given a server with a created session that is then closed
    let (server, _tmp) = test_server(None);
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    converse_once(&server, &session_id).await;
    server
        .call_method("session.close", json!({ "session_id": &session_id }))
        .await
        .unwrap();

    // When the resumed session's events are subscribed before the resume
    // fires (the client that asked for the resume)
    let mut events = server.subscribe_events().await.unwrap();
    server
        .call_method("session.resume", json!({ "session_id": &session_id }))
        .await
        .unwrap();

    // Then the resumed announcement reaches the subscriber
    let deadline = tokio::time::Instant::now() + Duration::from_secs(5);
    loop {
        let notification = tokio::time::timeout_at(deadline, events.recv())
            .await
            .expect("the resumed announcement must arrive within 5s")
            .expect("event channel stays open");
        if notification.method == "event.session.updated" {
            assert_eq!(notification.params["change"], "resumed");
            return;
        }
    }
}

/// Given a session whose relay already stamped durable events, when the
/// session is closed and resumed in the same process, then the new relay's
/// durable seq continues from the old relay's watermark — the stream stays
/// monotonic with the same epoch instead of silently restarting at 1
/// (indistinguishable from a gap).
#[tokio::test]
async fn should_continue_the_durable_seq_across_a_same_process_resume() {
    // Given a server with a created session and a subscriber
    let (server, _tmp) = test_server(None);
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    converse_once(&server, &session_id).await;
    let mut events = server.subscribe_events().await.unwrap();

    // And the session's bus carries one durable event (the relay stamps seq 2
    // — the auto-title's `session.meta.updated` already consumed seq 1, and
    // the failed conversation's `message.received` is no longer published on
    // the no-provider path (session-consistency batch 2 F1 deferred it past
    // the commit fence, which no-provider sends never reach) — the prior
    // events may still be in flight on this current-thread runtime, so drain
    // until the marker turn)
    let artifacts = server
        .session_manager()
        .session_artifacts(&SessionId::new(&session_id))
        .expect("created session has artifacts");
    let epoch = {
        artifacts.event_bus.publish(SessionEvent::TurnStarted {
            agent_id: "main".to_string(),
            session_id: session_id.clone(),
            turn_id: "turn-1".to_string(),
        });
        let notification = loop {
            let notification = tokio::time::timeout(Duration::from_secs(5), events.recv())
                .await
                .expect("the first durable event must arrive")
                .expect("event channel stays open");
            if notification.method == "event.turn.started" {
                break notification;
            }
        };
        assert_eq!(notification.params["seq"], json!(2));
        notification.params["epoch"].as_str().unwrap().to_string()
    };

    // When the session is closed and resumed in the same process, and the
    // resumed session's bus carries another durable event
    server
        .call_method("session.close", json!({ "session_id": &session_id }))
        .await
        .unwrap();
    server
        .call_method("session.resume", json!({ "session_id": &session_id }))
        .await
        .unwrap();
    let artifacts = server
        .session_manager()
        .session_artifacts(&SessionId::new(&session_id))
        .expect("resumed session has fresh artifacts");
    artifacts.event_bus.publish(SessionEvent::TurnStarted {
        agent_id: "main".to_string(),
        session_id: session_id.clone(),
        turn_id: "turn-2".to_string(),
    });

    // Then the new relay stamps the durable event with a seq continuing
    // the old relay's watermark (never restarting at 1) under the same
    // epoch — the same-process stream is monotonic end to end
    let deadline = tokio::time::Instant::now() + Duration::from_secs(5);
    loop {
        let notification = tokio::time::timeout_at(deadline, events.recv())
            .await
            .expect("the post-resume durable event must arrive")
            .expect("event channel stays open");
        if notification.method == "event.turn.started"
            && notification.params["turnId"] == json!("turn-2")
        {
            let seq = notification.params["seq"].as_u64().expect("durable seq");
            // Every durable event occupies exactly one seq slot, with no
            // overlap between the old and the new relay: session.meta.updated
            // (auto-title) = 1, turn-1 = 2, work_changed (the turn-1 fold
            // transition) = 3, session.closed = 4, session.updated resumed =
            // 5, turn-2 = 6. (The failed conversation's `message.received`
            // no longer takes a slot — batch 2 F1 deferred its publish past
            // the commit fence, which the no-provider path never reaches.)
            assert_eq!(
                seq, 6,
                "the resumed relay must continue the seq watermark with no gap or overlap"
            );
            assert_eq!(
                notification.params["epoch"].as_str().unwrap(),
                epoch,
                "a same-process resume keeps the epoch"
            );
            return;
        }
    }
}

/// Given a turn driven through `message.send`, when its step events arrive,
/// then every `turn.step.*` carries the same wire turn id (`turn-<uuid>`)
/// the `turn.started` bracket announced — the turn-step family routes by
/// the same key the turn boundary events use, not the engine's internal
/// numeric counter.
#[tokio::test]
async fn should_align_turn_step_turn_ids_with_the_turn_started_wire_id_when_a_turn_runs() {
    // Given a server whose scripted LLM ends the turn with one text step
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("Done");
    let (server, _tmp) = test_server(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))));
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    let mut rx = server.subscribe_events().await.unwrap();

    // When a message is sent (fire mode)
    server
        .call_method(
            "message.send",
            json!({ "sessionId": &session_id, "text": "hello", "mode": "fire" }),
        )
        .await
        .unwrap();

    // Then every turn.step.started / turn.step.completed carries exactly
    // the turn.started turn id (a `turn-<uuid>` string)
    let mut started_turn_id: Option<String> = None;
    let mut checked_steps = 0;
    let deadline = tokio::time::Instant::now() + Duration::from_secs(5);
    while checked_steps < 2 {
        let notif = tokio::time::timeout_at(deadline, rx.recv())
            .await
            .expect("turn events must arrive")
            .expect("event channel stays open");
        match notif.method.as_str() {
            "event.turn.started" => {
                started_turn_id = Some(
                    notif.params["turnId"]
                        .as_str()
                        .expect("turn.started carries a turnId string")
                        .to_string(),
                );
                assert!(
                    started_turn_id
                        .as_deref()
                        .unwrap_or("")
                        .starts_with("turn-"),
                    "the wire turn id follows the turn-<uuid> convention: {}",
                    notif.params
                );
            }
            "event.turn.step.started" | "event.turn.step.completed" => {
                let step_turn_id = notif.params["turnId"].as_str().unwrap_or_default();
                assert_eq!(
                    Some(step_turn_id.to_string()),
                    started_turn_id,
                    "the step event must carry the turn.started wire turn id: {}",
                    notif.params
                );
                checked_steps += 1;
            }
            _ => {}
        }
    }
    assert!(checked_steps == 2, "both step events must have arrived");
}

/// Given a tool call driven through `message.send`, when its stream events
/// arrive, then `event.tool.call.started` carries the full argument object
/// under `args` and `event.tool.result` carries the tool's `name` — the
