/// Given a goal-mode session with an in-flight fire turn, when
/// `goal.pause` is called, then the goal flips to paused AND the
/// in-flight turn is cancelled (settles with the aborted reason) —
/// pausing must stop the machine, not just flip a state bit.
#[tokio::test]
async fn should_cancel_the_in_flight_turn_when_goal_pause_is_called() {
    let (server, _tmp) = test_server(Some(Arc::new(CancelAwareBlockingLlmFactory)));
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    let mut events = server.subscribe_events().await.unwrap();

    let fired = server
        .call_method(
            "message.send",
            json!({ "session_id": &session_id, "text": "work on the goal", "mode": "fire" }),
        )
        .await
        .unwrap();
    let turn_id = fired["turn_id"].as_str().unwrap().to_string();
    let _ = next_event_where(&mut events, |n| n.method == "event.turn.started", |_| {}).await;

    // A goal exists (created through the session's goal manager so the
    // pause handler sees one).
    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .unwrap();
    session
        .goal()
        .create("Do the thing".to_string(), None)
        .unwrap();

    let paused = server
        .call_method("goal.pause", json!({ "session_id": &session_id }))
        .await
        .unwrap();
    assert_eq!(paused["status"], "paused");

    let ended = next_event_where(&mut events, |n| n.method == "event.turn.ended", |_| {}).await;
    assert_eq!(ended.params["turnId"], json!(turn_id));
    // WAIT-fire contract: the cancelled fire turn settles as failed via
    // the aborting side's TurnFailed (reason "failed",
    // abort.user_cancelled).
    assert_eq!(ended.params["reason"], "failed");
    assert_eq!(ended.params["error"]["code"], "abort.user_cancelled");
    // The cancel cause names the goal RPC (the kernel's
    // `format!("turn aborted by {cause}")` with the pause cause) — the
    // web can tell a goal-driven freeze from a plain message.abort.
    assert!(
        ended.params["error"]["message"]
            .as_str()
            .expect("error message")
            .contains("via goal.pause"),
        "the turn.ended error must name goal.pause: {}",
        ended.params["error"]["message"]
    );
}

/// Given an active goal and an in-flight fire turn, when `message.abort`
/// cancels it, then the goal parks as paused with the interruption
/// reason — the user's stop must freeze the loop, not just the turn
/// (TS `pauseOnInterrupt` parity).
#[tokio::test]
async fn should_pause_the_goal_when_message_abort_cancels_the_in_flight_turn() {
    let (server, _tmp) = test_server(Some(Arc::new(CancelAwareBlockingLlmFactory)));
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    let mut events = server.subscribe_events().await.unwrap();

    let fired = server
        .call_method(
            "message.send",
            json!({ "session_id": &session_id, "text": "work on the goal", "mode": "fire" }),
        )
        .await
        .unwrap();
    let turn_id = fired["turn_id"].as_str().unwrap().to_string();
    let _ = next_event_where(&mut events, |n| n.method == "event.turn.started", |_| {}).await;

    // A goal exists (created through the session's goal manager so the
    // abort kernel sees one) and is active when the user stops the turn.
    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .unwrap();
    session
        .goal()
        .create("Do the thing".to_string(), None)
        .unwrap();
    assert_eq!(
        session.goal().get().unwrap().status,
        mirri_core::GoalStatus::Active
    );

    // When the user aborts the in-flight turn (session level).
    let aborted = server
        .call_method("message.abort", json!({ "session_id": &session_id }))
        .await
        .unwrap();
    assert_eq!(aborted["ok"], true);

    // Then the fire turn settles via the aborting side's TurnFailed
    // (reason "failed", abort.user_cancelled, naming message.abort),
    // capturing any goal.updated that lands ahead of the ending on the
    // wire (either arrival order is accepted).
    let mut goal_updated: Option<mirri_transport::frame::JsonRpcNotification> = None;
    let ended = next_event_where(
        &mut events,
        |n| n.method == "event.turn.ended",
        |n| {
            if n.method == "event.goal.updated" {
                goal_updated = Some(n.clone());
            }
        },
    )
    .await;
    assert_eq!(ended.params["turnId"], json!(turn_id));
    assert_eq!(ended.params["reason"], "failed");
    assert_eq!(ended.params["error"]["code"], "abort.user_cancelled");
    assert!(
        ended.params["error"]["message"]
            .as_str()
            .expect("error message")
            .contains("via message.abort"),
        "the turn.ended error must name message.abort: {}",
        ended.params["error"]["message"]
    );

    // And the goal parks as paused with the interruption reason.
    let goal_updated = match goal_updated {
        Some(event) => event,
        None => next_event_where(&mut events, |n| n.method == "event.goal.updated", |_| {}).await,
    };
    assert_eq!(goal_updated.params["snapshot"]["status"], "paused");
    assert_eq!(goal_updated.params["change"]["kind"], "lifecycle");
    assert_eq!(
        goal_updated.params["change"]["reason"],
        "Paused after interruption"
    );
    let goal = session.goal().get().expect("the goal survives the pause");
    assert_eq!(goal.status, mirri_core::GoalStatus::Paused);
    assert_eq!(
        goal.terminal_reason,
        Some("Paused after interruption".to_string())
    );
}

/// Given an active goal and a turn that fails at the LLM layer,
/// when the engine settles the failed turn, then the goal is paused
/// with a "Paused after turn failure: ..." reason and the wire log
/// records the goal.update — pre-fix the goal stayed dangling Active.
///
/// (The failure is scripted via `push_error`, not the config-level
/// `FailingLlmFactory`: that factory fails `create_llm`, which the
/// dispatch-time `resolve_turn_llm` pre-check rejects before a turn ever
/// runs — the Err arm under test is the engine turn itself failing.)
#[tokio::test]
async fn should_pause_the_goal_when_a_turn_fails_at_the_llm_layer() {
    // Given a server whose scripted model fails the first chat outright,
    // a session with an active goal, and an event subscription.
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_error("provider exploded");
    let (server, _tmp) = test_server(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))));
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    let mut events = server.subscribe_events().await.unwrap();

    // The goal is created directly on the session's goal manager so the
    // settlement sees it (the turn never runs, so no agent-side tool
    // call could create one).
    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .unwrap();
    session.goal().create("ship it".to_string(), None).unwrap();
    assert_eq!(
        session.goal().get().unwrap().status,
        mirri_core::GoalStatus::Active
    );

    // When the wait-mode turn fails at the LLM layer, the send surfaces
    // the provider error.
    let error = server
        .call_method(
            "message.send",
            json!({ "session_id": &session_id, "text": "work on the goal" }),
        )
        .await
        .unwrap_err();
    assert!(
        error.to_string().contains("provider exploded"),
        "the send must surface the provider error: {error:?}"
    );

    // Then the goal parks as paused with the failure reason and the
    // runtime actor's goal.update lands in the wire log (pre-fix the
    // goal stayed dangling Active).
    let goal_updated = next_event_where_within(
        &mut events,
        |n| n.method == "event.goal.updated",
        Duration::from_secs(10),
    )
    .await;
    assert_eq!(goal_updated.params["snapshot"]["status"], "paused");
    assert_eq!(goal_updated.params["change"]["actor"], "runtime");
    let reason = goal_updated.params["change"]["reason"]
        .as_str()
        .expect("reason");
    assert!(
        reason.starts_with("Paused after turn failure"),
        "the reason must carry the turn-failure prefix: {reason}"
    );

    // The raw provider text rides the reason (the wait arm surfaces the
    // engine error's own message, which for a provider error is the raw
    // provider text — not `EngineTurnError::message()`'s class-prefixed
    // rendering used by the Err-response arm).
    assert!(
        reason.contains("provider exploded"),
        "the reason must carry the provider text: {reason}"
    );

    let goal = session.goal().get().expect("the goal survives the pause");
    assert_eq!(goal.status, mirri_core::GoalStatus::Paused);
    assert!(
        goal.terminal_reason
            .as_deref()
            .is_some_and(|reason| reason.starts_with("Paused after turn failure")),
        "the terminal reason must carry the turn-failure prefix: {:?}",
        goal.terminal_reason
    );

    let ops = read_wire_ops(&server, &session_id).await;
    let runtime_goal_updates = ops
        .iter()
        .filter(|op| {
            matches!(
                op,
                WireOp::GoalUpdate {
                    status: Some(status),
                    actor: Some(actor),
                    ..
                } if status == "paused" && actor == "runtime"
            )
        })
        .count();
    assert_eq!(
        runtime_goal_updates, 1,
        "exactly one runtime goal.update (paused) must land: {ops:?}"
    );
}

/// Given a goal already paused by message.abort's cancel kernel,
/// when the aborted wait turn's own settlement runs, then no second
/// goal.update lands — the Active guard dedupes against the cancel
/// kernel's pause.
#[tokio::test]
async fn should_not_double_settle_the_goal_when_abort_already_paused_it() {
    // Given a server with a cancel-aware blocking model, a session with
    // an active goal, and an event subscription.
    let (server, _tmp) = test_server(Some(Arc::new(CancelAwareBlockingLlmFactory)));
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    let mut events = server.subscribe_events().await.unwrap();

    // When the user aborts the in-flight turn, the cancel kernel
    // parks the active goal as paused and the turn settles. Fire mode
    // (like the abort-parity template above): the send returns before
    // the turn ends, so the turn id is in hand before the events flow.
    let fired = server
        .call_method(
            "message.send",
            json!({
                "session_id": &session_id,
                "text": "work on the goal",
                "mode": "fire"
            }),
        )
        .await
        .unwrap();
    let turn_id = fired["turn_id"].as_str().unwrap().to_string();
    let _ = next_event_where(&mut events, |n| n.method == "event.turn.started", |_| {}).await;

    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .unwrap();
    session
        .goal()
        .create("Do the thing".to_string(), None)
        .unwrap();
    assert_eq!(
        session.goal().get().unwrap().status,
        mirri_core::GoalStatus::Active
    );

    // When the user aborts the in-flight wait turn, the cancel kernel
    // parks the active goal as paused and the turn settles.
    let aborted = server
        .call_method("message.abort", json!({ "session_id": &session_id }))
        .await
        .unwrap();
    assert_eq!(aborted["ok"], true);
    let ended = next_event_where(
        &mut events,
        |n| n.method == "event.turn.ended" && n.params["turnId"] == json!(turn_id.clone()),
        |_| {},
    )
    .await;
    assert!(ended.params["reason"] != "completed");

    // Then the goal is paused exactly once — the wire log carries exactly
    // ONE status-changing goal.update (the cancel kernel's, actor "user"),
    // never a second from the turn's own Aborted settlement. Usage
    // accounting ops (turns/tokens-only, status None) are expected to
    // keep landing — they never change the goal's status.
    let goal = session.goal().get().expect("the goal survives the pause");
    assert_eq!(goal.status, mirri_core::GoalStatus::Paused);

    let ops = read_wire_ops(&server, &session_id).await;
    let status_updates = ops
        .iter()
        .filter(|op| {
            matches!(
                op,
                WireOp::GoalUpdate {
                    status: Some(_),
                    ..
                }
            )
        })
        .collect::<Vec<_>>();
    assert_eq!(
        status_updates.len(),
        1,
        "exactly one status-changing goal.update (the cancel kernel's) must land: {ops:?}"
    );
    match status_updates[0] {
        WireOp::GoalUpdate { status, actor, .. } => {
            assert_eq!(status.as_deref(), Some("paused"));
            assert_eq!(actor.as_deref(), Some("user"));
        }
        other => panic!("expected goal.update, got {other:?}"),
    }
}

/// Given a stalled turn (short stall timeout injected via
/// `with_turn_stall_timeout`) under an active goal, when the watchdog
/// cancels it, then the goal is paused with "Paused after stalled turn".
#[tokio::test]
async fn should_pause_the_goal_when_a_turn_stalls() {
    // Given a server with a short stall window over a silent
    // (cancel-aware blocking) model, a session with an active goal, and
    // an event subscription.
    let (server, _tmp) = test_server(Some(Arc::new(CancelAwareBlockingLlmFactory)));
    // ADR-006: a silent model is the "model never answers" shape — the
    // InStep registration routes it to the Degraded tier and the LONG
    // backstop window (model death is the HTTP read-idle timeout's job;
    // the fake LLM has no HTTP layer, so the backstop is the only
    // terminator). Shorten BOTH windows so the test still settles fast.
    let server = server
        .with_turn_stall_timeout(std::time::Duration::from_millis(400))
        .with_turn_backstop_timeout(std::time::Duration::from_millis(400));
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    let mut events = server.subscribe_events().await.unwrap();

    // When a fire-mode turn runs against the silent model, the watchdog
    // cancels it at the stall window.
    server
        .call_method(
            "message.send",
            json!({
                "session_id": &session_id,
                "text": "work on the goal",
                "mode": "fire"
            }),
        )
        .await
        .unwrap();
    let _ = next_event_where(&mut events, |n| n.method == "event.turn.started", |_| {}).await;

    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .unwrap();
    session
        .goal()
        .create("Do the thing".to_string(), None)
        .unwrap();
    assert_eq!(
        session.goal().get().unwrap().status,
        mirri_core::GoalStatus::Active
    );

    // Then the stalled turn's settlement pauses the goal — the goal must
    // not stay dangling Active. Fix F landed (fire arm coerces the
    // watchdog's stall cancel into a Stalled stop reason), so the reason
    // is the stalled one.
    let goal_updated = next_event_where_within(
        &mut events,
        |n| n.method == "event.goal.updated",
        Duration::from_secs(10),
    )
    .await;
    assert_eq!(goal_updated.params["snapshot"]["status"], "paused");
    assert_eq!(goal_updated.params["change"]["actor"], "runtime");
    assert_eq!(
        goal_updated.params["change"]["reason"],
        "Paused after stalled turn"
    );

    let goal = session.goal().get().expect("the goal survives the pause");
    assert_eq!(goal.status, mirri_core::GoalStatus::Paused);
    assert!(
        goal.terminal_reason
            .as_deref()
            .is_some_and(|reason| reason.starts_with("Paused after")),
        "the goal must land paused with a pause reason: {:?}",
        goal.terminal_reason
    );
}

/// Given an active goal whose turn budget is exhausted,
/// when a turn settles, then the goal is blocked with
/// "Blocked after goal budget reached" and no continuation is launched.
#[tokio::test]
async fn should_block_the_goal_when_the_budget_is_exhausted_after_a_turn() {
    // Given a scripted model, a created session, and an event subscription.
    // The session is titled so the side title call never competes for the
    // scripted replies (each scripted step reports usage through the goal's
    // accounting-only flow wiring).
    let mock = Arc::new(ScriptedLlm::new());
    let (server, _tmp) = test_server(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))));
    let created = server
        .call_method("session.create", json!({ "title": "budget exhaust" }))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    // And a goal with a one-turn budget (created through the session's goal
    // manager so the settlement sees it; the budget through the manager too,
    // mirroring run_main_agent_tool's SetGoalBudget effect).
    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .unwrap();
    session
        .goal()
        .create("ship the budget-guard slice".to_string(), None)
        .unwrap();
    session.goal().set_budget(mirri_core::GoalBudget {
        turns: Some(1),
        tokens: None,
        wall_clock_ms: None,
    });

    // When one normal turn runs and consumes the whole budget (the model
    // ends the turn with plain text — no UpdateGoal, so the goal stays
    // Active and the budget check is the only settlement the turn owes).
    mock.push_text("one budgeted turn");
    server
        .call_method(
            "message.send",
            json!({ "session_id": &session_id, "text": "go", "mode": "wait" }),
        )
        .await
        .unwrap();

    // Then the goal is blocked: the turn-level budget enforcement blocks
    // it mid-turn ("hard budget reached", the turn_flow step-level guard),
    // and — the layer under test — the settle point's continuation gating
    // sees a non-active goal and launches nothing. The wire-reason layering
    // (the settle-path `block_goal_on_budget` fallback with the TS-parity
    // "Blocked after goal budget reached" wording) covers the paths the
    // step-level guard cannot see; here the observable requirement is the
    // blocked status plus the absence of any continuation.
    let goal = session.goal().get().expect("the goal survives the block");
    assert_eq!(goal.status, mirri_core::GoalStatus::Blocked);
    assert!(
        goal.terminal_reason
            .as_deref()
            .is_some_and(|reason| reason.contains("budget")),
        "the goal must land blocked with a budget reason: {:?}",
        goal.terminal_reason
    );

    // And the runtime's blocked goal.update landed in the wire log, and no
    // continuation turn was launched: the settle point's chain gating sees
    // a non-active goal and exits — the strongest observable is that no
    // turn.prompt follows the budgeted turn's turn.ended after the settle
    // drains.
    let ops = read_wire_ops(&server, &session_id).await;
    let runtime_blocked = ops
        .iter()
        .filter(|op| {
            matches!(
                op,
                WireOp::GoalUpdate {
                    status: Some(status),
                    actor: Some(actor),
                    ..
                } if status == "blocked" && actor == "runtime"
            )
        })
        .count();
    assert_eq!(
        runtime_blocked, 1,
        "exactly one runtime budget-block goal.update must land: {ops:?}"
    );
    let turn_prompts = ops
        .iter()
        .filter(|op| matches!(op, WireOp::TurnPrompt { .. }))
        .count();
    assert_eq!(
        turn_prompts, 1,
        "no continuation turn.prompt may follow the budgeted turn: {ops:?}"
    );
}

/// Whether a `turn.prompt` op carries the goal-continuation origin.
fn is_goal_continuation_prompt(op: &WireOp) -> bool {
    matches!(
        op,
        WireOp::TurnPrompt { origin, .. }
            if origin["kind"] == "system_trigger" && origin["name"] == "goal_continuation"
    )
}

/// Poll the wire log until it contains at least `expected` `turn.prompt`
/// ops (each continuation turn opens one) or the deadline passes — the
/// settle-drain window the chain tests assert within. Returns the last
/// read ops (callers re-derive whatever they were waiting for).
async fn wait_for_turn_prompts(
    server: &EmbeddedServer,
    session_id: &str,
    expected: usize,
) -> Vec<WireOp> {
    let deadline = std::time::Instant::now() + Duration::from_secs(10);
    loop {
        let ops = read_wire_ops_opt(server, session_id)
            .await
            .unwrap_or_default();
        let turn_prompts = ops
            .iter()
            .filter(|op| matches!(op, WireOp::TurnPrompt { .. }))
            .count();
        if turn_prompts >= expected || std::time::Instant::now() >= deadline {
            return ops;
        }
        tokio::time::sleep(Duration::from_millis(20)).await;
    }
}

/// Given an active goal and a turn that completes without UpdateGoal,
/// when the turn settles, then a continuation turn is launched with the
/// goal_continuation origin and the TS-parity prompt, and the chain
/// stops once UpdateGoal complete lands.
#[tokio::test(flavor = "multi_thread")]
async fn should_launch_a_goal_continuation_turn_when_a_turn_completes_with_an_active_goal() {
    // Given a scripted model (turn 1: plain text, no tools; the
    // continuation turn 2: UpdateGoal complete), a titled session with an
    // active goal, and an event subscription.
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("working on it");
    mock.push_tool_use(vec![LlmToolCall {
        id: "call-update-goal-1".to_string(),
        name: "UpdateGoal".to_string(),
        args: json!({ "status": "complete" }),
    }]);
    mock.push_text("(unused third turn)");
    let (server, _tmp) = test_server(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))));
    let created = server
        .call_method("session.create", json!({ "title": "goal continuation" }))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .unwrap();
    session
        .goal()
        .create("ship the continuation slice".to_string(), None)
        .unwrap();

    // When the first turn runs and completes without UpdateGoal, the
    // chain task wakes and injects the continuation turn.
    server
        .call_method(
            "message.send",
            json!({ "session_id": &session_id, "text": "go", "mode": "wait" }),
        )
        .await
        .unwrap();

    // Wait for the continuation turn to run and settle with the
    // UpdateGoal complete (goal leaves Active — the chain stops).
    let deadline = std::time::Instant::now() + Duration::from_secs(10);
    loop {
        let goal = session.goal().get().expect("goal survives");
        if goal.status == mirri_core::GoalStatus::Complete || std::time::Instant::now() >= deadline
        {
            break;
        }
        tokio::time::sleep(Duration::from_millis(20)).await;
    }

    // Then the goal completed through the continuation turn's UpdateGoal.
    let goal = session.goal().get().expect("goal survives");
    assert_eq!(
        goal.status,
        mirri_core::GoalStatus::Complete,
        "the continuation turn must complete the goal"
    );

    // And the wire log carries the continuation turn's opening with the
    // goal_continuation origin and the TS-parity prompt text.
    let ops = wait_for_turn_prompts(&server, &session_id, 2).await;
    let continuation_prompts: Vec<_> = ops
        .iter()
        .filter(|op| is_goal_continuation_prompt(op))
        .collect();
    assert_eq!(
        continuation_prompts.len(),
        1,
        "exactly one goal_continuation turn.prompt must land: {ops:?}"
    );
    // The ContextAppendMessage carries the same origin and the prompt
    // body starts with the TS-parity opening.
    let continuation_messages: Vec<_> = ops
        .iter()
        .filter(|op| {
            matches!(
                op,
                WireOp::ContextAppendMessage { message }
                    if message["origin"]["kind"] == "system_trigger"
                        && message["origin"]["name"] == "goal_continuation"
            )
        })
        .collect();
    assert_eq!(
        continuation_messages.len(),
        1,
        "exactly one goal_continuation context.append_message must land: {ops:?}"
    );
    let WireOp::ContextAppendMessage { message } = continuation_messages[0] else {
        unreachable!()
    };
    let text = message["content"][0]["text"].as_str().expect("prompt text");
    assert!(
        text.starts_with("Continue working toward the active goal"),
        "the continuation prompt must open with the TS-parity text: {text}"
    );

    // And the chain stopped: no third turn.prompt follows after the
    // drain window (the goal left Active with the UpdateGoal complete).
    tokio::time::sleep(Duration::from_millis(300)).await;
    let ops = read_wire_ops(&server, &session_id).await;
    let turn_prompts = ops
        .iter()
        .filter(|op| matches!(op, WireOp::TurnPrompt { .. }))
        .count();
    assert_eq!(
        turn_prompts, 2,
        "no third turn.prompt may follow the completed goal: {ops:?}"
    );
}

/// Given a wire log containing a turn prompted with the goal_continuation
/// origin, when the session is restored by replay, then the reducer
/// accepts it without error: the continuation message replays intact and
/// its origin parses as SystemTrigger (the extra `name` field is silently
/// dropped — `PromptOrigin` carries no deny_unknown_fields).
#[tokio::test(flavor = "multi_thread")]
async fn should_replay_a_session_containing_goal_continuation_turns() {
    // Given a scripted model (turn 1: plain text, no tools; the
    // continuation turn 2: UpdateGoal complete), a titled session with an
    // agent-created active goal (so the wire log carries a well-formed
    // goal.create → goal.update chain for the replay).
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("working on it");
    mock.push_tool_use(vec![LlmToolCall {
        id: "call-update-goal-replay".to_string(),
        name: "UpdateGoal".to_string(),
        args: json!({ "status": "complete" }),
    }]);
    mock.push_text("(unused third turn)");
    let (server, _tmp) = test_server(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))));
    let created = server
        .call_method(
            "session.create",
            json!({ "title": "goal continuation replay" }),
        )
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    let result = run_main_agent_tool(
        &server,
        &session_id,
        "CreateGoal",
        json!({ "objective": "ship the replay slice" }),
    )
    .await;
    assert!(!result.is_error, "{result:?}");

    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .unwrap();

    // When the first turn runs, settles, and the chain injects a real
    // goal_continuation turn whose UpdateGoal completes the goal.
    server
        .call_method(
            "message.send",
            json!({ "session_id": &session_id, "text": "go", "mode": "wait" }),
        )
        .await
        .unwrap();
    let deadline = std::time::Instant::now() + Duration::from_secs(10);
    loop {
        let goal = session.goal().get().expect("goal survives");
        if goal.status == mirri_core::GoalStatus::Complete || std::time::Instant::now() >= deadline
        {
            break;
        }
        tokio::time::sleep(Duration::from_millis(20)).await;
    }
    assert_eq!(
        session.goal().get().expect("goal survives").status,
        mirri_core::GoalStatus::Complete,
        "the continuation turn must complete the goal before the close"
    );

    // Precondition: the persisted wire log really carries the continuation
    // turn's message with the goal_continuation origin JSON (the `name`
    // field the engine-side enum never sees).
    let ops = read_wire_ops(&server, &session_id).await;
    let continuation_messages: Vec<_> = ops
        .iter()
        .filter(|op| {
            matches!(
                op,
                WireOp::ContextAppendMessage { message }
                    if message["origin"]["kind"] == "system_trigger"
                        && message["origin"]["name"] == "goal_continuation"
            )
        })
        .collect();
    assert_eq!(
        continuation_messages.len(),
        1,
        "exactly one goal_continuation context.append_message must be persisted: {ops:?}"
    );

    // When the session is closed and restored by replaying that wire log
    server
        .call_method("session.close", json!({ "session_id": &session_id }))
        .await
        .unwrap();
    server
        .call_method("session.resume", json!({ "session_id": &session_id }))
        .await
        .unwrap();

    // Then the replayed history serves the continuation message intact
    // (role user, the TS-parity prompt body), and its origin parsed as
    // SystemTrigger — serialized back WITHOUT the `name` field (dropped
    // silently by the serde parse, no replay error).
    let history = server
        .call_method("session.getHistory", json!({ "session_id": &session_id }))
        .await
        .unwrap();
    let history = history
        .as_array()
        .expect("session.getHistory returns a bare array")
        .clone();
    let continuation = history
        .iter()
        .find(|m| {
            m["role"] == "user"
                && m["content"][0]["text"]
                    .as_str()
                    .is_some_and(|t| t.starts_with("Continue working toward the active goal"))
        })
        .expect("the goal continuation message must survive the replay");
    assert_eq!(
        continuation["origin"],
        json!({ "kind": "system_trigger" }),
        "the origin must parse as SystemTrigger with the name field dropped: {continuation:?}"
    );

    // And the replayed goal kept its terminal state (the goal.update the
    // continuation turn's UpdateGoal tool recorded).
    let resumed = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .expect("resumed session is live");
    let goal = resumed.goal().get().expect("goal must be restored");
    assert_eq!(goal.status, mirri_core::GoalStatus::Complete);
}

/// Given an active goal and in-flight background tasks,
/// when a turn settles, then no continuation is launched — the task
/// notification turn is the wake-up path.
#[tokio::test(flavor = "multi_thread")]
async fn should_not_launch_a_continuation_when_background_tasks_are_in_flight() {
    // Given a scripted model whose only turn ends in plain text (no tools),
    // a session with an active goal, and a registered background task that
    // stays non-terminal for the whole assertion window (registered on the
    // session's task manager directly — the same seeding the task-driver
    // tests apply; a Bash `run_in_background` would need the approval gate
    // a bare test server does not carry).
    let mock = Arc::new(ScriptedLlm::new());
    for _ in 0..5 {
        mock.push_text("nothing to do while the background work runs");
    }
    let (server, _tmp) = test_server(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))));
    let created = server
        .call_method("session.create", json!({ "title": "goal continuation bg" }))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .unwrap();
    session
        .goal()
        .create("ship the background-gated slice".to_string(), None)
        .unwrap();
    session.tasks().register(
        TaskKind::Process {
            command: None,
            dispatcher: None,
        },
        "long background slice".to_string(),
        session_id.clone(),
    );

    // When the turn runs and ends with the background task still in
    // flight (non-terminal).
    server
        .call_method(
            "message.send",
            json!({ "session_id": &session_id, "text": "go", "mode": "wait" }),
        )
        .await
        .unwrap();

    // Then no continuation turn is launched: the background task stays
    // non-terminal for the whole drain window, so the settle point's
    // chain gating suspends the goal instead of injecting.
    tokio::time::sleep(Duration::from_millis(500)).await;
    assert!(
        session
            .tasks()
            .list()
            .iter()
            .any(|task| !task.status.is_terminal()),
        "the background task must still be in flight for the test to be valid"
    );
    let ops = read_wire_ops(&server, &session_id).await;
    let continuation_prompts = ops
        .iter()
        .filter(|op| is_goal_continuation_prompt(op))
        .count();
    assert_eq!(
        continuation_prompts, 0,
        "no goal_continuation turn.prompt may land while a background task is in flight: {ops:?}"
    );
    // The goal stays Active (suspended, not settled).
    let goal = session.goal().get().expect("goal survives");
    assert_eq!(goal.status, mirri_core::GoalStatus::Active);
}

/// Given three consecutive continuation turns that call no tools and
/// change no goal state, when the third settles, then the goal is paused
/// with "Paused after repeated idle goal turns" and the chain stops.
#[tokio::test(flavor = "multi_thread")]
async fn should_pause_the_goal_after_repeated_idle_continuation_turns() {
    // Given a scripted model that answers every turn with bare text (no
    // tools, no UpdateGoal) — every continuation turn is idle.
    let mock = Arc::new(ScriptedLlm::new());
    for _ in 0..10 {
        mock.push_text("just talking, no tools");
    }
    let (server, _tmp) = test_server(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))));
    let created = server
        .call_method(
            "session.create",
            json!({ "title": "goal continuation idle" }),
        )
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .unwrap();
    session
        .goal()
        .create("ship the idle-guard slice".to_string(), None)
        .unwrap();

    // When the first turn runs, the chain launches and keeps injecting
    // idle continuation turns until the idle-streak guard trips.
    server
        .call_method(
            "message.send",
            json!({ "session_id": &session_id, "text": "go", "mode": "wait" }),
        )
        .await
        .unwrap();

    let deadline = std::time::Instant::now() + Duration::from_secs(10);
    loop {
        let goal = session.goal().get().expect("goal survives");
        if goal.status == mirri_core::GoalStatus::Paused || std::time::Instant::now() >= deadline {
            break;
        }
        tokio::time::sleep(Duration::from_millis(20)).await;
    }

    // Then the goal is paused with the idle-streak reason.
    let goal = session.goal().get().expect("goal survives");
    assert_eq!(
        goal.status,
        mirri_core::GoalStatus::Paused,
        "the idle-streak guard must pause the goal"
    );
    assert_eq!(
        goal.terminal_reason.as_deref(),
        Some("Paused after repeated idle goal turns"),
        "the idle-streak reason must land: {:?}",
        goal.terminal_reason
    );

    // And the chain stopped: the user turn plus exactly three idle
    // continuations ran — no fourth continuation turn.prompt follows.
    tokio::time::sleep(Duration::from_millis(300)).await;
    let ops = read_wire_ops(&server, &session_id).await;
    let continuation_prompts = ops
        .iter()
        .filter(|op| is_goal_continuation_prompt(op))
        .count();
    assert_eq!(
        continuation_prompts, 3,
        "exactly three idle continuation turns, then the guard: {ops:?}"
    );
}

/// Given more continuation turns than the absolute cap allows, when the
/// cap is hit, then the goal is paused with "Paused after continuation
/// limit" and the chain stops.
#[tokio::test(flavor = "multi_thread")]
async fn should_pause_the_goal_when_the_absolute_continuation_limit_is_reached() {
    // Given a scripted model that calls one trivial tool every turn (so
    // every continuation turn is busy — the idle guard never trips) and
    // never touches the goal state.
    let mock = Arc::new(ScriptedLlm::new());
    for i in 0..(super::goal_driver::GOAL_MAX_CONTINUATIONS + 10) {
        mock.push_tool_use(vec![LlmToolCall {
            id: format!("call-trivial-{i}"),
            name: "Bash".to_string(),
            args: json!({ "command": "true", "description": "trivial slice" }),
        }]);
        mock.push_text("one trivial slice done");
    }
    let (server, _tmp) = test_server(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))));
    let created = server
        .call_method(
            "session.create",
            json!({ "title": "goal continuation cap" }),
        )
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .unwrap();
    session
        .goal()
        .create("ship the cap-guard slice".to_string(), None)
        .unwrap();
    // The trivial Bash calls must actually run (a bare test server has no
    // approval mechanism — Yolo mode auto-approves them so every turn is
    // genuinely busy, the shape the idle guard must NOT catch).
    session
        .get_agent(&AgentId::new(DEFAULT_MAIN_AGENT_ID))
        .await
        .expect("main agent exists")
        .permission_manager()
        .set_mode(mirri_core::PermissionMode::Yolo);

    // When the first turn runs, the chain launches and keeps injecting
    // busy continuation turns until the absolute cap trips.
    server
        .call_method(
            "message.send",
            json!({ "session_id": &session_id, "text": "go", "mode": "wait" }),
        )
        .await
        .unwrap();

    let deadline = std::time::Instant::now() + Duration::from_secs(30);
    loop {
        let goal = session.goal().get().expect("goal survives");
        if goal.status == mirri_core::GoalStatus::Paused || std::time::Instant::now() >= deadline {
            break;
        }
        tokio::time::sleep(Duration::from_millis(20)).await;
    }

    // Then the goal is paused with the continuation-limit reason.
    let goal = session.goal().get().expect("goal survives");
    assert_eq!(
        goal.status,
        mirri_core::GoalStatus::Paused,
        "the absolute cap must pause the goal"
    );
    assert_eq!(
        goal.terminal_reason.as_deref(),
        Some("Paused after continuation limit"),
        "the continuation-limit reason must land: {:?}",
        goal.terminal_reason
    );

    // And exactly GOAL_MAX_CONTINUATIONS continuation turns ran — no
    // further turn.prompt follows the cap.
    tokio::time::sleep(Duration::from_millis(300)).await;
    let ops = read_wire_ops(&server, &session_id).await;
    let continuation_prompts = ops
        .iter()
        .filter(|op| is_goal_continuation_prompt(op))
        .count();
    assert_eq!(
        continuation_prompts,
        super::goal_driver::GOAL_MAX_CONTINUATIONS as usize,
        "exactly the cap's worth of continuation turns, then the guard: {ops:?}"
    );
}

/// Given an active goal whose chain bookkeeping already carries an idle
/// streak one turn short of the guard, when a user turn runs and settles,
/// then the counters reset — the chain runs a full fresh streak before the
/// idle guard parks the goal instead of tripping on the inherited one.
#[tokio::test(flavor = "multi_thread")]
async fn should_reset_the_burn_guards_when_a_user_turn_intervenes() {
    // Given a scripted model that answers every turn with idle text, a
    // session with an active goal, and chain bookkeeping carrying a
    // pre-reset streak of GOAL_MAX_IDLE_CONTINUATIONS - 1 (one short of
    // the guard). Seeding the bookkeeping rather than racing a live chain
    // is what makes the intervention deterministic: the chain cannot
    // advance between the seed and the user turn, so the only thing that
    // can clear the streak is the user turn's own reset.
    let mock = Arc::new(ScriptedLlm::new());
    for _ in 0..30 {
        mock.push_text("idle chatter");
    }
    let (server, _tmp) = test_server(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))));
    let created = server
        .call_method(
            "session.create",
            json!({ "title": "goal continuation reset" }),
        )
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .unwrap();
    session
        .goal()
        .create("ship the reset-guard slice".to_string(), None)
        .unwrap();
    {
        let mut states = server
            .goal_chain_states
            .lock()
            .unwrap_or_else(|e| e.into_inner());
        let state = states.entry(session_id.clone()).or_default();
        state.idle_streak = super::goal_driver::GOAL_MAX_IDLE_CONTINUATIONS - 1;
        state.continuations = 2;
    }

    // When a user-originated turn runs and settles
    server
        .call_method(
            "message.send",
            json!({ "session_id": &session_id, "text": "user steer", "mode": "wait" }),
        )
        .await
        .unwrap();

    // Then the counters reset before the chain gate runs: the chain launches
    // a full fresh streak first. Without the reset the inherited streak
    // would trip the guard after ONE continuation; with it the chain runs
    // GOAL_MAX_IDLE_CONTINUATIONS, so passing the one-continuation mark is
    // the discriminating signal.
    let deadline = std::time::Instant::now() + Duration::from_secs(30);
    let mut continuations;
    loop {
        let ops = read_wire_ops_opt(&server, &session_id)
            .await
            .unwrap_or_default();
        continuations = ops
            .iter()
            .filter(|op| is_goal_continuation_prompt(op))
            .count();
        // A park ends the wait: a parked goal launches nothing further, so
        // polling on would only burn the deadline before failing the same
        // way.
        let parked = session
            .goal()
            .get()
            .is_some_and(|goal| goal.status != mirri_core::GoalStatus::Active);
        if continuations >= 2 || parked || std::time::Instant::now() >= deadline {
            break;
        }
        tokio::time::sleep(Duration::from_millis(20)).await;
    }
    assert!(
        continuations >= 2,
        "the inherited idle streak must not pause the goal after a user turn \
         intervenes: the chain must run a fresh streak, saw {continuations} continuation(s)"
    );

    // And the goal parks on the fresh streak's own guard — the same reason
    // it would have paused on, only GOAL_MAX_IDLE_CONTINUATIONS turns later.
    let deadline = std::time::Instant::now() + Duration::from_secs(30);
    let mut goal = session.goal().get().expect("goal survives");
    while goal.status == mirri_core::GoalStatus::Active
        && std::time::Instant::now() < deadline
    {
        tokio::time::sleep(Duration::from_millis(20)).await;
        goal = session.goal().get().expect("goal survives");
    }
    assert_eq!(
        goal.status,
        mirri_core::GoalStatus::Paused,
        "the fresh idle streak must park the goal like any other"
    );
    assert_eq!(
        goal.terminal_reason.as_deref(),
        Some("Paused after repeated idle goal turns"),
        "the park must come from the idle guard, not the cap or the budget: {:?}",
        goal.terminal_reason
    );
}

/// Given a session with an active goal created through the agent tool,
/// when the agent updates the goal status through `UpdateGoal`, then the
/// wire log records the `goal.create` and `goal.update` ops with the
/// agent-side actor.
#[tokio::test]
async fn should_persist_goal_tool_mutations_to_wire_log_when_agent_updates_goal_status() {
    // Given a server with a created session and an agent-created goal
    let (server, _tmp) = test_server(None);
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    converse_once(&server, &session_id).await;
    let result = run_main_agent_tool(
        &server,
        &session_id,
        "CreateGoal",
        json!({
            "objective": "Refactor the scheduler",
            "completion_criterion": "All scheduler tests pass"
        }),
    )
    .await;
    assert!(!result.is_error, "{result:?}");

    // When the agent completes the goal through the UpdateGoal tool
    // (terminal transitions are legal from an active goal; the model
    // cannot supply `paused` — pausing is reserved for the user)
    let result = run_main_agent_tool(
        &server,
        &session_id,
        "UpdateGoal",
        json!({ "status": "complete" }),
    )
    .await;
    assert!(!result.is_error, "{result:?}");

    // Then the wire log records the agent-side goal.create → goal.update
    let ops = read_wire_ops(&server, &session_id).await;
    assert_eq!(ops.len(), 2, "exactly the two goal ops: {ops:?}");
    match &ops[0] {
        WireOp::GoalCreate {
            objective,
            completion_criterion,
            status,
            actor,
            ..
        } => {
            assert_eq!(objective, "Refactor the scheduler");
            assert_eq!(
                completion_criterion.as_deref(),
                Some("All scheduler tests pass")
            );
            assert_eq!(status.as_deref(), Some("active"));
            assert_eq!(actor.as_deref(), Some("agent"));
        }
        other => panic!("expected goal.create, got {other:?}"),
    }
    match &ops[1] {
        WireOp::GoalUpdate { status, actor, .. } => {
            assert_eq!(status.as_deref(), Some("completed"));
            assert_eq!(actor.as_deref(), Some("agent"));
        }
        other => panic!("expected goal.update, got {other:?}"),
    }
}

/// Given a persisted session whose goal (with a budget) was created through
/// the agent tools and whose plan mode was entered, when the session is
/// resumed, then the goal (status, completion criterion, budget) and the
/// plan-mode state are restored to their pre-restart values.
#[tokio::test]
async fn should_restore_goal_budget_and_plan_mode_when_session_is_resumed_after_mutations() {
    // Given a server with a created session, an agent-created goal with a
    // budget, and plan mode entered
    let (server, _tmp) = test_server(None);
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    converse_once(&server, &session_id).await;
    let result = run_main_agent_tool(
        &server,
        &session_id,
        "CreateGoal",
        json!({
            "objective": "Land parity batch P2a",
            "completion_criterion": "Wire tests pass"
        }),
    )
    .await;
    assert!(!result.is_error, "{result:?}");
    let result = run_main_agent_tool(
        &server,
        &session_id,
        "SetGoalBudget",
        json!({ "turns": 40, "tokens": 5000 }),
    )
    .await;
    assert!(!result.is_error, "{result:?}");
    server
        .call_method(
            "plan.enter",
            json!({ "session_id": &session_id, "plan": "1. Survey the write sides" }),
        )
        .await
        .unwrap();

    // Sanity: the mutations were persisted before the close
    let ops = read_wire_ops(&server, &session_id).await;
    assert!(
        ops.iter().any(|op| matches!(op, WireOp::GoalCreate { .. })),
        "goal.create must be recorded: {ops:?}"
    );
    assert!(
        ops.iter().any(|op| matches!(op, WireOp::GoalUpdate { .. })),
        "goal.update (budget) must be recorded: {ops:?}"
    );
    assert!(
        ops.iter()
            .any(|op| matches!(op, WireOp::PlanModeEnter { .. })),
        "plan_mode.enter must be recorded: {ops:?}"
    );

    // When the session is closed and resumed
    server
        .call_method("session.close", json!({ "session_id": &session_id }))
        .await
        .unwrap();
    server
        .call_method("session.resume", json!({ "session_id": &session_id }))
        .await
        .unwrap();

    // Then the goal is restored with its objective, criterion, status and
    // budget, and plan mode is active again
    let manager = server.session_manager();
    let resumed = manager
        .get_session(&SessionId::new(&session_id))
        .await
        .expect("resumed session is live");
    let goal = resumed.goal().get().expect("goal must be restored");
    assert_eq!(goal.objective, "Land parity batch P2a");
    assert_eq!(
        goal.completion_criterion.as_deref(),
        Some("Wire tests pass")
    );
    assert_eq!(goal.status, mirri_core::GoalStatus::Active);
    let budget = goal.budget.expect("budget must be restored");
    assert_eq!(budget.turns, Some(40));
    assert_eq!(budget.tokens, Some(5000));
    assert_eq!(budget.wall_clock_ms, None);
    assert!(
        resumed.plan().is_active(),
        "plan mode must be restored as active"
    );
}

/// Given a session that entered plan mode with a plan text (the `plan.enter`
/// RPC carries the content), When the session is closed and resumed, Then
/// plan mode is active again with the full plan text — not the minted plan
/// id the legacy restore fell back to (F12).
#[tokio::test]
async fn should_restore_the_plan_text_when_a_plan_mode_session_is_resumed() {
    // Given a server with a created session in plan mode with real content
    let (server, _tmp) = test_server(None);
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    converse_once(&server, &session_id).await;
    let plan_text = "1. Survey the write sides\n2. Add the reducer branch\n3. Wire the resume";
    server
        .call_method(
            "plan.enter",
            json!({ "session_id": &session_id, "plan": plan_text }),
        )
        .await
        .unwrap();

    // And the enter op carried the plan text (the rust dialect's versioned
    // `planText` field)
    let ops = read_wire_ops(&server, &session_id).await;
    let enter = ops
        .iter()
        .find_map(|op| match op {
            WireOp::PlanModeEnter { id, plan_text } => Some((id.clone(), plan_text.clone())),
            _ => None,
        })
        .expect("plan_mode.enter must be recorded");
    assert_eq!(enter.1.as_deref(), Some(plan_text), "ops: {ops:?}");
    assert!(
        enter.0.starts_with("plan-"),
        "the id stays the TS-contract identifier: {ops:?}"
    );

    // When the session is closed and resumed
    server
        .call_method("session.close", json!({ "session_id": &session_id }))
        .await
        .unwrap();
    server
        .call_method("session.resume", json!({ "session_id": &session_id }))
        .await
        .unwrap();

    // Then plan mode is active again and the plan text is the full content
    let status = server
        .call_method("plan.status", json!({ "session_id": &session_id }))
        .await
        .unwrap();
    assert_eq!(status["active"], true, "status: {status}");
    assert_eq!(status["plan"], plan_text, "status: {status}");
}

/// Given a session whose approved plan was recorded through the ExitPlanMode
/// tool (a `plan.revision` op carrying the content), When the session is
/// closed and resumed, Then plan mode stays inactive but the plan text is
/// fully readable — the reference surfaces (`plan.status`, the resume
/// summary) show the plan, not an empty or id-shaped placeholder (F12).
#[tokio::test]
async fn should_restore_the_plan_text_after_exit_plan_mode_and_a_restart() {
    // Given a server with a created session in plan mode with real content
    let (server, _tmp) = test_server(None);
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    converse_once(&server, &session_id).await;
    let plan_text = "1. Map the migration chain\n2. Convert the task payload\n3. Pin both shapes";
    server
        .call_method(
            "plan.enter",
            json!({ "session_id": &session_id, "plan": plan_text }),
        )
        .await
        .unwrap();

    // And the model presents the plan for approval through ExitPlanMode
    let result = run_main_agent_tool(&server, &session_id, "ExitPlanMode", json!({})).await;
    assert!(!result.is_error, "{result:?}");

    // And the revision op was recorded — the plan content rides the
    // `plan.revision` carrier (the TS restore-semantics truth source) with
    // the reference fields (id, version, path, sha256, bytes) alongside
    let ops = read_wire_ops(&server, &session_id).await;
    let revision = ops
        .iter()
        .find_map(|op| match op {
            WireOp::PlanRevision {
                id,
                version,
                path,
                sha256,
                bytes,
                plan_text,
            } => Some((
                id.clone(),
                *version,
                path.clone(),
                sha256.clone(),
                *bytes,
                plan_text.clone(),
            )),
            _ => None,
        })
        .expect("plan.revision must be recorded: {ops:?}");
    let (rev_id, rev_version, _rev_path, rev_sha256, rev_bytes, rev_text) = revision;
    assert!(rev_id.starts_with("plan-"), "revision keys on the plan id");
    assert_eq!(rev_version, 1, "the first revision mints version 1");
    assert_eq!(rev_bytes, plan_text.len() as u64);
    assert_eq!(rev_sha256.len(), 64, "the sha256 hex digest of the text");
    assert_eq!(rev_text.as_deref(), Some(plan_text), "ops: {ops:?}");
    assert!(
        ops.iter()
            .any(|op| matches!(op, WireOp::PlanModeExit { .. })),
        "the exit op is recorded after the revision: {ops:?}"
    );

    // When the session is closed and resumed
    server
        .call_method("session.close", json!({ "session_id": &session_id }))
        .await
        .unwrap();
    server
        .call_method("session.resume", json!({ "session_id": &session_id }))
        .await
        .unwrap();

    // Then plan mode is inactive (the exit was durable) but the plan text
    // survives for reference
    let status = server
        .call_method("plan.status", json!({ "session_id": &session_id }))
        .await
        .unwrap();
    assert_eq!(status["active"], false, "status: {status}");
    assert_eq!(status["plan"], plan_text, "status: {status}");
}

/// Given a persisted session, when plan mode is entered and left through
/// both faces (RPC and agent tools), then the wire log records the
/// `plan_mode.*` lifecycle in dispatch order, and a resume of the exited
/// state leaves plan mode inactive.
#[tokio::test]
async fn should_persist_plan_mode_lifecycle_to_wire_log_when_plan_is_entered_and_left() {
    // Given a server with a created session
    let (server, _tmp) = test_server(None);
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    converse_once(&server, &session_id).await;

    // When plan mode cycles: RPC enter → agent exit → agent enter → RPC cancel
    server
        .call_method(
            "plan.enter",
            json!({ "session_id": &session_id, "plan": "1. Survey the write sides" }),
        )
        .await
        .unwrap();
    let result = run_main_agent_tool(&server, &session_id, "ExitPlanMode", json!({})).await;
    assert!(!result.is_error, "{result:?}");
    let result = run_main_agent_tool(&server, &session_id, "EnterPlanMode", json!({})).await;
    assert!(!result.is_error, "{result:?}");
    server
        .call_method("plan.cancel", json!({ "session_id": &session_id }))
        .await
        .unwrap();

    // Then the wire log records plan_mode.enter → plan.revision → exit →
    // enter → cancel (the revision is the F12 content carrier the
    // ExitPlanMode tool records ahead of the exit)
    let ops = read_wire_ops(&server, &session_id).await;
    assert_eq!(ops.len(), 5, "exactly the five plan ops: {ops:?}");
    match &ops[0] {
        WireOp::PlanModeEnter { id, plan_text, .. } => {
            assert!(!id.is_empty(), "a plan id must be minted");
            assert_eq!(
                plan_text.as_deref(),
                Some("1. Survey the write sides"),
                "the RPC enter carries the plan text: {ops:?}"
            );
        }
        other => panic!("expected plan_mode.enter, got {other:?}"),
    }
    assert!(
        matches!(&ops[1], WireOp::PlanRevision { .. }),
        "expected plan.revision, got {:?}",
        ops[1]
    );
    assert!(
        matches!(&ops[2], WireOp::PlanModeExit { .. }),
        "expected plan_mode.exit, got {:?}",
        ops[2]
    );
    assert!(
        matches!(&ops[3], WireOp::PlanModeEnter { .. }),
        "expected plan_mode.enter, got {:?}",
        ops[3]
    );
    assert!(
        matches!(&ops[4], WireOp::PlanModeCancel { .. }),
        "expected plan_mode.cancel, got {:?}",
        ops[4]
    );

    // And when the session is closed and resumed, plan mode stays inactive
    // (the cancel cleared it, and the wire log replays that)
    server
        .call_method("session.close", json!({ "session_id": &session_id }))
        .await
        .unwrap();
    server
        .call_method("session.resume", json!({ "session_id": &session_id }))
        .await
        .unwrap();
    let manager = server.session_manager();
    let resumed = manager
        .get_session(&SessionId::new(&session_id))
        .await
        .expect("resumed session is live");
    assert!(
        !resumed.plan().is_active(),
        "plan mode must stay inactive after resuming a cancelled plan"
    );
}

