    let session = manager
        .get_session(&SessionId::new(&session_id))
        .await
        .expect("session is live");
    session
        .create_agent(AgentId::new("agent-worker"), AgentScopeConfig::default())
        .await
        .expect("worker agent");

    // When the permission mode is switched to auto
    server
        .call_method(
            "agent.setPermission",
            json!({ "session_id": &session_id, "mode": "auto" }),
        )
        .await
        .unwrap();

    // Then every live agent adjudicates at the new mode — the main agent
    // and the already-existing worker alike
