/// Given a live session already running a non-default mode (the create-time
/// seed journaled it), when `agent.setPermission` re-pushes that same mode —
/// what the web client's post-create profile sync does — then the wire log
/// records no duplicate `permission.set_mode` op, while a genuinely new
/// mode still journals one.
#[tokio::test(flavor = "multi_thread")]
async fn should_not_journal_a_duplicate_permission_set_mode_when_repushing_the_current_mode() {
    // Given a server whose config seeds yolo, and a session created on it
    // (the create-time seed journaled exactly one permission.set_mode op)
    let (server, _tmp, _config_path) = test_server_with_config_toml(
        "default_model = \"test-default-model\"\n\
         default_permission_mode = \"yolo\"\n",
    );
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    converse_once(&server, &session_id).await;
    let ops = read_wire_ops(&server, &session_id).await;
    assert_eq!(ops.len(), 1, "the create-time seed is the only op: {ops:?}");
    match &ops[0] {
        WireOp::PermissionSetMode { mode } => assert_eq!(mode, "yolo"),
        other => panic!("expected permission.set_mode, got {other:?}"),
    }

    // When the client re-pushes the mode the session already runs at
    server
        .call_method(
            "agent.setPermission",
            json!({ "session_id": &session_id, "mode": "yolo" }),
        )
        .await
        .unwrap();

    // Then the wire log still holds exactly the one seeded op — the
    // same-value push is not a state change, so it journals nothing
    let ops = read_wire_ops(&server, &session_id).await;
    assert_eq!(
        ops.len(),
        1,
        "re-pushing the current mode must not journal a duplicate op: {ops:?}"
    );

    // But when the mode genuinely changes, the op is journaled
    server
        .call_method(
            "agent.setPermission",
            json!({ "session_id": &session_id, "mode": "auto" }),
        )
        .await
        .unwrap();
    let ops = read_wire_ops(&server, &session_id).await;
    assert_eq!(ops.len(), 2, "a real mode change journals one op: {ops:?}");
    match &ops[1] {
        WireOp::PermissionSetMode { mode } => assert_eq!(mode, "auto"),
        other => panic!("expected permission.set_mode, got {other:?}"),
    }
}

