/// Given a session whose turn asks for tool approval and a client that
/// approves the request for the session, then the wire log records the
/// `permission.record_approval_result` op carrying the tool name and the
/// session approval rule, and a resume restores the approval so the same
/// tool pattern is no longer asked about.
#[tokio::test]
async fn should_persist_session_approval_to_wire_log_when_user_approves_for_session() {
    // Given a server whose client approves every approval request for the
    // session, with a scripted LLM that first calls Bash then finishes
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_tool_use(vec![LlmToolCall {
        id: "call-bash-1".to_string(),
        name: "Bash".to_string(),
        args: json!({ "command": "true" }),
    }]);
    mock.push_text("Command ran fine");
    let (server, _tmp) = test_server(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))));
    let handler: ReverseRpcHandler = Arc::new(|method, params| {
        Box::pin(async move {
            assert_eq!(method, "approval.ask");
            assert_eq!(params["tool_name"], "Bash");
            assert_eq!(
                params["approval_rule"], "Bash",
                "the ask must carry the facet it gated on"
            );
            Ok(json!({ "decision": "approved", "scope": "session" }))
        })
    });
    server.on_reverse_rpc(handler).await.unwrap();
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    // When a message runs a turn whose only tool call is Bash (manual mode
    // asks for it) and the client approves it for the session
    server
        .call_method(
            "message.send",
            json!({ "session_id": &session_id, "text": "run true" }),
        )
        .await
        .unwrap();

    // Then the wire log records the approval result with the tool name and
    // the session approval rule pattern
    let ops = read_wire_ops(&server, &session_id).await;
    let approval = ops
        .iter()
        .find_map(|op| match op {
            WireOp::PermissionRecordApprovalResult { record } => Some(record),
            _ => None,
        })
        .expect("permission.record_approval_result must be recorded");
    assert_eq!(approval["toolName"], "Bash");
    assert_eq!(approval["sessionApprovalRule"], "Bash");
    assert_eq!(approval["result"]["decision"], "approved");
    assert_eq!(approval["result"]["scope"], "session");

    // And the live session memorized the approval (a second Bash call in
    // the same session is not asked about again)
    {
        let manager = server.session_manager();
        let session = manager
            .get_session(&SessionId::new(&session_id))
            .await
            .expect("session stays live");
        let agent = session
            .get_agent(&AgentId::new(DEFAULT_MAIN_AGENT_ID))
            .await
            .expect("main agent exists");
        assert_eq!(
            agent.permission_manager().all_session_approvals(),
            vec!["Bash".to_string()]
        );
    }

    // And when the session is closed and resumed, the approval is restored:
    // the same tool pattern no longer asks
    server
        .call_method("session.close", json!({ "session_id": &session_id }))
        .await
        .unwrap();
    server
        .call_method("session.resume", json!({ "session_id": &session_id }))
        .await
        .unwrap();
    let manager = server.session_manager();
    let resumed = manager
        .get_session(&SessionId::new(&session_id))
        .await
        .expect("resumed session is live");
    let agent = resumed
        .get_agent(&AgentId::new(DEFAULT_MAIN_AGENT_ID))
        .await
        .expect("main agent restored");
    let pm = agent.permission_manager();
    assert_eq!(pm.all_session_approvals(), vec!["Bash".to_string()]);

    let args = json!({ "command": "true" });
    let display = mirri_core::ToolInputDisplay::Command {
        command: "true".to_string(),
    };
    let cancel = mirri_core::CancelToken::new();
    let approvals: std::collections::HashSet<String> =
        pm.all_session_approvals().into_iter().collect();
    let ctx = mirri_core::PermissionPolicyContext {
        tool_name: "Bash",
        tool_call_id: "call-after-resume",
        args: &args,
        approval_rule: "Bash",
        display: &display,
        accesses: &[],
        mode: mirri_core::PermissionMode::Manual,
        rules: &[],
        session_approvals: &approvals,
        cancel: &cancel,
    };
    match pm.evaluate(&ctx) {
        mirri_core::PermissionPolicyResult::Approve { .. } => {}
        other => panic!(
            "expected the restored session approval to approve Bash without asking, got {other:?}"
        ),
    }
}

// ── B9 R3: user-config permission rules reach the live agents ──────────

/// Given a config.toml declaring a `[[permission.rules]]` deny for Bash,
