#[tokio::test]
async fn should_fork_child_session_when_session_create_child_called() {
    // Given a server with a created session
    let (server, _tmp) = test_server(None);
    let created = server
        .call_method("session.create", json!({ "title": "parent" }))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    // When a child session is created from it
    let child = server
        .call_method(
            "session.createChild",
            json!({ "sourceSessionId": session_id }),
        )
        .await
        .unwrap();

    // Then the klient scope-handle shape answers: a new session id and
    // the Session lifecycle-scope kind
    assert!(child["id"].as_str().unwrap().starts_with("session-"));
    assert_ne!(child["id"], session_id);
    assert_eq!(child["kind"], json!(2));

    // And the child carries the v2 default title
    let child_view = server
        .call_method("session.get", json!({ "sessionId": child["id"] }))
        .await
        .unwrap();
    assert_eq!(child_view["title"], "Child: parent");

    // And a caller-minted id is rejected explicitly (no silent drift)
    let error = server
        .call_method(
            "session.createChild",
            json!({ "sourceSessionId": session_id, "newSessionId": "session-chosen" }),
        )
        .await
        .expect_err("newSessionId must not be silently ignored");
    assert!(
        matches!(&error, EngineError::Rpc { code, .. } if *code == -32602),
        "expected invalid_params, got: {error}"
    );
}

#[tokio::test]
async fn should_create_agent_when_session_register_agent_called() {
    // Given a server with a created session
    let (server, _tmp) = test_server(None);
    let created = server
        .call_method("session.create", json!({ "title": "host" }))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    // When an agent is registered into it (klient agentMeta shape)
    let result = server
        .call_method(
            "session.registerAgent",
            json!({
                "sessionId": session_id,
                "agentId": "worker",
                "type": "sub",
                "parentAgentId": DEFAULT_MAIN_AGENT_ID,
            }),
        )
        .await
        .unwrap();

    // Then the klient noResult spelling answers (JSON null)
    assert_eq!(result, Value::Null);

    // And the agent exists in the session afterwards (list order is not
    // guaranteed, so the ids are compared as a set)
    let details = server
        .call_method("session.get", json!({ "sessionId": session_id }))
        .await
        .unwrap();
    assert_eq!(details["agentCount"], 2);
    let mut agents = Vec::new();
    for agent in details["agents"].as_array().unwrap() {
        agents.push(agent["id"].as_str().unwrap().to_string());
    }
    agents.sort();
    assert_eq!(
        agents,
        vec![DEFAULT_MAIN_AGENT_ID.to_string(), "worker".to_string()]
    );

    // And re-registering the same id answers request_invalid (-32602, the
    // D5 shared mapping for `request.invalid`)
    let error = server
        .call_method(
            "session.registerAgent",
            json!({ "sessionId": session_id, "agentId": "worker" }),
        )
        .await
        .expect_err("duplicate agent ids must not be silently accepted");
    assert!(
        matches!(&error, EngineError::Rpc { code, .. } if *code == -32602),
        "expected a request-invalid error, got: {error}"
    );
}

