#[tokio::test]
async fn should_stop_task_and_return_it_when_task_stop_called_with_reason() {
    // Given a server with a session holding one running background task
    let (server, _tmp) = test_server(None);
    let created = server
        .call_method("session.create", json!({ "title": "t" }))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    let session = server
        .session_manager()
        .get_session(&mirri_core::SessionId::new(&session_id))
        .await
        .expect("the created session is live");
    let task_id = session.tasks().register(
        TaskKind::Process {
            command: None,
            dispatcher: None,
        },
        "demo work".to_string(),
        session_id.clone(),
    );

    // When the task is stopped with a reason (klient camelCase payload)
    let stopped = server
        .call_method(
            "task.stop",
            json!({ "sessionId": session_id, "taskId": task_id, "reason": "user asked" }),
        )
        .await
        .unwrap();

    // Then the stopped AgentTask serialization answers (the task.list
    // element shape, tagged status object)
    assert_eq!(stopped["id"], json!(task_id));
    assert_eq!(stopped["description"], json!("demo work"));
    assert_eq!(stopped["status"], json!({ "status": "stopped" }));

    // And the same call under the dotted snake_case spelling works too
    let task_id2 = session.tasks().register(
        TaskKind::Process {
            command: None,
            dispatcher: None,
        },
        "more work".to_string(),
        session_id.clone(),
    );
    let stopped2 = server
        .call_method(
            "task.stop",
            json!({ "session_id": session_id, "task_id": task_id2 }),
        )
        .await
        .unwrap();
    assert_eq!(stopped2["id"], json!(task_id2));
    assert_eq!(stopped2["status"], json!({ "status": "stopped" }));

    // And an unknown task id errors exactly like task.cancel (-32001)
    let error = server
        .call_method(
            "task.stop",
            json!({ "sessionId": session_id, "taskId": "no-such-task" }),
        )
        .await
        .expect_err("an unknown task id must not be silently stopped");
    assert!(
        matches!(&error, EngineError::Rpc { code, .. } if *code == -32001),
        "expected not found, got: {error}"
    );
}

#[tokio::test]
async fn should_rename_and_update_metadata_when_session_metadata_methods_called() {
    // Given a server with a created session
    let (server, _tmp) = test_server(None);
    let created = server
        .call_method("session.create", json!({ "title": "old" }))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    // When it is renamed and its tags are updated (TS patch shape)
    let renamed = server
        .call_method(
            "renameSession",
            json!({ "sessionId": session_id, "title": "new" }),
        )
        .await
        .unwrap();
    assert_eq!(renamed["title"], "new");
    let updated = server
        .call_method(
            "updateSessionMetadata",
            json!({ "sessionId": session_id, "metadata": { "tags": ["a", "b"] } }),
        )
        .await
        .unwrap();
    assert_eq!(updated["title"], "new");

    // Then the metadata reports the new title and tags
    let metadata = server
        .call_method("getSessionMetadata", json!({ "sessionId": session_id }))
        .await
        .unwrap();
    assert_eq!(metadata["title"], "new");
    assert_eq!(metadata["id"], session_id);
    assert_eq!(metadata["agents"], json!([DEFAULT_MAIN_AGENT_ID]));
    // Tags are stored in a `HashSet`, whose iteration order is
    // randomized per process — compare as an unordered set, not a
    // fixed-order array.
    let tags: std::collections::HashSet<String> = metadata["tags"]
        .as_array()
        .unwrap()
        .iter()
        .filter_map(|tag| tag.as_str().map(str::to_string))
        .collect();
    assert_eq!(
        tags,
        std::collections::HashSet::from(["a".to_string(), "b".to_string()])
    );
}

#[tokio::test]
async fn should_apply_model_and_thinking_when_update_meta_is_called_with_them() {
    // Given a seeded config with two aliases and a created session
    let (server, _tmp, _path) = test_server_with_config_toml(
        r#"
default_model = "prov-a/m-1"

[providers.prov-a]
type = "openai"
api_key = "sk-test"

[models."prov-a/m-1"]
provider = "prov-a"
model = "m-1"
max_context_size = 128000

[models."prov-a/m-2"]
provider = "prov-a"
model = "m-2"
max_context_size = 128000
"#,
    );
    let created = server
        .call_method("session.create", json!({ "title": "meta" }))
        .await
        .expect("session created");
    let session_id = created["id"].as_str().expect("session id").to_string();

    // When updateMeta switches the model and raises the thinking effort
    let updated = server
        .call_method(
            "session.updateMeta",
            json!({ "sessionId": session_id, "model": "prov-a/m-2", "thinking": "high" }),
        )
        .await
        .expect("updateMeta with model and thinking");

    // Then the returned view already reflects the applied model
    assert_eq!(updated["model"], json!("prov-a/m-2"));

    // And the engine side really applied it — agent.getModel reads the alias back
    let model = server
        .call_method("agent.getModel", json!({ "sessionId": session_id }))
        .await
        .expect("getModel");
    assert_eq!(model.as_str(), Some("prov-a/m-2"));

    // And the thinking effort took effect on the agent config
    let thinking = server
        .call_method(
            "agent.getEffectiveThinkingLevel",
            json!({ "sessionId": session_id }),
        )
        .await
        .expect("getEffectiveThinkingLevel");
    assert_eq!(thinking.as_str(), Some("high"));
}

