/// Given m-1 (no declaration) and m-2 declaring
/// `support_efforts = ["low", "high", "max"]`, when updateMeta carries
/// both fields, then the thinking is validated against the NEW model:
/// an effort outside m-2's declaration is rejected with a message naming
/// m-2 (the pre-switch m-1 declares nothing and would have accepted it),
/// while a declared spelling on the same switch succeeds.
#[tokio::test]
async fn should_validate_the_thinking_against_the_new_model_when_update_meta_carries_both_fields() {
    // Given m-1 without declarations and m-2 declaring its efforts
    let (server, _tmp, _path) = test_server_with_config_toml(
        r#"
default_model = "prov-a/m-1"

[providers.prov-a]
type = "openai"
api_key = "sk-test"

[models."prov-a/m-1"]
provider = "prov-a"
model = "m-1"
max_context_size = 128000

[models."prov-a/m-2"]
provider = "prov-a"
model = "m-2"
max_context_size = 128000
support_efforts = ["low", "high", "max"]
"#,
    );
    let created = server
        .call_method("session.create", json!({ "title": "meta" }))
        .await
        .expect("session created");
    let session_id = created["id"].as_str().expect("session id").to_string();

    // When updateMeta switches to m-2 while asking for "medium" — a
    // level the undeclared pre-switch m-1 would accept, but which is
    // outside m-2's declaration
    let error = server
        .call_method(
            "session.updateMeta",
            json!({ "sessionId": session_id, "model": "prov-a/m-2", "thinking": "medium" }),
        )
        .await
        .expect_err("the thinking must be validated against the post-switch model");

    // Then the rejection names the NEW model (m-2) and its available
    // efforts — validation ran against the post-switch model, not the
    // pre-switch m-1
    let text = error.to_string();
    assert!(
        text.contains("unsupported thinking effort 'medium'"),
        "the rejection names the rejected effort: {text}"
    );
    assert!(
        text.contains("for model prov-a/m-2"),
        "the rejection names the post-switch model: {text}"
    );
    assert!(
        text.contains("low, high, max"),
        "the rejection lists the post-switch model's efforts: {text}"
    );

    // And the same switch with a declared spelling succeeds
    let updated = server
        .call_method(
            "session.updateMeta",
            json!({ "sessionId": session_id, "model": "prov-a/m-2", "thinking": "max" }),
        )
        .await
        .expect("a model-declared effort on the same switch is accepted");
    assert_eq!(updated["model"], json!("prov-a/m-2"));
    let thinking = server
        .call_method(
            "agent.getEffectiveThinkingLevel",
            json!({ "sessionId": session_id }),
        )
        .await
        .expect("getEffectiveThinkingLevel");
    assert_eq!(thinking.as_str(), Some("max"));
}

