#[tokio::test]
async fn should_dispatch_all_core_api_wire_methods_when_called_with_ts_client_names() {
    // Given a server with a created session
    let (server, _tmp) = test_server(None);
    let created = server
        .call_method("createSession", json!({ "title": "coverage root" }))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    // When every TS client wire name is called with minimal params
    let calls = core_api_coverage_calls(&session_id);
    let mut dispatched = 0usize;
    let mut method_not_found: Vec<String> = Vec::new();
    for (method, params) in calls {
        match server.call_method(method, params).await {
            Ok(_) => dispatched += 1,
            Err(EngineError::MethodNotFound(unmatched)) => {
                method_not_found.push(unmatched.to_string());
            }
            // A real RPC error (invalid params, not found, no provider,
            // …) still proves the method dispatches to a handler.
            Err(_) => dispatched += 1,
        }
    }

    // Then every one of the 93 tested wire names (all 94 minus
    // exportSession, covered separately) dispatches — 93/94 = 98.9%,
    // above the 80% Phase 4.4 target.
    assert!(
        method_not_found.is_empty(),
        "methods missing a dispatch arm: {method_not_found:?}"
    );
    assert_eq!(dispatched, 93);
    assert!(
        dispatched >= 75,
        "Phase 4.4 target: 80%+ of 94 (75 methods)"
    );
}

