/// A server whose `shell.run` foreground window is shrunk to `timeout`, on a
/// throwaway tempdir workspace.
fn test_server_with_shell_timeout(timeout: Duration) -> (EmbeddedServer, tempfile::TempDir) {
    let tmp = tempfile::tempdir().expect("tempdir must be creatable");
    let workspace = Arc::new(WorkspaceScope::new(
        WorkspaceId::new("test-ws"),
        tmp.path().to_path_buf(),
        WorkspaceScopeConfig::default(),
    ));
    let manager = Arc::new(SessionManager::new(workspace));
    (
        EmbeddedServer::with_providers(manager, None, None, None, None, test_server_config(), None)
            .with_shell_foreground_timeout(timeout),
        tmp,
    )
}

/// Given a session and an event subscriber, when `runShellCommand` echoes,
/// then the result carries the stdout, the event stream brackets the run
/// (started → output → completed), and both context messages land.
#[tokio::test]
async fn should_stream_started_output_and_completed_events_when_shell_run_echoes() {
    let (server, _tmp) = test_server(None);
    let created = server
        .call_method("createSession", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    let mut events = server.subscribe_events().await.unwrap();

    // When the command runs with a command id
    let result = server
        .call_method(
            "runShellCommand",
            json!({ "sessionId": session_id, "command": "echo hello", "commandId": "cmd-echo" }),
        )
        .await
        .expect("shell.run must succeed");

    // Then the result carries the stdout and no error
    assert_eq!(result["stdout"], "hello\n");
    assert_eq!(result["isError"], false);
    assert!(result.get("backgrounded").is_none());

    // And the event stream observed started, the stdout chunk, and the
    // settlement (both carrying the command and task ids).
    let mut saw_started = false;
    let mut saw_output = false;
    let mut task_id = String::new();
    for _ in 0..100 {
        let notification = tokio::time::timeout(Duration::from_secs(5), events.recv())
            .await
            .expect("event must arrive within 5s")
            .expect("event channel stays open");
        match notification.method.as_str() {
            "event.shell.started" => {
                saw_started = true;
                assert_eq!(notification.params["commandId"], "cmd-echo");
                task_id = notification.params["taskId"].as_str().unwrap().to_string();
                assert!(task_id.starts_with("task-"));
            }
            "event.shell.output" => {
                assert_eq!(notification.params["commandId"], "cmd-echo");
                assert_eq!(notification.params["taskId"], task_id);
                assert_eq!(notification.params["update"]["kind"], "stdout");
                if notification.params["update"]["text"].as_str() == Some("hello\n") {
                    saw_output = true;
                }
            }
            "event.shell.completed" => {
                assert_eq!(notification.params["commandId"], "cmd-echo");
                assert_eq!(notification.params["isError"], false);
                assert_eq!(notification.params["taskId"], task_id);
                break;
            }
            _ => {}
        }
    }
    assert!(saw_started, "shell.started must precede the chunks");
    assert!(saw_output, "echo stdout must stream as event.shell.output");

    // And both context messages landed (the wrapped input and output pair).
    let context = server
        .call_method("getContext", json!({ "sessionId": session_id }))
        .await
        .unwrap();
    assert_eq!(
        context["context"]["messageCount"], 2,
        "the bash-input and bash-stdout messages must land in context memory"
    );
}

/// Given a slow command under a tiny foreground window, when the window
/// elapses, then the run detaches: `backgrounded` is the boolean flag, the
/// task is registered and settles, and no completed event ever fires.
#[tokio::test]
async fn should_detach_to_background_task_when_the_shell_foreground_timeout_elapses() {
    let (server, _tmp) = test_server_with_shell_timeout(Duration::from_millis(300));
    let created = server
        .call_method("createSession", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    let mut events = server.subscribe_events().await.unwrap();

    // When the slow command runs
    let result = server
        .call_method(
            "runShellCommand",
            json!({
                "sessionId": session_id,
                "command": "sleep 1 && echo detached-done",
                "commandId": "cmd-slow"
            }),
        )
        .await
        .expect("shell.run must succeed");

    // Then the result reports the boolean detach flag (the TS
    // `RunShellCommandResult` contract — the task id rides shell.started,
    // not the result), and the task is registered in the session's task
    // list under the id the started event carried.
    assert_eq!(result["backgrounded"], true, "timeout detaches");
    let mut task_id: Option<String> = None;
    let mut saw_started = false;
    while let Ok(notification) = tokio::time::timeout(Duration::from_secs(5), events.recv()).await {
        let notification = notification.expect("event channel stays open");
        if notification.method == "event.shell.started"
            && notification.params["commandId"] == "cmd-slow"
        {
            task_id = notification.params["taskId"].as_str().map(String::from);
            saw_started = true;
            break;
        }
    }
    let task_id = task_id.expect("shell.started must carry the detached task's id");
    let listed = server
        .call_method("getBackground", json!({ "sessionId": session_id }))
        .await
        .unwrap();
    let listed = listed.as_array().expect("task.list returns an array");
    let entry = listed
        .iter()
        .find(|task| task["id"].as_str() == Some(task_id.as_str()))
        .expect("the detached task is registered");
    // `getBackground` returns the direct `AgentTask` serialization, so the
    // process kind nests its discriminator (`{"kind": "process", "command"}`)
    // rather than flattening the way `BackgroundTaskInfo` does.
    assert_eq!(entry["kind"]["kind"], "process");
    assert_eq!(entry["kind"]["command"], "sleep 1 && echo detached-done");

    // And the task settles once the process exits (the detached run
    // reports through the task lifecycle, not shell.completed). The
    // status serializes as the internally tagged `{"status": …}` object,
    // so the running check reads the nested discriminator.
    let mut settled = false;
    for _ in 0..200 {
        let listed = server
            .call_method("getBackground", json!({ "sessionId": session_id }))
            .await
            .unwrap();
        let done = listed.as_array().unwrap().iter().any(|task| {
            task["id"].as_str() == Some(task_id.as_str()) && task["status"]["status"] != "running"
        });
        if done {
            settled = true;
            break;
        }
        tokio::time::sleep(Duration::from_millis(50)).await;
    }
    assert!(
        settled,
        "the detached task must settle when the process exits"
    );
    // Drain the event stream: background.task.* events may arrive, but
    // shell.completed never does for a detached run (the started event was
    // already consumed above, so it is not re-checked here).
    while let Ok(notification) = tokio::time::timeout(Duration::from_secs(2), events.recv()).await {
        let notification = notification.expect("event channel stays open");
        if notification.method == "event.shell.completed" {
            panic!("a detached run must not emit shell.completed");
        }
    }
    assert!(saw_started, "shell.started must precede the detach");
}

/// Given a slow command under the default foreground window, when
/// `cancelShellCommand` arrives, then the run settles as an error without
/// registering a background task.
#[tokio::test]
async fn should_cancel_the_running_command_when_cancel_shell_command_arrives() {
    let (server, _tmp) = test_server(None);
    let server = Arc::new(server);
    let created = server
        .call_method("createSession", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    let mut events = server.subscribe_events().await.unwrap();

    // When the slow command runs on a spawned task and is cancelled mid-run
    let server_for_run = Arc::clone(&server);
    let run_session = session_id.clone();
    let run = tokio::spawn(async move {
        server_for_run
            .call_method(
                "runShellCommand",
                json!({ "sessionId": run_session, "command": "sleep 30", "commandId": "cmd-cancel" }),
            )
            .await
            .expect("shell.run must succeed")
    });
    loop {
        let notification = tokio::time::timeout(Duration::from_secs(5), events.recv())
            .await
            .expect("started must arrive within 5s")
            .expect("event channel stays open");
        if notification.method == "event.shell.started" {
            // The started frame carries the task id (used by shell.output/
            // completed consumers; the cancel path itself addresses the
            // command id).
            assert!(
                notification.params["taskId"]
                    .as_str()
                    .is_some_and(|id| !id.is_empty()),
                "shell.started must carry a taskId"
            );
            break;
        }
    }
    server
        .call_method(
            "cancelShellCommand",
            json!({ "sessionId": session_id, "commandId": "cmd-cancel" }),
        )
        .await
        .expect("shell.cancel must succeed");
    let result = run.await.unwrap();

    // Then the run reports an error, no background task, and a completed
    // event carrying the error.
    assert_eq!(result["isError"], true);
    assert!(result.get("backgrounded").is_none());
    let listed = server
        .call_method("getBackground", json!({ "sessionId": session_id }))
        .await
        .unwrap();
    assert!(
        listed.as_array().unwrap().is_empty(),
        "a cancelled run must not leave a background task"
    );
    let mut saw_error_completed = false;
    while let Ok(notification) = tokio::time::timeout(Duration::from_secs(5), events.recv()).await {
        let notification = notification.expect("event channel stays open");
        if notification.method == "event.shell.completed" {
            assert_eq!(notification.params["isError"], true);
            saw_error_completed = true;
            break;
        }
    }
    assert!(
        saw_error_completed,
        "the cancelled run emits shell.completed"
    );
}

/// Given a slow command under the default foreground window, when
/// `detachBackground` addresses its task id, then the run converts to the
/// same background task the timeout path produces.
#[tokio::test]
async fn should_convert_the_foreground_command_when_detach_background_arrives() {
    let (server, _tmp) = test_server(None);
    let server = Arc::new(server);
    let created = server
        .call_method("createSession", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    let mut events = server.subscribe_events().await.unwrap();

    // When the slow command runs on a spawned task and is detached by task id
    let server_for_run = Arc::clone(&server);
    let run_session = session_id.clone();
    let run = tokio::spawn(async move {
        server_for_run
            .call_method(
                "runShellCommand",
                json!({ "sessionId": run_session, "command": "sleep 2", "commandId": "cmd-detach" }),
            )
            .await
            .expect("shell.run must succeed")
    });
    let task_id = loop {
        let notification = tokio::time::timeout(Duration::from_secs(5), events.recv())
            .await
            .expect("started must arrive within 5s")
            .expect("event channel stays open");
        if notification.method == "event.shell.started" {
            break notification.params["taskId"].as_str().unwrap().to_string();
        }
    };
    let detached = server
        .call_method(
            "detachBackground",
            json!({ "sessionId": session_id, "taskId": task_id }),
        )
        .await
        .expect("task.detach must succeed");

    // Then the RPC answers the converted task's info snapshot…
    assert_eq!(detached["taskId"].as_str(), Some(task_id.as_str()));
    assert_eq!(detached["kind"], "process");
    assert_eq!(detached["status"], "running");
    // …the run reports the boolean detach flag (the TS contract; the task
    // id itself rode shell.started and the RPC's own answer)…
    let result = run.await.unwrap();
    assert_eq!(result["backgrounded"], true);
    // …and the task is live in the session's list.
    let listed = server
        .call_method("getBackground", json!({ "sessionId": session_id }))
        .await
        .unwrap();
    assert!(
        listed
            .as_array()
            .unwrap()
            .iter()
            .any(|task| task["id"].as_str() == Some(task_id.as_str())),
        "the converted task must be registered"
    );
}

/// Given a model Bash tool call still running in the foreground, when
/// `task.detach` addresses it by `toolCallId`, then the RPC answers the
/// converted task's `background_task_info`, the tool result the model
/// receives is the moved-to-background text, and the task stays visible in
/// `task.list` (detached) until the process settles (B7 D-3).
#[tokio::test]
async fn should_detach_a_foreground_bash_tool_call_by_tool_call_id() {
    // Given a scripted LLM that calls the Bash tool with a long-running
    // command, then ends the turn
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_tool_use(vec![mirri_core::LlmToolCall {
        id: "call_detach_1".to_string(),
        name: "Bash".to_string(),
        args: json!({ "command": "sleep 2 && echo settled", "timeout": 30 }),
    }]);
    mock.push_text("Noted");
    let (server, _tmp) = test_server(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))));
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    server
        .call_method(
            "setPermission",
            json!({ "sessionId": &session_id, "mode": "yolo" }),
        )
        .await
        .unwrap();
    let mut events = server.subscribe_events().await.unwrap();

    // When the turn runs the long foreground Bash call
    server
        .call_method(
            "message.send",
            json!({ "sessionId": &session_id, "text": "run it", "mode": "fire" }),
        )
        .await
        .unwrap();
    let tool_call_id = loop {
        let notification = tokio::time::timeout(Duration::from_secs(5), events.recv())
            .await
            .expect("started must arrive within 5s")
            .expect("event channel stays open");
        if notification.method == "event.tool.call.started" {
            break notification.params["toolCallId"]
                .as_str()
                .expect("toolCallId rides the started event")
                .to_string();
        }
    };

    // The started event can race the tool's own foreground registration —
    // poll until the session's manager holds the running foreground task.
    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .expect("session is live");
    let tasks = session.tasks();
    let registration_deadline = tokio::time::Instant::now() + Duration::from_secs(5);
    loop {
        if tasks
            .list()
            .iter()
            .any(|task| task.status == mirri_core::TaskStatus::Running && !task.detached)
        {
            break;
        }
        assert!(
            tokio::time::Instant::now() < registration_deadline,
            "the Bash tool must register its foreground task"
        );
        tokio::time::sleep(Duration::from_millis(10)).await;
    }

    // Then task.detach by toolCallId converts the foreground run
    let detached = server
        .call_method(
            "task.detach",
            json!({ "sessionId": &session_id, "toolCallId": tool_call_id }),
        )
        .await
        .expect("task.detach must succeed");
    assert_eq!(detached["kind"], json!("process"));
    assert_eq!(detached["status"], json!("running"));
    let task_id = detached["taskId"].as_str().expect("taskId").to_string();
    assert!(!task_id.is_empty());

    // And the task is live (detached) in task.list
    let listed = server
        .call_method("task.list", json!({ "sessionId": &session_id }))
        .await
        .unwrap();
    let entry = listed
        .as_array()
        .unwrap()
        .iter()
        .find(|task| task["id"] == json!(task_id))
        .expect("the converted task must be listed");
    assert_eq!(entry["detached"], json!(true));

    // And the tool result the model receives is the moved-to-background
    // text (task id + next-step guidance).
    let result_output = loop {
        let notification = tokio::time::timeout(Duration::from_secs(5), events.recv())
            .await
            .expect("tool result must arrive within 5s")
            .expect("event channel stays open");
        if notification.method == "event.tool.result"
            && notification.params["toolCallId"] == json!(tool_call_id)
        {
            break notification.params["output"]
                .as_str()
                .expect("text output")
                .to_string();
        }
    };
    assert!(
        result_output.contains(&format!("task_id: {task_id}")),
        "was: {result_output}"
    );
    assert!(
        result_output.contains("next_step: The task now runs in the background"),
        "was: {result_output}"
    );

    // And the background task settles Completed when the process exits.
    let deadline = tokio::time::Instant::now() + Duration::from_secs(10);
    loop {
        let settled = tasks
            .get(&task_id)
            .is_some_and(|task| task.status.is_terminal());
        if settled {
            break;
        }
        assert!(
            tokio::time::Instant::now() < deadline,
            "the detached task must settle; last status: {:?}",
            tasks.get(&task_id).map(|task| task.status.clone())
        );
        tokio::time::sleep(Duration::from_millis(50)).await;
    }
    assert_eq!(
        tasks.get(&task_id).unwrap().status,
        mirri_core::task::TaskStatus::Completed { exit_code: 0 }
    );
}

/// Given `task.detach` for an unknown or settled tool call, when addressed
/// by `toolCallId`, then the RPC answers `null` (the klient noResult
/// spelling) with no state change.
#[tokio::test]
async fn should_answer_null_when_the_tool_call_is_unknown_or_settled() {
    let (server, _tmp) = test_server(None);
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    // An unknown tool call id answers null.
    let unknown = server
        .call_method(
            "task.detach",
            json!({ "sessionId": &session_id, "toolCallId": "toolu-unknown" }),
        )
        .await
        .unwrap();
    assert_eq!(unknown, json!(null));

    // A settled foreground registration answers null too.
    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .expect("session is live");
    let tasks = session.tasks();
    let reg = tasks.register_foreground(
        mirri_core::task::TaskKind::Process {
            command: Some("true".to_string()),
            dispatcher: None,
        },
        "true".to_string(),
        session_id.clone(),
        Some("toolu-settled".to_string()),
    );
    tasks.complete(&reg.task_id, 0);
    let settled = server
        .call_method(
            "task.detach",
            json!({ "sessionId": &session_id, "toolCallId": "toolu-settled" }),
        )
        .await
        .unwrap();
    assert_eq!(settled, json!(null));
}

/// Given a foreground model tool task, when `task.detach` addresses its task
/// id WITHOUT `toolCallId` (the legacy `!` shell addressing), then the RPC
/// answers null — the shell path only reaches `!` shell commands, and the
/// tool-call face is the only address for a model Bash run (the legacy
/// conversion itself is pinned by the detachBackground test above).
#[tokio::test]
async fn should_keep_the_shell_command_detach_path_when_no_tool_call_id_is_given() {
    let (server, _tmp) = test_server(None);
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .expect("session is live");
    let reg = session.tasks().register_foreground(
        mirri_core::task::TaskKind::Process {
            command: Some("sleep 5".to_string()),
            dispatcher: None,
        },
        "sleep 5".to_string(),
        session_id.clone(),
        Some("toolu-1".to_string()),
    );

    // A model-foreground task id does not resolve through the legacy shell
    // face — null, and the task stays a running foreground registration.
    let answer = server
        .call_method(
            "task.detach",
            json!({ "sessionId": &session_id, "taskId": reg.task_id }),
        )
        .await
        .unwrap();
    assert_eq!(answer, json!(null));
    let task = session.tasks().get(&reg.task_id).expect("task stays live");
    assert_eq!(task.status, mirri_core::task::TaskStatus::Running);
    assert!(!task.detached);
}

#[tokio::test]
// The crate-wide home lock is a std Mutex held across the awaits on
// purpose: the pinned `$HOME` must survive the RPC that reads it, and
// each `#[tokio::test]` runs on its own (current-thread) runtime thread,
// so a waiter blocks its own thread while the holder — on another —
// finishes; no deadlock, only bounded serialization.
#[allow(clippy::await_holding_lock)]
async fn should_export_session_to_zip_when_export_session_called() {
    // Given a server under a tempdir workspace, staged under a fake
    // `$HOME` so the exporter writes into the test sandbox
    let (server, _tmp) = test_server(None);
    let created = server
        .call_method("session.create", json!({ "title": "exportable" }))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    converse_once(&server, &session_id).await;
    let fake_home = tempfile::tempdir().expect("fake home must be creatable");
    // The crate-wide home lock serializes this pin against the other
    // HOME-reading tests (the env is process-global; the harness runs the
    // binary's tests in parallel).
    let _home_lock = crate::bootstrap::test_env::home_lock();
    unsafe {
        std::env::set_var("HOME", fake_home.path());
    }
    // The exporter reads `<home>/.mirri-code/sessions/…`, so stage the
    // persisted session there from the manager's sessions dir (the
    // session's bucketed directory — Phase 2 nests it under the
    // workspace key).
    let staged = fake_home.path().join(".mirri-code").join("sessions");
    let source = server
        .session_manager()
        .persistence()
        .session_dir(&mirri_core::SessionId::new(&session_id));
    copy_dir_recursive(&source, &staged.join(&session_id));

    // When the session is exported through the RPC surface
    let result = server
        .call_method("exportSession", json!({ "sessionId": session_id }))
        .await
        .unwrap();

    // Then the zip archive is produced under the export root
    let zip_path = result["zipPath"].as_str().expect("zipPath is returned");
    assert!(zip_path.contains("exports"));
    assert!(std::path::Path::new(zip_path).exists());
    assert!(
        result["sessionDir"]
            .as_str()
            .expect("sessionDir is returned")
            .contains(&session_id)
    );

    // And the top-level keys are exactly the four v2 contract fields
    // (v2:ExportSessionResult — entryCount is gone)
    let mut top_keys: Vec<&str> = result
        .as_object()
        .expect("result must be an object")
        .keys()
        .map(String::as_str)
        .collect();
    top_keys.sort_unstable();
    assert_eq!(
        top_keys,
        vec!["entries", "manifest", "sessionDir", "zipPath"]
    );

    // And the entries are non-empty and include the archive manifest
    let entries: Vec<&str> = result["entries"]
        .as_array()
        .expect("entries must be an array")
        .iter()
        .filter_map(|entry| entry.as_str())
        .collect();
    assert!(!entries.is_empty(), "entries must not be empty");
    assert!(
        entries.contains(&"manifest.json"),
        "entries must include manifest.json, got {entries:?}"
    );

    // And the manifest reports the exported session
    assert_eq!(result["manifest"]["sessionId"], json!(session_id));

    // And the manifest keys are exactly the 17 v2 camelCase fields
    // (nodejsVersion present, runtimeVersion absent)
    let mut manifest_keys: Vec<&str> = result["manifest"]
        .as_object()
        .expect("manifest must be an object")
        .keys()
        .map(String::as_str)
        .collect();
    manifest_keys.sort_unstable();
    assert_eq!(
        manifest_keys,
        vec![
            "desktopLogPath",
            "desktopVersion",
            "exportedAt",
            "globalLogPath",
            "installSource",
            "kimiCodeVersion",
            "nodejsVersion",
            "os",
            "sessionFirstActivity",
            "sessionId",
            "sessionLastActivity",
            "sessionLogPath",
            "shellEnv",
            "title",
            "webLogPath",
            "wireProtocolVersion",
            "workspaceDir",
        ]
    );
}

#[tokio::test]
async fn should_return_core_info_and_config_when_core_info_methods_called() {
    // Given a server
    let (server, _tmp) = test_server(None);

    // When core info and config are requested
    let core = server.call_method("getCoreInfo", json!({})).await.unwrap();
    let config = server
        .call_method("getMirriConfig", json!({}))
        .await
        .unwrap();
    let features = server
        .call_method("getExperimentalFeatures", json!({}))
        .await
        .unwrap();
    let diagnostics = server
        .call_method("getConfigDiagnostics", json!({}))
        .await
        .unwrap();

    // Then the engine identity and stubbed feature/config shapes return
    assert_eq!(core["version"], env!("CARGO_PKG_VERSION"));
    assert_eq!(core["engine"], "rust");
    // config.get returns the MirriConfig wire shape: only providers (always
    // present, even if empty) is included when the config is default.
    // Absent optional fields are omitted, not null, because TS zod
    // `.optional()` rejects `null`.
    assert_eq!(config["providers"], json!({}));
    assert!(
        config.get("models").is_none() || config["models"].is_null(),
        "models should be omitted when empty"
    );
    assert!(
        config.get("engine").is_none(),
        "engine belongs to core.info"
    );
    assert!(
        config.get("version").is_none(),
        "version belongs to core.info"
    );
    // The TS wire contract is a bare array (v1 `explainAll()` / v2
    // `flags.list()`); the client calls `.map` on it, so a wrapped object
    // crashes TUI startup. The composition root registers the engine's own
    // gate flags (hook-command-rewrite and session-consistency-follow, both
    // default off, env-gated), so the array carries them.
    let features = features.as_array().expect("bare array");
    assert_eq!(features.len(), 2);
    let ids: Vec<&str> = features.iter().filter_map(|f| f["id"].as_str()).collect();
    assert!(ids.contains(&"hook-command-rewrite"));
    assert!(ids.contains(&"session-consistency-follow"));
    for feature in features {
        assert_eq!(feature["defaultEnabled"], false);
    }
    assert_eq!(diagnostics, json!({ "warnings": [] }));
}

