/// Given a session holding one cron task, when `cron.delete` names it, then
/// the RPC acknowledges the removal and the list no longer carries the task
/// (B6 management write face).
#[tokio::test]
async fn should_delete_a_cron_task_when_cron_delete_names_a_registered_task() {
    // Given a server with a session holding one cron task (created the
    // production way — the model tool)
    let (server, _tmp) = test_server(None);
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    converse_once(&server, &session_id).await;
    let result = run_main_agent_tool(
        &server,
        &session_id,
        "CronCreate",
        json!({ "cron": "*/5 * * * *", "prompt": "tick", "recurring": true }),
    )
    .await;
    assert!(!result.is_error, "{result:?}");
    let task_id = cron_task_id_from_tool_result(&result);

    // When the management write face removes it
    let deleted = server
        .call_method(
            "cron.delete",
            json!({ "sessionId": session_id, "taskId": task_id }),
        )
        .await
        .unwrap();

    // Then the ack carries the removed id and the list is empty
    assert_eq!(deleted["deleted"], true);
    assert_eq!(deleted["taskId"], task_id);
    let listed = server
        .call_method("cron.list", json!({ "sessionId": session_id }))
        .await
        .unwrap();
    assert_eq!(listed["tasks"].as_array().unwrap().len(), 0);
}

