/// Given a session holding a far-future cron task (never due during the
/// test), when `cron.trigger` targets it, then the fire is announced and
/// the prompt runs as an engine turn with the cron-job origin — through
/// the same injection path the driver uses (B6 run-now face).
#[tokio::test]
async fn should_inject_the_prompt_as_an_engine_turn_when_cron_trigger_targets_a_registered_task() {
    // Given a server with a scripted LLM and a session holding a cron task
    // that is NOT due (its next fire is far in the future)
    let mock = Arc::new(ScriptedLlm::new());
    let (server, _tmp) = test_server(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))));
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    converse_once(&server, &session_id).await;
    // The scripted reply is queued after the setup turn so the *manual*
    // injected turn is the one that consumes it.
    mock.push_text("manual cron reply");
    let result = run_main_agent_tool(
        &server,
        &session_id,
        "CronCreate",
        json!({ "cron": "0 9 1 1 *", "prompt": "do the manual thing", "recurring": true }),
    )
    .await;
    let task_id = cron_task_id_from_tool_result(&result);
    let mut events = server.subscribe_events().await.unwrap();

    // When the management run-now face triggers it
    let triggered = server
        .call_method(
            "cron.trigger",
            json!({ "sessionId": session_id, "taskId": task_id }),
        )
        .await
        .unwrap();
    assert_eq!(triggered["triggered"], true);
    assert_eq!(triggered["taskId"], task_id);

    // Then the fire is announced and the prompt runs as an engine turn —
    // not a user message, not a scheduled delivery
    let fired = next_event_where(&mut events, |n| n.method == "event.cron.fired", |_| {}).await;
    assert_eq!(fired.params["origin"]["jobId"], task_id);
    assert_eq!(fired.params["prompt"], "do the manual thing");
    let turn_started = next_event_where(
        &mut events,
        |n| n.method == "event.turn.started",
        |n| {
            assert_ne!(
                n.method, "event.message.received",
                "the injection is not a user message"
            )
        },
    )
    .await;
    assert!(
        turn_started.params["turnId"]
            .as_str()
            .is_some_and(|id| id.starts_with("turn-")),
        "the injected turn carries the turn-<uuid> bracket id"
    );
    // And the manual turn produces the scripted assistant reply — the
    // injection ran the real engine loop, not a silent drop. The reply
    // streams as chunked deltas; accumulate them until the turn ends.
    let mut reply = String::new();
    let _ = next_event_where(
        &mut events,
        |n| n.method == "event.turn.ended",
        |n| {
            if n.method == "event.assistant.delta"
                && let Some(delta) = n.params["delta"].as_str()
            {
                reply.push_str(delta);
            }
        },
    )
    .await;
    // Drain any straggler deltas the relay still holds past the ended
    // event before asserting (bounded, non-blocking).
    for _ in 0..8 {
        let Ok(maybe) = tokio::time::timeout(Duration::from_millis(50), events.recv()).await else {
            break;
        };
        let notification = maybe.expect("event channel stays open");
        if notification.method == "event.assistant.delta"
            && let Some(delta) = notification.params["delta"].as_str()
        {
            reply.push_str(delta);
        }
    }
    assert!(
        reply.contains("manual cron reply"),
        "the manual fire ran the engine loop and produced the scripted reply: {reply:?}"
    );
}

/// Given a session holding a far-future cron task, when `cron.trigger`
/// fires it, then the row still lists the task with the same next fire —
/// the run-now face never moves the schedule (D-2).
#[tokio::test]
async fn should_keep_the_schedule_untouched_when_cron_trigger_fires_a_task() {
    let (server, _tmp) = test_server(None);
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    converse_once(&server, &session_id).await;
    let result = run_main_agent_tool(
        &server,
        &session_id,
        "CronCreate",
        json!({ "cron": "0 9 1 1 *", "prompt": "tick", "recurring": true }),
    )
    .await;
    let task_id = cron_task_id_from_tool_result(&result);
    let before = server
        .call_method("cron.list", json!({ "sessionId": session_id }))
        .await
        .unwrap();
    let before_next = before["tasks"][0]["nextFireAt"].clone();

    // When the task is manually triggered
    server
        .call_method(
            "cron.trigger",
            json!({ "sessionId": session_id, "taskId": task_id }),
        )
        .await
        .unwrap();

    // Then the row still lists the task with the same next fire (D-2) —
    // the far-future expression never comes due during the test, so the
    // cron driver's own ticks stay inert.
    let after = server
        .call_method("cron.list", json!({ "sessionId": session_id }))
        .await
        .unwrap();
    let tasks = after["tasks"].as_array().unwrap();
    assert_eq!(
        tasks.len(),
        1,
        "the task survives the manual fire: {after:?}"
    );
    assert_eq!(
        tasks[0]["nextFireAt"], before_next,
        "the schedule is untouched"
    );
}

