    std::fs::create_dir_all(&skill_dir).expect("skill dir must be creatable");
    std::fs::write(
        skill_dir.join(mirri_core::SKILL_MD_FILE),
        "---\ndescription: Reviews designs.\n---\n\n# Design Review\n",
    )
    .expect("SKILL.md must be writable");
