#[tokio::test]
async fn should_discover_and_activate_skill_when_skill_methods_called() {
    // Given a server with a scripted LLM whose workspace catalog
    // discovers a skill
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("ok.");
    let (server, tmp) = test_server(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))));
    let skills_root = tmp.path().join("skills");
    let skill_dir = skills_root.join("code-review");
    std::fs::create_dir_all(&skill_dir).expect("skill dir must be creatable");
    std::fs::write(
        skill_dir.join(mirri_core::SKILL_MD_FILE),
        "---\ndescription: Review code carefully\n---\n\n# Code Review\n\nLook for bugs.",
    )
    .expect("SKILL.md must be writable");
    server
        .session_manager()
        .workspace()
        .skills()
        .discover(&skills_root, mirri_core::SkillSource::Project)
        .expect("discovery must succeed");
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    // When the skills are listed and one is activated (fire mode drives
    // the turn in the background, so a subscriber brackets the wait)
    let mut events = server.subscribe_events().await.unwrap();
    let listed = server
        .call_method("listSkills", json!({ "sessionId": session_id }))
        .await
        .unwrap();
    // Then the result is the TS `SkillSummary[]` bare array
    let skills = listed.as_array().unwrap();
    // The project skill "code-review" should be present. User-level
    // skills from the developer's ~/.agents/skills/ may also appear.
    let code_review = skills
        .iter()
        .find(|s| s["name"] == "code-review")
        .expect("code-review skill should be in the list");
    assert_eq!(code_review["source"], "project");
    // Plugin-provided skills are reported with the TS "extra" source value.
    let plugin_dir = skills_root.join("plugin-skill");
    std::fs::create_dir_all(&plugin_dir).expect("plugin skill dir must be creatable");
    std::fs::write(
        plugin_dir.join(mirri_core::SKILL_MD_FILE),
        "---\ndescription: Plugin-provided helper\n---\n\n# Helper\n",
    )
    .expect("SKILL.md must be writable");
    server
        .session_manager()
        .workspace()
        .skills()
        .discover(&skills_root, mirri_core::SkillSource::Plugin)
        .expect("plugin discovery must succeed");
    let relisted = server
        .call_method("listSkills", json!({ "sessionId": session_id }))
        .await
        .unwrap();
    let plugin_skill = relisted
        .as_array()
        .unwrap()
        .iter()
        .find(|s| s["name"] == "plugin-skill")
        .expect("plugin skill should be in the list");
    assert_eq!(plugin_skill["source"], "extra");

    let activated = server
        .call_method(
            "activateSkill",
            json!({ "sessionId": session_id, "name": "code-review" }),
        )
        .await
        .unwrap();
    assert_eq!(activated["ok"], true);
    assert_eq!(activated["skill"], "code-review");
    // Fire mode resolves at launch; wait for the turn to settle before
    // reading the memory the turn appended.
    let _ = next_event_where(&mut events, |n| n.method == "event.turn.ended", |_| {}).await;

    // Then the activation reached the agent as a user-slash skill turn
    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .unwrap();
    let agent = session
        .get_agent(&AgentId::new(DEFAULT_MAIN_AGENT_ID))
        .await
        .unwrap();
    let memory = agent.context_memory();
    let guard = memory.lock().unwrap_or_else(|e| e.into_inner());
    let history = guard.history();
    // The skill-activation user message plus the turn's assistant reply.
    assert_eq!(history.len(), 2, "the skill-activation turn's messages");
    assert!(history[0].message.text_content().contains("code-review"));
    assert!(matches!(
        history[0].origin,
        Some(mirri_core::PromptOrigin::SkillActivation { .. })
    ));
    assert_eq!(history[1].message.text_content(), "ok.");
}

// --- reverse RPC closed-loop tests ------------------------------------

/// A mock reverse-RPC handler that returns canned responses keyed by
/// method, and records every call so tests can assert what the engine
/// asked.
#[allow(clippy::type_complexity)]
fn mock_reverse_rpc_handler(
    responses: std::collections::HashMap<&'static str, Value>,
) -> (
    ReverseRpcHandler,
    Arc<std::sync::Mutex<Vec<(String, Value)>>>,
) {
    let calls: Arc<std::sync::Mutex<Vec<(String, Value)>>> =
        Arc::new(std::sync::Mutex::new(Vec::new()));
    let calls_clone = Arc::clone(&calls);
    let handler: ReverseRpcHandler = Arc::new(move |method: String, params: Value| {
        let calls = Arc::clone(&calls_clone);
        let responses = responses.clone();
        Box::pin(async move {
            calls.lock().unwrap().push((method.clone(), params.clone()));
            responses
                .get(method.as_str())
                .cloned()
                .ok_or_else(|| format!("unknown method: {method}"))
        })
    });
    (handler, calls)
}

/// Given a server with a reverse-RPC handler that approves, when the
/// engine evaluates a permission `Ask` policy result, then the engine
/// issues an `approval.ask` reverse RPC and the tool is approved.
#[tokio::test]
async fn should_issue_approval_ask_reverse_rpc_when_permission_returns_ask() {
    // Given a server with a reverse-RPC handler that returns
    // { decision: "approved" } (TS protocol shape)
    let mut responses = std::collections::HashMap::new();
    responses.insert("approval.ask", json!({ "decision": "approved" }));
    let (handler, calls) = mock_reverse_rpc_handler(responses);
    let (server, _tmp) = test_server(None);
    server.on_reverse_rpc(handler).await.unwrap();

    // When a session is created (wiring the callback into the agent)
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    // Then the agent's permission manager and tool services are wired
    // with the reverse-RPC callback. Verify by inspecting the agent.
    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .unwrap();
    let agent = session
        .get_agent(&AgentId::new(DEFAULT_MAIN_AGENT_ID))
        .await
        .unwrap();

    // The tool manager should include AskUserQuestion (the callback is set).
    let tm = agent.tool_manager();
    let tools = tm.read();
    let tool_names = tools.all_tool_names();
    assert!(
        tool_names.contains(&"AskUserQuestion".to_string()),
        "AskUserQuestion should be registered when a reverse-RPC callback is wired"
    );

    // No calls yet — the callback is only invoked during a turn.
    assert!(calls.lock().unwrap().is_empty());
}

