/// A no-op reverse-RPC callback for Arc-identity assertions — the mirror
/// test only compares the pointer, it never invokes the callback.
struct NoopReverseRpcCallback;

#[async_trait::async_trait]
impl ReverseRpcCallback for NoopReverseRpcCallback {
    async fn call(&self, _method: &str, _params: Value) -> Result<Value, String> {
        Ok(json!({ "ok": true }))
    }
}

/// Given a session whose artifacts carry a serve-transport callback (the WS
/// subscribe stamp, `ws_rpc.rs` — installed strictly later than the agent's
/// create-time snapshot), when a wait-mode `message.send` turn dispatches,
/// then the callback the dispatch resolves is mirrored into the agent's LIVE
/// config, so subagents spawned mid-turn inherit it (ADR-009, audit P0-1).
#[tokio::test]
async fn should_mirror_the_dispatch_callback_into_the_live_agent_config() {
    // Given a server with a scripted LLM and a created session
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("hello");
    let (server, _tmp) = test_server(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))));
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    // And the serve transport stamps its per-connection callback into the
    // session artifacts at subscribe (ws_rpc.rs) — strictly later than the
    // agent's create-time snapshot (which has no callback here)
    let callback: Arc<dyn ReverseRpcCallback> = Arc::new(NoopReverseRpcCallback);
    let artifacts = server
        .session_manager()
        .session_artifacts(&SessionId::new(&session_id))
        .expect("created session has artifacts");
    *artifacts
        .reverse_rpc_callback
        .write()
        .unwrap_or_else(|e| e.into_inner()) = Some(Arc::clone(&callback));

    // When a wait-mode message runs its turn (the dispatch resolves the
    // artifacts callback)
    server
        .call_method(
            "message.send",
            json!({ "session_id": session_id, "text": "hi" }),
        )
        .await
        .unwrap();

    // Then the main agent's LIVE slot resolves the artifacts callback —
    // the slot IS the artifacts' handle (aliased at artifacts install), so
    // the late subscribe reaches the agent's tools through the same Arc
    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .unwrap();
    let agent = session
        .get_agent(&AgentId::new(DEFAULT_MAIN_AGENT_ID))
        .await
        .unwrap();
    let live_callback = agent
        .config()
        .read()
        .unwrap_or_else(|e| e.into_inner())
        .reverse_rpc_slot
        .as_ref()
        .and_then(|slot| slot.read().unwrap_or_else(|e| e.into_inner()).clone());
    assert!(
        live_callback
            .map(|c| Arc::ptr_eq(&c, &callback))
            .unwrap_or(false),
        "the agent's live slot must resolve the same callback Arc the dispatch resolved"
    );
}

