/// Given a server with a profile manager and mock LLM, when the main
/// agent invokes AgentSwarm with two items, then both subagents run
/// concurrently and the main agent produces its final reply.
///
/// Scripted flow (shared FIFO queue):
/// 1. Main agent → tool_use(AgentSwarm, items=["alpha","beta"])
/// 2. Subagent 1 → "Result alpha" (end_turn)
/// 3. Subagent 2 → "Result beta" (end_turn)
/// 4. Main agent → "Swarm complete" (end_turn)
#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn should_dispatch_multiple_subagents_concurrently_when_agent_swarm_invoked() {
    let mock = Arc::new(ScriptedLlm::new());

    // 1. Main agent calls AgentSwarm
    mock.push_tool_use(vec![LlmToolCall {
        id: "call_0".to_string(),
        name: "AgentSwarm".to_string(),
        args: json!({
            "description": "swarm test",
            "prompt_template": "Process: {{item}}",
            "items": ["alpha", "beta"]
        }),
    }]);
    // 2. Subagent 1
    mock.push_text("Result alpha");
    // 3. Subagent 2
    mock.push_text("Result beta");
    // 4. Main agent final reply
    mock.push_text("Swarm complete");

    let (server, _tmp) =
        test_server_with_profiles(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock))));

    // A titled session — the test counts the mock's calls exactly, and an
    // untitled session's settle would spawn the side title call too.
    let created = server
        .call_method(
            "session.create",
            json!({"permissionMode": "yolo", "title": "concurrent swarm"}),
        )
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    // Subscribe to events
    let mut events = server.subscribe_events().await.unwrap();

    // Send message in fire mode
    server
        .call_method(
            "message.send",
            json!({
                "session_id": session_id,
                "text": "Use AgentSwarm to process alpha and beta",
                "mode": "fire"
            }),
        )
        .await
        .unwrap();

    // Collect events until we see "Swarm complete" or timeout
    let mut chunk_text = String::new();
    let deadline = tokio::time::Instant::now() + Duration::from_secs(30);
    while let Ok(Some(notification)) = tokio::time::timeout_at(deadline, events.recv()).await {
        match notification.method.as_str() {
            "event.assistant.delta" => {
                if let Some(text) = notification.params["delta"].as_str() {
                    chunk_text.push_str(text);
                    if chunk_text.contains("Swarm complete") {
                        break;
                    }
                }
            }
            "event.turn.ended" => break,
            _ => {}
        }
    }

    // The main agent should have produced its final reply
    assert!(
        chunk_text.contains("Swarm complete"),
        "expected 'Swarm complete' in chunks, got: {chunk_text}"
    );

    // The mock should have been called 4 times:
    // 1 (main tool_use) + 2 (subagents) + 1 (main final) = 4
    assert_eq!(
        mock.chat_call_count(),
        4,
        "expected 4 chat calls (1 main tool_use + 2 subagents + 1 main final)"
    );
}

