#[tokio::test]
async fn should_start_and_complete_manual_compaction_when_begin_compaction_called_with_mock_llm() {
    // Given a server with a scripted mock LLM and a session with some history
    // (two exchanges — with a single [user, assistant] pair the whole history
    // is one indivisible retention-tail unit and compaction must give up,
    // US2.6)
    let mock = Arc::new(ScriptedLlm::new());
    // First two calls: respond to the messages to create history
    mock.push_text("Hello from the scripted LLM");
    mock.push_text("Another hello from the scripted LLM");
    // Third call: respond to the compaction summarizer
    mock.push_text("This is a compaction summary of the conversation.");

    let (server, _tmp) = test_server(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))));
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    // Send messages to create conversation history
    server
        .call_method(
            "message.send",
            json!({ "sessionId": &session_id, "text": "Tell me a story" }),
        )
        .await
        .unwrap();
    server
        .call_method(
            "message.send",
            json!({ "sessionId": &session_id, "text": "Tell me another story" }),
        )
        .await
        .unwrap();

    // When beginCompaction is called (no active turn)
    let result = server
        .call_method(
            "beginCompaction",
            json!({ "sessionId": &session_id, "instruction": "summarize the story" }),
        )
        .await
        .unwrap();

    // Then the RPC returns immediately with the bare boolean true — the
    // engine-service `begin(): boolean` contract (no {ok, started} envelope)
    assert_eq!(result, json!(true));

    // Give the background compaction task time to complete
    tokio::time::sleep(tokio::time::Duration::from_millis(500)).await;

    // The mock should have been called at least three times (messages +
    // compaction)
    assert!(
        mock.chat_call_count() >= 3,
        "expected at least 3 chat calls (2 messages + compaction), got {}",
        mock.chat_call_count()
    );
}

#[tokio::test]
async fn should_skip_with_info_notice_when_manual_compaction_has_nothing_to_compact() {
    // Given a server with a scripted mock LLM and a session whose whole
    // history is a single [user, assistant] pair — one indivisible
    // retention-tail unit, nothing older to compact (US2.6/SDR-003)
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("Hello from the scripted LLM");

    let (server, _tmp) = test_server(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))));
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    // Send one message to create a single-exchange history
    server
        .call_method(
            "message.send",
            json!({ "sessionId": &session_id, "text": "Tell me a story" }),
        )
        .await
        .unwrap();
    let chat_calls_before = mock.chat_call_count();

    // When beginCompaction is called with nothing to compact
    let result = server
        .call_method("beginCompaction", json!({ "sessionId": &session_id }))
        .await;

    // Then the RPC resolves (no error bubble) with the bare boolean false —
    // an info-level skip per the `begin(): boolean` contract (SDR-003)
    assert_eq!(result.unwrap(), json!(false));

    // And the summarizer never ran — the skip must not pay for an LLM call
    tokio::time::sleep(tokio::time::Duration::from_millis(200)).await;
    assert_eq!(
        mock.chat_call_count(),
        chat_calls_before,
        "the summarizer must not run when there is nothing to compact"
    );

    // And the skip leaves no residual in-flight registration — a second
    // begin after the skip is judged on its own (still false, not the
    // already-in-flight error)
    let second = server
        .call_method("beginCompaction", json!({ "sessionId": &session_id }))
        .await;
    assert_eq!(second.unwrap(), json!(false));
}

