#[tokio::test]
async fn should_persist_changes_to_disk_when_config_mutated() {
    // Given a seeded config on disk
    let (server, _tmp, config_path) = test_server_with_config_toml(CONFIG_WRITE_SEED_TOML);

    // When a patch is applied through config.set
    server
        .call_method(
            "config.set",
            json!({
                "providers": { "openai": { "type": "openai" } },
                "defaultProvider": "openai",
            }),
        )
        .await
        .unwrap();

    // Then the merged config is persisted to config.toml (re-read without
    // env overrides, exactly as the next boot would see it)
    let on_disk = ServerConfig::load_without_env(&config_path, &mirri_os::LocalSyncFs)
        .expect("persisted config should parse");
    let providers = on_disk.providers.expect("providers should be persisted");
    assert!(providers.contains_key("openai"));
    assert!(
        providers.contains_key("kimi"),
        "unpatched providers must survive the merge"
    );
    assert_eq!(on_disk.default_provider.as_deref(), Some("openai"));
    assert_eq!(on_disk.default_model.as_deref(), Some("kimi/alpha"));
}

/// Given a Mirri home with NO config.toml (the fresh-environment boot —
/// the funnel must still resolve the well-known path so config writes
/// land there, mirroring the TS `resolveConfigPath` contract), when a
/// provider patch is set, then the write succeeds and the file is
/// created at `<home>/config.toml`.
#[tokio::test]
async fn should_create_config_file_when_config_set_called_without_existing_config() {
    // Given a fresh home assembled through the serve-shaped funnel (the
    // same `assemble` `mirri serve` / `mirri web` build through)
    let workspace = tempfile::tempdir().expect("workspace tempdir");
    let home = tempfile::tempdir().expect("home tempdir");
    let config_path = home.path().join("config.toml");
    assert!(
        !config_path.exists(),
        "the fresh home must not carry a config.toml"
    );
    let parts = crate::bootstrap::assemble(
        WorkspaceId::new("fresh-home-ws"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        None,
        crate::bootstrap::WorkspacePolicy::TrustedFromConfig,
        Vec::new(),
    );
    let server = EmbeddedServer::from_parts(parts);

    // When a patch adds a provider and a model alias and points the
    // default model at it
    let result = server
        .call_method(
            "config.set",
            json!({
                "providers": {
                    "openai": { "type": "openai", "apiKey": "sk-fresh" }
                },
                "models": {
                    "openai/gpt-4o": {
                        "provider": "openai",
                        "model": "gpt-4o",
                        "maxContextSize": 200000
                    }
                },
                "defaultModel": "openai/gpt-4o"
            }),
        )
        .await
        .unwrap();

    // Then the config file was created and carries the patch
    assert!(config_path.is_file(), "config.toml must be created");
    assert_eq!(result["providers"]["openai"]["apiKey"], "[REDACTED]");
    assert_eq!(result["models"]["openai/gpt-4o"]["model"], "gpt-4o");
    assert_eq!(result["defaultModel"], "openai/gpt-4o");
    let disk = std::fs::read_to_string(&config_path).expect("config.toml readable");
    assert!(disk.contains("[providers.openai]"), "on disk: {disk}");
    assert!(disk.contains("sk-fresh"), "on disk: {disk}");
}

