#[tokio::test]
async fn should_reject_config_set_when_retention_keys_conflict_and_leave_file_unchanged() {
    // Given a valid seed config whose loop-control section carries no
    // retention key yet
    let (server, _tmp, config_path) = test_server_with_config_toml(
        r#"
default_provider = "kimi"
default_model = "kimi/alpha"

[providers.kimi]
type = "openai"
api_key = "sk-test"

[models."kimi/alpha"]
provider = "kimi"
model = "alpha"
max_context_size = 128000

[loop_control]
max_steps_per_turn = 30
"#,
    );
    let before = std::fs::read_to_string(&config_path).expect("seed config should be readable");

    // When a patch carries both mutually exclusive retention keys at once
    let error = server
        .call_method(
            "config.set",
            json!({
                "loopControl": {
                    "retentionTailRatio": 0.2,
                    "retentionTailTokens": 4000
                }
            }),
        )
        .await
        .unwrap_err();

    // Then the set fails with an invalid-params RPC error naming both keys
    match error {
        EngineError::Rpc { code, message, .. } => {
            assert_eq!(code, -32602, "error: {message}");
            assert!(
                message.contains("retention_tail_ratio")
                    && message.contains("retention_tail_tokens")
                    && message.contains("mutually exclusive"),
                "error: {message}"
            );
        }
        other => panic!("expected an Rpc error, got: {other}"),
    }

    // And the config file on disk is byte-identical to before the failed
    // set (no poisoned file for the next boot to trip over)
    let after = std::fs::read_to_string(&config_path).expect("config should still be readable");
    assert_eq!(before, after, "a failed config.set must not touch the file");

    // And when a second set adds one key on top of the other already
    // persisted, it is rejected the same way (the merge validates the
    // merged result, not just the patch)
    server
        .call_method(
            "config.set",
            json!({ "loopControl": { "retentionTailRatio": 0.2 } }),
        )
        .await
        .unwrap();
    let before_second = std::fs::read_to_string(&config_path)
        .expect("config after the single-key set should be readable");
    let error = server
        .call_method(
            "config.set",
            json!({ "loopControl": { "retentionTailTokens": 4000 } }),
        )
        .await
        .unwrap_err();
    match error {
        EngineError::Rpc { code, message, .. } => {
            assert_eq!(code, -32602, "error: {message}");
            assert!(
                message.contains("retention_tail_ratio")
                    && message.contains("retention_tail_tokens"),
                "error: {message}"
            );
        }
        other => panic!("expected an Rpc error, got: {other}"),
    }
    let after_second = std::fs::read_to_string(&config_path)
        .expect("config should still be readable after the second failed set");
    assert_eq!(
        before_second, after_second,
        "a failed config.set must not touch the file"
    );
}

