/// Given a connected workspace server advertising two tools with one of
/// them disabled by the stored config filter, when `mcp.tools` addresses
/// it by name, then every advertised tool lists with its per-tool filter
/// state — including the disabled one (`connected: true`, `enabled:
/// false`), the call-time merged-config verdict, not a filtered-out
/// silence (F-5 / ADR-004).
#[tokio::test]
async fn should_return_tools_with_filter_state_when_mcp_tools_is_called_for_connected_server() {
    // Given: a workspace-layer server connected through the startup path,
    // advertising two tools with one disabled in the stored filter
    let mock = spawn_mock_mcp_http_server_with_tools(
        0,
        false,
        &[("t1", "first tool"), ("t2", "second tool")],
    )
    .await;
    let (home, workspace) = layered_mcp_fixture(
        json!({}),
        Some(json!({"demo": {"transport": "http", "url": mock.url, "disabledTools": ["t2"]}})),
    );
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("mcp-tools-filter-state"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );
    let manager = Arc::clone(server.mcp_manager().expect("workspace manager attached"));

    server
        .call_method("mcp.list", json!({}))
        .await
        .expect("first call");
    wait_for_pool_state(&manager, "demo", "Connected", |state| {
        matches!(state, Some(mirri_mcp::McpConnectionState::Connected { .. }))
    })
    .await;

    // When
    let result = server
        .call_method("mcp.tools", json!({ "name": "demo" }))
        .await
        .expect("mcp.tools should succeed");

    // Then: the single-server view lists both tools with the filter verdict
    assert_eq!(result["connected"], json!(true));
    let tools = result["tools"].as_array().expect("tools array");
    assert_eq!(tools.len(), 2);
    assert_eq!(tools[0]["name"], json!("t1"));
    assert_eq!(tools[0]["description"], json!("first tool"));
    assert_eq!(tools[0]["enabled"], json!(true));
    assert_eq!(tools[1]["name"], json!("t2"));
    assert_eq!(tools[1]["enabled"], json!(false));
}

