/// A home whose `/.mirri-code/mcp.json` user layer declares `user_servers`,
/// plus a workspace root whose `.mcp.json` project layer declares
/// `project_servers` (when given). Servers use `"enabled": false` so entry
/// registration is observable without spawning a real process.
fn layered_mcp_fixture(
    user_servers: serde_json::Value,
    project_servers: Option<serde_json::Value>,
) -> (tempfile::TempDir, tempfile::TempDir) {
    let home = tempfile::tempdir().expect("home tempdir");
    let workspace = tempfile::tempdir().expect("workspace tempdir");
    // The create chain requires a resolvable model (spec 11 R4 — no
    // built-in fallback), so the fixture home carries the config.toml
    // seed alongside the MCP user layer.
    seed_home_default_model(home.path());
    let mirri_home = home.path().join(".mirri-code");
    std::fs::create_dir_all(&mirri_home).expect("create mirri home dir");
    std::fs::write(
        mirri_home.join("mcp.json"),
        serde_json::json!({ "mcpServers": user_servers }).to_string(),
    )
    .expect("write user-layer mcp.json");
    if let Some(project) = project_servers {
        std::fs::write(
            workspace.path().join(".mcp.json"),
            serde_json::json!({ "mcpServers": project }).to_string(),
        )
        .expect("write project-layer .mcp.json");
    }
    (home, workspace)
}

/// Poll `list_connections` on a pool's manager until it holds `name`
/// (the lazy connect registers entries from a spawned task, so the
/// first poll may legitimately run before the task lands).
async fn wait_for_connection(manager: &Arc<mirri_mcp::McpConnectionManager>, name: &str) {
    let deadline = tokio::time::Instant::now() + std::time::Duration::from_secs(5);
    loop {
        let present = manager
            .list_connections()
            .await
            .iter()
            .any(|(conn_name, _)| conn_name == name);
        if present {
            return;
        }
        if tokio::time::Instant::now() >= deadline {
            panic!("connection '{name}' never registered in the pool");
        }
        tokio::time::sleep(std::time::Duration::from_millis(20)).await;
    }
}

/// Given an engine assembled from a home with a user-layer server, when no
/// RPC call has been made, then the user pool holds zero connections — and
/// after the first call the layer's entry is registered (the lazy-connect
/// contract: workspace-open cost is decoupled from the user layer).
#[tokio::test]
async fn should_defer_user_layer_connection_until_the_first_engine_call() {
    let (home, workspace) = layered_mcp_fixture(
        json!({"alpha": {"command": "echo", "args": [], "enabled": false}}),
        None,
    );
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("lazy-user-pool"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );
    let pool = Arc::clone(server.user_mcp_pool().expect("user pool attached"));

    // Before the first call: zero connections
    assert!(
        pool.manager().list_connections().await.is_empty(),
        "the user layer must not connect before the first engine call"
    );

    // The first call (any method) spawns the connect
    server
        .call_method("mcp.list", json!({}))
        .await
        .expect("mcp.list should succeed");

    // After: the user layer's entry is registered (Disabled — the fixture
    // never spawns a process)
    wait_for_connection(&pool.manager(), "alpha").await;
    let connections = pool.manager().list_connections().await;
    assert_eq!(connections.len(), 1, "exactly the user-layer entry");
    assert!(
        matches!(connections[0].1, mirri_mcp::McpConnectionState::Disabled),
        "a disabled fixture server must register without spawning"
    );
}

/// Given an engine whose project layer holds a slow server (a real
/// process needing >=200ms of wall clock before the connect attempt
/// settles), when the first engine call triggers the background connect
/// and the startup metrics are polled, then the measured span covers the
/// spawned connect's window (in-flight elapsed or finished duration —
/// either way >=150ms; the old stub answered a constant 0).
#[tokio::test]
async fn should_report_the_measured_mcp_initial_load_duration_when_connections_settle() {
    let (home, workspace) = layered_mcp_fixture(
        json!({}),
        Some(json!({"slow": {"command": "sleep", "args": ["0.2"]}})),
    );
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("mcp-startup-metrics"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );

    // The first call (any method) spawns the connect set
    server
        .call_method("mcp.list", json!({}))
        .await
        .expect("mcp.list should succeed");

    let deadline = tokio::time::Instant::now() + std::time::Duration::from_secs(5);
    let duration_ms = loop {
        let metrics = server
            .call_method("mcp.startupMetrics", json!({}))
            .await
            .expect("mcp.startupMetrics should succeed");
        let duration_ms = metrics["durationMs"].as_u64().unwrap_or(0);
        if duration_ms >= 150 {
            break duration_ms;
        }
        if tokio::time::Instant::now() >= deadline {
            panic!("startup metrics never reported the measured window (last: {duration_ms}ms)");
        }
        tokio::time::sleep(std::time::Duration::from_millis(20)).await;
    };
    assert!(duration_ms >= 150, "measured duration was {duration_ms}ms");
}

