/// Given two engines wired to one shared user pool (the NAPI composition),
/// when both take their first call, then only the claiming engine's user
/// layer connects — the second engine's claim is refused and its own layer
/// never registers (the desktop N-workspaces case: one connection set per
/// home, not one per workspace).
#[tokio::test]
async fn should_connect_the_user_layer_once_when_engines_share_a_pool() {
    let (home_a, workspace_a) = layered_mcp_fixture(
        json!({"alpha": {"command": "echo", "args": [], "enabled": false}}),
        None,
    );
    let (home_b, workspace_b) = layered_mcp_fixture(
        json!({"beta": {"command": "echo", "args": [], "enabled": false}}),
        None,
    );
    let engine_a = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("shared-pool-a"),
        workspace_a.path().to_path_buf(),
        Some(home_a.path().to_path_buf()),
        Vec::new(),
    );
    let shared_pool = Arc::clone(engine_a.user_mcp_pool().expect("user pool attached"));
    let engine_b = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("shared-pool-b"),
        workspace_b.path().to_path_buf(),
        Some(home_b.path().to_path_buf()),
        Vec::new(),
    )
    .with_user_mcp_pool(Arc::clone(&shared_pool));

    engine_a
        .call_method("mcp.list", json!({}))
        .await
        .expect("engine A's first call");
    engine_b
        .call_method("mcp.list", json!({}))
        .await
        .expect("engine B's first call");

    wait_for_connection(&shared_pool.manager(), "alpha").await;
    // A wrong claim from engine B would register "beta" within one
    // scheduler tick of its returned call; a short stability window is
    // enough to let that betrayal show up.
    tokio::time::sleep(std::time::Duration::from_millis(150)).await;
    let names: Vec<String> = shared_pool
        .manager()
        .list_connections()
        .await
        .into_iter()
        .map(|(name, _)| name)
        .collect();
    assert_eq!(names, vec!["alpha".to_string()]);
}

/// Given a user layer and a project layer that declare the same server
/// name, when the engine connects, then `mcp.list` shows exactly one
/// entry — the workspace one — while the shadowed user connection stays
/// alive in the user pool (spec R3: retain, do not disconnect).
#[tokio::test]
async fn should_shadow_the_user_layer_entry_when_the_project_layer_reuses_its_name() {
    let (home, workspace) = layered_mcp_fixture(
        json!({"shared": {"command": "echo", "args": [], "enabled": false}}),
        Some(json!({"shared": {"command": "cat", "args": [], "enabled": false}})),
    );
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("shadowed-user-entry"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );
    let workspace_manager = Arc::clone(server.mcp_manager().expect("workspace manager attached"));
    let pool = Arc::clone(server.user_mcp_pool().expect("user pool attached"));

    server
        .call_method("mcp.list", json!({}))
        .await
        .expect("mcp.list should succeed");

    // Both pools register their own connection for the shared name…
    wait_for_connection(&workspace_manager, "shared").await;
    wait_for_connection(&pool.manager(), "shared").await;

    // …but the effective view shows exactly one entry: the workspace's
    let result = server
        .call_method("mcp.list", json!({}))
        .await
        .expect("mcp.list should succeed");
    let entries = result.as_array().expect("bare array wire shape");
    assert_eq!(entries.len(), 1, "one entry for the shared name");
    assert_eq!(entries[0]["name"], json!("shared"));
    assert_eq!(entries[0]["pool"], json!("workspace"));
    assert_eq!(entries[0]["source"], json!("project"));
}

/// Given a user layer and a project layer that declare the same server
/// name, when `mcp.status` is called, then the global view shows BOTH
/// entries — one per pool, no shadowing (spec §4.4: the app-level config
