/// Given a persisted user-layer entry, when `mcp.config.test` addresses it
/// by scope and name, then the stored config (expanded per A5) is tested
/// — a `${VAR}`-command entry fails with the expanded value in the
/// diagnostics, and the stored file keeps its raw text.
#[tokio::test]
async fn should_expand_and_test_the_persisted_entry_when_addressed_by_scope_and_name() {
    let (home, workspace) = layered_mcp_fixture(
        json!({"persisted": {"command": "definitely-not-a-real-command-xyz", "args": [], "enabled": false}}),
        None,
    );
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("config-test-persisted"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );

    // The stored toggle is off — the connectivity test still runs (it
    // tests the entry, not its enablement).
    let result = server
        .call_method(
            "mcp.config.test",
            json!({"scope": "user", "name": "persisted"}),
        )
        .await
        .expect("mcp.config.test should succeed with a result");
    assert_eq!(result["status"], json!("error"));
    assert_eq!(result["toolCount"], json!(0));
    assert!(
        result["error"]
            .as_str()
            .unwrap_or_default()
            .contains("definitely-not-a-real-command-xyz")
    );

    // An unknown name answers the domain-coded not-found, not a result.
    let missing = server
        .call_method("mcp.config.test", json!({"scope": "user", "name": "nope"}))
        .await;
    let error = missing.expect_err("an unknown entry must not answer a result");
    assert!(
        error.to_string().contains("mcp.server_not_found") || error.to_string().contains("nope"),
        "the not-found error must name the domain and the entry: {error}"
    );

    // Missing both the config and the scope+name pair is a bad request.
    let bad = server
        .call_method("mcp.config.test", json!({}))
        .await
        .expect_err("an argument-less test must not answer a result");
    assert!(
        bad.to_string().contains("mcp.config.test takes"),
        "the missing-argument error must be the invalid-params rejection: {bad}"
    );
}

/// Given a direct-config `mcp.config.test` whose env map key carries a
/// `${VAR}` reference, when the config is expanded, then the key is left
/// verbatim — expansion is value-level only, so a key whose variable value
/// would corrupt JSON text never reaches the text layer and the config
/// still reaches the connection test intact (spec §4.6 environment row).
#[tokio::test]
async fn should_not_expand_object_keys_when_mcp_config_test_expands_direct_config() {
    // SAFETY: Test-only env vars in a uniquely named test scope.
    unsafe { std::env::set_var("MCP_TEST_DIRECT_CMD", "definitely-not-a-real-command-xyz") };
    unsafe { std::env::set_var("MCP_TEST_KEY_QUOTE", "bad\"key") };

    let (home, workspace) = layered_mcp_fixture(json!({}), None);
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("config-test-keys"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );

    // Given a direct config whose command comes from a value reference and
    // whose env *key* holds a reference whose expansion would break JSON
    // text if spliced in place of the key.
    let request = json!({"config": {
        "command": "${MCP_TEST_DIRECT_CMD}",
        "args": [],
        "env": {"${MCP_TEST_KEY_QUOTE}": "v"}
    }});

    // When the direct-config connection test runs.
    let result = server
        .call_method("mcp.config.test", request)
        .await
        .expect("the key must survive expansion intact — never spliced into JSON text");

    // Then the value reference expanded (the spawn failure names the
    // resolved command) and the key was not rewritten (the config reached
    // the connection test as valid JSON, not an invalid-JSON rejection).
    assert_eq!(result["status"], json!("error"));
    assert_eq!(result["toolCount"], json!(0));
    assert!(
        result["error"]
            .as_str()
            .unwrap_or_default()
            .contains("definitely-not-a-real-command-xyz"),
        "the failure must be the spawn error of the expanded command, proving the \
         ${{...}} env key was not rewritten: {result}"
    );

    // SAFETY: Test-only env vars restored so the uniquely named values
    // cannot leak into any later test in the same process.
    unsafe { std::env::remove_var("MCP_TEST_DIRECT_CMD") };
    unsafe { std::env::remove_var("MCP_TEST_KEY_QUOTE") };
}

/// Given a persisted user-layer server whose string values reference env
/// variables (one set in the process environment, one unset), when
/// `mcp.config.preview` addresses it by scope + name, then the response
/// carries the config with every `${VAR}` reference expanded to its
/// resolved value plus the names of the variables that stayed undefined —
/// the adjudication A5 sole sanctioned outlet for resolved values (F-4),
/// and the stored text keeps its references verbatim (nothing persists).
#[tokio::test]
async fn should_return_expanded_config_and_undefined_vars_when_preview_is_requested() {
    // SAFETY: Test-only env var in a uniquely named test scope, removed at
    // the end of the test.
    unsafe { std::env::set_var("MCP_TEST_PREVIEW_TOKEN", "no-secret") };

    let (home, workspace) = layered_mcp_fixture(
        json!({"demo": {
            "command": "echo",
            "args": ["${MCP_TEST_PREVIEW_TOKEN}"],
            "env": {
                "TOKEN": "${MCP_TEST_PREVIEW_TOKEN}",
                "MISSING": "${MCP_TEST_PREVIEW_UNDEF}"
            }
        }}),
        None,
    );
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("config-preview"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );

    // When the preview addresses the persisted entry by scope + name
    let result = server
        .call_method(
            "mcp.config.preview",
            json!({"scope": "user", "name": "demo"}),
        )
        .await
        .expect("the preview must answer the addressed entry");

    // Then the config is the wire form (the flat transport tag inferred
    // like the list view) with the resolved values in place of the
    // references, and the undefined variable is named.
    assert_eq!(result["config"]["transport"], json!("stdio"));
    assert_eq!(result["config"]["args"], json!(["no-secret"]));
    assert_eq!(result["config"]["env"]["TOKEN"], json!("no-secret"));
    assert_eq!(result["config"]["env"]["MISSING"], json!(""));
    assert_eq!(result["undefined_vars"], json!(["MCP_TEST_PREVIEW_UNDEF"]));

    // And the read never writes anything back: the stored text keeps its
    // `${VAR}` references verbatim (A5 — resolution never persists).
    let stored = std::fs::read_to_string(home.path().join(".mirri-code").join("mcp.json"))
        .expect("the user layer file must survive the preview");
    assert!(
        stored.contains("${MCP_TEST_PREVIEW_TOKEN}"),
        "the stored text must keep its references verbatim: {stored}"
    );

    // SAFETY: Test-only env var cleanup.
    unsafe { std::env::remove_var("MCP_TEST_PREVIEW_TOKEN") };
}

/// Given an unsaved config carried directly in the preview call (one
/// `${VAR}` reference to an unset variable), when `mcp.config.preview`
/// resolves it, then the undefined reference expands to the empty string
/// (the compatible semantics) and is named in `undefined_vars`, and no
/// config layer file is touched (the preview never persists anything).
#[tokio::test]
async fn should_expand_unsaved_config_when_preview_is_called_with_direct_config() {
    let (home, workspace) = layered_mcp_fixture(json!({}), None);
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("config-preview-direct"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );
    let user_layer = home.path().join(".mirri-code").join("mcp.json");
    let before =
        std::fs::read_to_string(&user_layer).expect("the seeded user layer must be readable");

    // When the preview carries the unsaved config directly
    let result = server
        .call_method(
            "mcp.config.preview",
            json!({"config": {
                "command": "echo",
                "args": ["${MCP_TEST_PREVIEW_UNSAVED}"]
            }}),
        )
        .await
        .expect("the direct-config preview must answer");

    // Then the undefined reference expanded to the empty string and is
    // named in the undefined-variable list.
    assert_eq!(result["config"]["transport"], json!("stdio"));
    assert_eq!(result["config"]["command"], json!("echo"));
    assert_eq!(result["config"]["args"], json!([""]));
    assert_eq!(
        result["undefined_vars"],
        json!(["MCP_TEST_PREVIEW_UNSAVED"])
    );

    // And nothing was persisted — every layer file keeps its exact bytes.
    let after = std::fs::read_to_string(&user_layer).expect("the user layer must stay readable");
    assert_eq!(before, after, "the preview must not write any layer");
}

