// N1/N2/N3 — the klient pluginSummarySchema / pluginInfoSchema wire shapes
// ---------------------------------------------------------------------------

/// A server with an installed plugin contributing the full surface: display
/// name, skills, two MCP servers (one disabled in-manifest), hooks, and an
/// md command — the N1/N2/N3 wire-shape fixture.
async fn plugin_summary_server() -> (EmbeddedServer, tempfile::TempDir, tempfile::TempDir) {
    let workspace = tempfile::tempdir().expect("workspace tempdir");
    let source_dir = tempfile::tempdir().expect("plugin source dir");
    std::fs::write(
        source_dir.path().join("mirri.plugin.json"),
        serde_json::json!({
            "name": "demo-plugin",
            "version": "1.2.3",
            "interface": { "displayName": "Demo Plugin" },
            "skills": ["./skills"],
            "mcpServers": {
                "helper": { "command": "node", "args": ["server.js"], "env": { "PORT": "8080" } },
                "disabler": { "command": "node", "args": ["off.js"], "enabled": false }
            },
            "hooks": [
                { "event": "PostToolUse", "command": "echo done", "matcher": "read" }
            ],
            "commands": ["./commands"]
        })
        .to_string(),
    )
    .expect("plugin manifest");
    std::fs::create_dir_all(source_dir.path().join("skills")).unwrap();
    // The skill root holds ONE real SKILL.md directory: skillCount is the
    // discovery count (D-N2), not the manifest entry count.
    std::fs::create_dir_all(source_dir.path().join("skills/reader")).unwrap();
    std::fs::write(
        source_dir.path().join("skills/reader/SKILL.md"),
        "# Reader\n",
    )
    .unwrap();
    std::fs::create_dir_all(source_dir.path().join("commands")).unwrap();
    std::fs::write(
        source_dir.path().join("commands").join("hello.md"),
        "---\nname: hello\n---\n\nHi.",
    )
    .unwrap();

    let plugins_dir = tempfile::tempdir().expect("plugins dir");
    let manager = mirri_plugin_host::PluginManager::new(plugins_dir.path().to_path_buf());
    manager
        .install(&format!("local:{}", source_dir.path().display()))
        .await
        .expect("plugin install");

    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("plugin-summary-ws"),
        workspace.path().to_path_buf(),
        None,
        Vec::new(),
    )
    .with_plugin_manager(std::sync::Arc::new(manager));
    (server, workspace, plugins_dir)
}

/// Given an installed plugin with skills, MCP servers, hooks and commands,
/// when `plugin.list` is called, then the rows match the klient
/// `pluginSummarySchema` field for field: `displayName`, the TS count
/// semantics, `source` as the wire kind string, `originalSource`, and the
/// health flags.
#[tokio::test]
async fn should_return_plugin_summary_rows_when_plugin_list_is_called() {
    let (server, _workspace, _plugins_dir) = plugin_summary_server().await;

    let result = server
        .call_method("plugin.list", json!({}))
        .await
        .expect("plugin.list should succeed");
    let rows = result.as_array().expect("bare array");
    assert_eq!(rows.len(), 1);

    let row = &rows[0];
    assert_eq!(row["id"], json!("demo-plugin"));
    assert_eq!(row["displayName"], json!("Demo Plugin"));
    assert_eq!(row["version"], json!("1.2.3"));
    assert_eq!(row["enabled"], json!(true));
    assert_eq!(row["state"], json!("ok"));
    // skillCount is the real discovery count (D-N2): one SKILL.md
    // directory under the single `./skills` manifest entry.
    assert_eq!(row["skillCount"], json!(1));
    assert_eq!(row["mcpServerCount"], json!(2));
    assert_eq!(row["enabledMcpServerCount"], json!(1));
    assert_eq!(row["hookCount"], json!(1));
    assert_eq!(row["commandCount"], json!(1));
    assert_eq!(row["hasErrors"], json!(false));
    assert_eq!(row["source"], json!("local-path"));
    // The `local:` prefix is stripped for local-path sources (the TS
    // `resolved.path` semantics), so originalSource is the absolute path.
    assert!(
        row["originalSource"]
            .as_str()
            .is_some_and(|s| s.starts_with('/')),
        "originalSource should carry the persisted source path: {row}"
    );
    assert!(row.get("github").is_none(), "no github attribution: {row}");
}

/// Given two installed plugins, when `plugin.list` is called, then the rows
/// are sorted by id; the rust `status` superset filter (D-N1) still narrows
/// by enablement.
#[tokio::test]
async fn should_sort_plugin_list_rows_and_filter_by_status_when_called() {
    let workspace = tempfile::tempdir().expect("workspace tempdir");
    let plugins_dir = tempfile::tempdir().expect("plugins dir");
    let manager = mirri_plugin_host::PluginManager::new(plugins_dir.path().to_path_buf());

    let make_source = |name: &str| {
        let dir = tempfile::tempdir().expect("plugin source dir");
        std::fs::write(
            dir.path().join("mirri.plugin.json"),
            serde_json::json!({ "name": name }).to_string(),
        )
        .unwrap();
        (format!("local:{}", dir.path().display()), dir)
    };
    let (zeta_source, _zeta_dir) = make_source("zeta-plugin");
    let (alpha_source, _alpha_dir) = make_source("alpha-plugin");
    manager.install(&zeta_source).await.expect("install zeta");
    manager.install(&alpha_source).await.expect("install alpha");
    manager.disable("alpha-plugin").expect("disable alpha");

    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("plugin-sort-ws"),
        workspace.path().to_path_buf(),
        None,
        Vec::new(),
    )
    .with_plugin_manager(std::sync::Arc::new(manager));

    // Sorted by id.
    let result = server
        .call_method("plugin.list", json!({}))
        .await
        .expect("plugin.list should succeed");
    let ids: Vec<&str> = result
        .as_array()
        .expect("bare array")
        .iter()
        .map(|row| row["id"].as_str().expect("id"))
        .collect();
    assert_eq!(ids, vec!["alpha-plugin", "zeta-plugin"]);

    // The rust `status` superset still works.
    let result = server
        .call_method("plugin.list", json!({ "status": "active" }))
        .await
        .expect("plugin.list should succeed");
    let ids: Vec<&str> = result
        .as_array()
        .expect("bare array")
        .iter()
        .map(|row| row["id"].as_str().expect("id"))
        .collect();
    assert_eq!(ids, vec!["zeta-plugin"]);

    let result = server
        .call_method("plugin.list", json!({ "status": "inactive" }))
        .await
        .expect("plugin.list should succeed");
    let ids: Vec<&str> = result
        .as_array()
        .expect("bare array")
        .iter()
        .map(|row| row["id"].as_str().expect("id"))
        .collect();
    assert_eq!(ids, vec!["alpha-plugin"]);
}

// ---------------------------------------------------------------------------
// E / J / I — runtime consumption wiring (plugin hooks, systemPrompt
// sections, skillInstructions, sessionStart)
// ---------------------------------------------------------------------------

/// A plugin source contributing the full runtime surface: hooks, a
/// systemPrompt, a `sessionStart:{skill}`, and a skill with
/// `skillInstructions` — the item E/J/I fixture.
fn write_runtime_plugin_source(source_dir: &tempfile::TempDir) {
    std::fs::create_dir_all(source_dir.path().join("skills").join("greeter")).unwrap();
    std::fs::write(
        source_dir
            .path()
            .join("skills")
            .join("greeter")
            .join("SKILL.md"),
        "# Greeter\n\nDo the demo thing.",
    )
    .unwrap();
    std::fs::write(
        source_dir.path().join("mirri.plugin.json"),
        serde_json::json!({
            "name": "demo-plugin",
            "systemPrompt": "Follow the plugin guidance.",
            "sessionStart": { "skill": "greeter" },
            "skillInstructions": "Always be helpful.",
            "skills": ["./skills"],
            "hooks": [{ "event": "SessionStart", "command": "echo plugin-start" }]
        })
        .to_string(),
    )
    .unwrap();
}

/// A server assembled over an injected home carrying an installed plugin
/// with the full runtime surface (hooks / systemPrompt / sessionStart /
/// skills + instructions) — the full bootstrap path (`for_workspace_root`),
/// where the plugin hooks merge, the plugin skill discovery, and the
/// session-creation plugin-seeding all run. Returns the server, the home,
/// and the workspace root.
async fn plugin_runtime_server() -> (EmbeddedServer, tempfile::TempDir, tempfile::TempDir) {
    let home = tempfile::tempdir().expect("home tempdir");
    let workspace = tempfile::tempdir().expect("workspace tempdir");
    // `session.create` requires a resolvable default model (spec 11 R4).
    std::fs::write(
        home.path().join("config.toml"),
        "default_model = \"test-default-model\"\n",
    )
    .expect("config.toml");
    let plugins_dir = home.path().join("plugins");
    std::fs::create_dir_all(&plugins_dir).expect("plugins dir");
    let manager = mirri_plugin_host::PluginManager::new(plugins_dir);
    let source_dir = tempfile::tempdir().expect("plugin source dir");
    write_runtime_plugin_source(&source_dir);
    manager
        .install(&format!("local:{}", source_dir.path().display()))
        .await
        .expect("plugin install");

    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("plugin-runtime-ws"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );
    (server, home, workspace)
}

/// Given an assembled server with an installed plugin declaring a hook,
/// when a session is created, then the session's hook engine carries the
/// plugin hook decorated with the runtime facts (item E): cwd pinned to the
/// plugin root and env with `MIRRICODE_HOME` / `MIRRI_PLUGIN_ROOT`.
#[tokio::test]
async fn should_wire_decorated_plugin_hooks_into_session_hook_engine_when_assembled() {
    let (server, home, _workspace) = plugin_runtime_server().await;
    let created = server
        .call_method("session.create", json!({}))
        .await
        .expect("session.create");
    let session_id = created["id"].as_str().unwrap().to_string();
    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .expect("live session");

    let hooks = session.hook_engine().list();
    assert_eq!(hooks.len(), 1);
    let hook = &hooks[0];
    assert_eq!(hook.event, HookEventType::SessionStart);
    assert_eq!(hook.command, "echo plugin-start");
    let expected_root = std::fs::canonicalize(
        home.path()
            .join("plugins")
            .join("managed")
            .join("demo-plugin"),
    )
    .expect("canonicalize the managed plugin root")
    .display()
    .to_string();
    let expected_home = home.path().display().to_string();
    assert_eq!(
        hook.cwd.as_deref(),
        Some(expected_root.as_str()),
        "the plugin hook's cwd is the plugin root"
    );
    let env = hook.env.as_ref().expect("env injected");
    assert_eq!(
        env.get("MIRRICODE_HOME").map(String::as_str),
        Some(expected_home.as_str())
    );
    assert_eq!(
        env.get("MIRRI_PLUGIN_ROOT").map(String::as_str),
        Some(expected_root.as_str())
    );
}

/// Given an assembled server with an installed plugin declaring a
/// systemPrompt and a skill root, when a session is created, then the main
/// agent's default-base prompt carries the plugin's section as a
/// `<!-- From: plugin {id} -->` block (item J) and the catalog resolves the
/// plugin skill with its instructions attribution (item J).
#[tokio::test]
async fn should_render_plugin_system_prompt_section_and_attributed_skills_when_session_created() {
    let (server, _home, _workspace) = plugin_runtime_server().await;
    let created = server
        .call_method("session.create", json!({}))
        .await
        .expect("session.create");
    let session_id = created["id"].as_str().unwrap().to_string();
    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .expect("live session");

    let agent = session
        .get_agent(&AgentId::new(DEFAULT_MAIN_AGENT_ID))
        .await
        .expect("main agent");
    let prompt = agent
        .config()
        .read()
        .unwrap_or_else(|e| e.into_inner())
        .system_prompt
        .clone()
        .expect("the default base assembled");
    assert!(
        prompt.contains("<!-- From: plugin demo-plugin -->\nFollow the plugin guidance."),
        "the plugin system-prompt section must ride the prompt: {prompt}"
    );
    assert!(
        !prompt.contains("{{plugin_sections}}"),
        "the plugin slot placeholder is substituted: {prompt}"
    );

    // The plugin skill is discovered with its attribution (source extra +
    // the TS SkillPluginContext shape).
    let skill = session
        .skill_catalog()
        .get_plugin_skill("demo-plugin", "greeter")
        .expect("plugin skill resolved by (pluginId, name)");
    assert_eq!(skill.source, mirri_core::skill::SkillSource::Plugin);
    assert_eq!(
        skill
            .plugin
            .as_ref()
            .and_then(|plugin| plugin.instructions.as_deref()),
        Some("Always be helpful.")
    );
}

/// Given a server with an installed plugin declaring `sessionStart:{skill}`
/// and a mock LLM, when the first user message runs a turn on the MAIN
/// agent, then a `<plugin_session_start>` reminder carrying the skill body
/// and the plugin's `skillInstructions` is injected into the context (item
/// I — the TS `AgentPluginService` first-turn injection), and a second turn
/// does not duplicate it.
#[tokio::test]
async fn should_inject_plugin_session_start_reminder_once_on_first_user_turn() {
    // Given a server with the plugin manager, the plugin skills discovered,
    // and a scripted mock LLM
    let tmp = tempfile::tempdir().expect("tempdir");
    let source_dir = tempfile::tempdir().expect("plugin source dir");
    write_runtime_plugin_source(&source_dir);
    let plugins_dir = tempfile::tempdir().expect("plugins dir");
    let manager = mirri_plugin_host::PluginManager::new(plugins_dir.path().to_path_buf());
    manager
        .install(&format!("local:{}", source_dir.path().display()))
        .await
        .expect("plugin install");

    let workspace = Arc::new(WorkspaceScope::new(
        WorkspaceId::new("plugin-inject-ws"),
        tmp.path().to_path_buf(),
        WorkspaceScopeConfig::default(),
    ));
    for root in manager.plugin_skill_roots() {
        workspace
            .skills()
            .discover_plugin(
                &root.path,
                &mirri_core::skill::SkillPluginContext {
                    id: root.plugin.id.clone(),
                    instructions: root.plugin.instructions.clone(),
                },
            )
            .unwrap();
    }
    let session_manager = Arc::new(SessionManager::new(workspace));
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("ok");
    mock.push_text("ok");
    let server = EmbeddedServer::with_providers(
        session_manager,
        Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))),
        None,
        None,
        None,
        test_server_config(),
        None,
    )
    .with_plugin_manager(Arc::new(manager));

    let created = server
        .call_method("session.create", json!({}))
        .await
        .expect("session.create");
    let session_id = created["id"].as_str().unwrap().to_string();

    // When the first user turn runs
    server
        .call_method(
            "message.send",
            json!({ "session_id": &session_id, "text": "hi", "mode": "wait" }),
        )
        .await
        .expect("first message.send");

    // Then the main agent's context carries the plugin session-start
    // reminder with the skill body and the instructions block
    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .expect("live session");
    let agent = session
        .get_agent(&AgentId::new(DEFAULT_MAIN_AGENT_ID))
        .await
        .expect("main agent");
    let history = agent
        .context_memory()
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .history()
        .to_vec();
    let reminders: Vec<String> = history
        .iter()
        .filter_map(injection_text)
        .filter(|text| text.contains("<plugin_session_start"))
        .collect();
    assert_eq!(reminders.len(), 1, "one reminder on the first turn");
    assert!(
        reminders[0].contains("<plugin_session_start plugin=\"demo-plugin\" skill=\"greeter\">"),
        "unexpected block: {}",
        reminders[0]
    );
    assert!(
        reminders[0].contains(
            "<kimi-plugin-instructions plugin=\"demo-plugin\">\nAlways be helpful.\n</kimi-plugin-instructions>"
        ),
        "the instructions must ride the block: {}",
        reminders[0]
    );
    assert!(reminders[0].contains("Do the demo thing."));

    // And a second turn does not duplicate the reminder (once-only)
    server
        .call_method(
            "message.send",
            json!({ "session_id": session_id, "text": "again", "mode": "wait" }),
        )
        .await
        .expect("second message.send");
    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .expect("live session");
    let agent = session
        .get_agent(&AgentId::new(DEFAULT_MAIN_AGENT_ID))
        .await
        .expect("main agent");
    let history = agent
        .context_memory()
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .history()
        .to_vec();
    let reminder_count = history
        .iter()
        .filter_map(injection_text)
        .filter(|text| text.contains("<plugin_session_start"))
        .count();
    assert_eq!(
        reminder_count, 1,
        "the session-start reminder stays once across turns"
    );
}

// ---------------------------------------------------------------------------
// C4 — reload consumer refresh (skills, hooks, profiles, MCP)
// ---------------------------------------------------------------------------

/// The `plugin.reload` consumer-refresh e2e: given an assembled server
/// with an installed plugin, when the plugin's installed copy gains a new
/// skill, a new agent profile, and a new hook (manifest rewrite) and
/// `plugin.reload` runs, then the workspace skill catalog carries the new
/// skill, the profile manager carries the new profile with `plugin`
/// provenance, a NEW session's hook engine carries the new hook — while an
/// EXISTING session's hook engine keeps its assembly-time registrations
/// (live-session hooks are assembly-time data; new sessions inherit the
/// refreshed workspace engine).
#[tokio::test]
async fn should_apply_plugin_reload_to_skills_hooks_and_profiles_when_consumers_exist() {
    // Given an assembled server with the full-surface plugin installed and
    // one session created (its hook engine snapshots the plugin hooks)
    let (server, home, _workspace) = plugin_runtime_server().await;
    let first_session = server
        .call_method("session.create", json!({}))
        .await
        .expect("session.create");
    let first_session_id = first_session["id"].as_str().unwrap().to_string();
    let first_session = server
        .session_manager()
        .get_session(&SessionId::new(&first_session_id))
        .await
        .expect("live session");
    assert_eq!(first_session.hook_engine().list().len(), 1);

    // When the installed plugin gains a skill, a profile, and a hook, and
    // `plugin.reload` runs
    let plugin_root = home
        .path()
        .join("plugins")
        .join("managed")
        .join("demo-plugin");
    std::fs::create_dir_all(plugin_root.join("skills/extra-skill")).unwrap();
    std::fs::write(
        plugin_root.join("skills/extra-skill").join("SKILL.md"),
        "# Extra skill\n\nAdded after assembly.",
    )
    .unwrap();
    std::fs::create_dir_all(plugin_root.join("agents")).unwrap();
    std::fs::write(
        plugin_root.join("agents/reviewer.md"),
        "---\nname: reviewer\ndescription: Reviews code\n---\nYou review code.",
    )
    .unwrap();
    std::fs::write(
        plugin_root.join("mirri.plugin.json"),
        serde_json::json!({
            "name": "demo-plugin",
            "systemPrompt": "Follow the plugin guidance.",
            "sessionStart": { "skill": "greeter" },
            "skillInstructions": "Always be helpful.",
            "skills": ["./skills"],
            "agents": ["./agents"],
            "hooks": [
                { "event": "SessionStart", "command": "echo plugin-start" },
                { "event": "Notification", "command": "echo plugin-reloaded" }
            ]
        })
        .to_string(),
    )
    .unwrap();
    server
        .call_method("plugin.reload", json!({ "pluginId": "demo-plugin" }))
        .await
        .expect("plugin.reload");

    // Then the shared skill catalog carries the new plugin skill
    let session_manager = server.session_manager();
    let workspace_skills = session_manager.workspace().skills();
    let extra = workspace_skills
        .get("extra-skill")
        .expect("the reloaded plugin skill must be discovered");
    assert_eq!(
        extra.source,
        mirri_core::skill::SkillSource::Plugin,
        "the reloaded skill is plugin-sourced"
    );

    // And the profile manager carries the plugin profile with `plugin`
    // provenance
    let reviewer = server
        .profile_manager
        .as_ref()
        .expect("server profile manager")
        .get("reviewer")
        .expect("the reloaded plugin profile must be registered");
    assert_eq!(
        reviewer.system_prompt.as_deref().unwrap_or_default(),
        "You review code."
    );
    let provenance = server
        .profile_manager
        .as_ref()
        .expect("server profile manager")
        .provenance("reviewer")
        .expect("plugin profile provenance");
    assert_eq!(
        provenance.source,
        mirri_core::profile::ProfileSource::Plugin,
        "the reloaded plugin profile carries the plugin source"
    );

    // And a NEW session's hook engine carries the new hook, while the
    // EXISTING session keeps its assembly-time hook set
    let second_session = server
        .call_method("session.create", json!({}))
        .await
        .expect("session.create");
    let second_session_id = second_session["id"].as_str().unwrap().to_string();
    let second_session = server
        .session_manager()
        .get_session(&SessionId::new(&second_session_id))
        .await
        .expect("live session");
    let second_hooks = second_session.hook_engine().list();
    assert_eq!(
        second_hooks.len(),
        2,
        "the new session inherits the refreshed workspace hook engine"
    );
    assert!(
        second_hooks
            .iter()
            .any(|hook| hook.command == "echo plugin-reloaded"),
        "the new session sees the reloaded plugin hook"
    );
    assert_eq!(
        first_session.hook_engine().list().len(),
        1,
        "an existing session keeps its assembly-time hook registrations"
    );
}

/// The joined text of an injection-origin message, for the injection
/// assertions above.
fn injection_text(message: &mirri_core::ContextMessage) -> Option<String> {
    if message.origin.as_ref() != Some(&mirri_core::origin::PromptOrigin::Injection) {
        return None;
    }
    let mut text = String::new();
    for part in &message.message.content {
        if let mirri_core::message::ContentPart::Text { text: part_text } = part {
            text.push_str(part_text);
        }
    }
    Some(text)
}

/// Given a plugin source, when `plugin.install` is called with the TS bare
/// absolute-path syntax (A1), then the success body is the full klient
/// `pluginSummarySchema` row of the installed plugin, not the historical
/// `{id, ok}`.
#[tokio::test]
async fn should_return_plugin_summary_when_plugin_install_is_called() {
    let workspace = tempfile::tempdir().expect("workspace tempdir");
    let source_dir = tempfile::tempdir().expect("plugin source dir");
    std::fs::write(
        source_dir.path().join("mirri.plugin.json"),
        serde_json::json!({
            "name": "install-me",
            "interface": { "displayName": "Install Me" },
            "mcpServers": { "helper": { "command": "node" } }
        })
        .to_string(),
    )
    .expect("plugin manifest");

    let plugins_dir = tempfile::tempdir().expect("plugins dir");
    let manager = mirri_plugin_host::PluginManager::new(plugins_dir.path().to_path_buf());
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("plugin-install-ws"),
        workspace.path().to_path_buf(),
        None,
        Vec::new(),
    )
    .with_plugin_manager(std::sync::Arc::new(manager));

    // TS grammar: a bare absolute path, no `local:` prefix (A1).
    let result = server
        .call_method(
            "plugin.install",
            json!({ "source": source_dir.path().display().to_string() }),
        )
        .await
        .expect("plugin.install should succeed");

    assert_eq!(result["id"], json!("install-me"));
    assert_eq!(result["displayName"], json!("Install Me"));
    assert_eq!(result["enabled"], json!(true));
    assert_eq!(result["state"], json!("ok"));
    assert_eq!(result["mcpServerCount"], json!(1));
    assert_eq!(result["skillCount"], json!(0));
    assert_eq!(result["hookCount"], json!(0));
    assert_eq!(result["commandCount"], json!(0));
    assert_eq!(result["source"], json!("local-path"));
    assert_eq!(
        result["originalSource"],
        json!(source_dir.path().display().to_string())
    );
    assert_eq!(result["hasErrors"], json!(false));
}

/// Given an installed plugin, when `plugin.info` is called, then the row
/// matches the klient `pluginInfoSchema`: the summary super-set plus root,
/// installedAt, updatedAt, manifestKind, manifestPath, the wire manifest,
/// per-server info, and diagnostics (N3/L).
#[tokio::test]
async fn should_return_plugin_info_when_plugin_info_is_called() {
    let (server, _workspace, _plugins_dir) = plugin_summary_server().await;

    let result = server
        .call_method("plugin.info", json!({ "id": "demo-plugin" }))
        .await
        .expect("plugin.info should succeed");

    // Summary super-set.
    assert_eq!(result["id"], json!("demo-plugin"));
    assert_eq!(result["displayName"], json!("Demo Plugin"));
    assert_eq!(result["state"], json!("ok"));
    assert_eq!(result["source"], json!("local-path"));

    // Install metadata.
    assert!(
        result["root"].as_str().unwrap().ends_with("demo-plugin"),
        "root is the plugin directory: {result}"
    );
    assert!(
        result["installedAt"]
            .as_str()
            .is_some_and(|s| !s.is_empty()),
        "installedAt is an ISO string: {result}"
    );
    assert!(
        result["updatedAt"].as_str().is_some_and(|s| !s.is_empty()),
        "updatedAt is an ISO string: {result}"
    );

    // Manifest location.
    assert_eq!(result["manifestKind"], json!("kimi-plugin-root"));
    assert!(
        result["manifestPath"]
            .as_str()
            .is_some_and(|p| p.ends_with("mirri.plugin.json"))
    );

    // Wire manifest (klient pluginManifestSchema).
    let manifest = result["manifest"].clone();
    assert_eq!(manifest["name"], json!("demo-plugin"));
    assert_eq!(manifest["interface"]["displayName"], json!("Demo Plugin"));
    assert_eq!(manifest["mcpServers"]["disabler"]["enabled"], json!(false));
    let commands = manifest["commands"].as_array().expect("commands array");
    assert_eq!(commands.len(), 1);
    assert!(commands[0]["name"].is_string());
    assert!(commands[0]["path"].is_string());
    let hooks = manifest["hooks"].as_array().expect("hooks array");
    assert_eq!(hooks.len(), 1);
    assert_eq!(hooks[0]["event"], json!("PostToolUse"));
    assert_eq!(hooks[0]["matcher"], json!("read"));

    // Per-server info rows (klient pluginMcpServerInfo), sorted by name.
    let servers = result["mcpServers"].as_array().expect("mcpServers array");
    assert_eq!(servers.len(), 2);
    assert_eq!(servers[0]["name"], json!("disabler"));
    assert_eq!(
        servers[0]["runtimeName"],
        json!("plugin-demo-plugin:disabler")
    );
    assert_eq!(servers[0]["transport"], json!("stdio"));
    assert_eq!(servers[0]["enabled"], json!(false));
    assert_eq!(servers[0]["command"], json!("node"));
    assert_eq!(servers[1]["name"], json!("helper"));
    assert_eq!(servers[1]["enabled"], json!(true));
    assert_eq!(
        servers[1]["envKeys"],
        json!(["PORT"]),
        "envKeys is the sorted env key names"
    );
    assert!(servers[1].get("url").is_none());

    // Diagnostics and no shadowed manifest.
    assert_eq!(result["diagnostics"], json!([]));
    assert!(result.get("shadowedManifestPath").is_none());
}

/// Given a plugin that fails to parse, when `plugin.list` and `plugin.info`
/// are called, then the error-state plugin stays in the list with
/// `state: 'error'`/`hasErrors: true` and the info row still carries its
/// diagnostics (the B2/K model on the new wire shapes). Install refuses an
/// unusable manifest (TS semantics), so the broken plugin is seeded through
/// the store and picked up by `load_all`.
#[tokio::test]
async fn should_keep_error_state_plugin_in_list_and_info_when_manifest_is_broken() {
    let workspace = tempfile::tempdir().expect("workspace tempdir");
    let plugins_dir = tempfile::tempdir().expect("plugins dir");
    let plugins_root = plugins_dir.path().to_path_buf();
    // A plugin directory whose manifest is unreadable.
    std::fs::create_dir_all(plugins_root.join("broken-plugin")).unwrap();
    std::fs::write(
        plugins_root.join("broken-plugin").join("mirri.plugin.json"),
        r#"{ not json "#,
    )
    .expect("broken manifest");
    let now = chrono::Utc::now();
    mirri_plugin_host::PluginStore::new(&plugins_root)
        .add(mirri_plugin_host::InstalledPlugin {
            id: "broken-plugin".to_string(),
            version: None,
            source: mirri_plugin_host::PluginSource::Local {
                path: "/source".to_string(),
            },
            original_source: Some("/source".to_string()),
            enabled: true,
            installed_at: now,
            updated_at: now,
            path: plugins_root.join("broken-plugin"),
            github_ref: None,
            installed_sha: None,
            mcp_servers: std::collections::HashMap::new(),
        })
        .expect("seed broken record");

    let manager = mirri_plugin_host::PluginManager::new(plugins_root);
    manager
        .load_all()
        .expect("load_all keeps error-state plugins");
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("plugin-error-ws"),
        workspace.path().to_path_buf(),
        None,
        Vec::new(),
    )
    .with_plugin_manager(std::sync::Arc::new(manager));

    let result = server
        .call_method("plugin.list", json!({}))
        .await
        .expect("plugin.list should succeed");
    let rows = result.as_array().expect("bare array");
    assert_eq!(rows.len(), 1);
    assert_eq!(rows[0]["state"], json!("error"));
    assert_eq!(rows[0]["hasErrors"], json!(true));
    assert_eq!(rows[0]["skillCount"], json!(0));

    // info must find the id under the record id (manifest name unreadable).
    let id = rows[0]["id"].as_str().expect("id");
    let result = server
        .call_method("plugin.info", json!({ "id": id }))
        .await
        .expect("plugin.info should succeed");
    assert_eq!(result["state"], json!("error"));
    assert!(result["hasErrors"] == json!(true));
    assert_eq!(
        result["diagnostics"]
            .as_array()
            .expect("diagnostics array")
            .len(),
        1
    );
    assert_eq!(result["diagnostics"][0]["severity"], json!("error"));
    assert!(
        result.get("manifest").is_none(),
        "no wire manifest for an unparseable one"
    );
}

/// A stub GitHub resolver for the update-check tests — canned answers per
/// repo, so the wire test never touches the network.
struct StubGithubResolver {
    commit_shas: std::collections::HashMap<String, String>,
    latest_refs: std::collections::HashMap<String, (mirri_plugin_host::GithubRef, String)>,
    failing: std::collections::HashSet<String>,
}

impl mirri_plugin_host::GithubResolver for StubGithubResolver {
    fn resolve_commit_sha<'a>(
        &'a self,
        repo: &'a str,
        _ref_name: &'a str,
    ) -> mirri_plugin_host::ResolverFuture<'a, String> {
        Box::pin(async move {
            if self.failing.contains(repo) {
                return Err(format!("stub: {repo} unreachable"));
            }
            self.commit_shas
                .get(repo)
                .cloned()
                .ok_or_else(|| format!("stub: no SHA configured for {repo}"))
        })
    }

    fn resolve_latest_ref<'a>(
        &'a self,
        repo: &'a str,
    ) -> mirri_plugin_host::ResolverFuture<'a, (mirri_plugin_host::GithubRef, String)> {
        Box::pin(async move {
            if self.failing.contains(repo) {
                return Err(format!("stub: {repo} unreachable"));
            }
            self.latest_refs
                .get(repo)
                .cloned()
                .ok_or_else(|| format!("stub: no latest ref configured for {repo}"))
        })
    }
}

