#[tokio::test]
async fn should_return_sorted_update_statuses_when_github_plugins_are_installed() {
    const SHA: &str = "0123456789abcdef0123456789abcdef01234567";

    // Given a plugins dir whose installed.json carries three github records in
    // the TS v1 shape (a pinned SHA, an unpinned HEAD follower, and one
    // whose repo is unreachable) and a stub resolver with canned answers
    let plugins_dir = tempfile::tempdir().expect("plugins dir");
    let records = json!({
        "version": 1,
        "plugins": [
            {
                "id": "zeta-plugin",
                "root": plugins_dir.path().join("managed/zeta-plugin"),
                "source": "github",
                "enabled": true,
                "installedAt": "2024-01-01T00:00:00Z",
                "updatedAt": "2024-01-01T00:00:00Z",
                "github": {
                    "owner": "zeta",
                    "repo": "repo",
                    "ref": {"kind": "branch", "value": "HEAD"},
                    "installedSha": SHA,
                },
            },
            {
                "id": "pinned-plugin",
                "root": plugins_dir.path().join("managed/pinned-plugin"),
                "source": "github",
                "enabled": true,
                "installedAt": "2024-01-01T00:00:00Z",
                "updatedAt": "2024-01-01T00:00:00Z",
                "originalSource": "https://github.com/pin/repo/commit/0123456789abcdef0123456789abcdef01234567",
                "github": {
                    "owner": "pin",
                    "repo": "repo",
                    "ref": {"kind": "sha", "value": SHA},
                    "installedSha": SHA,
                },
            },
            {
                "id": "alpha-plugin",
                "root": plugins_dir.path().join("managed/alpha-plugin"),
                "source": "github",
                "enabled": true,
                "installedAt": "2024-01-01T00:00:00Z",
                "updatedAt": "2024-01-01T00:00:00Z",
                "github": {
                    "owner": "alpha",
                    "repo": "repo",
                    "ref": {"kind": "branch", "value": "HEAD"},
                    "installedSha": SHA,
                },
            },
        ],
    });
    std::fs::write(
        plugins_dir.path().join("installed.json"),
        serde_json::to_string_pretty(&records).unwrap(),
    )
    .unwrap();

    let mut stub = StubGithubResolver {
        commit_shas: std::collections::HashMap::new(),
        latest_refs: std::collections::HashMap::new(),
        failing: std::collections::HashSet::new(),
    };
    stub.commit_shas
        .insert("zeta/repo".to_string(), SHA.to_string());
    stub.latest_refs.insert(
        "zeta/repo".to_string(),
        (
            mirri_plugin_host::GithubRef::branch("HEAD"),
            "HEAD".to_string(),
        ),
    );
    stub.failing.insert("alpha/repo".to_string());
    let manager = Arc::new(mirri_plugin_host::PluginManager::new_with_github_resolver(
        plugins_dir.path().to_path_buf(),
        Arc::new(stub),
    ));
    let (server, _tmp) = test_server(None);
    let server = server.with_plugin_manager(manager);

    // When checking plugins for updates
    let result = server
        .call_method("plugin.checkUpdates", json!({}))
        .await
        .expect("plugin.checkUpdates should succeed");

    // Then the result is the klient `pluginUpdateStatusSchema` array,
    // field for field: the unreachable repo is skipped, the rest sorted
    // by id — a pinned SHA reports no update, the HEAD follower whose
    // resolved SHA still matches the installed one reports none either.
    assert_eq!(
        result,
        json!([
            {
                "id": "pinned-plugin",
                "source": "github",
                "current": {"kind": "sha", "value": SHA},
                "latest": {"kind": "sha", "value": SHA},
                "displayVersion": SHA,
                "updateAvailable": false,
            },
            {
                "id": "zeta-plugin",
                "source": "github",
                "current": {"kind": "branch", "value": "HEAD"},
                "latest": {"kind": "branch", "value": "HEAD"},
                "displayVersion": "HEAD",
                "updateAvailable": false,
            },
        ])
    );
}

#[tokio::test]
async fn should_return_not_implemented_for_mcp_reconnect_when_no_manager_configured() {
    // Given a server without an MCP manager
    let (server, _tmp) = test_server(None);

    // When reconnecting an MCP server
    let error = server
        .call_method("mcp.reconnect", json!({ "name": "test-server" }))
        .await
        .expect_err("mcp.reconnect without an MCP manager must not silently succeed");

    // Then it fails with an explicit not_implemented error (not the former
    // `{"ok": true, "note": ...}` silent acknowledgement)
    assert!(
        matches!(
            error,
            EngineError::Rpc { code: -32603, data: Some(ref data), .. }
                if data.get("domainCode").and_then(Value::as_str) == Some("not_implemented")
        ),
        "error: {error}"
    );
}

#[tokio::test]
async fn should_return_error_status_when_test_connect_called_without_manager() {
    // Given a server without an MCP manager
    let (server, _tmp) = test_server(None);

    // When testing connectivity to an MCP server
    let result = server
        .call_method("mcp.global.testConnect", json!({ "name": "test" }))
        .await
        .expect("testConnect should succeed");

    // Then the response reports an error status
    assert_eq!(result["status"], "error");
    assert_eq!(result["toolCount"], 0);
}

#[tokio::test]
async fn should_return_not_implemented_when_retired_mcp_methods_are_called() {
    // Given a server (with or without an MCP manager; the retired methods
    // must never run a real manager path)
    let (server, _tmp) = test_server(None);
    let manager = Arc::new(mirri_mcp::McpConnectionManager::new());
    let server = server.with_mcp_manager(manager);

    let retired = [
        "mcp.enable",
        "mcp.disable",
        "mcp.enableTool",
        "mcp.disableTool",
        "mcp.global.update",
        "mcp.global.delete",
        "mcp.global.toggle",
        "mcp.global.reload",
    ];

    // When each retired method is called with plausible params
    // Then it fails with an explicit not_implemented error (not the former
    // silent acknowledgement, and not a silent real operation)
    for method in retired {
        let error = server
            .call_method(
                method,
                json!({ "name": "demo", "server": "demo", "tool": "demo" }),
            )
            .await
            .expect_err("{method} must not silently succeed (P9)");
        assert!(
            matches!(
                error,
                EngineError::Rpc { code: -32603, data: Some(ref data), .. }
                    if data.get("domainCode").and_then(Value::as_str) == Some("not_implemented")
            ),
            "{method} must answer not_implemented, got: {error}"
        );
    }
}

// ---------------------------------------------------------------------------
// mcp.config.* — the P1 layered configuration surface (batch 3)
// ---------------------------------------------------------------------------

/// A `for_workspace_root` server over an injected home (the user layer:
/// `<home>/.mirri-code/mcp.json`) and a throwaway workspace root (the
/// project layers: `<root>/.mcp.json` and `<root>/.mirri-code/mcp.json`).
fn mcp_config_test_server() -> (EmbeddedServer, tempfile::TempDir, tempfile::TempDir) {
    let home = tempfile::tempdir().expect("home tempdir");
    let workspace = tempfile::tempdir().expect("workspace tempdir");
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("mcp-config-ws"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );
    (server, home, workspace)
}

/// Write one raw config file (creating parent directories as needed).
fn write_mcp_config(path: &std::path::Path, contents: &str) {
    if let Some(dir) = path.parent() {
        std::fs::create_dir_all(dir).expect("create config dir");
    }
    std::fs::write(path, contents).expect("write config");
}

/// Index a `mcp.config.list` result by server name.
fn mcp_config_entries(listed: &serde_json::Value) -> HashMap<String, serde_json::Value> {
    listed
        .as_array()
        .expect("the list result is an array")
        .iter()
        .map(|entry| {
            (
                entry["name"].as_str().expect("entry name").to_string(),
                entry.clone(),
            )
        })
        .collect()
}

/// Given all three config layers, when the merged view is listed, then each
/// server appears once with its effective layer's entry: the local layer
/// replaces the user-layer `alpha` (source `project`), the project-root
/// `beta` keeps its own, and the user-only `omega` survives.
#[tokio::test]
async fn should_merge_the_three_layers_when_mcp_config_list_is_called_without_scope() {
    let (server, home, workspace) = mcp_config_test_server();
    write_mcp_config(
        &home.path().join(".mirri-code").join("mcp.json"),
        r#"{"mcpServers":{"alpha":{"transport":"stdio","command":"user-alpha"},"omega":{"transport":"stdio","command":"user-omega"}}}"#,
    );
    write_mcp_config(
        &workspace.path().join(".mcp.json"),
        r#"{"mcpServers":{"beta":{"transport":"stdio","command":"root-beta"}}}"#,
    );
    write_mcp_config(
        &workspace.path().join(".mirri-code").join("mcp.json"),
        r#"{"mcpServers":{"alpha":{"transport":"stdio","command":"local-alpha"},"gamma":{"transport":"stdio","command":"local-gamma"}}}"#,
    );

    let listed = server
        .call_method("mcp.config.list", json!({}))
        .await
        .expect("the merged view must list");

    let entries = mcp_config_entries(&listed);
    assert_eq!(entries.len(), 4, "one entry per server name: {listed}");
    assert_eq!(entries["alpha"]["source"], "project");
    assert_eq!(entries["alpha"]["config"]["command"], "local-alpha");
    assert_eq!(entries["beta"]["source"], "projectRoot");
    assert_eq!(entries["gamma"]["source"], "project");
    assert_eq!(entries["omega"]["source"], "user");
    assert_eq!(
        entries["omega"]["effective"]["enabled"], true,
        "an omitted enabled field defaults to enabled"
    );
}

/// Given all three config layers, when the view is scoped, then `user`
/// lists the user file as stored and `workspace` lists the two project
/// layers merged — never the user layer.
#[tokio::test]
async fn should_return_the_scoped_layer_view_when_mcp_config_list_is_called_with_scope() {
    let (server, home, workspace) = mcp_config_test_server();
    write_mcp_config(
        &home.path().join(".mirri-code").join("mcp.json"),
        r#"{"mcpServers":{"alpha":{"transport":"stdio","command":"user-alpha"}}}"#,
    );
    write_mcp_config(
        &workspace.path().join(".mcp.json"),
        r#"{"mcpServers":{"beta":{"transport":"stdio","command":"root-beta"}}}"#,
    );
    write_mcp_config(
        &workspace.path().join(".mirri-code").join("mcp.json"),
        r#"{"mcpServers":{"alpha":{"transport":"stdio","command":"local-alpha"}}}"#,
    );

    let user_view = server
        .call_method("mcp.config.list", json!({ "scope": "user" }))
        .await
        .expect("the user view must list");
    let user_entries = mcp_config_entries(&user_view);
    assert_eq!(user_entries.len(), 1, "user view: {user_view}");
    assert_eq!(user_entries["alpha"]["source"], "user");
    assert_eq!(
        user_entries["alpha"]["config"]["command"], "user-alpha",
        "the user view shows the user file as stored, not the merged override"
    );

    let workspace_view = server
        .call_method("mcp.config.list", json!({ "scope": "workspace" }))
        .await
        .expect("the workspace view must list");
    let workspace_entries = mcp_config_entries(&workspace_view);
    assert_eq!(
        workspace_entries.len(),
        2,
        "workspace view: {workspace_view}"
    );
    assert_eq!(workspace_entries["alpha"]["source"], "project");
    assert_eq!(workspace_entries["beta"]["source"], "projectRoot");
}

/// Given a stored Claude-form entry (no `transport` key) carrying a `${VAR}`
/// reference and server-level overrides, when the view is listed, then the
/// presented config infers the flat transport tag while keeping every other
/// byte verbatim (A5), and the effective view derives the parsed state.
#[tokio::test]
async fn should_present_stored_text_and_derive_effective_state_when_mcp_config_list_is_called() {
    let (server, home, _workspace) = mcp_config_test_server();
    write_mcp_config(
        &home.path().join(".mirri-code").join("mcp.json"),
        r#"{"mcpServers":{"classic":{"command":"npx","args":["${MY_SECRET_VAR}/x"],"enabled":false,"enabledTools":["only-this"],"startupTimeoutMs":5000}}}"#,
    );

    let listed = server
        .call_method("mcp.config.list", json!({}))
        .await
        .expect("the view must list");

    let entries = mcp_config_entries(&listed);
    let classic = &entries["classic"];
    assert_eq!(classic["config"]["transport"], "stdio");
    assert_eq!(
        classic["config"]["args"][0], "${MY_SECRET_VAR}/x",
        "the stored ${{VAR}} reference is never expanded on this surface (A5)"
    );
    assert_eq!(classic["effective"]["enabled"], false);
    assert_eq!(classic["effective"]["enabledTools"], json!(["only-this"]));
    assert_eq!(classic["effective"]["startupTimeoutMs"], 5000);
}

/// Given layered entries whose effective state crosses layers — a
/// project-root complete entry carrying `enabledTools` with a local
/// connection-only redefinition of the same name (the A7 inheritance
/// shape), and a user-layer complete entry with a local filter-only
/// override (the cross-pool shape `setToolFilter` writes) — when the
/// merged and workspace views are listed, then each entry's `effective`
/// field carries the A7 family merge, not the top layer's stored fields
/// alone (the read-modify-write flows round-trip the merged truth).
#[tokio::test]
async fn should_derive_the_effective_state_from_the_layer_merge_when_mcp_config_list_is_called() {
    let (server, home, workspace) = mcp_config_test_server();
    write_mcp_config(
        &home.path().join(".mirri-code").join("mcp.json"),
        r#"{"mcpServers":{"db":{"transport":"stdio","command":"user-cmd"}}}"#,
    );
    write_mcp_config(
        &workspace.path().join(".mcp.json"),
        r#"{"mcpServers":{"beta":{"transport":"stdio","command":"root-beta","enabledTools":["beta.get"]}}}"#,
    );
    write_mcp_config(
        &workspace.path().join(".mirri-code").join("mcp.json"),
        r#"{"mcpServers":{"beta":{"transport":"stdio","command":"local-beta"},"db":{"disabledTools":["db.query"]}}}"#,
    );

    let listed = server
        .call_method("mcp.config.list", json!({}))
        .await
        .expect("the merged view must list");
    let entries = mcp_config_entries(&listed);

    // The local entry surfaces (its layer owns the slot) but the effective
    // state is the merge: the local connection with the root layer's
    // inherited allowlist.
    assert_eq!(entries["beta"]["source"], "project");
    assert_eq!(entries["beta"]["config"]["command"], "local-beta");
    assert_eq!(
        entries["beta"]["effective"]["enabledTools"],
        json!(["beta.get"]),
        "the effective view inherits the shadowed root layer's filter"
    );
    // The cross-pool shape: the user layer's connection with the local
    // filter-only override applied.
    assert_eq!(
        entries["db"]["effective"]["disabledTools"],
        json!(["db.query"]),
        "the effective view applies the local filter-only override to the user-layer server"
    );

    // The workspace view derives from the same project merge.
    let workspace_view = server
        .call_method("mcp.config.list", json!({ "scope": "workspace" }))
        .await
        .expect("the workspace view must list");
    let workspace_entries = mcp_config_entries(&workspace_view);
    assert_eq!(
        workspace_entries["beta"]["effective"]["enabledTools"],
        json!(["beta.get"]),
        "the scoped view derives the effective state from the same A7 merge"
    );

    // The user view stays the stored file as it is — no cross-layer merge.
    let user_view = server
        .call_method("mcp.config.list", json!({ "scope": "user" }))
        .await
        .expect("the user view must list");
    let user_entries = mcp_config_entries(&user_view);
    assert!(
        user_entries["db"]["effective"]
            .get("disabledTools")
            .is_none(),
        "the single-layer user view keeps the stored derivation"
    );
}

/// Given a project-local filter-only override of a name whose complete
/// entry lives in the project-root layer, when the preview resolves the
/// persisted entry, then it answers the shadowed layer's complete entry —
/// the placeholder transport a filter-only entry would normalize to never
/// reaches the resolved-value surface.
#[tokio::test]
async fn should_resolve_the_shadowed_complete_entry_when_preview_addresses_a_filter_only_name() {
    let (server, _home, workspace) = mcp_config_test_server();
    write_mcp_config(
        &workspace.path().join(".mcp.json"),
        r#"{"mcpServers":{"beta":{"transport":"stdio","command":"root-beta","args":["${MCP_TEST_OVERRIDE_LOOKUP}"]}}}"#,
    );
    write_mcp_config(
        &workspace.path().join(".mirri-code").join("mcp.json"),
        r#"{"mcpServers":{"beta":{"disabledTools":["beta.query"]}}}"#,
    );

    let preview = server
        .call_method(
            "mcp.config.preview",
            json!({"scope": "workspace", "name": "beta"}),
        )
        .await
        .expect("the preview must resolve through the override");
    assert_eq!(
        preview["config"]["command"], "root-beta",
        "the preview answers the shadowed complete entry, never the filter-only override"
    );
    assert_eq!(
        preview["config"]["args"],
        json!([""]),
        "the resolved-value outlet keeps its semantics through the override"
    );
    assert_eq!(
        preview["undefined_vars"],
        json!(["MCP_TEST_OVERRIDE_LOOKUP"]),
        "the undefined reference is named as usual"
    );
}

/// Given set calls for both scopes, when they succeed, then `user` lands in
/// the global file and `workspace` in the project layer only — the
/// project-root `.mcp.json` stays untouched (A2).
#[tokio::test]
async fn should_write_the_addressed_file_when_mcp_config_set_is_called() {
    let (server, home, workspace) = mcp_config_test_server();

    server
        .call_method(
            "mcp.config.set",
            json!({ "scope": "user", "name": "remote", "config": { "transport": "http", "url": "https://example.test/mcp" } }),
        )
        .await
        .expect("user-scope set must succeed");
    server
        .call_method(
            "mcp.config.set",
            json!({ "scope": "workspace", "name": "local", "config": { "transport": "stdio", "command": "node", "args": ["${HOME}/server.js"] } }),
        )
        .await
        .expect("workspace-scope set must succeed");
    // The positional tuple spelling is accepted alongside the named object
    // (the same tolerance the other v2 routes carry).
    server
        .call_method(
            "mcp.config.set",
            json!(["user", "positional", { "transport": "stdio", "command": "node" }]),
        )
        .await
        .expect("the positional spelling must be accepted");

    let user_file: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(home.path().join(".mirri-code").join("mcp.json"))
            .expect("the user file exists after set"),
    )
    .expect("the user file parses");
    assert_eq!(
        user_file["mcpServers"]["remote"]["url"],
        "https://example.test/mcp"
    );

    let local_file: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(workspace.path().join(".mirri-code").join("mcp.json"))
            .expect("the project-local file exists after set"),
    )
    .expect("the project-local file parses");
    assert_eq!(local_file["mcpServers"]["local"]["command"], "node");
    assert_eq!(
        local_file["mcpServers"]["local"]["args"][0], "${HOME}/server.js",
        "the stored form keeps the ${{VAR}} reference (A5)"
    );
    assert!(
        !workspace.path().join(".mcp.json").exists(),
        "the workspace scope never writes the project-root file (A2)"
    );
}

/// Given a plugin-bundled server name or an unconnectable config, when set
/// is called, then the write is rejected client-side — plugin connection
/// definitions are read-only (A1) and an illegal config names its server.
#[tokio::test]
async fn should_reject_plugin_names_and_invalid_configs_when_mcp_config_set_is_called() {
    let (server, _home, _workspace) = mcp_config_test_server();

    let plugin_error = server
        .call_method(
            "mcp.config.set",
            json!({ "scope": "user", "name": "plugin-demo:helper", "config": { "transport": "stdio", "command": "node" } }),
        )
        .await
        .expect_err("plugin names must be rejected (A1)");
    assert!(
        matches!(plugin_error, EngineError::Rpc { code: -32602, ref message, .. }
            if message.contains("plugin")),
        "error: {plugin_error}"
    );

    let invalid_error = server
        .call_method(
            "mcp.config.set",
            json!({ "scope": "user", "name": "broken", "config": { "transport": "stdio" } }),
        )
        .await
        .expect_err("a config without command/url must be rejected");
    assert!(
        matches!(invalid_error, EngineError::Rpc { code: -32602, ref message, .. }
            if message.contains("broken")),
        "the rejection names the server: {invalid_error}"
    );
}

/// Given entries in both scopes, when remove is called, then each addressed
/// file loses its entry and removing an absent name stays an idempotent
/// success.
#[tokio::test]
async fn should_remove_entries_and_stay_idempotent_when_mcp_config_remove_is_called() {
    let (server, home, workspace) = mcp_config_test_server();
    write_mcp_config(
        &home.path().join(".mirri-code").join("mcp.json"),
        r#"{"mcpServers":{"alpha":{"transport":"stdio","command":"a"},"omega":{"transport":"stdio","command":"o"}}}"#,
    );
    write_mcp_config(
        &workspace.path().join(".mirri-code").join("mcp.json"),
        r#"{"mcpServers":{"beta":{"transport":"stdio","command":"b"}}}"#,
    );

    server
        .call_method(
            "mcp.config.remove",
            json!({ "scope": "user", "name": "alpha" }),
        )
        .await
        .expect("user-scope remove must succeed");
    server
        .call_method(
            "mcp.config.remove",
            json!({ "scope": "workspace", "name": "beta" }),
        )
        .await
        .expect("workspace-scope remove must succeed");
    server
        .call_method(
            "mcp.config.remove",
            json!({ "scope": "user", "name": "alpha" }),
        )
        .await
        .expect("removing an absent name stays an idempotent success");

    let user_file: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(home.path().join(".mirri-code").join("mcp.json")).unwrap(),
    )
    .unwrap();
    assert!(user_file["mcpServers"].get("alpha").is_none());
    assert!(user_file["mcpServers"]["omega"].is_object());
    let local_file: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(workspace.path().join(".mirri-code").join("mcp.json")).unwrap(),
    )
    .unwrap();
    assert!(local_file["mcpServers"].get("beta").is_none());
}

/// Given one server defined only in the user layer and another shadowed by
/// the project layer, when a tool filter is set, then the patch lands in
/// the highest-priority layer defining the name; a name no layer defines
/// answers a domain-coded not-found (as does a plugin-bundled name when no
/// plugin support is configured — the plugin path lands with the plugin
/// user state, batch 3c).
#[tokio::test]
async fn should_patch_the_owning_layer_when_mcp_config_set_tool_filter_is_called() {
    let (server, home, workspace) = mcp_config_test_server();
    write_mcp_config(
        &home.path().join(".mirri-code").join("mcp.json"),
        r#"{"mcpServers":{"solo":{"transport":"stdio","command":"a"},"shadowed":{"transport":"stdio","command":"u"}}}"#,
    );
    write_mcp_config(
        &workspace.path().join(".mirri-code").join("mcp.json"),
        r#"{"mcpServers":{"shadowed":{"transport":"stdio","command":"l"}}}"#,
    );

    server
        .call_method(
            "mcp.config.setToolFilter",
            json!({ "name": "solo", "filter": { "enabledTools": ["one", "two"] } }),
        )
        .await
        .expect("patching the user-layer owner must succeed");
    server
        .call_method(
            "mcp.config.setToolFilter",
            json!({ "name": "shadowed", "filter": { "disabledTools": ["nope"] } }),
        )
        .await
        .expect("patching the project-layer owner must succeed");

    let user_file: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(home.path().join(".mirri-code").join("mcp.json")).unwrap(),
    )
    .unwrap();
    assert_eq!(
        user_file["mcpServers"]["solo"]["enabledTools"],
        json!(["one", "two"])
    );
    assert!(
        user_file["mcpServers"]["shadowed"]
            .get("enabledTools")
            .is_none()
            && user_file["mcpServers"]["shadowed"]
                .get("disabledTools")
                .is_none(),
        "the shadowed server's filter patches the project layer, not the user layer"
    );
    let local_file: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(workspace.path().join(".mirri-code").join("mcp.json")).unwrap(),
    )
    .unwrap();
    assert_eq!(
        local_file["mcpServers"]["shadowed"]["disabledTools"],
        json!(["nope"])
    );

    let missing_error = server
        .call_method(
            "mcp.config.setToolFilter",
            json!({ "name": "never-defined", "filter": {} }),
        )
        .await
        .expect_err("an undefined server must answer not-found");
    assert!(
        matches!(missing_error,
            EngineError::Rpc { code: -32001, data: Some(ref data), .. }
                if data.get("domainCode").and_then(Value::as_str) == Some("mcp.server_not_found")),
        "error: {missing_error}"
    );

    let plugin_error = server
        .call_method(
            "mcp.config.setToolFilter",
            json!({ "name": "plugin-demo:helper", "filter": {} }),
        )
        .await
        .expect_err("a plugin name with no plugin support answers domain not-found");
    assert!(
        matches!(plugin_error,
            EngineError::Rpc { code: -32001, data: Some(ref data), .. }
                if data.get("domainCode").and_then(Value::as_str) == Some("mcp.server_not_found")),
        "error: {plugin_error}"
    );
}

// ---------------------------------------------------------------------------
// ---------------------------------------------------------------------------
// user-layer / project-local path overlap (the desktop shape: `mirri web`
// spawns with cwd=/ so the workspace root falls back to $HOME —
// <root>/.mirri-code/mcp.json IS ~/.mirri-code/mcp.json)
// ---------------------------------------------------------------------------

/// Given a workspace whose root equals the home directory (the desktop
/// fallback shape), when `mcp.config.list` runs with the default scope,
/// then the user-layer servers keep their `user` source and no duplicate
/// entry appears.
#[tokio::test]
async fn should_keep_user_source_when_workspace_root_is_home() {
    let home = tempfile::tempdir().expect("home tempdir");
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("overlap-ws"),
        home.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );
    write_mcp_config(
        &home.path().join(".mirri-code").join("mcp.json"),
        r#"{"mcpServers":{"global-one":{"transport":"stdio","command":"u"}}}"#,
    );

    let result = server
        .call_method("mcp.config.list", json!({}))
        .await
        .expect("listing must succeed");
    let entries = result.as_array().expect("a bare array");
    let entry = entries
        .iter()
        .find(|e| e["name"] == json!("global-one"))
        .expect("the user-layer server lists");
    assert_eq!(
        entry["source"],
        json!("user"),
        "the overlap must not re-label the user layer's entry as project"
    );
    assert_eq!(entries.len(), 1, "no duplicate entry from the same file");
}

/// Given the overlap shape, when `mcp.config.list` runs with the workspace
/// scope, then the answer is empty — no project layer exists.
#[tokio::test]
async fn should_answer_empty_workspace_list_when_workspace_root_is_home() {
    let home = tempfile::tempdir().expect("home tempdir");
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("overlap-ws"),
        home.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );
    write_mcp_config(
        &home.path().join(".mirri-code").join("mcp.json"),
        r#"{"mcpServers":{"global-one":{"transport":"stdio","command":"u"}}}"#,
    );

    let result = server
        .call_method("mcp.config.list", json!({ "scope": "workspace" }))
        .await
        .expect("listing must succeed");
    assert!(
        result.as_array().expect("a bare array").is_empty(),
        "the user file must not list under the workspace scope in the overlap shape"
    );
}

