// setToolFilter target-layer semantics (ADR-006/A2 + ADR-012 2026-10-17
// revision: project-root is never machine-written; a default-scope tool
// toggle on a project-root definition writes a filter-only override to the
// project-local layer — SDR-S005 / PS3.3: tool-level control works for
// every source)
// ---------------------------------------------------------------------------

/// Given a server defined only in the project-root layer (`.mcp.json`),
/// when `mcp.config.setToolFilter` targets it with the default scope, then
/// a filter-only override entry is created in the project-local layer
/// (never machine-writing the shared root file) and the call succeeds.
#[tokio::test]
async fn should_write_project_local_override_when_default_scope_targets_project_root_server() {
    // Given: 某 server 定义在 project-root 层（.mcp.json）
    let (server, _home, workspace) = mcp_config_test_server();
    let root_path = workspace.path().join(".mcp.json");
    write_mcp_config(
        &root_path,
        r#"{"mcpServers":{"rooty":{"transport":"stdio","command":"r"}}}"#,
    );
    let before = std::fs::read_to_string(&root_path).unwrap();

    // When: 缺省 scope 调 setToolFilter
    server
        .call_method(
            "mcp.config.setToolFilter",
            json!({ "name": "rooty", "filter": { "disabledTools": ["dangerous"] } }),
        )
        .await
        .expect("a default-scope tool toggle on a project-root server must succeed via override");

    // Then: 共享 root 文件字节不动（A2），override 落项目本地层且 filter-only
    assert_eq!(
        std::fs::read_to_string(&root_path).unwrap(),
        before,
        "the project-root file is untouched"
    );
    let local_file: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(workspace.path().join(".mirri-code").join("mcp.json")).unwrap(),
    )
    .unwrap();
    assert_eq!(
        local_file["mcpServers"]["rooty"]["disabledTools"],
        json!(["dangerous"])
    );
    assert!(
        local_file["mcpServers"]["rooty"].get("transport").is_none(),
        "the override must stay filter-only (ADR-006 A7)"
    );
}

/// Given a project-root server whose tool filter already has a
/// project-local override, when `mcp.config.setToolFilter` is called again
/// with the default scope, then the existing override entry is patched in
/// place (present fields replace, absent fields clear) and unrelated
/// entries in the project-local file are preserved.
#[tokio::test]
async fn should_patch_existing_override_when_default_scope_targets_project_root_server() {
    let (server, _home, workspace) = mcp_config_test_server();
    write_mcp_config(
        &workspace.path().join(".mcp.json"),
        r#"{"mcpServers":{"shared":{"transport":"stdio","command":"r"}}}"#,
    );
    write_mcp_config(
        &workspace.path().join(".mirri-code").join("mcp.json"),
        r#"{"mcpServers":{"shared":{"disabledTools":["old"],"enabledTools":["keep"]},"other":{"transport":"stdio","command":"x"}}}"#,
    );

    server
        .call_method(
            "mcp.config.setToolFilter",
            json!({ "name": "shared", "filter": { "disabledTools": ["new"] } }),
        )
        .await
        .expect("re-patching an existing override must succeed");

    let local_file: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(workspace.path().join(".mirri-code").join("mcp.json")).unwrap(),
    )
    .unwrap();
    assert_eq!(
        local_file["mcpServers"]["shared"]["disabledTools"],
        json!(["new"]),
        "present fields replace (the old list is gone)"
    );
    assert!(
        local_file["mcpServers"]["shared"]
            .get("enabledTools")
            .is_none(),
        "an absent field clears (the patch is the complete new filter state)"
    );
    assert!(
        local_file["mcpServers"]["other"].get("command").is_some(),
        "unrelated entries in the project-local file are preserved"
    );
}

/// Given a server defined only in the user layer, when `setToolFilter`
/// targets it with the explicit workspace scope, then a filter-override
/// entry (filter fields only, no transport) is created in the project
/// local layer while the connection definition stays the user layer's —
/// the merged view (A7) carries the user connection with the project
/// filter.
#[tokio::test]
async fn should_create_filter_override_entry_when_workspace_scope_targets_undefined_name() {
    // Given: server 只存在于 user 层
    let (server, home, workspace) = mcp_config_test_server();
    write_mcp_config(
        &home.path().join(".mirri-code").join("mcp.json"),
        r#"{"mcpServers":{"db":{"transport":"stdio","command":"user-cmd"}}}"#,
    );

    // When: scope='workspace' 调 setToolFilter
    server
        .call_method(
            "mcp.config.setToolFilter",
            json!({
                "name": "db",
                "filter": { "disabledTools": ["db.query"] },
                "scope": "workspace"
            }),
        )
        .await
        .expect("the workspace-scope filter write must succeed");

    // Then: 项目本地层出现仅含过滤字段的条目；连接定义仍取 user 层（合并验证）
    let local_file: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(workspace.path().join(".mirri-code").join("mcp.json")).unwrap(),
    )
    .unwrap();
    let local_db = &local_file["mcpServers"]["db"];
    assert_eq!(local_db["disabledTools"], json!(["db.query"]));
    assert!(
        local_db.get("transport").is_none() && local_db.get("command").is_none(),
        "the override entry carries only the filter fields, never a transport"
    );
    let user_file: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(home.path().join(".mirri-code").join("mcp.json")).unwrap(),
    )
    .unwrap();
    assert!(
        user_file["mcpServers"]["db"].get("disabledTools").is_none(),
        "the user layer keeps its stored form"
    );

    // The merged flat view (A7) binds the project filter to the user layer's
    // connection definition.
    let merged =
        mirri_mcp::config::load_mcp_config(home.path(), workspace.path(), workspace.path())
            .unwrap();
    let db = &merged["db"];
    match &db.transport {
        mirri_mcp::McpTransportConfig::Stdio { command, .. } => {
            assert_eq!(command, "user-cmd");
        }
        other => panic!("expected stdio transport, got {other:?}"),
    }
    assert_eq!(
        db.disabled_tools,
        Some(vec!["db.query".to_string()]),
        "the merged view applies the workspace filter override to the user connection"
    );
}

/// Case B regression (M4 review round 1): Given a project-root entry
/// carrying `enabledTools` and a project-local entry of the same name that
/// redefines only the connection (the A7 inheritance shape — the family
/// merge the pool connected with), when the workspace reconcile desired
/// set is computed, then it retains the inherited filter — the desired set
/// matches the A7-connected state, so the reconcile diff never emits a
/// RefreshToolFilter that reverts the filter against the live tool table.
#[tokio::test]
async fn should_retain_the_inherited_filter_when_the_workspace_desired_state_is_computed() {
    // Given: root 层 db 携带 enabledTools；local 层同名 db 仅重定义连接（无过滤字段）
    let home = tempfile::tempdir().expect("home tempdir");
    let workspace = tempfile::tempdir().expect("workspace tempdir");
    write_mcp_config(
        &workspace.path().join(".mcp.json"),
        r#"{"mcpServers":{"db":{"transport":"stdio","command":"root-cmd","enabledTools":["db.query"]}}}"#,
    );
    write_mcp_config(
        &workspace.path().join(".mirri-code").join("mcp.json"),
        r#"{"mcpServers":{"db":{"transport":"stdio","command":"local-cmd"}}}"#,
    );

    // When: workspace reconcile 期望集经 A7 项目合并计算
    let desired =
        desired_configs_for_scope(McpConfigScope::Workspace, None, workspace.path()).unwrap();
    let connected =
        mirri_mcp::config::load_mcp_config_layered(home.path(), workspace.path(), workspace.path())
            .unwrap()
            .project_merged();

    // Then: 期望集保留继承的过滤（reconcile diff 不产生清空过滤的 refresh）
    let db = &desired["db"];
    match &db.transport {
        mirri_mcp::McpTransportConfig::Stdio { command, .. } => {
            assert_eq!(
                command, "local-cmd",
                "the connection family takes the local entry"
            );
        }
        other => panic!("expected stdio transport, got {other:?}"),
    }
    assert_eq!(
        db.enabled_tools,
        Some(vec!["db.query".to_string()]),
        "the desired set inherits the root layer's filter (Case B)"
    );
    // The pool connected with the same A7 view (`project_merged`): an
    // A7-consistent desired set diffed against it is empty — no
    // RefreshToolFilter reverting the inherited filter on the live table.
    let ops = mirri_mcp::diff_pool_ops(&connected, &desired);
    assert!(
        ops.is_empty(),
        "desired equals the A7-connected state, so the reconcile is a no-op: {ops:?}"
    );
}

/// Case A regression (M4 review round 1): Given a connected workspace
/// server defined in the project-root layer, when `setToolFilter` with the
/// explicit workspace scope creates a filter-only override entry, then the
/// write's own reconcile applies the override filter to the live agent
/// tool table (no restart) — the desired set is the A7 project merge, so
/// the override surfaces instead of being dropped.
#[tokio::test]
async fn should_apply_the_override_filter_live_when_workspace_scope_creates_a_filter_override() {
    // Given: root 层定义 mock（无过滤）并已连接
    let mock = spawn_mock_mcp_http_server(0, false).await;
    let (home, workspace) = layered_mcp_fixture(json!({}), None);
    write_mcp_config(
        &workspace.path().join(".mcp.json"),
        &serde_json::json!({
            "mcpServers": { "mock": { "transport": "http", "url": mock.url } }
        })
        .to_string(),
    );
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("override-live-refresh"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );
    let manager = Arc::clone(server.mcp_manager().expect("workspace manager attached"));

    server
        .call_method("mcp.list", json!({}))
        .await
        .expect("first call");
    wait_for_pool_state(&manager, "mock", "Connected", |state| {
        matches!(state, Some(mirri_mcp::McpConnectionState::Connected { .. }))
    })
    .await;
    let created = server
        .call_method("session.create", json!({ "title": "override-refresh" }))
        .await
        .expect("session.create");
    let session_id = created["id"].as_str().expect("session id").to_string();
    wait_for_agent_tool(&server, &session_id, "mcp__mock__echo", true).await;

    // When: scope='workspace' 调 setToolFilter（在项目本地层创建过滤覆盖条目）
    server
        .call_method(
            "mcp.config.setToolFilter",
            json!({
                "name": "mock",
                "filter": { "enabledTools": ["nothing-else"] },
                "scope": "workspace"
            }),
        )
        .await
        .expect("the workspace-scope override write must succeed");

    // Then: 覆盖过滤立即作用于 live 工具表（写路径自身的 reconcile 经 A7 项目合并），
    //       连接保持（过滤族变更只刷新注册，不重连）
    wait_for_agent_tool(&server, &session_id, "mcp__mock__echo", false).await;
    assert!(
        matches!(
            manager.list_connections().await[0].1,
            mirri_mcp::McpConnectionState::Connected { .. }
        ),
        "a filter-only override must not disconnect the server"
    );
}

// ---------------------------------------------------------------------------
// F-3 revision optimistic lock (ADR-005/ADR-008)
// ---------------------------------------------------------------------------

/// Given a user-layer server whose listed revision is r1, when another
/// writer's set (r2) lands first and this client's set carries the stale
/// r1, then the write is rejected with the `mcp.config.conflict` domain
/// error — never a silent overwrite — and the error carries the current
/// revision for the client to re-list and retry.
#[tokio::test]
async fn should_reject_write_when_expected_revision_is_stale() {
    // Given a user-layer server and its listed revision r1
    let (server, home, _workspace) = mcp_config_test_server();
    server
        .call_method(
            "mcp.config.set",
            json!({
                "scope": "user", "name": "demo",
                "config": { "transport": "stdio", "command": "run", "args": ["a"] }
            }),
        )
        .await
        .expect("initial set");
    let list1 = server
        .call_method("mcp.config.list", json!({ "scope": "user" }))
        .await
        .expect("list");
    let rev1 = list1[0]["revision"]
        .as_str()
        .expect("revision present")
        .to_string();

    // When another client writes first (revision becomes r2) and this
    // client writes with the stale r1
    server
        .call_method(
            "mcp.config.set",
            json!({
                "scope": "user", "name": "demo",
                "config": { "transport": "stdio", "command": "run2", "args": ["b"] }
            }),
        )
        .await
        .expect("second write");
    let result = server
        .call_method(
            "mcp.config.set",
            json!({
                "scope": "user", "name": "demo",
                "expectedRevision": rev1,
                "config": { "transport": "stdio", "command": "run3", "args": ["c"] }
            }),
        )
        .await;

    // Then the stale revision is rejected explicitly rather than
    // overwritten, and the current revision rides the error
    let err = result.expect_err("stale revision must be rejected");
    assert!(format!("{err:?}").contains("mcp.config.conflict"));
    let list2 = server
        .call_method("mcp.config.list", json!({ "scope": "user" }))
        .await
        .expect("re-list");
    let rev2 = list2[0]["revision"]
        .as_str()
        .expect("revision present")
        .to_string();
    assert!(
        format!("{err:?}").contains(&rev2),
        "the conflict error carries the current revision: {err:?}"
    );
    let user_file: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(home.path().join(".mirri-code").join("mcp.json")).unwrap(),
    )
    .unwrap();
    assert_eq!(
        user_file["mcpServers"]["demo"]["command"], "run2",
        "the stale write never lands"
    );
}

/// Given entries in the user and project layers, when the merged view is
/// listed, then every entry carries a non-empty revision of its source
/// layer file — entries from the same file share it, different files do
/// not, and the value matches the content hash of the defining file.
#[tokio::test]
async fn should_return_per_layer_revision_when_mcp_config_list_is_called() {
    // Given entries in the user file and the project-local file
    let (server, home, workspace) = mcp_config_test_server();
    let user_path = home.path().join(".mirri-code").join("mcp.json");
    let local_path = workspace.path().join(".mirri-code").join("mcp.json");
    write_mcp_config(
        &user_path,
        r#"{"mcpServers":{"user-a":{"transport":"stdio","command":"u"},"user-b":{"transport":"stdio","command":"u2"}}}"#,
    );
    write_mcp_config(
        &local_path,
        r#"{"mcpServers":{"local-c":{"transport":"stdio","command":"l"}}}"#,
    );

    // When the scope-less merged view is listed
    let listed = server
        .call_method("mcp.config.list", json!({}))
        .await
        .expect("list");

    // Then every entry carries the revision of its source layer file
    let entries = mcp_config_entries(&listed);
    for (name, entry) in &entries {
        let revision = entry["revision"]
            .as_str()
            .expect("revision present")
            .to_string();
        assert!(!revision.is_empty(), "revision is non-empty for {name}");
        assert_eq!(revision.len(), 16, "revision is a hex u64 for {name}");
    }
    let user_rev_1 = entries["user-a"]["revision"].as_str().unwrap().to_string();
    let user_rev_2 = entries["user-b"]["revision"].as_str().unwrap().to_string();
    let local_rev = entries["local-c"]["revision"].as_str().unwrap().to_string();
    assert_eq!(
        user_rev_1, user_rev_2,
        "entries from the same layer file share its revision"
    );
    assert_ne!(
        user_rev_1, local_rev,
        "different layer files hash independently"
    );
    assert_eq!(
        user_rev_1,
        mirri_mcp::config::layer_revision(&user_path),
        "the revision is the source file's content hash"
    );
    assert_eq!(
        local_rev,
        mirri_mcp::config::layer_revision(&local_path),
        "the revision is the source file's content hash"
    );
}

/// Given a stored entry whose listed revision is r1, when `remove`
/// carries the stale r1 after a concurrent edit, then the removal answers
/// the `mcp.config.conflict` domain error and the file keeps the entry;
/// when `setToolFilter` carries the now-current revision, the lock
/// accepts the patch.
#[tokio::test]
async fn should_reject_remove_but_accept_tool_filter_when_expected_revision_matches_the_layer() {
    // Given a stored user-layer entry and its listed revision r1
    let (server, home, _workspace) = mcp_config_test_server();
    write_mcp_config(
        &home.path().join(".mirri-code").join("mcp.json"),
        r#"{"mcpServers":{"demo":{"transport":"stdio","command":"run"}}}"#,
    );
    let list1 = server
        .call_method("mcp.config.list", json!({ "scope": "user" }))
        .await
        .expect("list");
    let rev1 = list1[0]["revision"]
        .as_str()
        .expect("revision present")
        .to_string();

    // When another writer edits first and remove carries the stale r1
    server
        .call_method(
            "mcp.config.set",
            json!({
                "scope": "user", "name": "demo",
                "config": { "transport": "stdio", "command": "run2" }
            }),
        )
        .await
        .expect("concurrent edit");
    let remove_result = server
        .call_method(
            "mcp.config.remove",
            json!({ "scope": "user", "name": "demo", "expectedRevision": rev1 }),
        )
        .await;

    // Then remove answers the conflict domain error and the file is
    // untouched
    let remove_err = remove_result.expect_err("stale remove must be rejected");
    assert!(
        matches!(remove_err,
            EngineError::Rpc { code: -32001, data: Some(ref data), .. }
                if data.get("domainCode").and_then(Value::as_str) == Some("mcp.config.conflict")),
        "error: {remove_err}"
    );
    let user_file: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(home.path().join(".mirri-code").join("mcp.json")).unwrap(),
    )
    .unwrap();
    assert!(
        user_file["mcpServers"].get("demo").is_some(),
        "the stale remove never lands"
    );

    // When setToolFilter carries the now-current revision, the write lands
    let list2 = server
        .call_method("mcp.config.list", json!({ "scope": "user" }))
        .await
        .expect("re-list");
    let rev2 = list2[0]["revision"]
        .as_str()
        .expect("revision present")
        .to_string();
    server
        .call_method(
            "mcp.config.setToolFilter",
            json!({ "name": "demo", "filter": { "enabledTools": ["one"] }, "expectedRevision": rev2 }),
        )
        .await
        .expect("the current revision accepts the patch");
    let user_file: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(home.path().join(".mirri-code").join("mcp.json")).unwrap(),
    )
    .unwrap();
    assert_eq!(
        user_file["mcpServers"]["demo"]["enabledTools"],
        json!(["one"])
    );
}

// ---------------------------------------------------------------------------
// Config-write pool reconcile (plans/07 T1, spec §4.3)
// ---------------------------------------------------------------------------

/// A minimal in-test MCP HTTP (Streamable) server: one JSON-RPC POST per
/// connection, answering `initialize`, `tools/list` (one `echo` tool) and
/// `tools/call` (optionally delayed and/or erroring) — enough surface for a
/// real connect + tool round-trip with zero external binaries. The handle
/// keeps the accept loop alive; dropping it stops the server.
struct MockMcpHttpServer {
    #[allow(dead_code)] // held for lifetime; the loop ends with the runtime
    handle: tokio::task::JoinHandle<()>,
    url: String,
}

async fn spawn_mock_mcp_http_server(tool_delay_ms: u64, tool_error: bool) -> MockMcpHttpServer {
    spawn_mock_mcp_http_server_with_tools(tool_delay_ms, tool_error, &[("echo", "echo tool")]).await
}

/// A [`spawn_mock_mcp_http_server`] variant advertising an arbitrary tool
/// set (each entry a `(name, description)` pair; the default mock exposes
/// one `echo` tool) — the M1 `mcp.tools` wire needs a multi-tool server to
/// pin the per-tool filter state.
async fn spawn_mock_mcp_http_server_with_tools(
    tool_delay_ms: u64,
    tool_error: bool,
    tools: &[(&str, &str)],
) -> MockMcpHttpServer {
    let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
        .await
        .expect("bind the mock MCP HTTP server");
    let url = format!("http://{}/mcp", listener.local_addr().expect("local addr"));
    let tools: Vec<(String, String)> = tools
        .iter()
        .map(|(name, description)| (name.to_string(), description.to_string()))
        .collect();
    let handle = tokio::spawn(async move {
        loop {
            let Ok((stream, _)) = listener.accept().await else {
                return;
            };
            tokio::spawn(serve_mock_mcp_connection(
                stream,
                tool_delay_ms,
                tool_error,
                tools.clone(),
            ));
        }
    });
    MockMcpHttpServer { handle, url }
}

/// Serve one connection of the mock MCP HTTP server (the per-connection
/// half of [`spawn_mock_mcp_http_server`], extracted so other tests — the
/// T8 restart helper — can serve the same protocol on a rebound port).
async fn serve_mock_mcp_connection(
    stream: tokio::net::TcpStream,
    tool_delay_ms: u64,
    tool_error: bool,
    tools: Vec<(String, String)>,
) {
    use tokio::io::{AsyncBufReadExt, AsyncReadExt, AsyncWriteExt};
    let mut stream = tokio::io::BufReader::new(stream);
    // Read the request head line by line until the blank line.
    let mut head = String::new();
    let mut line = Vec::new();
    loop {
        line.clear();
        if stream.read_until(b'\n', &mut line).await.unwrap_or(0) == 0 {
            return;
        }
        head.push_str(&String::from_utf8_lossy(&line));
        if line == b"\r\n" {
            break;
        }
    }
    let content_length: usize = head
        .lines()
        .find_map(|l| {
            l.to_ascii_lowercase()
                .strip_prefix("content-length:")
                .and_then(|v| v.trim().parse().ok())
        })
        .unwrap_or(0);
    let mut body = vec![0u8; content_length];
    if stream.read_exact(&mut body).await.is_err() {
        return;
    }
    let Ok(request) = serde_json::from_slice::<serde_json::Value>(&body) else {
        return;
    };
    let method = request["method"].as_str().unwrap_or_default().to_string();
    let id = request["id"].clone();
    let is_notification = id.is_null();

    if tool_delay_ms > 0 {
        tokio::time::sleep(std::time::Duration::from_millis(tool_delay_ms)).await;
    }
    let (result, error) = match method.as_str() {
        "initialize" => (
            Some(json!({
                "protocolVersion": "2024-11-05",
                "capabilities": {},
                "serverInfo": {"name": "mock", "version": "1.0"}
            })),
            None,
        ),
        "tools/list" => (
            Some(json!({
                "tools": tools
                    .iter()
                    .map(|(name, description)| {
                        json!({
                            "name": name,
                            "description": description,
                            "inputSchema": {"type": "object", "properties": {}}
                        })
                    })
                    .collect::<Vec<_>>()
            })),
            None,
        ),
        "tools/call" if tool_error => (
            None,
            Some(json!({"code": -32000, "message": "mock tool failure"})),
        ),
        "tools/call" => (
            Some(json!({
                "content": [{"type": "text", "text": "echoed"}],
                "isError": false
            })),
            None,
        ),
        _ => (None, None),
    };

    // Notifications expect no response body; requests get the
    // JSON-RPC envelope echoing the request id.
    let payload = if is_notification {
        String::new()
    } else {
        let mut envelope = json!({"jsonrpc": "2.0", "id": id});
        if let Some(result) = result {
            envelope["result"] = result;
        }
        if let Some(error) = error {
            envelope["error"] = error;
        }
        envelope.to_string()
    };
    let response = format!(
        "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
        payload.len(),
        payload
    );
    let _ = stream.get_mut().write_all(response.as_bytes()).await;
    let _ = stream.get_mut().shutdown().await;
}

/// Poll a pool manager until `check` accepts the named entry's state
/// (`None` = the entry is absent). Panics with `what` after 5s.
async fn wait_for_pool_state<F>(
    manager: &Arc<mirri_mcp::McpConnectionManager>,
    name: &str,
    what: &str,
    check: F,
) where
    F: Fn(Option<&mirri_mcp::McpConnectionState>) -> bool,
{
    let deadline = tokio::time::Instant::now() + std::time::Duration::from_secs(5);
    loop {
        let state = manager
            .list_connections()
            .await
            .into_iter()
            .find(|(conn_name, _)| conn_name == name)
            .map(|(_, state)| state);
        if check(state.as_ref()) {
            return;
        }
        if tokio::time::Instant::now() >= deadline {
            panic!("pool never reached: {what} (last state: {state:?})");
        }
        tokio::time::sleep(std::time::Duration::from_millis(20)).await;
    }
}

/// Whether the session's (single) live agent's tool table currently holds
/// the qualified MCP tool name.
async fn agent_holds_tool(server: &EmbeddedServer, session_id: &str, qualified: &str) -> bool {
    let Some(session) = server
        .session_manager()
        .get_session(&SessionId::new(session_id))
        .await
    else {
        return false;
    };
    let agent_ids = session.list_agents().await;
    let Some(agent_id) = agent_ids.first() else {
        return false;
    };
    let Some(agent) = session.get_agent(agent_id).await else {
        return false;
    };
    let tool_manager = agent.tool_manager();
    let tm = tool_manager.read();
    tm.all_tool_names().iter().any(|name| name == qualified)
}

/// Poll until the session agent's tool table holds (or drops) the
/// qualified MCP tool name.
async fn wait_for_agent_tool(
    server: &EmbeddedServer,
    session_id: &str,
    qualified: &str,
    expect: bool,
) {
    let deadline = tokio::time::Instant::now() + std::time::Duration::from_secs(5);
    loop {
        if agent_holds_tool(server, session_id, qualified).await == expect {
            return;
        }
        if tokio::time::Instant::now() >= deadline {
            panic!(
                "agent tool table never {} '{qualified}'",
                if expect { "gained" } else { "dropped" }
            );
        }
        tokio::time::sleep(std::time::Duration::from_millis(20)).await;
    }
}

/// The `mcp.list` entry for `name`, if the effective view shows it.
async fn mcp_list_entry_for(server: &EmbeddedServer, name: &str) -> Option<serde_json::Value> {
    server
        .call_method("mcp.list", json!({}))
        .await
        .expect("mcp.list should succeed")
        .as_array()
        .expect("bare array wire shape")
        .iter()
        .find(|entry| entry["name"] == json!(name))
        .cloned()
}

/// Given a workspace-layer server connected through the startup path and a
/// session whose agent holds its tool, when `mcp.config.set` disables the
/// server, then the running pool tears the connection (the `mcp.list`
/// entry flips to `disabled`), the agent's tool table drops the tool, and
/// the config entry stays on disk — no process restart anywhere. A
/// re-enable write connects the server back and restores the tool.
#[tokio::test]
async fn should_reconcile_the_workspace_pool_when_a_config_write_toggles_the_server() {
    let mock = spawn_mock_mcp_http_server(0, false).await;
    let (home, workspace) = layered_mcp_fixture(
        json!({}),
        Some(json!({"mock": {"transport": "http", "url": mock.url}})),
    );
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("reconcile-workspace-toggle"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );
    let manager = Arc::clone(server.mcp_manager().expect("workspace manager attached"));

    // The startup path connects the server and a session agent holds the
    // tool.
    server
        .call_method("mcp.list", json!({}))
        .await
        .expect("first call");
    wait_for_pool_state(&manager, "mock", "Connected", |state| {
        matches!(state, Some(mirri_mcp::McpConnectionState::Connected { .. }))
    })
    .await;
    let created = server
        .call_method("session.create", json!({ "title": "reconcile-ws" }))
        .await
        .expect("session.create");
    let session_id = created["id"].as_str().expect("session id").to_string();
    wait_for_agent_tool(&server, &session_id, "mcp__mock__echo", true).await;

    // When the config write disables the server…
    server
        .call_method(
            "mcp.config.set",
            json!({ "scope": "workspace", "name": "mock", "config": {"transport": "http", "url": mock.url, "enabled": false} }),
        )
        .await
        .expect("the disabling write must succeed");

    // …the running pool flips the entry to Disabled (registered, shown by
    // `mcp.list`)…
    wait_for_pool_state(&manager, "mock", "Disabled", |state| {
        matches!(state, Some(mirri_mcp::McpConnectionState::Disabled))
    })
    .await;
    let entry = mcp_list_entry_for(&server, "mock")
        .await
        .expect("disabled entry stays listed");
    assert_eq!(entry["status"], json!("disabled"));
    // …the agent's tool table drops the tool…
    wait_for_agent_tool(&server, &session_id, "mcp__mock__echo", false).await;
    // …and the config entry stays on disk (disable keeps the definition).
    let local_file: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(workspace.path().join(".mirri-code").join("mcp.json"))
            .expect("the project-local file exists after set"),
    )
    .expect("the project-local file parses");
    assert_eq!(local_file["mcpServers"]["mock"]["enabled"], json!(false));

    // A re-enable write connects the server back and restores the tool.
    server
        .call_method(
            "mcp.config.set",
            json!({ "scope": "workspace", "name": "mock", "config": {"transport": "http", "url": mock.url} }),
        )
        .await
        .expect("the re-enabling write must succeed");
    wait_for_pool_state(&manager, "mock", "Connected", |state| {
        matches!(state, Some(mirri_mcp::McpConnectionState::Connected { .. }))
    })
    .await;
    wait_for_agent_tool(&server, &session_id, "mcp__mock__echo", true).await;
    let entry = mcp_list_entry_for(&server, "mock")
        .await
        .expect("re-enabled entry listed");
    assert_eq!(entry["status"], json!("connected"));
}

/// Given a user-layer server connected through the startup path, when
/// `mcp.config.set` (scope `user`) disables it and `mcp.config.remove`
/// then deletes it, then the user pool tears the connection (Disabled
/// flip) and unregisters the entry entirely (absent from `mcp.list`) —
/// the same semantics the workspace pool carries, on the user pool.
#[tokio::test]
async fn should_reconcile_the_user_pool_when_config_writes_disable_and_remove_the_server() {
    let mock = spawn_mock_mcp_http_server(0, false).await;
    let (home, workspace) = layered_mcp_fixture(
        json!({"mock": {"transport": "http", "url": mock.url}}),
        None,
    );
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("reconcile-user-pool"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );
    let pool = Arc::clone(server.user_mcp_pool().expect("user pool attached"));
    let manager = pool.manager();

    server
        .call_method("mcp.list", json!({}))
        .await
        .expect("first call");
    wait_for_pool_state(&manager, "mock", "Connected", |state| {
        matches!(state, Some(mirri_mcp::McpConnectionState::Connected { .. }))
    })
    .await;

    // Disabling through a user-scope write tears the user-pool connection.
    server
        .call_method(
            "mcp.config.set",
            json!({ "scope": "user", "name": "mock", "config": {"transport": "http", "url": mock.url, "enabled": false} }),
        )
        .await
        .expect("the disabling write must succeed");
    wait_for_pool_state(&manager, "mock", "Disabled", |state| {
        matches!(state, Some(mirri_mcp::McpConnectionState::Disabled))
    })
    .await;

    // Removing the entry unregisters the connection entirely.
    server
        .call_method(
            "mcp.config.remove",
            json!({ "scope": "user", "name": "mock" }),
        )
        .await
        .expect("the removing write must succeed");
    wait_for_pool_state(&manager, "mock", "unregistered", |state| state.is_none()).await;
    assert!(
        mcp_list_entry_for(&server, "mock").await.is_none(),
        "the removed server must leave mcp.list"
    );
}

// --- serve-shape regressions (injected home = `<base>/.mirri-code`, MCP
// base = `<base>`) — the `mirri serve` wiring whose RPC-time home
// re-resolution used to address a double-nested
// `~/.mirri-code/.mirri-code/mcp.json` the pools never loaded ----------

/// A `mirri serve`-shaped server: the injected Mirri home is the nested
/// `<base>/.mirri-code` (config.toml / profiles / sessions root) while the
/// MCP base is `<base>` itself (`mirri serve` passes `$HOME`), so the user
/// layer lives at `<base>/.mirri-code/mcp.json` while the two home chains
/// disagree — the exact shape the config surface and the reconcile kernel
/// must resolve through the bootstrap's pool-load base, never by
/// re-resolving from the injected home.
fn serve_shaped_mcp_test_server(
    user_servers: serde_json::Value,
) -> (EmbeddedServer, tempfile::TempDir, tempfile::TempDir) {
    let base = tempfile::tempdir().expect("base tempdir");
    let workspace = tempfile::tempdir().expect("workspace tempdir");
    let mirri_home = base.path().join(".mirri-code");
    std::fs::create_dir_all(&mirri_home).expect("create mirri home dir");
    std::fs::write(
        mirri_home.join("mcp.json"),
        serde_json::json!({ "mcpServers": user_servers }).to_string(),
    )
    .expect("write user-layer mcp.json");
    let parts = crate::bootstrap::assemble(
        WorkspaceId::new("serve-shape-ws"),
        workspace.path().to_path_buf(),
        Some(mirri_home),
        Some(base.path().to_path_buf()),
        crate::bootstrap::WorkspacePolicy::TrustedFromConfig,
        Vec::new(),
    );
    (EmbeddedServer::from_parts(parts), base, workspace)
}

/// Given a server defined only in the user layer of a serve-shaped engine,
/// when `mcp.config.setToolFilter` runs with the default scope, then the
/// patch lands in the user-layer file — never the "not defined in any
/// configuration layer" not-found the double-nested path used to answer.
#[tokio::test]
async fn should_find_the_user_layer_server_when_set_tool_filter_runs_in_the_serve_shape() {
    let (server, base, _workspace) = serve_shaped_mcp_test_server(json!({
        "atlassian": {"transport": "stdio", "command": "a"}
    }));

    server
        .call_method(
            "mcp.config.setToolFilter",
            json!({ "name": "atlassian", "filter": { "enabledTools": ["one"] } }),
        )
        .await
        .expect("setToolFilter must find the serve-shape user-layer server");

    let user_file: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(base.path().join(".mirri-code").join("mcp.json")).unwrap(),
    )
    .unwrap();
    assert_eq!(
        user_file["mcpServers"]["atlassian"]["enabledTools"],
        json!(["one"])
    );
}

/// Given two connected user-layer servers in a serve-shaped engine, when
/// `mcp.config.remove` removes one by name, then only that server's
/// connection is unregistered and only its entry leaves the file — the
/// double-nested write used to leave the real file untouched while the
/// reconcile's empty desired set unregistered the whole pool.
#[tokio::test]
async fn should_remove_only_the_named_server_from_the_serve_shape_user_pool() {
    let mock_alpha = spawn_mock_mcp_http_server(0, false).await;
    let mock_beta = spawn_mock_mcp_http_server(0, false).await;
    let (server, base, _workspace) = serve_shaped_mcp_test_server(json!({
        "alpha": {"transport": "http", "url": mock_alpha.url},
        "beta": {"transport": "http", "url": mock_beta.url}
    }));
    let pool = Arc::clone(server.user_mcp_pool().expect("user pool attached"));
    let manager = pool.manager();

    server
        .call_method("mcp.list", json!({}))
        .await
        .expect("first call");
    wait_for_pool_state(&manager, "alpha", "Connected", |state| {
        matches!(state, Some(mirri_mcp::McpConnectionState::Connected { .. }))
    })
    .await;
    wait_for_pool_state(&manager, "beta", "Connected", |state| {
        matches!(state, Some(mirri_mcp::McpConnectionState::Connected { .. }))
    })
    .await;

    server
        .call_method(
            "mcp.config.remove",
            json!({ "scope": "user", "name": "alpha" }),
        )
        .await
        .expect("the removing write must succeed");
    wait_for_pool_state(&manager, "alpha", "unregistered", |state| state.is_none()).await;

    let beta_state = manager
        .list_connections()
        .await
        .into_iter()
        .find(|(name, _)| name == "beta")
        .map(|(_, state)| state);
    assert!(
        matches!(
            beta_state,
            Some(mirri_mcp::McpConnectionState::Connected { .. })
        ),
        "removing one server must not unregister the others, got {beta_state:?}"
    );
    let user_file: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(base.path().join(".mirri-code").join("mcp.json")).unwrap(),
    )
    .unwrap();
    assert!(user_file["mcpServers"].get("alpha").is_none());
    assert!(
        user_file["mcpServers"]["beta"].is_object(),
        "the untouched server's entry must stay in the user layer"
    );
}

/// Given a connected user-pool server whose user-layer file then goes
/// missing, when the reconcile kernel runs, then the whole-pool unregister
/// is refused — an empty desired set against live connections with no
/// file behind it is a base-resolution divergence, not a user intent the
/// per-server remove surface could express.
#[tokio::test]
async fn should_keep_the_user_pool_connections_when_the_layer_file_goes_missing() {
    let mock = spawn_mock_mcp_http_server(0, false).await;
    let (server, base, _workspace) = serve_shaped_mcp_test_server(json!({
        "mock": {"transport": "http", "url": mock.url}
    }));
    let pool = Arc::clone(server.user_mcp_pool().expect("user pool attached"));
    let manager = pool.manager();

    server
        .call_method("mcp.list", json!({}))
        .await
        .expect("first call");
    wait_for_pool_state(&manager, "mock", "Connected", |state| {
        matches!(state, Some(mirri_mcp::McpConnectionState::Connected { .. }))
    })
    .await;

    std::fs::remove_file(base.path().join(".mirri-code").join("mcp.json"))
        .expect("delete the user-layer file");

    let summary = server
        .call_method("mcp.sync", json!({}))
        .await
        .expect("mcp.sync must succeed");
    assert_eq!(
        summary["removed"],
        json!(0),
        "the guardrail must refuse the batch unregister, got {summary}"
    );
    assert!(
        manager.registered_configs().await.contains_key("mock"),
        "the live connection must be kept when the layer file went missing"
    );
}

/// Given a connected user-pool server whose user layer is edited to zero
/// entries (the file still exists), when the reconcile kernel runs, then
/// the removal is honored — an explicitly emptied layer is a real user
/// intent, distinct from a missing file.
#[tokio::test]
async fn should_unregister_the_user_pool_when_the_layer_is_emptied() {
    let mock = spawn_mock_mcp_http_server(0, false).await;
    let (server, base, _workspace) = serve_shaped_mcp_test_server(json!({
        "mock": {"transport": "http", "url": mock.url}
    }));
    let pool = Arc::clone(server.user_mcp_pool().expect("user pool attached"));
    let manager = pool.manager();

    server
        .call_method("mcp.list", json!({}))
        .await
        .expect("first call");
    wait_for_pool_state(&manager, "mock", "Connected", |state| {
        matches!(state, Some(mirri_mcp::McpConnectionState::Connected { .. }))
    })
    .await;

    write_mcp_config(
        &base.path().join(".mirri-code").join("mcp.json"),
        r#"{"mcpServers":{}}"#,
    );

    let summary = server
        .call_method("mcp.sync", json!({}))
        .await
        .expect("mcp.sync must succeed");
    assert_eq!(
        summary["removed"],
        json!(1),
        "an explicitly emptied layer must remove its server, got {summary}"
    );
    wait_for_pool_state(&manager, "mock", "unregistered", |state| state.is_none()).await;
}

/// Given a user-layer server connected through the user pool and a session
/// whose agent holds its tool, when `mcp.config.setToolFilter` with the
/// workspace scope creates a filter-only override entry in the
/// project-local layer (the cross-pool A7 shape — the name is user-defined,
/// so the connection family stays with the user layer), then the write's
/// own reconcile applies the override filter to the live user pool's tool
/// table — no restart (the F-14 residual: the user pool's desired set
/// derives from `user_merged`, so the override reaches the diff as a
/// RefreshToolFilter instead of surviving only as a stale file entry).
#[tokio::test]
async fn should_apply_the_workspace_filter_override_to_the_user_pool_live() {
    // Given: user 层 mock 已连接，agent 工具已注册
    let mock = spawn_mock_mcp_http_server(0, false).await;
    let (home, workspace) = layered_mcp_fixture(
        json!({"mock": {"transport": "http", "url": mock.url}}),
        None,
    );
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("user-pool-filter-override"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );
    let pool = Arc::clone(server.user_mcp_pool().expect("user pool attached"));
    let manager = pool.manager();

    server
        .call_method("mcp.list", json!({}))
        .await
        .expect("first call");
    wait_for_pool_state(&manager, "mock", "Connected", |state| {
        matches!(state, Some(mirri_mcp::McpConnectionState::Connected { .. }))
    })
    .await;
    let created = server
        .call_method("session.create", json!({ "title": "user-override" }))
        .await
        .expect("session.create");
    let session_id = created["id"].as_str().expect("session id").to_string();
    wait_for_agent_tool(&server, &session_id, "mcp__mock__echo", true).await;

    // When: scope='workspace' 调 setToolFilter（在项目本地层创建跨池过滤覆盖条目）
    server
        .call_method(
            "mcp.config.setToolFilter",
            json!({
                "name": "mock",
                "filter": { "enabledTools": ["nothing-else"] },
                "scope": "workspace"
            }),
        )
        .await
        .expect("the workspace-scope override write must succeed");

    // Then: 覆盖过滤立即作用于 user pool 的活工具表（无重启），
    //       连接保持（过滤族变更只刷新注册，不重连）
    wait_for_agent_tool(&server, &session_id, "mcp__mock__echo", false).await;
    assert!(
        matches!(
            manager.list_connections().await[0].1,
            mirri_mcp::McpConnectionState::Connected { .. }
        ),
        "a filter-only override must not disconnect the user-pool server"
    );
    let registered = manager.registered_configs().await;
    assert_eq!(
        registered["mock"].enabled_tools,
        Some(vec!["nothing-else".to_string()]),
        "the live registration carries the override filter"
    );
}

/// Given a config state the pools already match (the startup lazy connect
/// registered the user layer's entry and the workspace layers are empty),
/// when `mcp.sync` is called, then the answer is the all-zero summary —
/// the reconcile is an idempotent no-op with zero applied operations.
#[tokio::test]
async fn should_return_zero_counts_when_mcp_sync_is_called_with_no_diff() {
    // Given: an engine whose user layer declares one disabled server (a
    // complete, connectable entry that registers without spawning a
    // process) and whose first RPC triggered the lazy connect, so the
    // pools and the config files already agree
    let (home, workspace) = layered_mcp_fixture(
        json!({"alpha": {"command": "echo", "args": [], "enabled": false}}),
        None,
    );
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("mcp-sync-no-diff"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );
    let pool = Arc::clone(server.user_mcp_pool().expect("user pool attached"));
    server
        .call_method("mcp.list", json!({}))
        .await
        .expect("the first call triggers the lazy connect");
    wait_for_connection(&pool.manager(), "alpha").await;

    // When: mcp.sync runs the idempotent reconcile
    let summary = server
        .call_method("mcp.sync", json!([]))
        .await
        .expect("mcp.sync must succeed");

    // Then: the summary is the all-zero shape — no pool operation anywhere
    assert_eq!(
        summary,
        json!({ "added": 0, "removed": 0, "reconnected": 0, "refreshed": 0 }),
        "a state the pools already match must reconcile as a zero-cost no-op"
    );
}

/// Given an engine that connected the user layer's entries through the
/// startup path, when the user layer file is then edited on disk behind
/// the engine's back (a simulated manual edit: one server removed, two
/// added, one redefined), then `mcp.sync` reports the summary counts of
/// exactly what it applied and the user pool follows the file — and when
/// the file is later broken past parsing, the call still succeeds while
/// the connections keep their current state (the conservative stance).
#[tokio::test]
async fn should_return_summary_counts_when_config_changed_outside_engine() {
    // Given: the engine connected with `old` (a disabled stdio entry —
    // registered without spawning a process) and `kept` (a live connection
    // to the mock MCP server) in the user layer
    let mock = spawn_mock_mcp_http_server(0, false).await;
    let (home, workspace) = layered_mcp_fixture(
        json!({
            "old": {"command": "echo", "args": [], "enabled": false},
            "kept": {"transport": "http", "url": mock.url}
        }),
        None,
    );
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("mcp-sync-external-edit"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );
    let pool = Arc::clone(server.user_mcp_pool().expect("user pool attached"));
    let manager = pool.manager();
    server
        .call_method("mcp.list", json!({}))
        .await
        .expect("the first call triggers the lazy connect");
    wait_for_pool_state(&manager, "kept", "Connected", |state| {
        matches!(state, Some(mirri_mcp::McpConnectionState::Connected { .. }))
    })
    .await;
    wait_for_connection(&manager, "old").await;

    // When: the user layer file is rewritten directly on disk — `old`
    // removed, `added-a`/`added-b` appended (disabled stdio entries),
    // `kept` redefined with a different URL (a connection-binding change)
    let user_layer = home.path().join(".mirri-code").join("mcp.json");
    std::fs::write(
        &user_layer,
        serde_json::json!({
            "mcpServers": {
                "kept": {"transport": "http", "url": format!("{}/redefined", mock.url)},
                "added-a": {"command": "echo", "args": [], "enabled": false},
                "added-b": {"command": "echo", "args": [], "enabled": false}
            }
        })
        .to_string(),
    )
    .expect("rewrite the user layer");

    // And: mcp.sync runs the reconcile against the edited file
    let summary = server
        .call_method("mcp.sync", json!([]))
        .await
        .expect("mcp.sync must succeed");

    // Then: the counts cover exactly the applied pool operations — two
    // connects, one unregister, one teardown-and-reconnect — and the
    // pool now matches the file (the awaited call means the operations
    // have landed by the time the answer returns)
    assert_eq!(
        summary,
        json!({ "added": 2, "removed": 1, "reconnected": 1, "refreshed": 0 }),
        "the summary must count the applied ops by kind"
    );
    let connections: Vec<(String, mirri_mcp::McpConnectionState)> =
        manager.list_connections().await;
    let mut names: Vec<&str> = connections.iter().map(|(name, _)| name.as_str()).collect();
    names.sort_unstable();
    assert_eq!(
        names,
        vec!["added-a", "added-b", "kept"],
        "the pool follows the file"
    );
    let kept_config = manager
        .get_server_config("kept")
        .await
        .expect("kept stays registered");
    assert!(
        serde_json::to_string(&kept_config)
            .expect("serialize kept config")
            .contains("/redefined"),
        "the reconnected entry carries the new definition"
    );

    // And: a file too broken to parse keeps the current connections (the
    // conservative stance — connections stay up) while the call still
    // answers a successful, zero-application summary
    std::fs::write(&user_layer, "{ not json").expect("break the user layer");
    let broken = server
        .call_method("mcp.sync", json!([]))
        .await
        .expect("a broken layer must not fail the sync call");
    assert_eq!(
        broken,
        json!({ "added": 0, "removed": 0, "reconnected": 0, "refreshed": 0 })
    );
    let mut after: Vec<String> = manager
        .list_connections()
        .await
        .into_iter()
        .map(|(name, _)| name)
        .collect();
    after.sort();
    assert_eq!(
        after,
        vec![
            "added-a".to_string(),
            "added-b".to_string(),
            "kept".to_string()
        ],
        "the unparseable file must keep the current connections"
    );
}

// ---------------------------------------------------------------------------
// M7 (F-9) — the event surface: the RefreshToolFilter re-emit and the
// app-level pool broadcast
// ---------------------------------------------------------------------------

/// Given a connected user-layer server and a live session with an event
/// subscriber, when `mcp.config.setToolFilter` changes the server's tool
/// filter (the reconcile kernel's RefreshToolFilter pool operation — a
/// persisted change that swaps the stored config in place, no reconnect),
/// then the subscriber observes `event.mcp.server.status` carrying
/// `changeKind: "field-change"` and the owning pool — before the fix the
/// branch re-registered the tools but never re-emitted the status event
/// (open item F-T1-4; ADR-008: every persisted change emits).
#[tokio::test]
async fn should_emit_event_when_refresh_tool_filter_changes_config() {
    // Given: a connected user-layer mock server and a live session whose
    // relay forwards the session bus to an event subscriber
    let mock = spawn_mock_mcp_http_server(0, false).await;
    let (home, workspace) = layered_mcp_fixture(
        json!({"mock": {"transport": "http", "url": mock.url}}),
        None,
    );
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("mcp-filter-reemit"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );
    let pool = Arc::clone(server.user_mcp_pool().expect("user pool attached"));
    server
        .call_method("mcp.list", json!({}))
        .await
        .expect("the first call triggers the lazy connect");
    wait_for_pool_state(&pool.manager(), "mock", "Connected", |state| {
        matches!(state, Some(mirri_mcp::McpConnectionState::Connected { .. }))
    })
    .await;
    let created = server
        .call_method("session.create", json!({ "title": "filter-reemit" }))
        .await
        .expect("session.create");
    let session_id = created["id"].as_str().expect("session id").to_string();
    let mut events = server.subscribe_events().await.expect("subscribe events");

    // When: setToolFilter narrows the server's tools (a filter-only change)
    server
        .call_method(
            "mcp.config.setToolFilter",
            json!({ "name": "mock", "filter": { "enabledTools": ["echo"] } }),
        )
        .await
        .expect("the filter write must succeed");

    // Then: the subscriber observes event.mcp.server.status for the
    // filter change, carrying the field-change kind and the owning pool
    let event = next_event_where(
        &mut events,
        |n| {
            n.method == "event.mcp.server.status"
                && n.params["server"]["changeKind"] == json!("field-change")
        },
        |_| {},
    )
    .await;
    assert_eq!(event.params["sessionId"], json!(session_id));
    assert_eq!(event.params["server"]["name"], json!("mock"));
    assert_eq!(event.params["server"]["status"], json!("connected"));
    assert_eq!(event.params["server"]["pool"], json!("user"));
}

/// Given an engine with a user-layer server and NO session anywhere, when
/// the app-level pool broadcast is subscribed through
/// `EngineAdapter::subscribe_mcp_pool_events` and the server's connection
/// state flips (the lazy startup connect), then the broadcast delivers the
/// `event.mcp.server.status` payload carrying the `pool` field — the
/// app-level surface that does not depend on any live session.
#[tokio::test]
async fn should_deliver_pool_event_without_any_session_when_subscribed_at_app_level() {
    // Given: an engine whose user layer declares a mock server, subscribed
    // at app level before any connection settles (no session exists)
    let mock = spawn_mock_mcp_http_server(0, false).await;
    let (home, workspace) = layered_mcp_fixture(
        json!({"mock": {"transport": "http", "url": mock.url}}),
        None,
    );
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("mcp-app-broadcast"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );
    let mut rx = server
        .subscribe_mcp_pool_events()
        .expect("the embedded engine exposes the app-level pool broadcast");

    // When: the first RPC triggers the lazy startup connect and the mock
    // server's state flips to connected
    server
        .call_method("mcp.list", json!({}))
        .await
        .expect("the first call triggers the lazy connect");

    // Then: the broadcast delivers the status payload for the connected
    // server, carrying the owning pool — with no session involved anywhere
    let payload = tokio::time::timeout(Duration::from_secs(5), async {
        loop {
            let payload = rx.recv().await.expect("the broadcast stays open");
            if payload["server"]["name"] == json!("mock")
                && payload["server"]["status"] == json!("connected")
            {
                return payload;
            }
        }
    })
    .await
    .expect("the pool event must arrive within 5s");
    assert_eq!(payload["server"]["pool"], json!("user"));
    assert_eq!(payload["server"]["transport"], json!("http"));
    assert!(
        payload["server"]["toolCount"]
            .as_u64()
            .is_some_and(|n| n > 0),
        "the connected payload carries the tool count: {payload}"
    );
}

/// Given a workspace-layer server connected through a config write and a
/// session whose agent holds its tool, when `mcp.config.remove` deletes it
/// directly (no disable step in between), then the pool unregisters the
/// entry AND the live agent's tool table drops the tool — `remove()` only
/// notifies `Pending`, which the status listeners do not treat as a
/// teardown, so the reconcile unregisters the stale bridge tools
/// explicitly (T1 review F-T1-1: a lingering `McpBridgeTool` would answer
/// `Disconnected` on call).
#[tokio::test]
async fn should_remove_the_server_tools_from_the_live_agent_when_a_connected_server_is_removed() {
    let mock = spawn_mock_mcp_http_server(0, false).await;
    let (home, workspace) = layered_mcp_fixture(json!({}), None);
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("reconcile-remove-connected"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );
    let manager = Arc::clone(server.mcp_manager().expect("workspace manager attached"));

    server
        .call_method("mcp.list", json!({}))
        .await
        .expect("first call");
    // The add write seeds the local layer and the reconcile connects it.
    server
        .call_method(
            "mcp.config.set",
            json!({ "scope": "workspace", "name": "mock", "config": {"transport": "http", "url": mock.url} }),
        )
        .await
        .expect("the adding write must succeed");
    wait_for_pool_state(&manager, "mock", "Connected", |state| {
        matches!(state, Some(mirri_mcp::McpConnectionState::Connected { .. }))
    })
    .await;
    let created = server
        .call_method("session.create", json!({ "title": "reconcile-remove" }))
        .await
        .expect("session.create");
    let session_id = created["id"].as_str().expect("session id").to_string();
    wait_for_agent_tool(&server, &session_id, "mcp__mock__echo", true).await;

    // Removing the connected server directly (no disable step in between).
    server
        .call_method(
            "mcp.config.remove",
            json!({ "scope": "workspace", "name": "mock" }),
        )
        .await
        .expect("the removing write must succeed");
    wait_for_pool_state(&manager, "mock", "unregistered", |state| state.is_none()).await;

    // The live agent's tool table must not hold the stale bridge tool.
    wait_for_agent_tool(&server, &session_id, "mcp__mock__echo", false).await;
    assert!(
        mcp_list_entry_for(&server, "mock").await.is_none(),
        "the removed server must leave mcp.list"
    );
}

