/// Given a slow mock tool (300ms) in flight, when a config write disables
/// the server, then the reconcile waits for the in-flight call to complete
/// (the call returns its result) before tearing the connection down —
/// R2's "let in-flight calls finish" half.
#[tokio::test]
async fn should_wait_for_the_in_flight_tool_call_when_the_reconcile_tears_a_connection_down() {
    let mock = spawn_mock_mcp_http_server(300, false).await;
    let (home, workspace) = layered_mcp_fixture(
        json!({}),
        Some(json!({"mock": {"transport": "http", "url": mock.url}})),
    );
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("reconcile-r2-wait"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );
    let manager = Arc::clone(server.mcp_manager().expect("workspace manager attached"));

    server
        .call_method("mcp.list", json!({}))
        .await
        .expect("first call");
    wait_for_pool_state(&manager, "mock", "Connected", |state| {
        matches!(state, Some(mirri_mcp::McpConnectionState::Connected { .. }))
    })
    .await;

    let call = tokio::spawn({
        let manager = Arc::clone(&manager);
        async move { manager.call_tool("mock", "echo", json!({})).await }
    });
    // Let the call get in flight before the disabling write.
    tokio::time::sleep(std::time::Duration::from_millis(100)).await;

    server
        .call_method(
            "mcp.config.set",
            json!({ "scope": "workspace", "name": "mock", "config": {"transport": "http", "url": mock.url, "enabled": false} }),
        )
        .await
        .expect("the disabling write must succeed");

    let result = call
        .await
        .expect("the in-flight call task")
        .expect("the in-flight call must complete while the reconcile waits");
    assert_eq!(
        result
            .content
            .first()
            .expect("one content block")
            .to_string(),
        "echoed"
    );
    wait_for_pool_state(&manager, "mock", "Disabled", |state| {
        matches!(state, Some(mirri_mcp::McpConnectionState::Disabled))
    })
    .await;
}

/// Given a slow, failing mock tool in flight, when the teardown does not
/// wait (the drain timeout elapses) and the connection is removed, then
/// the in-flight call fails with an error naming the server — R2's
/// force-fail half.
#[tokio::test]
async fn should_fail_an_in_flight_call_with_the_server_named_when_the_teardown_is_forced() {
    let mock = spawn_mock_mcp_http_server(300, true).await;
    let (home, workspace) = layered_mcp_fixture(
        json!({}),
        Some(json!({"mock": {"transport": "http", "url": mock.url}})),
    );
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("reconcile-r2-force"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );
    let manager = Arc::clone(server.mcp_manager().expect("workspace manager attached"));

    server
        .call_method("mcp.list", json!({}))
        .await
        .expect("first call");
    wait_for_pool_state(&manager, "mock", "Connected", |state| {
        matches!(state, Some(mirri_mcp::McpConnectionState::Connected { .. }))
    })
    .await;

    let call = tokio::spawn({
        let manager = Arc::clone(&manager);
        async move { manager.call_tool("mock", "echo", json!({})).await }
    });
    tokio::time::sleep(std::time::Duration::from_millis(100)).await;

    // A drain wait shorter than the tool call: the teardown must not stall
    // on it (the embedded reconcile uses a 10s budget; this exercises the
    // force-fail half directly through the manager API).
    assert!(
        !manager
            .wait_for_idle("mock", std::time::Duration::from_millis(50))
            .await,
        "the slow in-flight call must keep the pool busy"
    );
    manager.remove("mock").await.expect("forced teardown");

    let error = call
        .await
        .expect("the in-flight call task")
        .expect_err("a torn-down in-flight call must fail");
    assert!(
        error.to_string().contains("mock"),
        "the forced-fail error must name the server: {error}"
    );
}

/// Given a slow mock tool that hangs past the config's `toolTimeoutMs`, when
/// the teardown is forced while the call is in flight (it neither completes
/// nor fails before its own timeout), then the timed-out call still fails
/// with an error naming the server — R2's force-fail half on the timeout
/// arm (T1 review F-T1-2), not a bare `Timeout`.
#[tokio::test]
async fn should_fail_a_timed_out_in_flight_call_with_the_server_named_when_the_teardown_is_forced()
{
    // The mock delays every request by 1s; the connect cycle (initialize +
    // tools/list) finishes well inside the 5s pool wait, while a tool call
    // outlives the 400ms `toolTimeoutMs` below.
    let mock = spawn_mock_mcp_http_server(1000, false).await;
    let (home, workspace) = layered_mcp_fixture(
        json!({}),
        Some(json!({
            "mock": {
                "transport": "http",
                "url": mock.url,
                "toolTimeoutMs": 400
            }
        })),
    );
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("reconcile-r2-force-timeout"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );
    let manager = Arc::clone(server.mcp_manager().expect("workspace manager attached"));

    server
        .call_method("mcp.list", json!({}))
        .await
        .expect("first call");
    wait_for_pool_state(&manager, "mock", "Connected", |state| {
        matches!(state, Some(mirri_mcp::McpConnectionState::Connected { .. }))
    })
    .await;

    let call = tokio::spawn({
        let manager = Arc::clone(&manager);
        async move { manager.call_tool("mock", "echo", json!({})).await }
    });
    tokio::time::sleep(std::time::Duration::from_millis(50)).await;

    // Force the teardown well before the call's own timeout fires: the
    // client is taken off the connection, so when the tool timeout elapses
    // the call must be re-attributed to the teardown with the server named.
    assert!(
        !manager
            .wait_for_idle("mock", std::time::Duration::from_millis(20))
            .await,
        "the hung in-flight call must keep the pool busy"
    );
    manager.remove("mock").await.expect("forced teardown");

    let error = call
        .await
        .expect("the in-flight call task")
        .expect_err("a torn-down timed-out call must fail");
    assert!(
        error.to_string().contains("mock"),
        "the timed-out forced-fail error must name the server: {error}"
    );
}

// ---------------------------------------------------------------------------
// Plugin-contributed MCP servers (batch 3c) — the per-server user state
// ---------------------------------------------------------------------------

/// A `mcp_config_test_server` variant with a plugin manager wired: one
/// enabled plugin (`demo-plugin`) contributing one MCP server (`helper`,
/// an unconnectable stdio command — connection failures are expected and
/// non-blocking for the config surface). The plugins dir must outlive the
/// server: the store reads `installed.json` from it on every write.
async fn mcp_config_plugin_server() -> (
    EmbeddedServer,
    tempfile::TempDir,
    tempfile::TempDir,
    tempfile::TempDir,
) {
    let home = tempfile::tempdir().expect("home tempdir");
    let workspace = tempfile::tempdir().expect("workspace tempdir");

    let source_dir = tempfile::tempdir().expect("plugin source dir");
    std::fs::write(
        source_dir.path().join("mirri.plugin.json"),
        r#"{"name":"demo-plugin","description":"demo","mcpServers":{"helper":{"transport":"stdio","command":"mirri-missing-binary","args":["server.js"]}}}"#,
    )
    .expect("plugin manifest");

    let plugins_dir = tempfile::tempdir().expect("plugins dir");
    let manager = mirri_plugin_host::PluginManager::new(plugins_dir.path().to_path_buf());
    manager
        .install(&format!("local:{}", source_dir.path().display()))
        .await
        .expect("plugin install");

    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("mcp-plugin-ws"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );
    (
        server.with_plugin_manager(std::sync::Arc::new(manager)),
        home,
        workspace,
        plugins_dir,
    )
}

/// Given an installed plugin contributing an MCP server, when the
/// scope-less config view is listed, then the plugin entry appears with the
/// manifest config and the state-derived effective view — and the scoped
/// views stay file-only.
#[tokio::test]
async fn should_list_plugin_entries_with_user_state_when_mcp_config_list_is_called() {
    let (server, _home, _workspace, _plugins_dir) = mcp_config_plugin_server().await;

    let listed = server
        .call_method("mcp.config.list", json!({}))
        .await
        .expect("the merged view must list");
    let entries = mcp_config_entries(&listed);
    let entry = &entries["helper"];
    assert_eq!(entry["source"], "plugin");
    assert_eq!(entry["runtimeName"], "plugin-demo-plugin:helper");
    assert_eq!(entry["config"]["command"], "mirri-missing-binary");
    assert_eq!(entry["effective"]["enabled"], true);
    assert!(
        entry["effective"].get("enabledTools").is_none(),
        "no tool filter is recorded yet: {entry}"
    );

    // The per-server state overrides the manifest-derived view, and a
    // disabled server still lists so the view can re-enable it.
    server
        .call_method(
            "plugin.setMcpServerEnabled",
            json!({ "id": "demo-plugin", "server": "helper", "enabled": false }),
        )
        .await
        .expect("disabling the plugin server must succeed");
    let listed = server
        .call_method("mcp.config.list", json!({}))
        .await
        .expect("re-list");
    let entry = &mcp_config_entries(&listed)["helper"];
    assert_eq!(entry["effective"]["enabled"], false);

    // Scoped views never carry plugin entries (A1: plugin servers are not
    // file-layer config).
    for scope in ["user", "workspace"] {
        let scoped = server
            .call_method("mcp.config.list", json!({ "scope": scope }))
            .await
            .expect("the scoped view must list");
        assert!(
            mcp_config_entries(&scoped).is_empty(),
            "{scope} view must stay file-only: {scoped}"
        );
    }
}

/// Given an installed plugin contributing an MCP server, when a tool
/// filter targets its runtime name, then the patch writes the plugin user
/// state and the merged view reflects it; an unknown plugin server
/// answers the domain-coded not-found.
#[tokio::test]
async fn should_write_the_plugin_user_state_when_a_tool_filter_targets_a_plugin_server() {
    let (server, _home, _workspace, _plugins_dir) = mcp_config_plugin_server().await;

    server
        .call_method(
            "mcp.config.setToolFilter",
            json!({ "name": "plugin-demo-plugin:helper", "filter": { "enabledTools": ["one"] } }),
        )
        .await
        .expect("patching a plugin server's tool filter must succeed");

    let listed = server
        .call_method("mcp.config.list", json!({}))
        .await
        .expect("re-list");
    let entry = &mcp_config_entries(&listed)["helper"];
    assert_eq!(entry["effective"]["enabledTools"], json!(["one"]));

    let missing_error = server
        .call_method(
            "mcp.config.setToolFilter",
            json!({ "name": "plugin-demo-plugin:ghost", "filter": {} }),
        )
        .await
        .expect_err("an unknown plugin server must answer not-found");
    assert!(
        matches!(missing_error,
            EngineError::Rpc { code: -32001, data: Some(ref data), .. }
                if data.get("domainCode").and_then(Value::as_str) == Some("mcp.server_not_found")),
        "error: {missing_error}"
    );
}

/// Given a plugin-contributed server that has no config-layer file (its
/// list entry carries `revision: "absent"`), when a tool filter targets it
/// with a non-`"absent"` `expectedRevision`, then the write is rejected as
/// invalid params naming the plugin server — a client can never hold a lock
/// token for a layer that does not exist — and the filter is left
/// unchanged; the literal `"absent"` token still proceeds (the only value
/// the entry's revision can legitimately carry).
#[tokio::test]
async fn should_reject_expected_revision_on_a_plugin_server_when_the_token_is_not_absent() {
    // Given an installed plugin contributing a server and no filter
    let (server, _home, _workspace, _plugins_dir) = mcp_config_plugin_server().await;
    let listed = server
        .call_method("mcp.config.list", json!({}))
        .await
        .expect("list");
    let entry = &mcp_config_entries(&listed)["helper"];
    assert_eq!(
        entry["revision"], "absent",
        "the plugin entry lists the absent revision: {entry}"
    );

    // When a setToolFilter targets the plugin runtime name with a
    // non-"absent" expectedRevision
    let result = server
        .call_method(
            "mcp.config.setToolFilter",
            json!({
                "name": "plugin-demo-plugin:helper",
                "filter": { "enabledTools": ["one"] },
                "expectedRevision": "0000000000000000"
            }),
        )
        .await;

    // Then the call is rejected as invalid params naming the plugin server
    // and the filter stays unset
    let err = result.expect_err("a non-absent token on a plugin server must be rejected");
    assert!(
        matches!(err, EngineError::Rpc { code: -32602, ref message, .. }
            if message.contains("plugin")),
        "the rejection names the plugin server: {err}"
    );
    let listed = server
        .call_method("mcp.config.list", json!({}))
        .await
        .expect("re-list");
    let entry = &mcp_config_entries(&listed)["helper"];
    assert!(
        entry["effective"].get("enabledTools").is_none(),
        "the rejected patch never lands: {entry}"
    );

    // When the literal "absent" token — the revision the plugin entry
    // lists — is side-carried, the patch proceeds
    server
        .call_method(
            "mcp.config.setToolFilter",
            json!({
                "name": "plugin-demo-plugin:helper",
                "filter": { "enabledTools": ["two"] },
                "expectedRevision": "absent"
            }),
        )
        .await
        .expect("the absent token must match and proceed");
    let listed = server
        .call_method("mcp.config.list", json!({}))
        .await
        .expect("re-list");
    assert_eq!(
        mcp_config_entries(&listed)["helper"]["effective"]["enabledTools"],
        json!(["two"])
    );
}

/// Given a server with both a plugin manager and an MCP connection manager,
/// when a plugin server is disabled and re-enabled, then the live
/// connection set follows — the runtime-name entry unregisters on disable
/// and reconnects on enable; unknown ids and servers answer not-found.
#[tokio::test]
async fn should_follow_the_live_connection_when_a_plugin_server_is_toggled() {
    let (server, _home, _workspace, _plugins_dir) = mcp_config_plugin_server().await;
    let server =
        server.with_mcp_manager(std::sync::Arc::new(mirri_mcp::McpConnectionManager::new()));

    // The first call triggers the startup connect set, which now includes
    // the plugin server; wait for it to settle before toggling.
    let runtime_name = "plugin-demo-plugin:helper";
    let mut connected = false;
    for _ in 0..50 {
        let listed = server
            .call_method("mcp.global.list", json!({}))
            .await
            .expect("mcp.global.list");
        let present = listed
            .as_array()
            .expect("the list result is an array")
            .iter()
            .any(|entry| entry["name"].as_str() == Some(runtime_name));
        if present {
            connected = true;
            break;
        }
        tokio::time::sleep(std::time::Duration::from_millis(100)).await;
    }
    assert!(
        connected,
        "the plugin server must join the startup connect set"
    );

    server
        .call_method(
            "plugin.setMcpServerEnabled",
            json!({ "id": "demo-plugin", "server": "helper", "enabled": false }),
        )
        .await
        .expect("disabling the plugin server must succeed");
    let listed = server
        .call_method("mcp.global.list", json!({}))
        .await
        .expect("mcp.global.list");
    assert!(
        !listed
            .as_array()
            .expect("the list result is an array")
            .iter()
            .any(|entry| entry["name"].as_str() == Some(runtime_name)),
        "a disabled plugin server unregisters: {listed}"
    );

    server
        .call_method(
            "plugin.setMcpServerEnabled",
            json!({ "id": "demo-plugin", "server": "helper", "enabled": true }),
        )
        .await
        .expect("re-enabling the plugin server must succeed");
    let listed = server
        .call_method("mcp.global.list", json!({}))
        .await
        .expect("mcp.global.list");
    assert!(
        listed
            .as_array()
            .expect("the list result is an array")
            .iter()
            .any(|entry| entry["name"].as_str() == Some(runtime_name)),
        "a re-enabled plugin server reconnects: {listed}"
    );

    let plugin_error = server
        .call_method(
            "plugin.setMcpServerEnabled",
            json!({ "id": "ghost-plugin", "server": "helper", "enabled": true }),
        )
        .await
        .expect_err("an unknown plugin must answer not-found");
    assert!(
        matches!(plugin_error, EngineError::Rpc { code: -32001, .. }),
        "error: {plugin_error}"
    );

    let server_error = server
        .call_method(
            "plugin.setMcpServerEnabled",
            json!({ "id": "demo-plugin", "server": "ghost", "enabled": true }),
        )
        .await
        .expect_err("an unknown plugin server must answer domain not-found");
    assert!(
        matches!(server_error,
            EngineError::Rpc { code: -32001, data: Some(ref data), .. }
                if data.get("domainCode").and_then(Value::as_str) == Some("mcp.server_not_found")),
        "error: {server_error}"
    );
}

/// Given a server with a plugin-contributed MCP server in the live
/// connection set, when the installed manifest gains a second server and
/// `plugin.reload` runs, then the live set reconciles to the fresh desired
/// set — the new server connects while the existing one stays — and a
/// server disabled through the per-server state stays disconnected across
/// the reload (item C4, the TS `onDidReload` MCP reconcile).
#[tokio::test]
async fn should_reconcile_plugin_mcp_connections_when_a_plugin_reloads() {
    // Given a server with the plugin MCP server in the startup connect set
    let (server, _home, _workspace, plugins_dir) = mcp_config_plugin_server().await;
    let server =
        server.with_mcp_manager(std::sync::Arc::new(mirri_mcp::McpConnectionManager::new()));
    let helper_name = "plugin-demo-plugin:helper";
    server
        .call_method("mcp.global.list", json!({}))
        .await
        .expect("first call triggers the startup connect set");
    async fn wait_for_server(server: &EmbeddedServer, name: &str, present: bool) -> bool {
        for _ in 0..50 {
            let listed = server
                .call_method("mcp.global.list", json!({}))
                .await
                .expect("mcp.global.list");
            let seen = listed
                .as_array()
                .expect("the list result is an array")
                .iter()
                .any(|entry| entry["name"].as_str() == Some(name));
            if seen == present {
                return true;
            }
            tokio::time::sleep(std::time::Duration::from_millis(100)).await;
        }
        false
    }
    assert!(
        wait_for_server(&server, helper_name, true).await,
        "the plugin server must join the startup connect set"
    );

    // When the installed manifest gains a second server and the plugin
    // reloads
    let plugin_root = plugins_dir.path().join("managed").join("demo-plugin");
    std::fs::write(
        plugin_root.join("mirri.plugin.json"),
        r#"{"name":"demo-plugin","description":"demo","mcpServers":{"helper":{"transport":"stdio","command":"mirri-missing-binary","args":["server.js"]},"helper2":{"transport":"stdio","command":"mirri-missing-binary","args":["server2.js"]}}}"#,
    )
    .expect("plugin manifest rewrite");
    server
        .call_method("plugin.reload", json!({ "pluginId": "demo-plugin" }))
        .await
        .expect("plugin.reload");

    // Then the live set reconciles: the new server connects and the
    // existing one stays
    assert!(
        wait_for_server(&server, "plugin-demo-plugin:helper2", true).await,
        "the reloaded plugin's new server must join the live set"
    );
    assert!(
        wait_for_server(&server, helper_name, true).await,
        "the existing plugin server stays connected"
    );

    // And a server disabled through the per-server state stays
    // disconnected across another reload (the reconcile honors the state)
    server
        .call_method(
            "plugin.setMcpServerEnabled",
            json!({ "id": "demo-plugin", "server": "helper2", "enabled": false }),
        )
        .await
        .expect("disabling helper2 must succeed");
    assert!(
        wait_for_server(&server, "plugin-demo-plugin:helper2", false).await,
        "disabling unregisters the live entry"
    );
    server
        .call_method("plugin.reload", json!({ "pluginId": "demo-plugin" }))
        .await
        .expect("second plugin.reload");
    assert!(
        wait_for_server(&server, "plugin-demo-plugin:helper2", false).await,
        "the disabled server stays disconnected across the reload"
    );
}

/// `mcp_config_plugin_server` with a `config.toml` seed written into the
/// home before assembly — lets a test configure the `mirri-code` provider
/// (the item A7 managed-env fallback source, the TS `provider?.baseUrl`).
async fn mcp_config_plugin_server_with_config(
    config_toml: &str,
) -> (
    EmbeddedServer,
    tempfile::TempDir,
    tempfile::TempDir,
    tempfile::TempDir,
) {
    let home = tempfile::tempdir().expect("home tempdir");
    std::fs::write(home.path().join("config.toml"), config_toml).expect("config.toml");
    let workspace = tempfile::tempdir().expect("workspace tempdir");

    let source_dir = tempfile::tempdir().expect("plugin source dir");
    std::fs::write(
        source_dir.path().join("mirri.plugin.json"),
        r#"{"name":"demo-plugin","description":"demo","mcpServers":{"helper":{"transport":"stdio","command":"mirri-missing-binary","args":["server.js"]}}}"#,
    )
    .expect("plugin manifest");

    let plugins_dir = tempfile::tempdir().expect("plugins dir");
    let manager = mirri_plugin_host::PluginManager::new(plugins_dir.path().to_path_buf());
    manager
        .install(&format!("local:{}", source_dir.path().display()))
        .await
        .expect("plugin install");

    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("mcp-plugin-ws"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );
    (
        server.with_plugin_manager(std::sync::Arc::new(manager)),
        home,
        workspace,
        plugins_dir,
    )
}

/// Poll the workspace manager's stored plugin server config until the
/// startup connect set registers it. Registration precedes the spawn
/// attempt, so a failed spawn (`mirri-missing-binary`) still leaves the
/// config observable — the exact shape the connection layer received
/// (item A7).
async fn wait_for_plugin_server_config(
    server: &EmbeddedServer,
    runtime_name: &str,
) -> mirri_mcp::McpServerConfig {
    let manager = server.mcp_manager().expect("workspace manager attached");
    for _ in 0..50 {
        if let Some(config) = manager.get_server_config(runtime_name).await {
            return config;
        }
        tokio::time::sleep(std::time::Duration::from_millis(100)).await;
    }
    panic!("plugin server config {runtime_name} never reached the connection layer");
}

/// Serializes the item A7 managed-env e2e tests: they manipulate ambient
/// `MIRRICODE_BASE_URL` vars, which are process-global — a parallel
/// sibling would observe the override and misread its own source
/// resolution.
static MANAGED_PLUGIN_ENV_LOCK: tokio::sync::Mutex<()> = tokio::sync::Mutex::const_new(());

/// Removes every managed-env var on drop — panic-safe cleanup so a failed
/// ambient-env test never leaks process-global state into later runs.
struct ManagedEnvGuard;
impl Drop for ManagedEnvGuard {
    fn drop(&mut self) {
        unsafe {
            std::env::remove_var("MIRRICODE_BASE_URL");
        }
    }
}

/// Given an assembled server with an installed plugin contributing a stdio
/// MCP server and ambient `MIRRICODE_BASE_URL` env var, when the
/// startup connect set is spawned, then the plugin
/// server's config reaches the connection layer with the managed env
/// merged over the manager-level decoration (item A7 — the TS
/// `withManagedMirriPluginEnv` in pluginService.ts):
/// `MIRRICODE_BASE_URL` carries the trailing-slash-stripped env value,
/// alongside `MIRRICODE_HOME` / `MIRRI_PLUGIN_ROOT` and the cwd default.
#[tokio::test]
async fn should_inject_managed_mirri_env_into_plugin_stdio_servers_when_ambient_env_is_set() {
    let _guard = MANAGED_PLUGIN_ENV_LOCK.lock().await;
    // Given a server with the plugin stdio server in the startup set and
    // the managed env var set (an ambient override, trailing slashes
    // included to lock the trim)
    let (server, _home, _workspace, _plugins_dir) = mcp_config_plugin_server().await;
    let server =
        server.with_mcp_manager(std::sync::Arc::new(mirri_mcp::McpConnectionManager::new()));
    unsafe {
        std::env::set_var("MIRRICODE_BASE_URL", "https://managed.example.test//");
    }
    let _cleanup = ManagedEnvGuard;

    // When the first call spawns the startup connect set
    server
        .call_method("mcp.global.list", json!({}))
        .await
        .expect("first call triggers the startup connect set");

    // Then the config the connection layer stores carries the merged env
    let config = wait_for_plugin_server_config(&server, "plugin-demo-plugin:helper").await;
    let mirri_mcp::McpTransportConfig::Stdio {
        command, env, cwd, ..
    } = config.transport
    else {
        panic!("the plugin server must be stdio");
    };
    assert_eq!(command, "mirri-missing-binary");
    let env = env.expect("runtime env injected");
    assert_eq!(
        env.get("MIRRICODE_BASE_URL").map(String::as_str),
        Some("https://managed.example.test"),
        "trailing slashes are stripped like the TS replace(/\\/+$/, '')"
    );
    assert!(
        env.contains_key("MIRRICODE_HOME") && env.contains_key("MIRRI_PLUGIN_ROOT"),
        "the manager-level runtime env facts stay present"
    );
    assert!(
        cwd.as_ref()
            .is_some_and(|cwd| cwd.ends_with("managed/demo-plugin")),
        "cwd defaults to the plugin root: {cwd:?}"
    );
}

/// Given an assembled server whose config.toml configures the `mirri-code`
/// provider's `baseUrl` — the TS `provider?.baseUrl` fallback — when the
/// startup connect set is spawned with no ambient override, then the
/// plugin stdio server's env carries the provider-derived
/// `MIRRICODE_BASE_URL` (item A7).
#[tokio::test]
async fn should_inject_managed_mirri_env_from_provider_config_when_no_ambient_override_is_set() {
    let _guard = MANAGED_PLUGIN_ENV_LOCK.lock().await;
    // Given a server whose config.toml seeds the mirri-code provider with a
    // baseUrl
    let (server, _home, _workspace, _plugins_dir) = mcp_config_plugin_server_with_config(
        r#"
[providers.mirri-code]
base_url = "https://managed.from-config.test"
"#,
    )
    .await;
    let server =
        server.with_mcp_manager(std::sync::Arc::new(mirri_mcp::McpConnectionManager::new()));

    // When the first call spawns the startup connect set
    server
        .call_method("mcp.global.list", json!({}))
        .await
        .expect("first call triggers the startup connect set");

    // Then the provider-derived managed env lands in the connection config
    let config = wait_for_plugin_server_config(&server, "plugin-demo-plugin:helper").await;
    let mirri_mcp::McpTransportConfig::Stdio { env, .. } = config.transport else {
        panic!("the plugin server must be stdio");
    };
    let env = env.expect("runtime env injected");
    assert_eq!(
        env.get("MIRRICODE_BASE_URL").map(String::as_str),
        Some("https://managed.from-config.test"),
        "the provider base_url is the fallback source"
    );
}

/// Given an assembled server with no `MIRRICODE_BASE_URL` source (no
/// ambient env, no configured `mirri-code` provider baseUrl), when the
/// startup connect set is spawned, then the plugin stdio server's env
/// carries only the manager-level decoration — the managed env defaults
/// to "inject nothing" (the TS `if (Object.keys(managedEnv).length === 0)`
/// early return, item A7 / decision D-A7). The `MIRRICODE_OAUTH_HOST`
/// var is never injected: the oauth host left with the managed-login
/// domain.
#[tokio::test]
async fn should_not_inject_managed_mirri_env_when_no_source_is_configured() {
    let _guard = MANAGED_PLUGIN_ENV_LOCK.lock().await;
    // Given a server with the plugin stdio server in the startup set and no
    // managed-env source anywhere
    let (server, _home, _workspace, _plugins_dir) = mcp_config_plugin_server().await;
    let server =
        server.with_mcp_manager(std::sync::Arc::new(mirri_mcp::McpConnectionManager::new()));

    // When the first call spawns the startup connect set
    server
        .call_method("mcp.global.list", json!({}))
        .await
        .expect("first call triggers the startup connect set");

    // Then only the manager-level decoration reaches the connection layer
    let config = wait_for_plugin_server_config(&server, "plugin-demo-plugin:helper").await;
    let mirri_mcp::McpTransportConfig::Stdio { env, .. } = config.transport else {
        panic!("the plugin server must be stdio");
    };
    let env = env.expect("runtime env injected");
    assert!(
        !env.contains_key("MIRRICODE_BASE_URL"),
        "no base url source means no MIRRICODE_BASE_URL injection"
    );
    assert!(
        !env.contains_key("MIRRICODE_OAUTH_HOST"),
        "no oauth host source means no MIRRICODE_OAUTH_HOST injection"
    );
    assert!(
        env.contains_key("MIRRICODE_HOME") && env.contains_key("MIRRI_PLUGIN_ROOT"),
        "the manager-level decoration stays"
    );
}

/// Given a plugin manifest that declares a tool filter, when a setToolFilter
/// patch carries only absent fields, then the explicit empty record persists
/// and every view (merged list, effective state) shows no filter — the
/// manifest value no longer applies (the record is the complete user state).
#[tokio::test]
async fn should_clear_a_manifest_tool_filter_when_the_plugin_patch_is_empty() {
    let home = tempfile::tempdir().expect("home tempdir");
    let workspace = tempfile::tempdir().expect("workspace tempdir");
    let source_dir = tempfile::tempdir().expect("plugin source dir");
    std::fs::write(
        source_dir.path().join("mirri.plugin.json"),
        r#"{"name":"demo-plugin","description":"demo","mcpServers":{"helper":{"transport":"stdio","command":"mirri-missing-binary","enabledTools":["manifest-tool"]}}}"#,
    )
    .expect("plugin manifest");
    let plugins_dir = tempfile::tempdir().expect("plugins dir");
    let manager = mirri_plugin_host::PluginManager::new(plugins_dir.path().to_path_buf());
    manager
        .install(&format!("local:{}", source_dir.path().display()))
        .await
        .expect("plugin install");
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("mcp-plugin-ws"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    )
    .with_plugin_manager(std::sync::Arc::new(manager));

    server
        .call_method(
            "mcp.config.setToolFilter",
            json!({ "name": "plugin-demo-plugin:helper", "filter": {} }),
        )
        .await
        .expect("an empty patch must succeed");

    let listed = server
        .call_method("mcp.config.list", json!({}))
        .await
        .expect("re-list");
    let entry = &mcp_config_entries(&listed)["helper"];
    assert_eq!(entry["effective"]["enabled"], true);
    assert!(
        entry["effective"].get("enabledTools").is_none(),
        "the manifest filter must not resurrect after an empty patch: {entry}"
    );
}

/// Given a plugin-contributed server, when the very first RPC disables it
/// (racing the startup connect set), then the background connect never
/// leaves a live connection behind — the reconcile after `connect_all`
/// removes what the stale snapshot connected.
#[tokio::test]
async fn should_not_connect_a_plugin_server_disabled_by_the_first_call() {
    let (server, _home, _workspace, _plugins_dir) = mcp_config_plugin_server().await;
    let server =
        server.with_mcp_manager(std::sync::Arc::new(mirri_mcp::McpConnectionManager::new()));

    // The first call triggers the startup connect spawn AND carries the
    // disable — the racy interleaving the reconcile must survive.
    server
        .call_method(
            "plugin.setMcpServerEnabled",
            json!({ "id": "demo-plugin", "server": "helper", "enabled": false }),
        )
        .await
        .expect("disabling the plugin server must succeed");

    let runtime_name = "plugin-demo-plugin:helper";
    for _ in 0..5 {
        tokio::time::sleep(std::time::Duration::from_millis(200)).await;
        let listed = server
            .call_method("mcp.global.list", json!({}))
            .await
            .expect("mcp.global.list");
        let present = listed
            .as_array()
            .expect("the list result is an array")
            .iter()
            .any(|entry| entry["name"].as_str() == Some(runtime_name));
        assert!(
            !present,
            "a plugin server disabled by the first call must never stay connected: {listed}"
        );
    }
}

#[tokio::test]
async fn should_return_not_implemented_when_unimplemented_background_and_shell_methods_are_called()
{
    // Given a plain server (the arms error before any session lookup)
    let (server, _tmp) = test_server(None);

    // `task.detach`, `shell.cancel`, and `shell.run` landed with the shell
    // runner (P3i) and have dedicated behaviour tests; the print-mode pair
    // (`session.waitForBackgroundTasksOnPrint` /
    // `session.handlePrintMainTurnCompleted`) landed with B1 and has
    // dedicated behaviour tests in `b1_print_mode_tests`; only the
    // remaining stub must still answer not_implemented.
    let methods = ["session.generateAgentsMd"];

    // When each method is called with plausible params
    // Then it fails with an explicit not_implemented error (not the former
    // silent acknowledgement)
    for method in methods {
        let error = server
            .call_method(
                method,
                json!({ "sessionId": "session-nope", "taskId": "nope", "id": "nope" }),
            )
            .await
            .expect_err("{method} must not silently succeed (P9)");
        assert!(
            matches!(
                error,
                EngineError::Rpc { code: -32603, data: Some(ref data), .. }
                    if data.get("domainCode").and_then(Value::as_str) == Some("not_implemented")
            ),
            "{method} must answer not_implemented, got: {error}"
        );
    }
}

// -------------------------------------------------------------------------
// Route-table parity (M3): the registry-driven dispatch's static route
// table must stay in exact bidirectional parity with the authoritative
// method registry, with unique wire names — no residual match remains.
// -------------------------------------------------------------------------

#[test]
fn should_keep_route_canonical_names_within_the_authoritative_registry_when_the_route_table_lists_them()
 {
    // Given the authoritative set of embedded-current canonical names
    let authoritative: std::collections::HashSet<&str> =
        mirri_proto::rpc::current_names_for(mirri_proto::rpc::RpcBackend::Embedded).collect();

    // When the route table's canonical names are checked against it
    // Then every canonical method is one the embedded registry actually
    // dispatches — no wild methods outside the authoritative table
    for route in routes::all_routes() {
        assert!(
            authoritative.contains(route.method),
            "route canonical name {:?} is not an embedded-current method",
            route.method
        );
    }
}

#[test]
fn should_keep_wire_names_unique_when_the_route_table_is_indexed() {
    // Given the route table's canonical names and legacy aliases
    // When every wire name is flattened into one set
    let mut seen: std::collections::HashSet<&str> = std::collections::HashSet::new();
    for route in routes::all_routes() {
        for name in std::iter::once(route.method).chain(route.aliases.iter().copied()) {
            assert!(
                seen.insert(name),
                "wire name {name:?} is claimed by more than one route; the \
                 lookup index would silently keep only the last one"
            );
        }
    }

    // Then the canonical names alone are unique as well
    let canonicals: std::collections::HashSet<&str> =
        routes::all_routes().map(|route| route.method).collect();
    assert_eq!(
        canonicals.len(),
        routes::all_routes().count(),
        "two routes share a canonical method name"
    );

    // And the flattened cardinality matches the full migrated arm total:
    // 25 session + 20 mcp + 17 agent/message/tool/skill + 21 core/config/
    // model/shell/btw/plugin + 17 task/cron/plan/goal/swarm + the M5-3b
    // core.echo drill route + the five B2 gap routes
    // (agent.getEffectiveThinkingLevel / listCommands / runCommand,
    // task.stop, agent.activity) + the B3 plugin.checkUpdates gap route
    // + the eight B4-a interaction routes (approval.decide/listPending,
    // question.answer/dismiss/listPending, interaction.listPending/
    // respond/isRecentlyResolved) + the six B4-b workspace routes
    // (workspace.list/createOrTouch/update/delete/get/handlerFor)
    // + the twenty-one B5-a shallow-batch routes (thirteen env reads,
    // five flag reads, two fs rows, one providerDiscovery row)
    // + the fourteen B5-b shallow-batch-B routes (five config section
    // methods, five model record/catalog methods, four provider CRUD
    // rows) + the B5-c model.generate deep route + the four batch-3 P1 MCP
    // config routes (list/set/remove/setToolFilter) + the two batch-4 P2
    // MCP pool routes (config.test, status) + the P5d session.getHistory
    // read route + the five P6 agent profile CRUD routes
    // (agent.listProfiles / getProfile / createProfile / updateProfile /
    // deleteProfile) + the P10 session.search literal-search read route
    // + the two T2 user-tool management routes (tool.listUserTools /
    // tool.setUserToolEnabled) + the M1 mcp.tools single-server tool
    // listing route + the P6 B4a providerDiscovery.listCatalog browse
    // route + the M5 mcp.config.preview resolved-value preview route
    // + the P7 B4b providerDiscovery.importCatalog import route
    // + the M6 mcp.sync idempotent reconcile route
    // + the three R4 Task 25 profile lifecycle routes
    // (agent.enableProfile / disableProfile / resetProfile)
    // + the W8 workspace.setTrust trust management route
    // + the two collaboration mode-gate routes (collaboration.enter /
    // collaboration.exit, mirroring the swarm routes)
    // + the two B8 skills management routes (skill.getContent /
    // skill.setEnabled, mirroring the skill.list route)
    // + the three B9 approval rule CRUD routes (approval.listRules /
    // addRule / removeRule, the user-level permission rule management
    // face over the config.toml [permission] section)
    // + the two B6 cron management routes (cron.delete / cron.trigger,
    // the session cron task management face)
    // + the B7 task overview route (task.listWorkspace, the workspace
    // live-session task aggregation face)
    // (the eight B5-d auth routes left with the managed-login domain
    // removal)
    // = 191.
    assert_eq!(
        routes::all_routes().count(),
        191,
        "flattened route count drifted from the migrated arm total"
    );
}

#[test]
fn should_cover_every_embedded_current_session_method_when_the_session_domain_is_migrated() {
    // Given the authoritative embedded-current names of the session domain
    let session_current: std::collections::HashSet<&str> =
        mirri_proto::rpc::methods_for(mirri_proto::rpc::RpcBackend::Embedded)
            .filter(|entry| entry.domain == mirri_proto::rpc::MethodDomain::Session)
            .map(|entry| entry.name)
            .collect();

    // When the route table's canonical names are collected
    let routed: std::collections::HashSet<&str> =
        routes::all_routes().map(|route| route.method).collect();

    // Then every embedded-current session method has a route (the full
    // bidirectional parity across all domains is pinned by the dedicated
    // registry-parity test below).
    let missing: Vec<&str> = session_current.difference(&routed).copied().collect();
    assert!(
        missing.is_empty(),
        "embedded-current session methods without a route: {missing:?}"
    );
}

