/// The embedded-current canonical names of one domain — the authoritative
/// set that domain's routes must cover once it has migrated (M3 batch 3
/// onward; batches 1/2 inline the same query in their tests).
fn embedded_current_domain_names(
    domain: mirri_proto::rpc::MethodDomain,
) -> std::collections::HashSet<&'static str> {
    mirri_proto::rpc::methods_for(mirri_proto::rpc::RpcBackend::Embedded)
        .filter(|entry| entry.domain == domain)
        .map(|entry| entry.name)
        .collect()
}

/// Assert every embedded-current method of one domain has a route (one
/// direction of full parity; b5 flips the residual-match TODO to the
/// bidirectional check).
fn assert_domain_fully_routed(domain: mirri_proto::rpc::MethodDomain) {
    let current = embedded_current_domain_names(domain);
    let routed: std::collections::HashSet<&str> =
        routes::all_routes().map(|route| route.method).collect();
    let missing: Vec<&str> = current.difference(&routed).copied().collect();
    assert!(
        missing.is_empty(),
        "embedded-current {domain:?} methods without a route: {missing:?}"
    );
}

