#[test]
fn should_match_the_authoritative_registry_exactly_when_every_domain_has_migrated() {
    // Given the migration is complete and the authoritative set of
    // embedded-current names (106 canonical entries — the plan.status row
    // routes under its own canonical name since the M3-c rename, the M5-3b
    // core.echo drill route, plus the five B1 session additions and the
    // five B2 gap routes including agent.activity)
    let authoritative: std::collections::HashSet<&str> =
        mirri_proto::rpc::current_names_for(mirri_proto::rpc::RpcBackend::Embedded).collect();

    // When the route table's canonical names are collected as a set
    let routed: std::collections::HashSet<&str> =
        routes::all_routes().map(|route| route.method).collect();

    // Then the two sets are identical in both directions: every route
    // canonical is a current embedded name, and every current embedded
    // name has a route — no wild routes, no unrouted registry methods
    let unrouted: Vec<&str> = authoritative.difference(&routed).copied().collect();
    assert!(
        unrouted.is_empty(),
        "embedded-current methods without a route: {unrouted:?}"
    );
    let wild: Vec<&str> = routed.difference(&authoritative).copied().collect();
    assert!(
        wild.is_empty(),
        "route canonical names outside the embedded registry: {wild:?}"
    );
    assert_eq!(
        routed.len(),
        191,
        "the route table and the registry must both count 191 methods"
    );
}

// --- agent.activity: the engine-folded activity view --------------------

/// Poll `agent.activity` until its result satisfies `check`, with a
/// deadline. Returns the last result.
async fn poll_agent_activity(
    server: &EmbeddedServer,
    session_id: &str,
    mut check: impl FnMut(&Value) -> bool,
) -> Value {
    let deadline = tokio::time::Instant::now() + tokio::time::Duration::from_secs(5);
    loop {
        let result = server
            .call_method(
                "agent.activity",
                json!({ "session_id": session_id, "agent_id": "main" }),
            )
            .await
            .expect("agent.activity must answer");
        if check(&result) {
            return result;
        }
        assert!(
            tokio::time::Instant::now() < deadline,
            "agent.activity never satisfied the poll condition: {result}"
        );
        tokio::time::sleep(tokio::time::Duration::from_millis(10)).await;
    }
}

/// Given a fire-mode turn blocked inside its (never-yielding) LLM stream,
/// when `agent.activity` is queried mid-turn, then the snapshot shows the
/// real in-flight state — lifecycle ready, `turn` present with the live
/// turnId/phase/step, no pending approvals or tool calls.
#[tokio::test]
async fn should_show_in_flight_turn_state_when_agent_activity_queried_mid_turn() {
    // Given a server whose LLM stream never yields (the turn stays in
    // flight until the test aborts it)
    let (server, _tmp) = test_server(Some(Arc::new(BlockingLlmFactory {
        llm: Arc::new(BlockingLlm),
    })));
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    // When a fire-mode turn is sent (the send returns while the turn runs)
    let sent = server
        .call_method(
            "message.send",
            json!({ "session_id": &session_id, "text": "hello", "mode": "fire" }),
        )
        .await
        .unwrap();

    // Then a mid-turn read observes the real in-flight state (poll until the
    // step loop's before_step + pre_llm_request hooks have fired — the
    // blocked stream keeps the phase at streaming from then on)
    let mid = poll_agent_activity(&server, &session_id, |state| {
        state["turn"]["phase"] == "streaming"
    })
    .await;
    assert_eq!(mid["lifecycle"], "ready", "params: {mid}");
    let turn = &mid["turn"];
    assert_eq!(turn["turnId"], json!(1), "the first turn of the flow");
    // The step loop's before_step (step 1) and pre_llm_request hooks have
    // both fired — the phase is streaming while the response is awaited.
    assert_eq!(turn["phase"], "streaming", "params: {mid}");
    assert_eq!(turn["step"], json!(1));
    assert_eq!(turn["ending"], false);
    assert_eq!(turn["pendingApprovals"], json!([]));
    assert_eq!(turn["activeToolCalls"], json!([]));
    assert!(
        turn["since"].as_u64().unwrap_or(0) > 0,
        "turn.since is a real ms-epoch start timestamp"
    );

    // Cleanup: abort the still-blocked turn (the turn never ends on its
    // own; the fire task's JoinHandle is cancelled by message.abort).
    server
        .call_method(
            "message.abort",
            json!({ "session_id": &session_id, "turnId": sent["turnId"] }),
        )
        .await
        .unwrap();
}

/// Given a completed wait-mode turn, when `agent.activity` is queried after
/// the turn ended, then `lastTurn` carries the turnId, the end_turn →
/// completed reason mapping, a real duration and end timestamp — and the
/// `turn` is absent (idle shape).
#[tokio::test]
async fn should_report_last_turn_with_mapped_reason_when_agent_activity_queried_after_turn_end() {
    // Given a server with a scripted mock LLM that ends the turn with a
    // plain text reply
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("Hello from the scripted LLM");
    let (server, _tmp) = test_server(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))));
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    // When a wait-mode turn runs to completion
    server
        .call_method(
            "message.send",
            json!({ "session_id": &session_id, "text": "hi" }),
        )
        .await
        .unwrap();

    // Then the activity view reports the ended turn and nothing in flight
    let result = server
        .call_method(
            "agent.activity",
            json!({ "session_id": &session_id, "agent_id": "main" }),
        )
        .await
        .unwrap();
    assert_eq!(result["lifecycle"], "ready", "params: {result}");
    assert!(
        result["turn"].is_null(),
        "the ended turn is no longer in flight"
    );
    assert_eq!(result["background"], json!([]));
    let last = &result["lastTurn"];
    assert_eq!(last["turnId"], json!(1), "params: {result}");
    assert_eq!(
        last["reason"], "completed",
        "the scripted EndTurn stop reason maps to the klient completed word"
    );
    assert!(
        last["durationMs"].as_u64().is_some(),
        "durationMs is present on the wire"
    );
    assert!(last["at"].as_u64().unwrap_or(0) > 0);
}

/// Given a tool call whose permission policy returns `Ask` and a
/// reverse-RPC handler that blocks before answering, when `agent.activity`
/// is queried during the approval wait, then the snapshot shows both the
/// pending approval (keyed by the tool call id — the engine→client
/// approval.ask request carries no request id) and the active tool call
/// window; both clear once the approval resolves.
#[tokio::test]
async fn should_show_pending_approval_and_active_tool_when_reverse_rpc_wait_in_flight() {
    // Given a blocking approval handler that approves once released
    let release = Arc::new(tokio::sync::Notify::new());
    let release_for_handler = Arc::clone(&release);
    let handler: ReverseRpcHandler = Arc::new(move |_method: String, _params: Value| {
        let release = Arc::clone(&release_for_handler);
        Box::pin(async move {
            release.notified().await;
            Ok(json!({ "decision": "approved" }))
        })
    });
    // And a scripted LLM that first calls Bash (not on the default-approve
    // list, so the fallback policy returns Ask under Manual mode), then
    // ends the turn.
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_tool_use(vec![mirri_core::LlmToolCall {
        id: "call_bash".to_string(),
        name: "Bash".to_string(),
        args: json!({ "command": "echo hello" }),
    }]);
    mock.push_text("done");
    let (server, _tmp) = test_server(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))));
    server.on_reverse_rpc(handler).await.unwrap();
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    // When the fire-mode turn reaches the approval wait
    server
        .call_method(
            "message.send",
            json!({ "session_id": &session_id, "text": "read env", "mode": "fire" }),
        )
        .await
        .unwrap();

    // Then the mid-wait snapshot shows the pending approval and the tool
    // window (prepare_tool_execution → the authorize wait).
    let mid = poll_agent_activity(&server, &session_id, |state| {
        state["turn"]["pendingApprovals"]
            .as_array()
            .is_some_and(|a| !a.is_empty())
    })
    .await;
    let turn = &mid["turn"];
    assert_eq!(turn["phase"], "tool_call", "params: {mid}");
    let pending = turn["pendingApprovals"].as_array().unwrap();
    assert_eq!(pending.len(), 1);
    assert_eq!(pending[0]["approvalId"], "call_bash");
    assert_eq!(pending[0]["toolCallId"], "call_bash");
    assert!(pending[0]["since"].as_u64().unwrap_or(0) > 0);
    let active = turn["activeToolCalls"].as_array().unwrap();
    assert_eq!(active.len(), 1);
    assert_eq!(active[0]["toolCallId"], "call_bash");
    assert_eq!(active[0]["name"], "Bash");

    // When the approval is granted and the turn finishes
    release.notify_one();
    let end = poll_agent_activity(&server, &session_id, |state| {
        state["turn"].is_null() && state["lastTurn"].is_object()
    })
    .await;

    // Then the pending approval and the tool call are both cleared
    // (lastTurn is the completed turn's record).
    assert_eq!(end["lastTurn"]["reason"], "completed");
}

