#[tokio::test]
async fn should_rename_the_workspace_when_updating_its_name() {
    // Given an assembled server with an injected home and a registered
    // second workspace (real builder + real persistence paths)
    let (server, _workspace, home) = assembled_server();
    let new_root = tempfile::tempdir().expect("new workspace tempdir");
    let workspace_id = mirri_core::encode_work_dir_key(new_root.path());
    server
        .call_method(
            "workspace.createOrTouch",
            json!({ "root": new_root.path().to_string_lossy(), "name": "before" }),
        )
        .await
        .expect("createOrTouch resolves");
    let mut events = server.subscribe_events().await.expect("subscriber");

    // When renaming the workspace (both key spellings)
    for (label, params) in [
        (
            "camelCase",
            json!({ "workspaceId": workspace_id, "name": "renamed" }),
        ),
        (
            "snake_case",
            json!({ "workspace_id": workspace_id, "name": "renamed" }),
        ),
    ] {
        let value = server
            .call_method("workspace.update", params)
            .await
            .expect("workspace.update resolves");

        // Then the result is the renamed workspace's view (the W6 real
        // semantics — no more `applied: false` honest ack)
        assert_eq!(value["id"], json!(workspace_id), "{label}: the view id");
        assert_eq!(value["name"], json!("renamed"), "{label}: the new name");
        assert_eq!(value["sessionCount"], json!(0), "{label}: the count");

        // And the rename is visible through the listing immediately
        let listed = list_workspace_ids(&server).await;
        assert!(listed.contains(&workspace_id), "{label}: still registered");

        // And the rename landed in the cross-engine registry file
        let registry: serde_json::Value = serde_json::from_str(
            &std::fs::read_to_string(home_registry_path(&home)).expect("workspaces.json written"),
        )
        .expect("workspaces.json parses");
        assert_eq!(
            registry["workspaces"][&workspace_id]["name"],
            json!("renamed"),
            "{label}: the registry file carries the new name"
        );

        // And the lifecycle event was announced (server-scoped envelope)
        let notification = tokio::time::timeout(std::time::Duration::from_secs(2), events.recv())
            .await
            .expect("{label}: the updated event must arrive")
            .expect("a notification is delivered");
        assert_eq!(notification.method, "event.workspace.updated");
        assert_eq!(notification.params["sessionId"], json!(""));
        assert_eq!(
            notification.params["workspace"]["id"],
            json!(workspace_id),
            "{label}: the event names the renamed workspace"
        );
    }
}

