#[tokio::test]
async fn should_purge_the_workspace_data_when_deleting_in_purge_mode() {
    // Given an assembled server with a registered second workspace holding
    // one live session
    let (server, _workspace, home) = assembled_server();
    let new_root = tempfile::tempdir().expect("new workspace tempdir");
    let workspace_id = mirri_core::encode_work_dir_key(new_root.path());
    server
        .call_method(
            "workspace.createOrTouch",
            json!({ "root": new_root.path().to_string_lossy(), "name": "doomed" }),
        )
        .await
        .expect("createOrTouch resolves");
    let created = server
        .call_method(
            "session.create",
            json!({ "title": "Doomed", "workspaceId": workspace_id }),
        )
        .await
        .expect("session.create routes to the workspace");
    let session_id = created["id"].as_str().expect("session id").to_string();
    converse_once(&server, &session_id).await;
    server.registry.flush_pending_registry_touches();
    let index = server.session_index().expect("the index is open");
    assert!(
        index.get_session(&session_id).is_some(),
        "the session row exists before the purge"
    );
    let mut events = server.subscribe_events().await.expect("subscriber");

    // When deleting the workspace in purge mode
    let value = server
        .call_method(
            "workspace.delete",
            json!({ "workspaceId": workspace_id, "mode": "purge" }),
        )
        .await
        .expect("workspace.delete resolves");

    // Then the result reports the executed mode and the removed rows
    assert_eq!(
        value,
        json!({
            "ok": true,
            "mode": "purge",
            "workspaceId": workspace_id,
            "deletedSessions": 1,
        })
    );
    // And the workspace is gone from the listing…
    let listed = list_workspace_ids(&server).await;
    assert!(!listed.contains(&workspace_id), "the row is unregistered");
    // …and the index rows (session + workspace) are deleted…
    assert!(
        index.get_session(&session_id).is_none(),
        "the session row is purged"
    );
    assert!(
        index.get_workspace(&workspace_id).is_none(),
        "the workspace row is purged"
    );
    // …and the bucket directory is removed…
    let bucket = home.path().join("v3_sessions").join(&workspace_id);
    assert!(!bucket.exists(), "the bucket directory is purged");
    // …and the registry file tombstones the id (a cold read never sees it)
    let registry: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(home_registry_path(&home)).expect("workspaces.json written"),
    )
    .expect("workspaces.json parses");
    assert_eq!(
        registry["deleted_workspace_ids"],
        json!([workspace_id]),
        "the purge tombstones the id"
    );
    assert!(
        registry["workspaces"].get(&workspace_id).is_none(),
        "the purge removed the file row"
    );

    // And the lifecycle event was announced after the persistence landed
    // (the converse's message events ride the same stream — scan to the
    // deleted event).
    let mut notification = None;
    for _ in 0..16 {
        let received = tokio::time::timeout(std::time::Duration::from_secs(2), events.recv())
            .await
            .expect("the deleted event must arrive")
            .expect("a notification is delivered");
        if received.method == "event.workspace.deleted" {
            notification = Some(received);
            break;
        }
    }
    let notification =
        notification.expect("the deleted event must be delivered on the event stream");
    assert_eq!(notification.params["workspaceId"], json!(workspace_id));
    assert_eq!(
        notification.params["root"],
        json!(new_root.path().to_string_lossy()),
        "the deleted event carries the workspace root"
    );
}

#[tokio::test]
async fn should_preserve_the_workspace_data_when_deleting_in_remove_mode() {
    // Given an assembled server with a registered second workspace holding
    // one live session
    let (server, _workspace, home) = assembled_server();
    let new_root = tempfile::tempdir().expect("new workspace tempdir");
    let workspace_id = mirri_core::encode_work_dir_key(new_root.path());
    server
        .call_method(
            "workspace.createOrTouch",
            json!({ "root": new_root.path().to_string_lossy(), "name": "parked" }),
        )
        .await
        .expect("createOrTouch resolves");
    let created = server
        .call_method(
            "session.create",
            json!({ "title": "Parked", "workspaceId": workspace_id }),
        )
        .await
        .expect("session.create routes to the workspace");
    let session_id = created["id"].as_str().expect("session id").to_string();
    converse_once(&server, &session_id).await;
    server.registry.flush_pending_registry_touches();
    let index = server.session_index().expect("the index is open");

    // When deleting the workspace in remove mode
    let value = server
        .call_method(
            "workspace.delete",
            json!({ "workspaceId": workspace_id, "mode": "remove" }),
        )
        .await
        .expect("workspace.delete resolves");

    // Then the result reports the executed mode with zero deleted rows…
    assert_eq!(
        value,
        json!({
            "ok": true,
            "mode": "remove",
            "workspaceId": workspace_id,
            "deletedSessions": 0,
        })
    );
    // …the workspace is gone from the listing (the tombstone)…
    let listed = list_workspace_ids(&server).await;
    assert!(!listed.contains(&workspace_id), "the row is unregistered");
    // …but EVERY byte is preserved: the session row, the index workspace
    // row, and the bucket directory all survive for a re-register restore.
    assert!(
        index.get_session(&session_id).is_some(),
        "the session row is preserved (data-preserving mode)"
    );
    let bucket = home.path().join("v3_sessions").join(&workspace_id);
    assert!(bucket.exists(), "the bucket directory is preserved");
    let registry: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(home_registry_path(&home)).expect("workspaces.json written"),
    )
    .expect("workspaces.json parses");
    assert_eq!(
        registry["deleted_workspace_ids"],
        json!([workspace_id]),
        "the remove tombstones the id (a cold read never sees it)"
    );
}

#[tokio::test]
async fn should_restore_a_removed_workspace_when_the_same_root_is_re_registered() {
    // Given an assembled server whose second workspace was REMOVED (data
    // preserved, tombstoned)
    let (server, _workspace, home) = assembled_server();
    let new_root = tempfile::tempdir().expect("new workspace tempdir");
    let workspace_id = mirri_core::encode_work_dir_key(new_root.path());
    server
        .call_method(
            "workspace.createOrTouch",
            json!({ "root": new_root.path().to_string_lossy(), "name": "removed" }),
        )
        .await
        .expect("createOrTouch resolves");
    server
        .call_method(
            "workspace.delete",
            json!({ "workspaceId": workspace_id, "mode": "remove" }),
        )
        .await
        .expect("remove resolves");

    // When the same root is re-registered through createOrTouch
    let value = server
        .call_method(
            "workspace.createOrTouch",
            json!({ "root": new_root.path().to_string_lossy(), "name": "restored" }),
        )
        .await
        .expect("re-register resolves");

    // Then the workspace is back (the reinstating write cleared the
    // tombstone — the D4 "cleared on re-register" rule)
    assert_eq!(value["id"], json!(workspace_id));
    assert_eq!(value["name"], json!("restored"));
    let listed = list_workspace_ids(&server).await;
    assert!(
        listed.contains(&workspace_id),
        "the row is registered again"
    );
    let registry: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(home_registry_path(&home)).expect("workspaces.json written"),
    )
    .expect("workspaces.json parses");
    assert!(
        registry["workspaces"].get(&workspace_id).is_some(),
        "the reinstating write restored the file row"
    );
    assert_eq!(
        registry["deleted_workspace_ids"],
        json!([]),
        "the reinstating write cleared the tombstone"
    );

    // And a cold registry read over the same home sees the restored
    // workspace (the read-side tombstone filter no longer hides it).
    let cold_read = mirri_session_index::read_workspace_registry(&home_registry_path(&home));
    assert!(
        cold_read.iter().any(|row| row.id == workspace_id),
        "a cold read sees the re-registered workspace"
    );
}

#[tokio::test]
async fn should_refuse_to_delete_the_default_workspace() {
    // Given an assembled server (its bound root is the pinned default,
    // registered under the derived work-dir key)
    let (server, workspace, _home) = assembled_server();
    let default_id = server
        .registry
        .default_workspace_id()
        .expect("a default is pinned");
    assert_eq!(
        default_id,
        mirri_core::encode_work_dir_key(workspace.path()),
        "the assembled default is the bound root"
    );

    // When deleting the default workspace in either mode
    for params in [
        json!({ "workspaceId": default_id, "mode": "purge" }),
        json!({ "workspaceId": default_id, "mode": "remove" }),
    ] {
        let error = server
            .call_method("workspace.delete", params)
            .await
            .unwrap_err();

        // Then the request is refused with invalid params — the default is
        // pinned to this engine's process root and every degrade path
        // addresses its runtime (a default re-election is a W9 candidate)
        assert!(
            matches!(&error, EngineError::Rpc { code, .. } if *code == -32602),
            "deleting the default must be refused: {error:?}"
        );
    }
    // And the default is still registered
    let listed = list_workspace_ids(&server).await;
    assert!(listed.contains(&default_id));
    assert!(workspace.path().exists(), "the default's data is untouched");
}

