#[tokio::test]
async fn should_write_the_registry_once_when_five_session_creations_quiesce() {
    // Given an assembled server with a registered second workspace whose
    // registry row is settled on disk
    let (server, _workspace, home) = assembled_server();
    let new_root = tempfile::tempdir().expect("new workspace tempdir");
    let workspace_id = mirri_core::encode_work_dir_key(new_root.path());
    server
        .call_method(
            "workspace.createOrTouch",
            json!({ "root": new_root.path().to_string_lossy(), "name": "busy" }),
        )
        .await
        .expect("createOrTouch resolves");
    let settled: serde_json::Value = serde_json::from_str(
        &std::fs::read_to_string(home_registry_path(&home)).expect("workspaces.json written"),
    )
    .expect("workspaces.json parses");
    let settled_touch = settled["workspaces"][&workspace_id]["last_opened_at"]
        .as_str()
        .expect("the settled last_opened_at")
        .to_string();

    // When five sessions are created in the workspace (each creation is a
    // debounced in-memory touch — never a direct registry write)
    for index in 0..5 {
        server
            .call_method(
                "session.create",
                json!({ "title": format!("s{index}"), "workspaceId": workspace_id }),
            )
            .await
            .expect("session.create routes to the workspace");
    }

    // Then the registry file is untouched (the write-amplification red
    // line: N touches → 0 writes)…
    let on_disk = std::fs::read_to_string(home_registry_path(&home)).unwrap();
    let touched_file: serde_json::Value = serde_json::from_str(&on_disk).unwrap();
    assert_eq!(
        touched_file["workspaces"][&workspace_id]["last_opened_at"],
        json!(settled_touch),
        "no session.create may write the registry before the debounce window ends"
    );
    assert!(
        server.registry.has_pending_registry_touches(),
        "the five touches are pending a flush"
    );

    // …and when the debounce quiesces, exactly ONE merged write lands…
    assert!(server.registry.flush_pending_registry_touches());
    assert_eq!(
        server.registry.touch_flush_count(),
        1,
        "five touches must produce exactly one flush"
    );
    let flushed: serde_json::Value =
        serde_json::from_str(&std::fs::read_to_string(home_registry_path(&home)).unwrap()).unwrap();
    assert_ne!(
        flushed["workspaces"][&workspace_id]["last_opened_at"],
        json!(settled_touch),
        "the flushed file carries the advanced last_opened_at"
    );

    // …and a second quiesce writes nothing more.
    assert!(!server.registry.flush_pending_registry_touches());
    assert_eq!(server.registry.touch_flush_count(), 1);
}

