// --- B4-b/W2: the real registry semantics (createOrTouch persistence, ---
// --- idempotent touch, list ordering, multi-client lifecycle events) ----

/// An assembled server on a throwaway workspace with an injected home —
/// the shape that owns a real runtime builder (so `createOrTouch` of a new
/// root can register + build) and a real registry file + session index
/// (so persistence is assertable).
/// Write the test default-model config.toml seed into an injected test
/// home — the fixture equivalent of a real user's config.toml. Needed
/// because the create chain requires a resolvable model (spec 11 R4 — no
/// built-in fallback).
fn seed_home_default_model(home: &std::path::Path) {
    std::fs::write(
        home.join("config.toml"),
        format!("default_model = \"{TEST_DEFAULT_MODEL}\"\n"),
    )
    .expect("seed config.toml must be writable");
}

fn assembled_server() -> (EmbeddedServer, tempfile::TempDir, tempfile::TempDir) {
    let workspace = tempfile::tempdir().expect("workspace tempdir");
    let home = tempfile::tempdir().expect("home tempdir");
    // The create chain requires a resolvable model (spec 11 R4 — no
    // built-in fallback), so the injected home carries a config.toml seed,
    // exactly like a real user's home would.
    seed_home_default_model(home.path());
    let server = EmbeddedServer::for_workspace_root(
        WorkspaceId::new("wired-ws"),
        workspace.path().to_path_buf(),
        Some(home.path().to_path_buf()),
        Vec::new(),
    );
    (server, workspace, home)
}

/// The registry file under an injected home (the assembled_server helper's
/// home).
fn home_registry_path(home: &tempfile::TempDir) -> std::path::PathBuf {
    home.path()
        .join(mirri_session_index::WORKSPACE_REGISTRY_FILENAME)
}

/// The workspace ids of a `workspace.list` call, in wire order.
async fn list_workspace_ids(server: &EmbeddedServer) -> Vec<String> {
    let listing = server
        .call_method("workspace.list", json!({}))
        .await
        .expect("workspace.list resolves");
    listing
        .as_array()
        .expect("bare array")
        .iter()
        .map(|entry| entry["id"].as_str().unwrap().to_string())
        .collect::<Vec<_>>()
}

#[tokio::test]
async fn should_persist_a_new_registration_to_the_registry_file_and_index_when_creating_a_workspace()
 {
    // Given an assembled server with an injected home (real builder +
    // real persistence paths)
    let (server, _workspace, home) = assembled_server();
    let new_root = tempfile::tempdir().expect("new workspace tempdir");
    let expected_id = mirri_core::encode_work_dir_key(new_root.path());

    // When a new root is registered through createOrTouch
    let value = server
        .call_method(
            "workspace.createOrTouch",
            json!({ "root": new_root.path().to_string_lossy(), "name": "persisted" }),
        )
        .await
        .expect("createOrTouch resolves");
    assert_eq!(value["id"], json!(expected_id));

    // Then the registry file carries the row (the cross-engine truth)…
    let registry_text =
        std::fs::read_to_string(home_registry_path(&home)).expect("workspaces.json written");
    let registry: serde_json::Value =
        serde_json::from_str(&registry_text).expect("workspaces.json parses");
    assert_eq!(
        registry["workspaces"][&expected_id]["name"],
        json!("persisted"),
        "the registry file must carry the new row"
    );
    // …and the session index carries the row too
    let index = server.session_index().expect("index opened");
    assert!(
        index.get_workspace(&expected_id).is_some(),
        "the index db must carry the new workspace row"
    );
    // And a cold re-read of the file sees the same row (the D8 write landed)
    let re_read = mirri_session_index::read_workspace_registry(&home_registry_path(&home));
    assert!(
        re_read.iter().any(|row| row.id == expected_id),
        "a fresh registry read must see the persisted row"
    );
}

#[tokio::test]
async fn should_touch_without_rebuilding_when_the_same_root_is_registered_twice() {
    // Given an assembled server and a registered root
    let (server, _workspace, _home) = assembled_server();
    let new_root = tempfile::tempdir().expect("new workspace tempdir");
    let expected_id = mirri_core::encode_work_dir_key(new_root.path());
    let first = server
        .call_method(
            "workspace.createOrTouch",
            json!({ "root": new_root.path().to_string_lossy(), "name": "first" }),
        )
        .await
        .expect("first createOrTouch resolves");
    let built_after_first = server.registry.built_count();

    // When the same root is created again with a new name
    let second = server
        .call_method(
            "workspace.createOrTouch",
            json!({ "root": new_root.path().to_string_lossy(), "name": "second" }),
        )
        .await
        .expect("second createOrTouch resolves");

    // Then the same workspace id is returned, the name was applied, and the
    // runtime was NOT rebuilt (idempotent touch)
    assert_eq!(second["id"], json!(expected_id));
    assert_eq!(first["id"], second["id"]);
    assert_eq!(
        second["name"],
        json!("second"),
        "the touch applied the new name"
    );
    assert_eq!(
        server.registry.built_count(),
        built_after_first,
        "the touch must not rebuild the runtime"
    );
    assert!(
        second["lastOpenedAt"].as_str() >= first["lastOpenedAt"].as_str(),
        "the touch advances last_opened_at"
    );
}

#[tokio::test]
async fn should_order_the_list_by_last_opened_at_desc_when_touching_is_immediately_visible() {
    // Given an assembled server with two registered roots (B created after
    // A, so B leads the list)
    let (server, _workspace, _home) = assembled_server();
    let root_a = tempfile::tempdir().expect("workspace a");
    let root_b = tempfile::tempdir().expect("workspace b");
    let id_a = mirri_core::encode_work_dir_key(root_a.path());
    let id_b = mirri_core::encode_work_dir_key(root_b.path());
    for root in [&root_a, &root_b] {
        server
            .call_method(
                "workspace.createOrTouch",
                json!({ "root": root.path().to_string_lossy() }),
            )
            .await
            .expect("createOrTouch resolves");
    }
    let initial = list_workspace_ids(&server).await;
    assert_eq!(
        initial[0], id_b,
        "the later-registered workspace leads the recency order"
    );

    // When A is touched
    server
        .call_method(
            "workspace.createOrTouch",
            json!({ "root": root_a.path().to_string_lossy() }),
        )
        .await
        .expect("touch resolves");

    // Then A jumps to the front of the very next listing (the in-memory
    // touch is immediately visible)
    let after = list_workspace_ids(&server).await;
    assert_eq!(
        after[0], id_a,
        "the touched workspace must lead the listing"
    );
    assert!(after.contains(&id_b));
}

#[tokio::test]
async fn should_mirror_a_created_workspace_to_other_subscribers_when_a_workspace_is_registered() {
    // Given an assembled server with two independent event subscribers
    let (server, _workspace, _home) = assembled_server();
    let new_root = tempfile::tempdir().expect("new workspace tempdir");
    let expected_id = mirri_core::encode_work_dir_key(new_root.path());
    let mut first_rx = server.subscribe_events().await.expect("first subscriber");
    let mut second_rx = server.subscribe_events().await.expect("second subscriber");

    // When a workspace is registered through one connection's RPC call
    server
        .call_method(
            "workspace.createOrTouch",
            json!({ "root": new_root.path().to_string_lossy(), "name": "mirrored" }),
        )
        .await
        .expect("createOrTouch resolves");

    // Then the OTHER subscriber receives event.workspace.created with the
    // server-scoped envelope (empty sessionId) and the snapshot payload
    for (label, rx) in [("first", &mut first_rx), ("second", &mut second_rx)] {
        let notification = tokio::time::timeout(std::time::Duration::from_secs(2), rx.recv())
            .await
            .unwrap_or_else(|_| panic!("{label} subscriber must receive the event"))
            .expect("a notification is delivered");
        assert_eq!(
            notification.method, "event.workspace.created",
            "{label}: the mirror event must be the created lifecycle event"
        );
        assert_eq!(
            notification.params["sessionId"],
            json!(""),
            "{label}: the server-scoped envelope carries the empty session id"
        );
        assert_eq!(
            notification.params["workspace"]["id"],
            json!(expected_id),
            "{label}: the payload carries the new workspace's id"
        );
        assert_eq!(
            notification.params["workspace"]["root"],
            json!(new_root.path().to_string_lossy()),
            "{label}: the payload carries the new workspace's root"
        );
    }
}

