/// Given a server whose flag registry carries a config-layer override
/// enabling the engine's hook-command-rewrite gate, When the flag surface
/// is read, Then `flag.enabled` resolves the config layer and `flag.explain`
/// reports the `config` source with the value — the wire view of the
/// `[experimental]` config section (TS parity: the `FlagService` chain).
#[tokio::test]
async fn should_report_config_layer_when_flag_registry_carries_experimental_override() {
    // Given a server with a config-layer override on the engine gate (the
    // composition root seeds this from the config's `[experimental]`
    // section; here the layer is installed directly)
    let (server, _tmp) = test_server(None);
    let mut overrides = std::collections::HashMap::new();
    overrides.insert(mirri_core::HOOK_COMMAND_REWRITE_FLAG.to_string(), true);
    server.flag_registry().set_config_overrides(overrides);

    // When the flag surface is read
    let enabled = server
        .call_method("flag.enabled", json!({ "id": "hook-command-rewrite" }))
        .await
        .unwrap();
    let explained = server
        .call_method("flag.explain", json!({ "id": "hook-command-rewrite" }))
        .await
        .unwrap();

    // Then the config layer resolved the flag enabled, with the config
    // source and value on the rich explain shape
    assert_eq!(enabled, json!(true));
    assert_eq!(explained["source"], "config");
    assert_eq!(explained["configValue"], true);
    assert_eq!(explained["enabled"], true);
}

#[tokio::test]
async fn should_list_only_directories_when_fs_browse_called() {
    // Given a directory holding one subdirectory, one file, and one
    // symlinked directory
    let root = tempfile::tempdir().expect("root tempdir");
    std::fs::create_dir(root.path().join("a-dir")).expect("mkdir a-dir");
    std::fs::write(root.path().join("a-file"), "x").expect("write a-file");
    #[cfg(unix)]
    std::os::unix::fs::symlink(root.path().join("a-dir"), root.path().join("a-link"))
        .expect("symlink a-link");

    // Given a server bound to a throwaway workspace
    let (server, _tmp) = test_server(None);

    // When the directory is browsed through fs.browse (the object
    // spelling; the positional tuple spelling is accepted below)
    let object_form = server
        .call_method(
            "fs.browse",
            json!({ "path": root.path().to_string_lossy() }),
        )
        .await
        .unwrap();
    let tuple_form = server
        .call_method("fs.browse", json!([root.path().to_string_lossy()]))
        .await
        .unwrap();
    assert_eq!(object_form, tuple_form);

    // Then the klient snake_case shape is served, the entries list
    // directories only (the is_dir literal), and the parent resolves
    assert_eq!(object_form["path"], json!(root.path().to_string_lossy()));
    assert_eq!(
        object_form["parent"],
        json!(root.path().parent().unwrap().to_string_lossy())
    );
    let entries = object_form["entries"].as_array().expect("entries array");
    let names: Vec<&str> = entries
        .iter()
        .map(|e| e["name"].as_str().expect("entry name"))
        .collect();
    assert_eq!(names, vec!["a-dir"]); // the file is not part of the wire face
    assert_eq!(entries[0]["is_dir"], json!(true));
    assert_eq!(
        entries[0]["path"],
        json!(root.path().join("a-dir").to_string_lossy())
    );

    // And a non-absolute path is invalid params, a missing path is not
    // found (the protocol fsBrowse error semantics)
    let relative = server
        .call_method("fs.browse", json!({ "path": "not/absolute" }))
        .await
        .unwrap_err();
    assert!(
        matches!(&relative, EngineError::Rpc { code, .. } if *code == -32602),
        "a relative path must be invalid params: {relative:?}"
    );
    let missing = server
        .call_method("fs.browse", json!({ "path": "/definitely/not/here" }))
        .await
        .unwrap_err();
    assert!(
        matches!(&missing, EngineError::Rpc { code, .. } if *code == -32001),
        "a missing path must be not found: {missing:?}"
    );
}

