#[tokio::test]
async fn should_expose_layered_sections_when_config_get_all_and_inspect_called() {
    // Given a seeded config with providers, models, and defaults
    let (server, _tmp, _config_path) = test_server_with_config_toml(CONFIG_WRITE_SEED_TOML);

    // When the section record and the layered snapshot are read
    let all = server
        .call_method("config.getAll", json!({}))
        .await
        .unwrap();
    let inspect = server
        .call_method("config.inspect", json!({ "key": "providers" }))
        .await
        .unwrap();

    // Then getAll answers every top-level section in the camelCase record
    // spelling (the wire projection union the raw document's unmodeled keys)
    assert_eq!(all["defaultProvider"], "kimi");
    assert_eq!(all["defaultModel"], "kimi/alpha");
    assert_eq!(all["providers"]["kimi"]["type"], "openai");
    assert_eq!(all["models"]["kimi/alpha"]["maxContextSize"], 128000);
    // And the provider secret is redacted like the Settled config.get wire
    assert_eq!(all["providers"]["kimi"]["apiKey"], "[REDACTED]");
    // And the raw passthrough document is not part of the record
    assert!(all.get("raw").is_none());

    // And inspect answers the layered snapshot: value / userValue present,
    // the defaultValue / memoryValue layers honestly absent (no section
    // registry, no memory layer — TSV note records the DRIFT)
    assert_eq!(inspect["value"]["kimi"]["type"], "openai");
    assert_eq!(inspect["userValue"]["kimi"]["type"], "openai");
    assert!(inspect.get("defaultValue").is_none());
    assert!(inspect.get("memoryValue").is_none());
    assert_eq!(
        inspect["value"]["kimi"]["apiKey"], "[REDACTED]",
        "the inspect snapshot redacts secrets like config.get"
    );
}

#[tokio::test]
async fn should_make_sections_visible_when_config_replace_sections_then_get_all_called() {
    // Given a seeded config
    let (server, _tmp, _config_path) = test_server_with_config_toml(CONFIG_WRITE_SEED_TOML);

    // When sections are replaced (an unmodeled custom section included, in
    // the positional tuple spelling the klient contract sends)
    let result = server
        .call_method(
            "config.replaceSections",
            json!([{
                "thinking": { "enabled": true, "effort": "high" },
                "customSection": { "flag": "on" }
            }]),
        )
        .await
        .unwrap();

    // Then the write is noResult and both sections are visible in getAll
    assert!(result.is_null());
    let all = server
        .call_method("config.getAll", json!({}))
        .await
        .unwrap();
    assert_eq!(all["thinking"]["enabled"], true);
    assert_eq!(all["thinking"]["effort"], "high");
    assert_eq!(all["customSection"]["flag"], "on");

    // And a JSON-null section value clears it (the klient clear encoding)
    server
        .call_method(
            "config.replaceSections",
            json!({ "sections": { "thinking": null, "customSection": { "flag": "off" } } }),
        )
        .await
        .unwrap();
    let all = server
        .call_method("config.getAll", json!({}))
        .await
        .unwrap();
    assert!(all.get("thinking").is_none(), "cleared: {all}");
    assert_eq!(all["customSection"]["flag"], "off");

    // And a section value carrying a null member is rejected before the
    // disk is touched (TOML has no null; stripping it would lie)
    let error = server
        .call_method(
            "config.replace",
            json!({ "key": "thinking", "value": { "effort": null } }),
        )
        .await
        .unwrap_err();
    assert!(
        matches!(&error, EngineError::Rpc { code, .. } if *code == -32602),
        "a null member must be invalid params: {error:?}"
    );
}

#[tokio::test]
async fn should_reload_from_disk_when_config_reload_called() {
    // Given a seeded config whose file is edited behind the engine's back
    let (server, tmp, config_path) = test_server_with_config_toml(CONFIG_WRITE_SEED_TOML);
    let edited = r#"
default_provider = "edited"

[providers.edited]
type = "openai"
api_key = "sk-edited"
"#;
    std::fs::write(&config_path, edited).expect("edited config write should succeed");
    let stale = server
        .call_method("config.getAll", json!({}))
        .await
        .unwrap();
    assert_eq!(stale["defaultProvider"], "kimi");

    // When the engine is told to reload
    let result = server
        .call_method("config.reload", json!({}))
        .await
        .unwrap();

    // Then the write is noResult and the in-memory snapshot serves the
    // file's new truth
    assert!(result.is_null());
    let reloaded = server
        .call_method("config.getAll", json!({}))
        .await
        .unwrap();
    assert_eq!(reloaded["defaultProvider"], "edited");
    assert_eq!(reloaded["providers"]["edited"]["type"], "openai");
    assert!(reloaded["providers"].get("kimi").is_none());
    let _ = tmp.keep(); // the edited file is asserted via getAll above
}

