#[tokio::test]
async fn should_roundtrip_passthrough_keys_when_model_set_then_get_called() {
    // Given a seeded config
    let (server, _tmp, config_path) = test_server_with_config_toml(CONFIG_WRITE_SEED_TOML);

    // When a model record carrying klient passthrough fields is set
    let result = server
        .call_method(
            "model.set",
            json!({
                "id": "test/alias",
                "config": {
                    "provider": "kimi",
                    "model": "m1",
                    "maxContextSize": 1000,
                    "providerId": "kimi",
                    "baseUrl": "https://example.test",
                    "apiKey": "sk-inline",
                    "overrides": { "displayName": "M1" },
                    "customFlag": "keep-me"
                }
            }),
        )
        .await
        .unwrap();

    // Then the write is noResult and model.get returns the full record:
    // the typed alias fields plus every passthrough key (snake_case on
    // disk, camelCase on the wire), with the inline secret redacted
    assert!(result.is_null());
    let record = server
        .call_method("model.get", json!({ "id": "test/alias" }))
        .await
        .unwrap();
    assert_eq!(record["provider"], "kimi");
    assert_eq!(record["model"], "m1");
    assert_eq!(record["maxContextSize"], 1000);
    assert_eq!(record["providerId"], "kimi");
    assert_eq!(record["baseUrl"], "https://example.test");
    assert_eq!(record["apiKey"], "[REDACTED]");
    assert_eq!(record["overrides"]["displayName"], "M1");
    assert_eq!(record["customFlag"], "keep-me");

    // And an unknown id answers JSON null (the klient maybe semantics)
    let missing = server
        .call_method("model.get", json!(["no-such-alias"]))
        .await
        .unwrap();
    assert!(missing.is_null());

    // And the record survives a struct-path save (config.set must not drop
    // the passthrough keys it does not model)
    server
        .call_method("config.set", json!({ "yolo": true }))
        .await
        .unwrap();
    let record = server
        .call_method("model.get", json!({ "id": "test/alias" }))
        .await
        .unwrap();
    assert_eq!(record["customFlag"], "keep-me");
    assert_eq!(record["providerId"], "kimi");

    // And delete removes the record (and the on-disk section) — the global
    // defaultModel pointer is cleared when it addressed the deleted alias
    server
        .call_method("model.setDefaultModel", json!({ "modelId": "test/alias" }))
        .await
        .unwrap();
    let deleted = server
        .call_method("model.delete", json!({ "id": "test/alias" }))
        .await
        .unwrap();
    assert!(deleted.is_null());
    let gone = server
        .call_method("model.get", json!({ "id": "test/alias" }))
        .await
        .unwrap();
    assert!(gone.is_null());
    let disk = std::fs::read_to_string(config_path).unwrap();
    assert!(
        !disk.contains("test/alias"),
        "record persisted away: {disk}"
    );
    let config = server.call_method("config.get", json!({})).await.unwrap();
    assert!(
        config.get("defaultModel").is_none(),
        "the default pointer was cleared: {config}"
    );

    // And a flat record without the typed alias trio is honestly rejected
    // (the rust models section cannot hold baseUrl-only records)
    let error = server
        .call_method(
            "model.set",
            json!({ "id": "flat", "config": { "baseUrl": "https://flat.test" } }),
        )
        .await
        .unwrap_err();
    assert!(
        matches!(&error, EngineError::Rpc { code, .. } if *code == -32602),
        "a flat record must be invalid params: {error:?}"
    );
}

#[tokio::test]
async fn should_answer_catalog_shapes_when_model_get_provider_and_set_default_model_called() {
    // Given a seeded config with a connected provider
    let (server, _tmp, _config_path) = test_server_with_config_toml(CONFIG_WRITE_SEED_TOML);

    // When the provider catalog item and the default-model pointer are read
    let provider = server
        .call_method("model.getProvider", json!({ "providerId": "kimi" }))
        .await
        .unwrap();
    let response = server
        .call_method("model.setDefaultModel", json!({ "modelId": "kimi/beta" }))
        .await
        .unwrap();

    // Then getProvider answers the klient providerCatalogItem shape
    assert_eq!(provider["id"], "kimi");
    assert_eq!(provider["type"], "openai");
    assert_eq!(provider["has_api_key"], true);
    assert_eq!(provider["status"], "connected");
    assert_eq!(provider["models"], json!(["alpha", "beta"]));

    // And setDefaultModel answers the klient setDefaultModelResponse shape
    // and persists the pointer
    assert_eq!(response["default_model"], "kimi/beta");
    assert!(
        response["model"].get("id").is_none(),
        "setDefaultModel's catalog item carries no id (klient setDefaultModelResponseSchema — T3)"
    );
    assert_eq!(response["model"]["provider"], "kimi");
    assert_eq!(response["model"]["model"], "beta");
    assert_eq!(response["model"]["max_context_size"], 200000);
    let config = server.call_method("config.get", json!({})).await.unwrap();
    assert_eq!(config["defaultModel"], "kimi/beta");

    // And an unknown provider id answers the TS provider.not_found domain
    // code (the ModelCatalogErrors wire contract)
    let error = server
        .call_method("model.getProvider", json!({ "providerId": "ghost" }))
        .await
        .unwrap_err();
    assert!(matches!(
        &error,
        EngineError::Rpc { code: -32001, data: Some(data), .. }
            if data["domainCode"] == "provider.not_found"
    ));

    // And an unknown model id answers the TS model.not_found domain code
    let error = server
        .call_method("model.setDefaultModel", json!({ "modelId": "ghost/model" }))
        .await
        .unwrap_err();
    assert!(matches!(
        &error,
        EngineError::Rpc { code: -32001, data: Some(data), .. }
            if data["domainCode"] == "model.not_found"
    ));
}

#[tokio::test]
async fn should_roundtrip_records_when_provider_set_list_get_delete_called() {
    // Given a seeded config whose default provider is kimi
    let (server, _tmp, config_path) = test_server_with_config_toml(CONFIG_WRITE_SEED_TOML);

    // When a provider record is set (the klient providerConfigSchema
    // fields, in the positional tuple spelling)
    let result = server
        .call_method(
            "provider.set",
            json!([
                "openai2",
                {
                    "type": "openai",
                    "apiKey": "sk-2",
                    "baseUrl": "https://api.example.test",
                    "modelSource": "static",
                    "customHeaders": { "X-Extra": "yes" },
                    "env": { "OPENAI_LOG": "debug" },
                    "source": { "kind": "manual" }
                }
            ]),
        )
        .await
        .unwrap();

    // Then the write is noResult and the record is visible on get/list with
    // every field round-tripped (the secret redacted like config.get)
    assert!(result.is_null());
    let record = server
        .call_method("provider.get", json!({ "name": "openai2" }))
        .await
        .unwrap();
    assert_eq!(record["type"], "openai");
    assert_eq!(record["apiKey"], "[REDACTED]");
    assert_eq!(record["baseUrl"], "https://api.example.test");
    assert_eq!(record["modelSource"], "static");
    assert_eq!(record["customHeaders"]["X-Extra"], "yes");
    assert_eq!(record["env"]["OPENAI_LOG"], "debug");
    assert_eq!(record["source"]["kind"], "manual");

    let list = server
        .call_method("provider.list", json!({}))
        .await
        .unwrap();
    assert_eq!(list["openai2"]["type"], "openai");
    assert_eq!(list["kimi"]["type"], "openai");

    // And an unknown id answers JSON null (the klient maybe semantics)
    let missing = server
        .call_method("provider.get", json!(["no-such-provider"]))
        .await
        .unwrap();
    assert!(missing.is_null());

    // And delete removes the record without cascading the models — but the
    // defaultProvider pointer is cleared when it addressed the provider
    let deleted = server
        .call_method("provider.delete", json!({ "name": "kimi" }))
        .await
        .unwrap();
    assert!(deleted.is_null());
    let gone = server
        .call_method("provider.get", json!({ "name": "kimi" }))
        .await
        .unwrap();
    assert!(gone.is_null());
    let config = server.call_method("config.get", json!({})).await.unwrap();
    assert!(
        config.get("defaultProvider").is_none(),
        "the default provider pointer was cleared: {config}"
    );
    assert_eq!(
        config["models"]["kimi/alpha"]["model"], "alpha",
        "no model cascade (that is config.removeProvider's behavior)"
    );
    let disk = std::fs::read_to_string(config_path).unwrap();
    assert!(!disk.contains("[providers.kimi]"), "persisted away: {disk}");
    assert!(disk.contains("kimi/alpha"), "models untouched: {disk}");
}

// ===========================================================================
// model.generate (B5-c — the only streaming contract)
// ===========================================================================

/// Drain `event.generate.chunk` notifications for `request_id` until the
/// finish chunk (or the iteration cap), proving the streaming face stays
/// open without asserting its content.
async fn drain_generate_chunks(
    events: &mut tokio::sync::mpsc::Receiver<JsonRpcNotification>,
    request_id: &str,
) {
    for _ in 0..50 {
        let notification = tokio::time::timeout(Duration::from_secs(5), events.recv())
            .await
            .expect("chunk must arrive within 5s")
            .expect("event channel stays open");
        if notification.method == "event.generate.chunk"
            && notification.params["requestId"] == request_id
            && notification.params["chunk"]["type"] == "finish"
        {
            break;
        }
    }
}

/// A config seed pointing one model alias at an OpenAI-compatible endpoint
/// whose base URL the caller fills in (the wiremock server's).
fn generate_seed_toml(base_url: &str, provider_type: &str) -> String {
    format!(
        r#"
[providers.test]
type = "{provider_type}"
api_key = "sk-test"
base_url = "{base_url}"

[models."test/model"]
provider = "test"
model = "gpt-test"
max_context_size = 128000
"#
    )
}

/// A generate config seed with an explicit alias-level wire protocol
/// (the `models."test/model".protocol` field the TS resolver reads first).
fn generate_seed_toml_with_protocol(base_url: &str, provider_type: &str, protocol: &str) -> String {
    format!(
        r#"
[providers.test]
type = "{provider_type}"
api_key = "sk-test"
base_url = "{base_url}"

[models."test/model"]
provider = "test"
model = "gpt-test"
max_context_size = 128000
protocol = "{protocol}"
"#
    )
}

#[tokio::test]
async fn should_stream_part_usage_finish_chunks_when_model_generate_runs_an_openai_stream() {
    use wiremock::{Mock, MockServer, ResponseTemplate, matchers::*};

    // Given a mock OpenAI endpoint streaming two text deltas, a stop
    // chunk, and a trailing usage chunk (the include_usage ordering)
    let mock = MockServer::start().await;
    Mock::given(method("POST"))
        .and(path("/v1/chat/completions"))
        .respond_with(
            ResponseTemplate::new(200)
                .insert_header("content-type", "text/event-stream")
                .set_body_string(
                    "data: {\"id\":\"chatcmpl-1\",\"object\":\"chat.completion.chunk\",\"choices\":[{\"index\":0,\"delta\":{\"role\":\"assistant\",\"content\":\"Hello\"},\"finish_reason\":null}]}\n\n\
                     data: {\"id\":\"chatcmpl-1\",\"object\":\"chat.completion.chunk\",\"choices\":[{\"index\":0,\"delta\":{\"content\":\" world\"},\"finish_reason\":null}]}\n\n\
                     data: {\"id\":\"chatcmpl-1\",\"object\":\"chat.completion.chunk\",\"choices\":[{\"index\":0,\"delta\":{},\"finish_reason\":\"stop\"}]}\n\n\
                     data: {\"id\":\"chatcmpl-1\",\"object\":\"chat.completion.chunk\",\"choices\":[],\"usage\":{\"prompt_tokens\":12,\"completion_tokens\":7,\"prompt_tokens_details\":{\"cached_tokens\":2}}}\n\n\
                     data: [DONE]\n\n",
                ),
        )
        .mount(&mock)
        .await;
    let (server, _tmp, _path) =
        test_server_with_config_toml(&generate_seed_toml(&format!("{}/v1", mock.uri()), "openai"));

    // When a subscriber listens and model.generate runs with a client
    // requestId (the rust-side params[2] extension)
    let mut events = server.subscribe_events().await.unwrap();
    let result = server
        .call_method(
            "model.generate",
            json!([
                "test/model",
                { "systemPrompt": "You are a test.", "messages": [
                    { "role": "user", "content": "hi" }
                ] },
                { "requestId": "req-42" },
            ]),
        )
        .await
        .unwrap();

    // Then the chunk frames arrive keyed by the echoed requestId, in the
    // klient chunk vocabulary: part(text) → part(text) → usage → finish
    let mut chunks = Vec::new();
    for _ in 0..50 {
        let notification = tokio::time::timeout(Duration::from_secs(5), events.recv())
            .await
            .expect("chunk must arrive within 5s")
            .expect("event channel stays open");
        if notification.method == "event.generate.chunk"
            && notification.params["requestId"] == "req-42"
        {
            chunks.push(notification.params["chunk"].clone());
            if chunks
                .last()
                .and_then(|chunk| chunk["type"].as_str())
                .is_some_and(|kind| kind == "finish")
            {
                break;
            }
        }
    }
    let kinds: Vec<&str> = chunks
        .iter()
        .map(|chunk| chunk["type"].as_str().unwrap())
        .collect();
    assert_eq!(kinds, ["part", "part", "usage", "finish"]);
    assert_eq!(
        chunks[0]["part"],
        json!({ "type": "text", "text": "Hello" })
    );
    assert_eq!(
        chunks[1]["part"],
        json!({ "type": "text", "text": " world" })
    );
    assert_eq!(
        chunks[2]["usage"],
        json!({ "inputTokens": 10, "outputTokens": 7, "cacheReadTokens": 2, "cacheCreationTokens": 0 })
    );
    // The finish chunk carries the aggregated message and reason
    assert_eq!(chunks[3]["finishReason"], "completed");
    assert_eq!(chunks[3]["message"]["content"][0]["text"], "Hello world");

    // And the aggregated response is authoritative: the requestId is
    // echoed, the finish reason and usage agree with the chunks, and the
    // assistant message is assembled
    assert_eq!(result["requestId"], "req-42");
    assert_eq!(result["finishReason"], "completed");
    assert_eq!(
        result["usage"],
        json!({ "inputTokens": 10, "outputTokens": 7, "cacheReadTokens": 2, "cacheCreationTokens": 0 })
    );
    assert_eq!(result["message"]["role"], "assistant");
    assert_eq!(
        result["message"]["content"],
        json!([{ "type": "text", "text": "Hello world" }])
    );

    // And exactly one provider request was made (no turn mechanism, no
    // retry loop — a single direct call)
    let requests = mock.received_requests().await.unwrap();
    assert_eq!(requests.len(), 1);
}

#[tokio::test]
async fn should_send_kimi_thinking_dialect_when_model_generate_runs_a_kimi_provider() {
    use wiremock::{Mock, MockServer, ResponseTemplate, matchers::*};

    // Given a mock OpenAI-shaped endpoint and a config seeding a kimi
    // provider alias with a high thinking effort
    let mock = MockServer::start().await;
    Mock::given(method("POST"))
        .and(path("/v1/chat/completions"))
        .respond_with(
            ResponseTemplate::new(200)
                .insert_header("content-type", "text/event-stream")
                .set_body_string(
                    "data: {\"id\":\"chatcmpl-1\",\"object\":\"chat.completion.chunk\",\"choices\":[{\"index\":0,\"delta\":{\"role\":\"assistant\",\"content\":\"Hello\"},\"finish_reason\":null}]}\n\n\
                     data: {\"id\":\"chatcmpl-1\",\"object\":\"chat.completion.chunk\",\"choices\":[{\"index\":0,\"delta\":{},\"finish_reason\":\"stop\"}]}\n\n\
                     data: [DONE]\n\n",
                ),
        )
        .mount(&mock)
        .await;
    let (server, _tmp, _path) =
        test_server_with_config_toml(&generate_seed_toml(&format!("{}/v1", mock.uri()), "kimi"));

    // When model.generate runs with a high thinking effort
    let mut events = server.subscribe_events().await.unwrap();
    let _result = server
        .call_method(
            "model.generate",
            json!([
                "test/model",
                { "systemPrompt": "You are a test.", "messages": [
                    { "role": "user", "content": "hi" }
                ] },
                { "requestId": "req-kimi-1", "thinkingEffort": "high" },
            ]),
        )
        .await
        .expect("generate over kimi provider succeeds");
    for _ in 0..50 {
        let notification = tokio::time::timeout(Duration::from_secs(5), events.recv())
            .await
            .expect("chunk must arrive within 5s")
            .expect("event channel stays open");
        if notification.method == "event.generate.chunk"
            && notification.params["requestId"] == "req-kimi-1"
            && notification.params["chunk"]["type"] == "finish"
        {
            break;
        }
    }

    // Then the single provider request carried the Kimi thinking dialect
    // (a top-level thinking object), not OpenAI's reasoning_effort
    let requests = mock.received_requests().await.unwrap();
    assert_eq!(requests.len(), 1);
    let body: serde_json::Value =
        serde_json::from_slice(&requests[0].body).expect("request body is JSON");
    assert_eq!(
        body["thinking"],
        json!({ "type": "enabled", "effort": "high" })
    );
    assert!(
        body.get("reasoning_effort").is_none(),
        "kimi provider must not send reasoning_effort"
    );
}

