#[tokio::test]
async fn should_prefer_alias_protocol_when_provider_type_disagrees() {
    use wiremock::{Mock, MockServer, ResponseTemplate, matchers::*};

    // Given a mock Anthropic endpoint and a config whose provider type
    // says openai but whose alias protocol says anthropic
    let mock = MockServer::start().await;
    Mock::given(method("POST"))
        .and(path("/v1/messages"))
        .respond_with(
            ResponseTemplate::new(200)
                .insert_header("content-type", "text/event-stream")
                .set_body_string(
                    "event: message_start\n\
                     data: {\"type\":\"message_start\",\"message\":{\"id\":\"msg_1\",\"model\":\"claude-test\",\"usage\":{\"input_tokens\":10}}}\n\n\
                     event: content_block_delta\n\
                     data: {\"type\":\"content_block_delta\",\"index\":0,\"delta\":{\"type\":\"text_delta\",\"text\":\"Hello\"}}\n\n\
                     event: message_delta\n\
                     data: {\"type\":\"message_delta\",\"delta\":{\"stop_reason\":\"end_turn\"},\"usage\":{\"output_tokens\":10}}\n\n\
                     event: message_stop\n\
                     data: {\"type\":\"message_stop\"}\n\n",
                ),
        )
        .mount(&mock)
        .await;
    let (server, _tmp, _path) = test_server_with_config_toml(&generate_seed_toml_with_protocol(
        &format!("{}/v1", mock.uri()),
        "openai",
        "anthropic",
    ));

    // When model.generate runs
    let mut events = server.subscribe_events().await.unwrap();
    let result = server
        .call_method(
            "model.generate",
            json!([
                "test/model",
                { "systemPrompt": "You are a test.", "messages": [
                    { "role": "user", "content": "hi" }
                ] },
                { "requestId": "req-protocol-1" },
            ]),
        )
        .await
        .expect("generate with protocol override succeeds");
    // The Anthropic stop reason passes through verbatim (the protocol
    // override selected the Anthropic wire, whose native reason is
    // end_turn, not the OpenAI-vocabulary completed)
    assert_eq!(result["finishReason"], "end_turn");
    drain_generate_chunks(&mut events, "req-protocol-1").await;

    // Then the request used the Anthropic wire (the alias protocol won
    // over the provider type), hitting /v1/messages exactly once
    let requests = mock.received_requests().await.unwrap();
    assert_eq!(requests.len(), 1);
    assert_eq!(requests[0].url.path(), "/v1/messages");
}

