// ── P4: file-part entry resolution on message.send ─────────────────────

/// A server with a scripted LLM and a files store rooted at a temp dir —
/// the fixture the P4 entry-resolution tests need.
fn test_server_with_files(
    llm_factory: Option<Arc<dyn LlmFactory>>,
) -> (EmbeddedServer, tempfile::TempDir, tempfile::TempDir) {
    let (server, workspace) = test_server(llm_factory);
    let files = tempfile::tempdir().expect("files tempdir");
    let server = server.with_files_dir(files.path().to_path_buf());
    (server, workspace, files)
}

/// The main agent's context memory after a turn (one lock acquisition).
async fn user_parts_of(server: &EmbeddedServer, session_id: &str) -> Vec<mirri_core::ContentPart> {
    let session = server
        .session_manager()
        .get_session(&SessionId::new(session_id))
        .await
        .expect("session stays live");
    let agent = session
        .get_agent(&AgentId::new(DEFAULT_MAIN_AGENT_ID))
        .await
        .expect("main agent stays live");
    let memory = agent.context_memory();
    let guard = memory.lock().unwrap_or_else(|e| e.into_inner());
    let messages = guard.messages();
    messages
        .iter()
        .find(|message| message.role == mirri_core::Role::User)
        .expect("at least the user message")
        .content
        .clone()
}

#[tokio::test]
async fn should_resolve_file_part_to_inline_data_when_message_send_input_references_file() {
    // Given a file in the files store and a scripted LLM
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("got it");
    let (server, _workspace, files) =
        test_server_with_files(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))));
    let meta = crate::file_store::FileStore::new(files.path())
        .save(
            b"pdf-bytes",
            "report.pdf",
            crate::file_store::SaveOptions {
                mime_type: Some("application/pdf".to_string()),
                ..Default::default()
            },
        )
        .expect("save file");
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    // When a message is sent with a text part plus a file part referencing it
    server
        .call_method(
            "message.send",
            json!({
                "session_id": session_id,
                "mode": "wait",
                "input": [
                    { "type": "text", "text": "please review" },
                    { "type": "file", "file_id": meta.id, "name": "report.pdf" },
                ],
            }),
        )
        .await
        .unwrap();

    // Then the user message in context memory carries the resolved inline
    // data URI — never the bare files-store reference
    let parts = user_parts_of(&server, &session_id).await;
    assert_eq!(parts.len(), 2, "both parts survive: {parts:?}");
    match &parts[1] {
        mirri_core::ContentPart::File {
            file_id,
            data,
            name,
            media_type,
            size,
        } => {
            assert_eq!(file_id, &None, "no bare file_id in context memory");
            assert_eq!(
                data.as_deref(),
                Some("data:application/pdf;base64,cGRmLWJ5dGVz"),
                "the file content resolves to its inline data URI"
            );
            assert_eq!(name.as_deref(), Some("report.pdf"));
            assert_eq!(media_type.as_deref(), Some("application/pdf"));
            assert_eq!(*size, Some(9));
        }
        other => panic!("expected File, got {other:?}"),
    }
}

#[tokio::test]
async fn should_resolve_image_file_source_to_image_url_part_with_store_media_type_when_sent() {
    // Given an image file in the files store (the media type only lives in
    // the store's metadata — the wire part carries none)
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("seen");
    let (server, _workspace, files) =
        test_server_with_files(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))));
    let meta = crate::file_store::FileStore::new(files.path())
        .save(
            b"pngbytes",
            "cat.png",
            crate::file_store::SaveOptions {
                mime_type: Some("image/png".to_string()),
                ..Default::default()
            },
        )
        .expect("save file");
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    // When a message is sent with a v1-style image part whose source
    // references the file
    server
        .call_method(
            "message.send",
            json!({
                "session_id": session_id,
                "mode": "wait",
                "input": [
                    { "type": "image", "source": { "kind": "file", "file_id": meta.id } },
                ],
            }),
        )
        .await
        .unwrap();

    // Then the part becomes an ImageUrl whose URL is the inline data URI
    // with the media type taken from the files-store metadata
    let parts = user_parts_of(&server, &session_id).await;
    assert_eq!(parts.len(), 1, "one part: {parts:?}");
    match &parts[0] {
        mirri_core::ContentPart::ImageUrl { image_url, .. } => {
            assert_eq!(
                image_url.url, "data:image/png;base64,cG5nYnl0ZXM=",
                "media type must come from the files metadata"
            );
            // And the ingestion archive stamped the blob's absolute path
            // into the hidden id channel — the recovery handle exists on
            // disk (Task 2's empirically verified assertion, landed per
            // the Task 10 checklist)
            let id = image_url
                .id
                .as_deref()
                .expect("the archive path must be stamped into the part id");
            assert!(
                std::path::Path::new(id).exists(),
                "the archived blob file must exist: {id}"
            );
        }
        other => panic!("expected ImageUrl, got {other:?}"),
    }
}

/// A minimal 1×1 transparent PNG — real image bytes so the read-media
/// tool's magic-byte validation accepts the archived original.
const MINIMAL_PNG: &[u8] = &[
    0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A, // PNG signature
    // IHDR chunk
    0x00, 0x00, 0x00, 0x0D, 0x49, 0x48, 0x44, 0x52, 0x00, 0x00, 0x00, 0x01, 0x00, 0x00, 0x00, 0x01,
    0x08, 0x06, 0x00, 0x00, 0x00, 0x1F, 0x15, 0xC4, 0x89, // CRC
    // IDAT chunk (minimal)
    0x00, 0x00, 0x00, 0x0A, 0x49, 0x44, 0x41, 0x54, 0x78, 0x9C, 0x62, 0x00, 0x01, 0x00, 0x00, 0x05,
    0x00, 0x01, 0x0D, 0x0A, 0x2D, 0xB4, // CRC
    // IEND chunk
    0x00, 0x00, 0x00, 0x00, 0x49, 0x45, 0x4E, 0x44, 0xAE, 0x42, 0x60, 0x82, // CRC
];

#[tokio::test]
async fn should_admit_archived_media_originals_into_session_sandbox_when_media_is_ingested() {
    // Given a real image file in the files store, and a server whose
    // session persistence (and blob store) lives OUTSIDE the workspace
    // root — the injected-home production shape (`<home>/v3_sessions`,
    // ADR-005-R1), where the archived original is a path traversal away
    // from the workspace sandbox unless the store is admitted
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("seen");
    let workspace = tempfile::tempdir().expect("workspace tempdir");
    let home = tempfile::tempdir().expect("home tempdir");
    let files = tempfile::tempdir().expect("files tempdir");
    let scope = Arc::new(WorkspaceScope::new(
        WorkspaceId::new("test-ws"),
        workspace.path().to_path_buf(),
        WorkspaceScopeConfig::default(),
    ));
    let manager = Arc::new(SessionManager::with_persistence_dir(
        scope,
        home.path().join("v3_sessions"),
        Arc::new(mirri_os::LocalFs::new()),
    ));
    let server = EmbeddedServer::with_providers(
        manager,
        Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))),
        None,
        None,
        None,
        test_server_config(),
        None,
    )
    .with_files_dir(files.path().to_path_buf());
    let meta = crate::file_store::FileStore::new(files.path())
        .save(
            MINIMAL_PNG,
            "cat.png",
            crate::file_store::SaveOptions {
                mime_type: Some("image/png".to_string()),
                ..Default::default()
            },
        )
        .expect("save file");
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    // When the image is sent (the ingestion archives the original into the
    // session's blob store and stamps the archive path into the part id)
    server
        .call_method(
            "message.send",
            json!({
                "session_id": session_id,
                "mode": "wait",
                "input": [
                    { "type": "image", "source": { "kind": "file", "file_id": meta.id } },
                ],
            }),
        )
        .await
        .unwrap();

    // Then the session sandbox — the same one every agent's read tools
    // (subagents included) validate against — admits the archived
    // original: the recovery handle must be genuinely readable (US5.1)
    // through the standard workspace validation (US7.3)
    let parts = user_parts_of(&server, &session_id).await;
    let id = match &parts[0] {
        mirri_core::ContentPart::ImageUrl { image_url, .. } => image_url
            .id
            .clone()
            .expect("the archive path must be stamped into the part id"),
        other => panic!("expected ImageUrl, got {other:?}"),
    };
    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .expect("session stays live");
    let paths = session
        .workspace_paths()
        .expect("session sandbox configured");
    paths
        .validate(std::path::Path::new(&id))
        .unwrap_or_else(|error| {
            panic!("archived original must be inside the session sandbox: {error}")
        });

    // And the read-media tool built on that sandbox (the same Arc the
    // agents' tools hold) reads the archived original back as media parts
    let tool =
        mirri_core::tools::ReadMediaFileTool::new(Some(paths), Arc::new(mirri_os::LocalFs::new()));
    let execution = tool
        .resolve_execution(json!({ "path": id }))
        .expect("resolve");
    let ToolExecution::Runnable { execute, .. } = execution else {
        panic!("expected a runnable execution, got a path-security refusal");
    };
    let result = execute(mirri_core::tool::ExecutableToolContext {
        wait_registry: None,
        turn_id: "test".to_string(),
        tool_call_id: "call-1".to_string(),
        cancel: Default::default(),
        progress: mirri_core::tool::ToolProgressHandle::default(),
    })
    .await;
    assert!(
        !result.is_error,
        "archived original must be readable, got: {:?}",
        result.output
    );
    assert!(matches!(result.output, mirri_core::ToolOutput::Parts(_)));
}

#[tokio::test]
async fn should_resolve_base64_and_url_sources_to_canonical_parts_when_sent() {
    // Given a server and a created session
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("ok");
    let (server, _workspace, _files) =
        test_server_with_files(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))));
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    // When a message carries base64-sourced image/video parts and a
    // url-sourced image part (the v1 REST wire spellings)
    server
        .call_method(
            "message.send",
            json!({
                "session_id": session_id,
                "mode": "wait",
                "input": [
                    { "type": "image", "source": { "kind": "base64", "media_type": "image/png", "data": "aGk=" } },
                    { "type": "video", "source": { "kind": "url", "url": "https://example.com/v.mp4" } },
                ],
            }),
        )
        .await
        .unwrap();

    // Then both map onto the canonical wire parts
    let parts = user_parts_of(&server, &session_id).await;
    match &parts[0] {
        mirri_core::ContentPart::ImageUrl { image_url, .. } => {
            assert_eq!(image_url.url, "data:image/png;base64,aGk=");
        }
        other => panic!("expected ImageUrl, got {other:?}"),
    }
    match &parts[1] {
        mirri_core::ContentPart::VideoUrl { video_url } => {
            assert_eq!(video_url, "https://example.com/v.mp4");
        }
        other => panic!("expected VideoUrl, got {other:?}"),
    }
}

/// The main `message.send` dispatch path (Task 10 review follow-up): the
/// server-level profile manager must reach the turn flow, so the US5.2
/// capability-gap injector fires on production turns. Given a text-only
/// model driving the turn, a vision-capable model alias in the server
/// config, and a profile whose default model is that alias, an
/// image-bearing message gets an injected dispatch hint naming the
/// profile — the same end-to-end shape `test_server`'s bare config
/// (no profile manager) never exercised.
#[tokio::test]
async fn should_inject_capability_gap_hint_on_the_main_message_send_path() {
    // Given a server whose profile manager names a vision-capable profile
    // and whose config catalog carries the vision model alias
    use mirri_core::{AgentProfile, ModelAlias, ProfileManager};

    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("got it");
    let tmp = tempfile::tempdir().expect("tempdir must be creatable");
    let workspace = Arc::new(WorkspaceScope::new(
        WorkspaceId::new("test-ws"),
        tmp.path().to_path_buf(),
        WorkspaceScopeConfig::default(),
    ));
    let manager = Arc::new(SessionManager::new(workspace));
    let config = ServerConfig {
        default_model: Some("text-model".to_string()),
        models: Some(
            [
                (
                    "text-model".to_string(),
                    ModelAlias {
                        provider: "openai".to_string(),
                        model: "gpt-4o-mini-text".to_string(),
                        max_context_size: 128_000,
                        ..ModelAlias::default()
                    },
                ),
                (
                    "vision-model".to_string(),
                    ModelAlias {
                        provider: "openai".to_string(),
                        model: "gpt-4o".to_string(),
                        max_context_size: 128_000,
                        capabilities: Some(vec!["vision".to_string()]),
                        ..ModelAlias::default()
                    },
                ),
            ]
            .into_iter()
            .collect(),
        ),
        ..ServerConfig::default()
    };
    let profile_manager = Arc::new(ProfileManager::new());
    profile_manager
        .register(AgentProfile {
            name: "vision-agent".to_string(),
            model: "vision-model".to_string(),
            ..Default::default()
        })
        .expect("profile registration should succeed");
    let server = EmbeddedServer::with_providers(
        manager,
        Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))),
        Some(profile_manager),
        None,
        None,
        Arc::new(std::sync::RwLock::new(config)),
        None,
    );

    // When an image-bearing message runs a turn on the main path
    let created = server
        .call_method("session.create", json!({ "modelId": "text-model" }))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    server
        .call_method(
            "message.send",
            json!({
                "session_id": session_id,
                "mode": "wait",
                "input": [
                    { "type": "image", "source": { "kind": "base64", "media_type": "image/png", "data": "aGk=" } },
                ],
            }),
        )
        .await
        .unwrap();

    // Then the capability-gap dispatch hint is injected into the main
    // agent's context memory, naming the vision-capable profile
    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .expect("session stays live");
    let agent = session
        .get_agent(&AgentId::new(DEFAULT_MAIN_AGENT_ID))
        .await
        .expect("main agent stays live");
    let memory = agent.context_memory();
    let injected = memory
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .history()
        .iter()
        .filter(|m| m.origin == Some(mirri_core::PromptOrigin::Injection))
        .map(|m| m.message.text_content())
        .collect::<Vec<_>>();
    let hint = injected
        .iter()
        .find(|t| t.contains("dispatch a subagent"))
        .unwrap_or_else(|| panic!("a capability-gap hint should be injected: {injected:?}"));
    assert!(
        hint.contains("vision-agent"),
        "the hint should name the vision-capable profile: {hint}"
    );
    assert!(
        hint.contains("image"),
        "the hint should name the image modality: {hint}"
    );
}

