#[tokio::test]
async fn should_list_but_not_dispatch_a_file_disabled_profile_when_a_profile_file_declares_it() {
    // Given a home whose profiles directory holds a profile file declaring
    // `enabled = false` (the unified model's file-level flag)
    let tmp = tempfile::tempdir().expect("tempdir must be creatable");
    let profiles_dir = tmp.path().join("profiles");
    std::fs::create_dir_all(&profiles_dir).expect("profiles dir must be creatable");
    std::fs::write(
        profiles_dir.join("ghost.toml"),
        "name = \"ghost\"\nmodel = \"claude-sonnet-4-20250514\"\nenabled = false\n",
    )
    .expect("profile file must be writable");

    // When the profiles are listed (the management face)
    let server = test_server_for_home(tmp.path());
    let listed = server
        .call_method("agent.listProfiles", json!({}))
        .await
        .unwrap();

    // Then the file-level flag is reflected on the wire (the sole
    // enablement source since R3-3 retired the config's `disabled_agents`
    // derivation), while profiles without the
    // flag stay enabled — the R3-1 flip: the wire lists-but-marks
    let items = listed["items"]
        .as_array()
        .expect("the wire shape is an {items, skipped} object");
    let ghost = items
        .iter()
        .find(|item| item["name"] == "ghost")
        .expect("ghost is listed (list_all semantics)");
    assert_eq!(ghost["enabled"], false);
    let coder = items
        .iter()
        .find(|item| item["name"] == "coder")
        .expect("coder is listed");
    assert_eq!(coder["enabled"], true);

    // And the engine's dispatch face excludes it: the dispatch listing
    // no longer offers it, and an explicit resolve is refused with the
    // TS-aligned disabled message
    let manager = server
        .profile_manager
        .as_ref()
        .expect("the home-rooted server carries a profile manager");
    assert!(!manager.list().contains(&"ghost".to_string()));
    let error = manager
        .resolve_profile("ghost")
        .expect_err("resolving a file-disabled profile must fail");
    match error {
        mirri_core::EngineError::RequestInvalid(message) => {
            assert_eq!(
                message,
                "Agent type \"ghost\" is disabled. Re-enable it in the agent \
                 profiles configuration to dispatch it."
            );
        }
        other => panic!("expected RequestInvalid, got: {other}"),
    }
}

#[tokio::test]
async fn should_list_and_dispatch_a_config_named_profile_when_the_disabled_agents_key_is_retired() {
    // Given a home whose config.toml still declares the retired
    // `disabled_agents` key naming `coder`, while no profile file carries
    // an `enabled = false` flag
    let tmp = tempfile::tempdir().expect("tempdir must be creatable");
    let config_path = tmp.path().join("config.toml");
    std::fs::write(&config_path, "disabled_agents = [\"coder\"]\n")
        .expect("config.toml write should succeed");
    let config = ServerConfig::load(&config_path, &mirri_os::LocalSyncFs)
        .expect("the retired key must still parse (compatibility)");
    let profiles = Arc::new(mirri_core::ProfileManager::new());
    let _ = profiles.load_from_dir(&tmp.path().join("profiles"), &mirri_os::LocalSyncFs);
    let workspace = Arc::new(WorkspaceScope::new(
        WorkspaceId::new("home-ws"),
        tmp.path().to_path_buf(),
        WorkspaceScopeConfig::default(),
    ));
    let server = EmbeddedServer::with_providers(
        Arc::new(SessionManager::new(workspace)),
        None,
        Some(profiles),
        None,
        None,
        Arc::new(RwLock::new(config)),
        None,
    )
    .with_home_dir(Some(tmp.path().to_path_buf()))
    .with_models_dev_url(None);

    // Then the wire row shows `enabled: true` — the file-level flag is the
    // sole derivation since R3-3 retired the config key — and the engine's
    // dispatch face still offers and resolves the config-named profile
    let listed = server
        .call_method("agent.listProfiles", json!({}))
        .await
        .unwrap();
    let coder = listed["items"]
        .as_array()
        .expect("the wire shape is an {items, skipped} object")
        .iter()
        .find(|item| item["name"] == "coder")
        .expect("coder is listed (the retired key does not hide it)");
    assert_eq!(coder["enabled"], true);

    let manager = server
        .profile_manager
        .as_ref()
        .expect("the home-rooted server carries a profile manager");
    assert!(manager.list().contains(&"coder".to_string()));
    assert!(manager.resolve_profile("coder").is_ok());

    // And the config wire still exposes the key verbatim (inert data,
    // compatibility) — the same shape the boot warning points past
    let config_get = server.call_method("config.get", json!({})).await.unwrap();
    assert_eq!(config_get["disabledAgents"], json!(["coder"]));
}

#[tokio::test]
async fn should_surface_config_warnings_when_config_diagnostics_is_called() {
    // Given a config with a dangling default_provider, a model alias over a
    // missing provider, and the legacy [model] section
    let (server, _tmp, _config_path) = test_server_with_config_toml(
        r#"
default_provider = "ghost"

[providers.kimi]
type = "openai"

[models."kimi/old"]
provider = "retired-provider"
model = "some-model"
max_context_size = 131072

[model]
id = "legacy-model"
"#,
    );

    // When the diagnostics are requested
    let diagnostics = server
        .call_method("config.diagnostics", json!({}))
        .await
        .unwrap();

    // Then every inconsistency is reported as a plain string warning
    let warnings: Vec<&str> = diagnostics["warnings"]
        .as_array()
        .expect("warnings is an array")
        .iter()
        .map(|warning| warning.as_str().expect("a warning is a string"))
        .collect();
    assert_eq!(warnings.len(), 3, "warnings: {warnings:?}");
    assert!(
        warnings
            .iter()
            .any(|warning| warning.contains("default_provider \"ghost\"")),
        "the dangling default_provider is flagged: {warnings:?}"
    );
    assert!(
        warnings
            .iter()
            .any(|warning| warning.contains("kimi/old") && warning.contains("retired-provider")),
        "the dangling model alias is flagged: {warnings:?}"
    );
    assert!(
        warnings.iter().any(|warning| warning.contains("[model]")),
        "the legacy section migration hint is present: {warnings:?}"
    );
}

