#[tokio::test]
async fn should_fetch_merge_and_cache_models_when_refresh_provider_models_succeeds() {
    use wiremock::{Mock, MockServer, ResponseTemplate, matchers::*};

    // Given a home-rooted server whose models.dev upstream is a wiremock
    // endpoint serving a two-provider directory
    let (server, tmp) = test_server_with_home();
    let upstream = MockServer::start().await;
    Mock::given(method("GET"))
        .and(path("/api.json"))
        .respond_with(ResponseTemplate::new(200).set_body_json(models_dev_catalog_json()))
        .mount(&upstream)
        .await;
    let server = server.with_models_dev_url(Some(format!("{}/api.json", upstream.uri())));

    // When the refresh runs
    let result = server
        .call_method(
            "providerDiscovery.refreshProviderModels",
            json!({ "scope": "all" }),
        )
        .await
        .unwrap();

    // Then the klient three-part shape reports the providers as changed
    // (their model sets grew from nothing; the catalog object iterates in
    // key-sorted order) and nothing failed
    assert_eq!(result["failed"], json!([]));
    let changed: Vec<&str> = result["changed"]
        .as_array()
        .unwrap()
        .iter()
        .map(|entry| entry["provider_id"].as_str().expect("provider_id"))
        .collect();
    assert_eq!(changed, vec!["other-ai", "wiremock-ai"]);

    // And the directory is cached under the home
    assert!(
        tmp.path().join("models-dev.json").is_file(),
        "the fetched directory must be cached under the home"
    );

    // And model.list serves only the configured aliases — the fetched
    // directory models never enter the picker surface (D-M9); the
    // directory only feeds the display-name fallback (D-M1)
    let models = server.call_method("model.list", json!({})).await.unwrap();
    let items = models.as_array().expect("the bare catalog array");
    assert!(
        items
            .iter()
            .all(|item| item["provider"] != "wiremock-ai" && item["provider"] != "other-ai"),
        "fetched directory models must not leak into model.list: {items:?}"
    );
}

#[tokio::test]
async fn should_keep_cached_models_and_warn_when_the_upstream_fails() {
    use wiremock::{Mock, MockServer, ResponseTemplate, matchers::*};

    // Given a successful refresh (the in-memory catalog is populated)
    let (server, _tmp) = test_server_with_home();
    let upstream = MockServer::start().await;
    Mock::given(method("GET"))
        .and(path("/api.json"))
        .respond_with(ResponseTemplate::new(200).set_body_json(models_dev_catalog_json()))
        .mount(&upstream)
        .await;
    let server = server.with_models_dev_url(Some(format!("{}/api.json", upstream.uri())));
    server
        .call_method("providerDiscovery.refreshProviderModels", json!({}))
        .await
        .unwrap();

    // When the upstream starts failing (500) and a refresh is requested
    upstream.reset().await;
    Mock::given(method("GET"))
        .and(path("/api.json"))
        .respond_with(ResponseTemplate::new(500))
        .mount(&upstream)
        .await;
    let result = server
        .call_method("providerDiscovery.refreshProviderModels", json!({}))
        .await
        .unwrap();

    // Then the RPC still succeeds (the degradation never errors the call)
    assert_eq!(result["failed"], json!([]));

    // And model.list still serves only the config aliases — the cached
    // directory backs providerDiscovery degradation, never the picker
    // surface (D-M9)
    let models = server.call_method("model.list", json!({})).await.unwrap();
    assert!(
        models
            .as_array()
            .unwrap()
            .iter()
            .all(|item| !(item["provider"] == "wiremock-ai" && item["model"] == "wm-large")),
        "cached directory models must not leak into model.list (D-M9)"
    );

    // And config.diagnostics surfaces the failed refresh as a warning
    let diagnostics = server
        .call_method("config.diagnostics", json!({}))
        .await
        .unwrap();
    let warned = diagnostics["warnings"]
        .as_array()
        .expect("warnings is an array")
        .iter()
        .any(|warning| {
            warning
                .as_str()
                .is_some_and(|text| text.contains("models.dev"))
        });
    assert!(warned, "the failed refresh must warn: {diagnostics}");
}

#[tokio::test]
async fn should_serve_the_disk_cache_when_a_restarted_server_cannot_refresh() {
    use wiremock::{Mock, MockServer, ResponseTemplate, matchers::*};

    // Given a successful refresh that wrote the cache file under the home
    let (server, tmp) = test_server_with_home();
    let live = MockServer::start().await;
    Mock::given(method("GET"))
        .and(path("/api.json"))
        .respond_with(ResponseTemplate::new(200).set_body_json(models_dev_catalog_json()))
        .mount(&live)
        .await;
    let server = server.with_models_dev_url(Some(format!("{}/api.json", live.uri())));
    server
        .call_method("providerDiscovery.refreshProviderModels", json!({}))
        .await
        .unwrap();
    assert!(tmp.path().join("models-dev.json").is_file());

    // When a restarted server over the same home refreshes against a dead
    // upstream (the cache file is the only directory source left)
    let dead = MockServer::start().await;
    Mock::given(method("GET"))
        .and(path("/api.json"))
        .respond_with(ResponseTemplate::new(500))
        .mount(&dead)
        .await;
    let restarted = test_server_for_home(tmp.path())
        .with_models_dev_url(Some(format!("{}/api.json", dead.uri())));
    let result = restarted
        .call_method("providerDiscovery.refreshProviderModels", json!({}))
        .await
        .unwrap();

    // Then the refresh degrades to the on-disk cache without erroring
    assert_eq!(result["failed"], json!([]));
    let models = restarted
        .call_method("model.list", json!({}))
        .await
        .unwrap();
    assert!(
        models
            .as_array()
            .unwrap()
            .iter()
            .all(|item| !(item["provider"] == "wiremock-ai" && item["model"] == "wm-large")),
        "the disk cache backs the refresh degradation but never model.list (D-M9)"
    );
}

/// A config seed for the P5 lazy-load tests: exactly one alias (the
/// `wiremock-ai` provider, `wm-large` model) with **no** displayName — the
/// only way a `display_name` row can appear is the models.dev directory
/// name fallback (D-M1 middle level).
const P5_LAZY_LOAD_SEED_TOML: &str = r#"
default_provider = "wiremock-ai"

[providers.wiremock-ai]
type = "openai"
api_key = "sk-test"

[models."wiremock-ai/wm-large"]
provider = "wiremock-ai"
model = "wm-large"
max_context_size = 123456
"#;

#[tokio::test]
async fn should_restore_catalog_from_disk_cache_without_refresh_after_restart() {
    // Given: home already holds a models-dev.json cache (the previous
    // server instance's refresh wrote it) and the config alias carries no
    // displayName — the directory name is the only display_name source
    let (server, tmp, _config_path) = test_server_with_config_toml(P5_LAZY_LOAD_SEED_TOML);
    std::fs::write(
        tmp.path().join("models-dev.json"),
        models_dev_catalog_json().to_string(),
    )
    .expect("the cache seed must be writable");
    let server = server
        .with_home_dir(Some(tmp.path().to_path_buf()))
        // Hermetic: the upstream is off, so this test cannot hit the
        // network even if some path tried to fetch.
        .with_models_dev_url(None);

    // When: a fresh server instance (no refresh called) requests model.list
    let models = server.call_method("model.list", json!({})).await.unwrap();

    // Then: the alias row's display_name comes from the disk cache (C1
    // lazy load restored the directory before name resolution) and the
    // in-memory catalog actually holds it — no network was involved
    let items = models.as_array().expect("the bare catalog array");
    assert_eq!(items.len(), 1);
    assert_eq!(items[0]["provider"], "wiremock-ai");
    assert_eq!(items[0]["model"], "wm-large");
    assert_eq!(
        items[0]["display_name"], "WM Large",
        "the disk-cache directory name must back the restarted server's list (C1)"
    );
    let in_memory = server
        .models_dev_catalog
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .clone();
    assert!(
        in_memory.is_some(),
        "the lazy load must restore the directory into the in-memory catalog"
    );
}

#[tokio::test]
async fn should_not_write_cache_file_when_persist_cache_is_disabled() {
    use wiremock::{Mock, MockServer, ResponseTemplate, matchers::*};

    // Given: [model_catalog] persist_cache=false, a reachable upstream,
    // a stale cache file left by an earlier (caching) instance, and an
    // alias without displayName
    let (server, tmp, config_path) = test_server_with_config_toml(&format!(
        "[model_catalog]\npersist_cache = false\n{P5_LAZY_LOAD_SEED_TOML}"
    ));
    let stale = json!({
        "stale-ai": {
            "id": "stale-ai",
            "name": "Stale AI",
            "models": { "stale-model": { "name": "Stale Model" } }
        }
    });
    std::fs::write(tmp.path().join("models-dev.json"), stale.to_string())
        .expect("the stale cache seed must be writable");
    let upstream = MockServer::start().await;
    Mock::given(method("GET"))
        .and(path("/api.json"))
        .respond_with(ResponseTemplate::new(200).set_body_json(models_dev_catalog_json()))
        .mount(&upstream)
        .await;
    let server = server
        .with_home_dir(Some(tmp.path().to_path_buf()))
        .with_models_dev_url(Some(format!("{}/api.json", upstream.uri())));

    // When: the refresh succeeds
    let result = server
        .call_method("providerDiscovery.refreshProviderModels", json!({}))
        .await
        .unwrap();

    // Then: no cache file is written — the stale file survives byte-
    // identical (R6: persist_cache off never writes nor deletes old files)
    assert_eq!(result["failed"], json!([]));
    let cache_path = tmp.path().join("models-dev.json");
    assert!(
        cache_path.is_file(),
        "persist_cache=false must not delete an old cache file (R6)"
    );
    let on_disk: Value =
        serde_json::from_str(&std::fs::read_to_string(&cache_path).expect("stale still there"))
            .expect("stale content is JSON");
    assert_eq!(
        on_disk, stale,
        "persist_cache=false must not overwrite the cache file with the fetched directory"
    );

    // And the refresh still merges into memory (the disk gate never
    // touches the in-session catalog): the same instance resolves the
    // directory name
    let models = server.call_method("model.list", json!({})).await.unwrap();
    assert_eq!(models.as_array().unwrap()[0]["display_name"], "WM Large");

    // And the lazy load honours the flag: a restarted server over the
    // same home does not read the stale file — model.list serves the raw
    // model name (no directory-name fallback)
    let workspace = Arc::new(WorkspaceScope::new(
        WorkspaceId::new("home-ws"),
        tmp.path().to_path_buf(),
        WorkspaceScopeConfig::default(),
    ));
    let manager = Arc::new(SessionManager::new(workspace));
    let config = Arc::new(RwLock::new(
        ServerConfig::load(&config_path, &mirri_os::LocalSyncFs).expect("seed config should load"),
    ));
    let restarted =
        EmbeddedServer::with_providers(manager, None, None, None, None, config, Some(config_path))
            .with_home_dir(Some(tmp.path().to_path_buf()))
            .with_models_dev_url(None);
    let models = restarted
        .call_method("model.list", json!({}))
        .await
        .unwrap();
    let items = models.as_array().expect("the bare catalog array");
    assert_eq!(items.len(), 1);
    assert!(
        items.iter().all(|item| item.get("display_name").is_none()),
        "persist_cache=false must not lazy-load the stale cache file (R6): {items:?}"
    );
}

#[tokio::test]
async fn should_merge_only_the_addressed_provider_when_provider_id_is_given() {
    use wiremock::{Mock, MockServer, ResponseTemplate, matchers::*};

    // Given a seeded config with the kimi provider and a live upstream whose
    // directory carries kimi (the addressed provider) next to another one
    let (server, tmp, _config_path) = test_server_with_config_toml(CONFIG_WRITE_SEED_TOML);
    let upstream = MockServer::start().await;
    let catalog = json!({
        "kimi": {
            "id": "kimi",
            "name": "Moonshot Kimi",
            "models": {
                "kimi-k2": { "name": "Kimi K2", "limit": { "context": 262144 } }
            }
        },
        "wiremock-ai": {
            "id": "wiremock-ai",
            "name": "WireMock AI",
            "models": {
                "wm-large": { "name": "WM Large", "limit": { "context": 123456 } }
            }
        }
    });
    Mock::given(method("GET"))
        .and(path("/api.json"))
        .respond_with(ResponseTemplate::new(200).set_body_json(catalog))
        .mount(&upstream)
        .await;
    let server = server
        .with_home_dir(Some(tmp.path().to_path_buf()))
        .with_models_dev_url(Some(format!("{}/api.json", upstream.uri())));

    // When the refresh is scoped to the configured kimi provider
    let result = server
        .call_method(
            "providerDiscovery.refreshProviderModels",
            json!({ "providerId": "kimi" }),
        )
        .await
        .unwrap();

    // Then the result addresses only kimi (the other directory provider
    // was never merged)
    let changed: Vec<&str> = result["changed"]
        .as_array()
        .unwrap()
        .iter()
        .map(|entry| entry["provider_id"].as_str().expect("provider_id"))
        .collect();
    assert_eq!(changed, vec!["kimi"]);
    let models = server.call_method("model.list", json!({})).await.unwrap();
    let items = models.as_array().expect("the bare catalog array");
    assert_eq!(
        items.len(),
        2,
        "model.list rows must equal the config alias count (D-M9)"
    );
    assert!(
        !items
            .iter()
            .any(|item| item["provider"] == "kimi" && item["model"] == "kimi-k2"),
        "the addressed provider's directory models are not merged into model.list"
    );
    assert!(
        !items.iter().any(|item| item["provider"] == "wiremock-ai"),
        "the unaddressed provider's models are not merged into model.list"
    );
    assert!(
        items
            .iter()
            .any(|item| item["provider"] == "kimi" && item["model"] == "alpha")
            && items
                .iter()
                .any(|item| item["provider"] == "kimi" && item["model"] == "beta"),
        "the configured aliases remain listed"
    );

    // And an unknown provider id answers provider.not_found (the wire
    // contract model.getProvider also branches on)
    let error = server
        .call_method(
            "providerDiscovery.refreshProviderModels",
            json!({ "providerId": "ghost" }),
        )
        .await
        .unwrap_err();
    assert!(
        matches!(
            &error,
            EngineError::Rpc { code: -32001, data: Some(data), .. }
                if data["domainCode"] == "provider.not_found"
        ),
        "an unknown providerId must answer provider.not_found: {error:?}"
    );
}

