/// should persist the activation and drive a turn when agent.activateSkill
/// is dispatched with a workspace skill
#[tokio::test]
async fn should_persist_activation_and_drive_turn_when_agent_activate_skill_is_dispatched() {
    // Given a server with a scripted LLM and a session whose catalog
    // carries a discovered skill
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("Skill loaded. Following its instructions.");
    let (server, tmp) = test_server(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))));
    let skill_dir = tmp.path().join("skills").join("commit");
    std::fs::create_dir_all(&skill_dir).unwrap();
    std::fs::write(
        skill_dir.join("SKILL.md"),
        "---\ndescription: commit helper\n---\nRun the commit flow.",
    )
    .unwrap();
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    let session = server
        .manager
        .get_session(&mirri_core::SessionId::new(&session_id))
        .await
        .unwrap();
    session
        .skill_catalog()
        .discover(
            skill_dir.parent().unwrap(),
            mirri_core::SkillSource::Project,
        )
        .unwrap();

    // When the skill is activated with args while a subscriber listens
    let mut events = server.subscribe_events().await.unwrap();
    server
        .call_method(
            "agent.activateSkill",
            json!({ "session_id": session_id, "name": "commit", "args": "fix the bug" }),
        )
        .await
        .unwrap();

    // Then the activation turn starts and completes (the wire event pair
    // the existing turn tests observe — `event.turn.ended` closes what
    // `event.turn.started` opened)
    let _ = next_event_where(&mut events, |n| n.method == "event.skill.activated", |_| {}).await;
    let _ = next_event_where(&mut events, |n| n.method == "event.turn.started", |_| {}).await;
    let _ = next_event_where(&mut events, |n| n.method == "event.turn.ended", |_| {}).await;

    // And the wire log carries the v2 kernel's activation records: the
    // skill.activate fact plus turn.prompt / context.append_message both
    // stamped with the skill_activation origin and its identity payload
    let manager = server.session_manager();
    let wire_log_path = manager
        .persistence()
        .wire_log_path(&mirri_core::SessionId::new(&session_id));
    let log = JsonlAppendLog::open(&wire_log_path).await.unwrap();
    let ops = log.read_all().await.unwrap();
    assert!(
        ops.iter().any(|op| matches!(
            op,
            WireOp::SkillActivate { origin }
                if origin["kind"] == "skill_activation"
                    && origin["skillName"] == "commit"
                    && origin["trigger"] == "user-slash"
                    && origin["skillArgs"] == "fix the bug"
        )),
        "the wire log must record the skill.activate fact: {ops:?}"
    );
    assert!(
        ops.iter().any(|op| matches!(
            op,
            WireOp::TurnPrompt { origin, .. } if origin["kind"] == "skill_activation"
        )),
        "turn.prompt must carry the skill_activation origin: {ops:?}"
    );
    assert!(
        ops.iter().any(|op| matches!(
            op,
            WireOp::ContextAppendMessage { message }
                if message["origin"]["kind"] == "skill_activation"
                    && message["origin"]["skillName"] == "commit"
                    && message["role"] == "user"
        )),
        "context.append_message must carry the origin payload: {ops:?}"
    );

    // And the turn's model call saw the rendered user-slash skill prompt
    // (serialized whole — the call's message shape varies by provider
    // adapter, so a substring match over the full JSON is the robust form)
    let first_call = serde_json::to_string(&mock.messages_of_call(0)).unwrap_or_default();
    assert!(
        first_call.contains("<kimi-skill-loaded name=\\\"commit\\\" trigger=\\\"user-slash\\\""),
        "the LLM must see the rendered skill prompt: {first_call}"
    );
}

/// should fail without recording the activation when agent.activateSkill
/// is dispatched with no LLM provider configured
#[tokio::test]
async fn should_fail_without_recording_the_activation_when_agent_activate_skill_has_no_llm_provider()
 {
    // Given a server with NO LLM factory and a session whose catalog
    // carries a discovered skill
    let (server, tmp) = test_server(None);
    let skill_dir = tmp.path().join("skills").join("commit");
    std::fs::create_dir_all(&skill_dir).unwrap();
    std::fs::write(
        skill_dir.join("SKILL.md"),
        "---\ndescription: commit helper\n---\nRun the commit flow.",
    )
    .unwrap();
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    let session = server
        .manager
        .get_session(&mirri_core::SessionId::new(&session_id))
        .await
        .unwrap();
    session
        .skill_catalog()
        .discover(
            skill_dir.parent().unwrap(),
            mirri_core::SkillSource::Project,
        )
        .unwrap();

    // When the skill is activated
    let error = server
        .call_method(
            "agent.activateSkill",
            json!({ "session_id": session_id, "name": "commit", "args": "fix the bug" }),
        )
        .await
        .unwrap_err();

    // Then the RPC fails with the no-provider error
    assert!(
        error.to_string().contains("no LLM provider configured"),
        "error was: {error}"
    );

    // And the wire log carries no half-activation — no `skill.activate`
    // fact exists without its turn pair. (A fresh create writes nothing
    // to disk under SDR-004, so the log may not even exist yet.)
    let manager = server.session_manager();
    let wire_log_path = manager
        .persistence()
        .wire_log_path(&mirri_core::SessionId::new(&session_id));
    let ops = if wire_log_path.exists() {
        let log = JsonlAppendLog::open(&wire_log_path).await.unwrap();
        log.read_all().await.unwrap()
    } else {
        Vec::new()
    };
    assert!(
        !ops.iter()
            .any(|op| matches!(op, WireOp::SkillActivate { .. })),
        "a half-activation must never reach the wire log: {ops:?}"
    );
}

/// A factory whose provider always fails to build — the broken-config
/// surface the pre-turn validation must catch.
struct FailingLlmFactory;

impl LlmFactory for FailingLlmFactory {
    fn create_llm(&self, _config: &AgentScopeConfig) -> Result<Arc<dyn Llm>, String> {
        Err("broken provider config".to_string())
    }
}

