// ===== SDR-005 / US3.6 message-inline skill references (rust landing) =====

/// A session whose catalog carries two project skills (`alpha`, `beta`).
async fn inline_skill_server(
    mock: &Arc<ScriptedLlm>,
) -> (
    EmbeddedServer,
    tempfile::TempDir,
    String,
    std::path::PathBuf,
    std::path::PathBuf,
) {
    let (server, tmp) = test_server(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(mock)))));
    let skills_root = tmp.path().join("skills");
    let alpha_dir = skills_root.join("alpha");
    let beta_dir = skills_root.join("beta");
    std::fs::create_dir_all(&alpha_dir).unwrap();
    std::fs::create_dir_all(&beta_dir).unwrap();
    std::fs::write(
        alpha_dir.join("SKILL.md"),
        "---\ndescription: alpha helper\n---\nAlways use the alpha path.",
    )
    .unwrap();
    std::fs::write(
        beta_dir.join("SKILL.md"),
        "---\ndescription: beta helper\n---\nAlways use the beta path.",
    )
    .unwrap();
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    let session = server
        .manager
        .get_session(&mirri_core::SessionId::new(&session_id))
        .await
        .unwrap();
    session
        .skill_catalog()
        .discover(&skills_root, mirri_core::SkillSource::Project)
        .unwrap();
    (
        server,
        tmp,
        session_id,
        alpha_dir.join("SKILL.md"),
        beta_dir.join("SKILL.md"),
    )
}

/// should activate a single inline skill reference when a message is sent
#[tokio::test]
async fn should_activate_inline_skill_when_message_carries_a_reference() {
    // Given a server with two discovered skills and a scripted LLM
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("ok.");
    let (server, _tmp, session_id, alpha_md, _) = inline_skill_server(&mock).await;

    // When a message with a single inline skill reference is sent (wait mode
    // so the turn settles and we can read the memory the engine fed)
    let mut events = server.subscribe_events().await.unwrap();
    let target = alpha_md.display().to_string();
    let text = format!("use [$alpha]({target}) then finish");
    server
        .call_method(
            "message.send",
            json!({ "session_id": session_id, "text": text, "mode": "wait" }),
        )
        .await
        .unwrap();

    // Then the subscriber observes one event.skill.activated with the
    // user-inline trigger and the alpha identity
    let event =
        next_event_where(&mut events, |n| n.method == "event.skill.activated", |_| {}).await;
    assert_eq!(event.params["skillName"], "alpha");
    assert_eq!(event.params["trigger"], "user-inline");
    assert_eq!(event.params["skillSource"], "project");
    assert_eq!(event.params["skillPath"], json!(target));
    assert!(
        event.params["activationId"]
            .as_str()
            .is_some_and(|id| id.contains('#')),
        "activation id is message-scoped with an ordinal: {}",
        event.params
    );

    // And the wire log carries the skill.activate fact and the wrap + body
    // message sequence — the turn opened with the wrap threaded BEFORE the
    // body (ADR-004 "N wraps + 1 body").
    let ops = read_wire_ops(&server, &session_id).await;
    assert_eq!(
        ops.iter()
            .filter(|op| matches!(op, WireOp::SkillActivate { .. }))
            .count(),
        1,
        "exactly one activation fact: {ops:?}"
    );
    let first_call = serde_json::to_string(&mock.messages_of_call(0)).unwrap_or_default();
    assert!(
        first_call.contains("<kimi-skill-loaded name=\\\"alpha\\\" trigger=\\\"user-inline\\\""),
        "the LLM must see the inline activation wrap: {first_call}"
    );
    assert!(
        first_call.contains("finish"),
        "the body text must reach the LLM: {first_call}"
    );
    // The last message (the body) carries the bare `[alpha]` marker.
    let last_user = mock.messages_of_call(0).to_string();
    assert!(
        last_user.contains("[alpha]"),
        "the body placeholder is the idempotent [alpha]: {last_user}"
    );
}

/// should activate multiple inline skill references in appearance order
#[tokio::test]
async fn should_activate_multiple_inline_skills_in_appearance_order() {
    // Given two discovered skills and a scripted LLM
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("ok.");
    let (server, _tmp, session_id, alpha_md, beta_md) = inline_skill_server(&mock).await;

    // When a message references both skills
    let mut events = server.subscribe_events().await.unwrap();
    let alpha_target = alpha_md.display().to_string();
    let beta_target = beta_md.display().to_string();
    let text = format!("[$alpha]({alpha_target}) + [$beta]({beta_target})");
    server
        .call_method(
            "message.send",
            json!({ "session_id": session_id, "text": text, "mode": "wait" }),
        )
        .await
        .unwrap();

    // Then two activation events arrive in appearance order (alpha then beta)
    let first =
        next_event_where(&mut events, |n| n.method == "event.skill.activated", |_| {}).await;
    assert_eq!(first.params["skillName"], "alpha");
    let second =
        next_event_where(&mut events, |n| n.method == "event.skill.activated", |_| {}).await;
    assert_eq!(second.params["skillName"], "beta");
    // And the model call carries both wraps before the body
    let call = serde_json::to_string(&mock.messages_of_call(0)).unwrap_or_default();
    assert!(
        call.contains("trigger=\\\"user-inline\\\"")
            && call.matches("alpha").count() >= 1
            && call.matches("beta").count() >= 1,
        "both wraps must reach the LLM: {call}"
    );
    // And the wire log holds two activation facts with distinct ids
    let ops = read_wire_ops(&server, &session_id).await;
    assert_eq!(
        ops.iter()
            .filter(|op| matches!(op, WireOp::SkillActivate { .. }))
            .count(),
        2,
        "two activation facts: {ops:?}"
    );
}

/// should fold duplicate inline references into a single activation
#[tokio::test]
async fn should_fold_duplicate_inline_references_into_a_single_activation() {
    // Given two discovered skills
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("ok.");
    let (server, _tmp, session_id, alpha_md, _) = inline_skill_server(&mock).await;

    // When the same skill is referenced twice (different paths would differ,
    // but the same SKILL.md path twice is one instance)
    let mut events = server.subscribe_events().await.unwrap();
    let target = alpha_md.display().to_string();
    let text = format!("[$a]({target}) and again [$a]({target})");
    server
        .call_method(
            "message.send",
            json!({ "session_id": session_id, "text": text, "mode": "wait" }),
        )
        .await
        .unwrap();

    // Then only one activation occurs (dup folded)
    next_event_where(&mut events, |n| n.method == "event.skill.activated", |_| {}).await;
    let ops = read_wire_ops(&server, &session_id).await;
    assert_eq!(
        ops.iter()
            .filter(|op| matches!(op, WireOp::SkillActivate { .. }))
            .count(),
        1,
        "duplicate references fold into one fact: {ops:?}"
    );
    // And the body replaced both spans with [a]
    let call = serde_json::to_string(&mock.messages_of_call(0)).unwrap_or_default();
    assert_eq!(
        call.matches("[$a]").count(),
        0,
        "no trigger link remains in the body: {call}"
    );
    assert_eq!(
        call.matches("[a]").count(),
        2,
        "both duplicate spans collapsed to bare [a]: {call}"
    );
}

/// should leave an unknown inline reference as plain text (fail soft)
#[tokio::test]
async fn should_leave_unknown_inline_reference_as_plain_text_when_not_in_catalog() {
    // Given two discovered skills
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("ok.");
    let (server, _tmp, session_id, _, _) = inline_skill_server(&mock).await;

    // When a message references a skill not in the catalog
    let text = "use [$ghost](/gone/ghost/SKILL.md) please";
    server
        .call_method(
            "message.send",
            json!({ "session_id": session_id, "text": text, "mode": "wait" }),
        )
        .await
        .unwrap();

    // Then no activation fact lands on the wire and the body keeps the link
    let ops = read_wire_ops(&server, &session_id).await;
    assert!(
        !ops.iter()
            .any(|op| matches!(op, WireOp::SkillActivate { .. })),
        "no activation fact for an unknown skill: {ops:?}"
    );
    let call = serde_json::to_string(&mock.messages_of_call(0)).unwrap_or_default();
    assert!(
        call.contains("[$ghost](/gone/ghost/SKILL.md)"),
        "unknown reference stays verbatim (fail soft): {call}"
    );
}

/// should not execute a command inline reference (engine stays neutral)
#[tokio::test]
async fn should_leave_command_reference_as_plain_text_when_inline() {
    // Given two discovered skills
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("ok.");
    let (server, _tmp, session_id, _, _) = inline_skill_server(&mock).await;

    // When a message carries a command reference
    let text = "run [$/clear](command:clear) now";
    server
        .call_method(
            "message.send",
            json!({ "session_id": session_id, "text": text, "mode": "wait" }),
        )
        .await
        .unwrap();

    // Then no activation fact and no command execution — the body keeps the
    // link (ADR-004 §4: command dispatch is the client's job)
    let ops = read_wire_ops(&server, &session_id).await;
    assert!(
        !ops.iter()
            .any(|op| matches!(op, WireOp::SkillActivate { .. })),
        "a command reference never activates: {ops:?}"
    );
    let call = serde_json::to_string(&mock.messages_of_call(0)).unwrap_or_default();
    assert!(
        call.contains("[$/clear](command:clear)"),
        "command link stays verbatim (engine does not execute): {call}"
    );
}

/// should disable an inline reference when the skill is user-disabled
#[tokio::test]
async fn should_leave_inline_reference_as_plain_text_when_skill_is_disabled() {
    // Given a server whose alpha skill is user-disabled
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("ok.");
    let (server, _tmp, session_id, alpha_md, _) = inline_skill_server(&mock).await;
    // Disable alpha at the catalog level (the RPC path needs a config file).
    let session = server
        .manager
        .get_session(&mirri_core::SessionId::new(&session_id))
        .await
        .unwrap();
    assert!(session.skill_catalog().set_enabled("alpha", false));

    // When a message references the disabled skill
    let target = alpha_md.display().to_string();
    let text = format!("use [$alpha]({target}) please");
    server
        .call_method(
            "message.send",
            json!({ "session_id": session_id, "text": text, "mode": "wait" }),
        )
        .await
        .unwrap();

    // Then no activation, and the body keeps the link (fail soft)
    let call = serde_json::to_string(&mock.messages_of_call(0)).unwrap_or_default();
    assert!(
        call.contains("[$alpha]"),
        "disabled skill's reference stays verbatim: {call}"
    );
    assert!(
        !call.contains("<kimi-skill-loaded"),
        "no wrap for a disabled skill: {call}"
    );
}

// ===== ADR-006 admission stamp: with_skills on the rewritten body =====
//
// The deduped activated-skill list must be stamped at BOTH persistence
// sites — the durable wire row and the live in-memory ContextMessage — so
// a resumed session and a live session expose the same chips.

/// should stamp with_skills on the rewritten user message when inline
/// skills activate — on the wire row AND the live in-memory message
#[tokio::test]
async fn should_stamp_with_skills_on_rewritten_message_when_inline_skills_activate() {
    // Given two discovered skills and a scripted LLM
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("ok.");
    let (server, _tmp, session_id, alpha_md, beta_md) = inline_skill_server(&mock).await;

    // When a message references both skills (wait mode, so the turn's
    // memory append has settled)
    let alpha_target = alpha_md.display().to_string();
    let beta_target = beta_md.display().to_string();
    let text = format!("[$alpha]({alpha_target}) + [$beta]({beta_target})");
    server
        .call_method(
            "message.send",
            json!({ "session_id": session_id, "text": text, "mode": "wait" }),
        )
        .await
        .unwrap();

    // Then the durable wire row of the BODY carries with_skills — the
    // wrap rows (skill_activation origin) never do
    let ops = read_wire_ops(&server, &session_id).await;
    let body_message = ops
        .iter()
        .filter_map(|op| match op {
            WireOp::ContextAppendMessage { message } => Some(message),
            _ => None,
        })
        .find(|message| message["origin"]["kind"] == "user")
        .expect("the body row must be journaled");
    assert_eq!(
        body_message["with_skills"],
        json!([
            { "name": "alpha", "target": alpha_target, "trigger": "user-inline" },
            { "name": "beta", "target": beta_target, "trigger": "user-inline" }
        ]),
        "the body row stamps the deduped activation list: {body_message}"
    );
    // Wrap rows carry no with_skills (their origin is skill_activation).
    for op in ops.iter() {
        if let WireOp::ContextAppendMessage { message } = op
            && message["origin"]["kind"] == "skill_activation"
        {
            assert!(
                !message.as_object().unwrap().contains_key("with_skills"),
                "a wrap row must never carry with_skills: {message}"
            );
        }
    }
    // And the LIVE in-memory face carries the same stamp — the point of
    // the two-site design (a session.resume rebuilds from the wire; a live
    // session reads memory).
    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .unwrap();
    let agent = session
        .get_agent(&AgentId::new(DEFAULT_MAIN_AGENT_ID))
        .await
        .unwrap();
    let memory = agent.context_memory();
    let guard = memory.lock().unwrap_or_else(|e| e.into_inner());
    let body = guard
        .history()
        .iter()
        .find(|entry| entry.origin == Some(mirri_core::PromptOrigin::User))
        .expect("the rewritten body must be in memory");
    assert_eq!(
        body.with_skills,
        Some(vec![
            mirri_core::WithSkillsEntry {
                name: "alpha".to_string(),
                target: alpha_target,
                trigger: "user-inline".to_string(),
            },
            mirri_core::WithSkillsEntry {
                name: "beta".to_string(),
                target: beta_target,
                trigger: "user-inline".to_string(),
            },
        ]),
        "the live body message carries the admission stamp: {:?}",
        body
    );
}

/// should omit with_skills when no inline skill activates — on the wire
/// row AND None in the live memory
#[tokio::test]
async fn should_omit_with_skills_when_no_inline_skill_activates() {
    // Given a server with discovered skills and a scripted LLM
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("ok.");
    let (server, _tmp, session_id, _, _) = inline_skill_server(&mock).await;

    // When a message carries only a command reference (never activated)
    // plus plain text, wait mode
    server
        .call_method(
            "message.send",
            json!({ "session_id": session_id, "text": "run [$/clear](command:clear) now", "mode": "wait" }),
        )
        .await
        .unwrap();

    // Then the journaled body row has no with_skills key
    let ops = read_wire_ops(&server, &session_id).await;
    let body_message = ops
        .iter()
        .filter_map(|op| match op {
            WireOp::ContextAppendMessage { message } => Some(message),
            _ => None,
        })
        .find(|message| message["origin"]["kind"] == "user")
        .expect("the body row must be journaled");
    assert!(
        !body_message
            .as_object()
            .unwrap()
            .contains_key("with_skills"),
        "a body with no activation must not carry with_skills: {body_message}"
    );
    // And the live in-memory body carries None
    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .unwrap();
    let agent = session
        .get_agent(&AgentId::new(DEFAULT_MAIN_AGENT_ID))
        .await
        .unwrap();
    let memory = agent.context_memory();
    let guard = memory.lock().unwrap_or_else(|e| e.into_inner());
    let body = guard
        .history()
        .iter()
        .find(|entry| entry.origin == Some(mirri_core::PromptOrigin::User))
        .expect("the body must be in memory");
    assert_eq!(
        body.with_skills, None,
        "no activation ⇒ no stamp in live memory: {:?}",
        body
    );
}

/// should collapse duplicate references to the same skill into a single
/// with_skills entry (dedup by skill name, in reference order)
#[tokio::test]
async fn should_dedupe_with_skills_entries_when_same_skill_referenced_twice() {
    // Given two discovered skills and a scripted LLM
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("ok.");
    let (server, _tmp, session_id, alpha_md, _) = inline_skill_server(&mock).await;

    // When the same skill is referenced twice, wait mode
    let target = alpha_md.display().to_string();
    let text = format!("[$a]({target}) and again [$a]({target})");
    server
        .call_method(
            "message.send",
            json!({ "session_id": session_id, "text": text, "mode": "wait" }),
        )
        .await
        .unwrap();

    // Then exactly one with_skills entry lands on the journaled body row
    let ops = read_wire_ops(&server, &session_id).await;
    let body_message = ops
        .iter()
        .filter_map(|op| match op {
            WireOp::ContextAppendMessage { message } => Some(message),
            _ => None,
        })
        .find(|message| message["origin"]["kind"] == "user")
        .expect("the body row must be journaled");
    assert_eq!(
        body_message["with_skills"],
        json!([{ "name": "alpha", "target": target.clone(), "trigger": "user-inline" }]),
        "duplicate references fold into one entry: {body_message}"
    );
    // And the live in-memory face agrees (single entry)
    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .unwrap();
    let agent = session
        .get_agent(&AgentId::new(DEFAULT_MAIN_AGENT_ID))
        .await
        .unwrap();
    let memory = agent.context_memory();
    let guard = memory.lock().unwrap_or_else(|e| e.into_inner());
    let body = guard
        .history()
        .iter()
        .find(|entry| entry.origin == Some(mirri_core::PromptOrigin::User))
        .expect("the body must be in memory");
    assert_eq!(
        body.with_skills,
        Some(vec![mirri_core::WithSkillsEntry {
            name: "alpha".to_string(),
            target,
            trigger: "user-inline".to_string(),
        }]),
        "the live body message carries the deduped stamp: {:?}",
        body
    );
}

// ===== builtin:// inline activation (ADR-007 D4 prerequisite) =====
//
// The admission path must activate inline references whose target is a
// `builtin://<name>` pseudo path — the form the web chips mint for builtin
// skills — and tolerate the dirty historical `builtin://<name>/SKILL.md`
// shape persisted by pre-fix insertion sites.

/// a helper building a session whose catalog carries a registered builtin
async fn builtin_inline_skill_server(
    mock: &Arc<ScriptedLlm>,
    name: &str,
    pseudo_path: &str,
) -> (EmbeddedServer, tempfile::TempDir, String) {
    let (server, tmp) = test_server(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(mock)))));
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    let session = server
        .manager
        .get_session(&mirri_core::SessionId::new(&session_id))
        .await
        .unwrap();
    session.skill_catalog().register_builtin([mirri_core::skill::builtin::BuiltinSkillDef {
        def: mirri_core::SkillDef {
            name: name.into(),
            description: format!("{name} helper"),
            path: std::path::PathBuf::from(pseudo_path),
            source: mirri_core::SkillSource::Builtin,
            plugin: None,
            disable_model_invocation: false,
            is_sub_skill: false,
        },
        content: "---\ndescription: builtin helper\n---\nAlways use the builtin path.",
    }]);
    (server, tmp, session_id)
}

/// should activate a builtin inline skill when the message carries a
/// `builtin://<name>` target
#[tokio::test]
async fn should_activate_builtin_inline_skill_when_message_carries_a_builtin_target() {
    // Given a server whose catalog carries a registered builtin skill
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("ok.");
    let (server, _tmp, session_id) =
        builtin_inline_skill_server(&mock, "update-config", "builtin://update-config").await;

    // When a message references it by its builtin pseudo path (wait mode)
    let mut events = server.subscribe_events().await.unwrap();
    server
        .call_method(
            "message.send",
            json!({ "session_id": session_id, "text": "use [$update-config](builtin://update-config) hello", "mode": "wait" }),
        )
        .await
        .unwrap();

    // Then the activation event fires with the builtin identity
    let event =
        next_event_where(&mut events, |n| n.method == "event.skill.activated", |_| {}).await;
    assert_eq!(event.params["skillName"], "update-config");
    assert_eq!(event.params["trigger"], "user-inline");
    assert_eq!(event.params["skillSource"], "builtin");
    assert_eq!(event.params["skillPath"], json!("builtin://update-config"));

    // And the LLM sees the wrap; the body carries the `[name]` marker
    let first_call = serde_json::to_string(&mock.messages_of_call(0)).unwrap_or_default();
    assert!(
        first_call.contains("<kimi-skill-loaded name=\\\"update-config\\\" trigger=\\\"user-inline\\\""),
        "the LLM must see the builtin activation wrap: {first_call}"
    );
    assert!(
        first_call.contains("[update-config]") && first_call.contains("hello"),
        "the body must be rewritten to the [name] marker with the tail: {first_call}"
    );

    // And the wire log carries the activation fact
    let ops = read_wire_ops(&server, &session_id).await;
    assert_eq!(
        ops.iter()
            .filter(|op| matches!(op, WireOp::SkillActivate { .. }))
            .count(),
        1,
        "one builtin activation fact: {ops:?}"
    );

    // And the journaled body carries the ADR-006 with_skills stamp
    let body_message = ops
        .iter()
        .filter_map(|op| match op {
            WireOp::ContextAppendMessage { message } => Some(message),
            _ => None,
        })
        .find(|message| message["origin"]["kind"] == "user")
        .expect("the body row must be journaled");
    assert_eq!(
        body_message["with_skills"],
        json!([{ "name": "update-config", "target": "builtin://update-config", "trigger": "user-inline" }]),
        "the body row stamps the builtin activation: {body_message}"
    );
}

/// should activate a builtin inline skill when the message carries the dirty
/// historical `builtin://name/SKILL.md` target form
#[tokio::test]
async fn should_activate_builtin_inline_skill_when_message_carries_a_stale_suffixed_target() {
    // Given a server whose catalog carries a registered builtin skill
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("ok.");
    let (server, _tmp, session_id) =
        builtin_inline_skill_server(&mock, "update-config", "builtin://update-config").await;

    // When a message references it with the pre-fix dirty target form
    let mut events = server.subscribe_events().await.unwrap();
    server
        .call_method(
            "message.send",
            json!({ "session_id": session_id, "text": "use [$update-config](builtin://update-config/SKILL.md) hello", "mode": "wait" }),
        )
        .await
        .unwrap();

    // Then the builtin still activates (the target normalizes)
    let event =
        next_event_where(&mut events, |n| n.method == "event.skill.activated", |_| {}).await;
    assert_eq!(event.params["skillName"], "update-config");
    assert_eq!(event.params["skillPath"], json!("builtin://update-config"));

    // And the body is rewritten to the [name] marker
    let call = serde_json::to_string(&mock.messages_of_call(0)).unwrap_or_default();
    assert!(
        call.contains("[update-config]") && !call.contains("builtin://update-config/SKILL.md"),
        "the dirty link must be rewritten away: {call}"
    );

    // And the journaled body carries the normalized target in with_skills
    let ops = read_wire_ops(&server, &session_id).await;
    let body_message = ops
        .iter()
        .filter_map(|op| match op {
            WireOp::ContextAppendMessage { message } => Some(message),
            _ => None,
        })
        .find(|message| message["origin"]["kind"] == "user")
        .expect("the body row must be journaled");
    assert_eq!(
        body_message["with_skills"],
        json!([{ "name": "update-config", "target": "builtin://update-config", "trigger": "user-inline" }]),
        "the with_skills stamp carries the normalized target: {body_message}"
    );
}

/// should skip inline activation when the skill disallows model invocation
/// (the sub-skill family registers `is_sub_skill` +
/// `disable_model_invocation` — fail soft, same as a disabled skill)
#[tokio::test]
async fn should_skip_inline_activation_when_the_skill_disallows_model_invocation() {
    // Given a session whose catalog carries an invocable builtin plus the
    // gated sub-skill family entry (`sub-skill/review` registration shape)
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("ok.");
    let (server, _tmp, session_id) =
        builtin_inline_skill_server(&mock, "update-config", "builtin://update-config").await;
    let session = server
        .manager
        .get_session(&mirri_core::SessionId::new(&session_id))
        .await
        .unwrap();
    session
        .skill_catalog()
        .register_builtin([mirri_core::skill::builtin::BuiltinSkillDef {
            def: mirri_core::SkillDef {
                name: "sub-skill.review".into(),
                description: "review helper".into(),
                path: std::path::PathBuf::from("builtin://sub-skill/review"),
                source: mirri_core::SkillSource::Builtin,
                plugin: None,
                disable_model_invocation: true,
                is_sub_skill: true,
            },
            content: "---\ndescription: review helper\n---\nReview the work.",
        }]);

    // When a message references the invocable builtin and the gated sub-skill
    let mut events = server.subscribe_events().await.unwrap();
    server
        .call_method(
            "message.send",
            json!({ "session_id": session_id, "text": "use [$update-config](builtin://update-config) and [$review](builtin://sub-skill/review) please", "mode": "wait" }),
        )
        .await
        .unwrap();

    // Then ONLY the invocable skill activates
    let event =
        next_event_where(&mut events, |n| n.method == "event.skill.activated", |_| {}).await;
    assert_eq!(event.params["skillName"], "update-config", "{event:?}");
    assert_eq!(event.params["trigger"], "user-inline");

    // And the wire log holds exactly one activation fact
    let ops = read_wire_ops(&server, &session_id).await;
    assert_eq!(
        ops.iter()
            .filter(|op| matches!(op, WireOp::SkillActivate { .. }))
            .count(),
        1,
        "the gated sub-skill must not activate: {ops:?}"
    );

    // And the LLM sees exactly one wrap; the gated sub-skill link stays a raw
    // link in the body (no `[name]` marker, no wrap)
    let call = serde_json::to_string(&mock.messages_of_call(0)).unwrap_or_default();
    assert_eq!(
        call.matches("<kimi-skill-loaded").count(),
        1,
        "only the invocable builtin wraps: {call}"
    );
    assert!(
        call.contains("<kimi-skill-loaded name=\\\"update-config\\\" trigger=\\\"user-inline\\\""),
        "the invocable builtin must still wrap: {call}"
    );
    assert!(
        call.contains("[$review](builtin://sub-skill/review)"),
        "the gated sub-skill link stays verbatim in the body: {call}"
    );
    assert!(
        !call.contains("[review]"),
        "the gated sub-skill must be neither wrapped nor rewritten: {call}"
    );

    // And the journaled body admits only the invocable entry
    let body_message = ops
        .iter()
        .filter_map(|op| match op {
            WireOp::ContextAppendMessage { message } => Some(message),
            _ => None,
        })
        .find(|message| message["origin"]["kind"] == "user")
        .expect("the body row must be journaled");
    assert_eq!(
        body_message["with_skills"],
        json!([{ "name": "update-config", "target": "builtin://update-config", "trigger": "user-inline" }]),
        "only the invocable skill is admitted: {body_message}"
    );
}

/// should emit goal.updated when the model calls the goal tools
#[tokio::test]
async fn should_emit_goal_updated_when_the_model_calls_the_goal_tools() {
    // Given a scripted LLM that creates a goal, budgets it, then completes
    // it before ending the turn
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_tool_use(vec![LlmToolCall {
        id: "call_1".to_string(),
        name: "CreateGoal".to_string(),
        args: json!({"objective": "Ship the feature", "completion_criterion": "Tests pass"}),
    }]);
    // The in-turn side title call — fires after the first step lands
    // (SDR-016) and consumes one scripted reply.
    mock.push_text("goal lifecycle");
    mock.push_tool_use(vec![LlmToolCall {
        id: "call_2".to_string(),
        name: "SetGoalBudget".to_string(),
        args: json!({"turns": 50}),
    }]);
    mock.push_tool_use(vec![LlmToolCall {
        id: "call_3".to_string(),
        name: "UpdateGoal".to_string(),
        args: json!({"status": "complete"}),
    }]);
    mock.push_text("Goal lifecycle done");
    let (server, _tmp) = test_server(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))));
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    // `auto` (not `yolo`): the goal-start review policy asks for CreateGoal
    // in every mode except Auto, and a test server has no approval channel.
    server
        .call_method(
            "setPermission",
            json!({ "sessionId": &session_id, "mode": "auto" }),
        )
        .await
        .unwrap();

    // When a subscriber listens and a wait-mode message runs the turn
    let mut events = server.subscribe_events().await.unwrap();
    server
        .call_method(
            "message.send",
            json!({ "session_id": session_id, "text": "manage your goal" }),
        )
        .await
        .unwrap();

    // Then the subscriber observes one event.goal.updated per mutation,
    // each with the model actor — the tool path is a model-initiated
    // mutation (distinct from the RPC path's `user` actor).
    let created_event =
        next_event_where(&mut events, |n| n.method == "event.goal.updated", |_| {}).await;
    assert_eq!(
        created_event.params["snapshot"]["objective"], "Ship the feature",
        "{}",
        created_event.params
    );
    assert_eq!(created_event.params["snapshot"]["status"], "active");
    assert_eq!(created_event.params["change"]["kind"], "lifecycle");
    assert_eq!(created_event.params["change"]["status"], "active");
    assert_eq!(created_event.params["change"]["actor"], "model");

    let budgeted =
        next_event_where(&mut events, |n| n.method == "event.goal.updated", |_| {}).await;
    assert_eq!(budgeted.params["snapshot"]["budget"]["turns"], 50);
    assert_eq!(budgeted.params["change"]["actor"], "model");
    // A budget change leaves the status untouched — no `status` key.
    assert!(budgeted.params["change"].get("status").is_none());

    let completed =
        next_event_where(&mut events, |n| n.method == "event.goal.updated", |_| {}).await;
    assert_eq!(
        completed.params["snapshot"]["status"], "complete",
        "protocol snapshot spelling: {}",
        completed.params
    );
    assert_eq!(completed.params["change"]["status"], "complete");
    assert_eq!(completed.params["change"]["actor"], "model");
}

/// should emit goal.updated from the goal tools after a cross-instance resume
#[tokio::test]
async fn should_emit_goal_updated_from_the_goal_tools_after_a_cross_instance_resume() {
    // Given a first server instance whose model creates a goal through the
    // CreateGoal tool (persisted via the wire log)
    let tmp = tempfile::tempdir().expect("tempdir must be creatable");
    let make_server = |mock: Arc<ScriptedLlm>| {
        let workspace = Arc::new(WorkspaceScope::new(
            WorkspaceId::new("test-ws"),
            tmp.path().to_path_buf(),
            WorkspaceScopeConfig::default(),
        ));
        let manager = Arc::new(SessionManager::new(workspace));
        // The create chain requires a resolvable model (spec 11 R4 — no
        // built-in fallback), so this bare instance seeds the test default.
        EmbeddedServer::with_providers(
            manager,
            Some(Arc::new(ScriptedLlmFactory::new(mock))),
            None,
            None,
            None,
            test_server_config(),
            None,
        )
    };
    let mock_one = Arc::new(ScriptedLlm::new());
    mock_one.push_tool_use(vec![LlmToolCall {
        id: "call_1".to_string(),
        name: "CreateGoal".to_string(),
        args: json!({"objective": "Ship the feature"}),
    }]);
    mock_one.push_text("Goal set before restart");
    let server_one = make_server(Arc::clone(&mock_one));
    let created = server_one
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    server_one
        .call_method(
            "setPermission",
            json!({ "sessionId": &session_id, "mode": "auto" }),
        )
        .await
        .unwrap();
    server_one
        .call_method(
            "message.send",
            json!({ "session_id": &session_id, "text": "set a goal" }),
        )
        .await
        .unwrap();
    server_one
        .call_method("session.close", json!({ "session_id": &session_id }))
        .await
        .unwrap();

    // When a second server instance resumes the session and the model
    // updates the replayed goal through the UpdateGoal tool
    let mock_two = Arc::new(ScriptedLlm::new());
    mock_two.push_tool_use(vec![LlmToolCall {
        id: "call_2".to_string(),
        name: "UpdateGoal".to_string(),
        args: json!({"status": "complete"}),
    }]);
    mock_two.push_text("Completed after restart");
    let server_two = make_server(Arc::clone(&mock_two));
    server_two
        .call_method("session.resume", json!({ "session_id": &session_id }))
        .await
        .unwrap();
    server_two
        .call_method(
            "setPermission",
            json!({ "sessionId": &session_id, "mode": "auto" }),
        )
        .await
        .unwrap();
    let mut events = server_two.subscribe_events().await.unwrap();
    server_two
        .call_method(
            "message.send",
            json!({ "session_id": &session_id, "text": "complete the goal" }),
        )
        .await
        .unwrap();

    // Then the resumed agent's goal tool still announces on the session's
    // fresh bus — the resume path bakes the fresh bus into the rebuilt
    // agent's tools, so the model-initiated mutation reaches subscribers
    // of the new instance.
    let event = next_event_where(&mut events, |n| n.method == "event.goal.updated", |_| {}).await;
    assert_eq!(event.params["snapshot"]["objective"], "Ship the feature");
    assert_eq!(event.params["snapshot"]["status"], "complete");
    assert_eq!(event.params["change"]["kind"], "lifecycle");
    assert_eq!(event.params["change"]["status"], "complete");
    assert_eq!(event.params["change"]["actor"], "model");
}

/// Given a session whose goal (paused by the user, so the goal-mode
/// automatic continuation chain never injects turns between the scripted
/// user turns) carries a 40-turn budget and which has run 30 budgeted
/// turns before the close, When a second server instance resumes the
/// session, Then the goal's replayed turnsUsed is still 30 and the
/// budget enforcement continues across the restart — ten more turns
/// exhaust the 40-turn limit exactly because the consumed 30 were
/// restored (F11).
#[tokio::test]
async fn should_persist_goal_budget_usage_across_a_restart_and_keep_enforcing_the_limit() {
    // Given a first server instance whose session has a 40-turn budgeted
    // goal (each scripted step reports 100 input + 50 output tokens)
    let tmp = tempfile::tempdir().expect("tempdir must be creatable");
    let make_server = |mock: Arc<ScriptedLlm>| {
        let workspace = Arc::new(WorkspaceScope::new(
            WorkspaceId::new("test-ws"),
            tmp.path().to_path_buf(),
            WorkspaceScopeConfig::default(),
        ));
        let manager = Arc::new(SessionManager::new(workspace));
        // The create chain requires a resolvable model (spec 11 R4 — no
        // built-in fallback), so this bare instance seeds the test default.
        EmbeddedServer::with_providers(
            manager,
            Some(Arc::new(ScriptedLlmFactory::new(mock))),
            None,
            None,
            None,
            test_server_config(),
            None,
        )
    };
    let mock_one = Arc::new(ScriptedLlm::new());
    mock_one.set_usage(100, 50, 0, 0);
    let server_one = make_server(Arc::clone(&mock_one));
    // A titled session — the test counts the mock's calls exactly (one per
    // budgeted turn), and an untitled session's first settle would spawn
    // the side title call too.
    let created = server_one
        .call_method("session.create", json!({ "title": "goal budget" }))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();

    let result = run_main_agent_tool(
        &server_one,
        &session_id,
        "CreateGoal",
        json!({"objective": "Land the parity batch"}),
    )
    .await;
    assert!(!result.is_error, "{result:?}");
    let result = run_main_agent_tool(
        &server_one,
        &session_id,
        "SetGoalBudget",
        json!({ "turns": 40 }),
    )
    .await;
    assert!(!result.is_error, "{result:?}");
    // The goal is paused by the user BEFORE the budgeted turns: goal mode
    // would otherwise auto-continue between the scripted idle turns (the
    // cross-turn continuation feature), and the test counts the mock's
    // calls exactly. A paused goal keeps the usage accounting running —
    // exactly the burn-down this test pins.
    server_one
        .call_method("goal.pause", json!({ "session_id": &session_id }))
        .await
        .unwrap();

    // And 30 turns run against the budget (one LLM call per turn — the
    // embedded main turn ends at the model's end-turn; the budget's step
    // level enforcement is what F11 persists and continues).
    for i in 0..30 {
        mock_one.push_text(&format!("working, turn {i}"));
        server_one
            .call_method(
                "message.send",
                json!({ "session_id": &session_id, "text": "go", "mode": "wait" }),
            )
            .await
            .unwrap();
    }
    assert_eq!(mock_one.chat_call_count(), 30);

    // And the usage-only goal.update ops were recorded (absolute totals,
    // no status change on the accounting ops)
    let ops = read_wire_ops(&server_one, &session_id).await;
    let turns_recorded: Vec<u64> = ops
        .iter()
        .filter_map(|op| match op {
            WireOp::GoalUpdate {
                turns_used, status, ..
            } => {
                if turns_used.is_some() {
                    assert_eq!(*status, None, "accounting ops carry no status: {op:?}");
                }
                *turns_used
            }
            _ => None,
        })
        .collect();
    assert_eq!(turns_recorded.len(), 30, "ops: {ops:?}");
    assert_eq!(turns_recorded.last(), Some(&30), "ops: {ops:?}");

    server_one
        .call_method("session.close", json!({ "session_id": &session_id }))
        .await
        .unwrap();

    // When a second server instance resumes the session
    let mock_two = Arc::new(ScriptedLlm::new());
    mock_two.set_usage(100, 50, 0, 0);
    let server_two = make_server(Arc::clone(&mock_two));
    server_two
        .call_method("session.resume", json!({ "session_id": &session_id }))
        .await
        .unwrap();

    // Then the goal snapshot reports the replayed usage (30 turns, the
    // 30 scripted steps' tokens: 30 × 150)
    let goal = server_two
        .call_method("goal.get", json!({ "session_id": &session_id }))
        .await
        .unwrap();
    assert_eq!(goal["goal"]["turnsUsed"], 30, "goal: {goal}");
    assert_eq!(goal["goal"]["tokensUsed"], 4_500, "goal: {goal}");
    assert_eq!(goal["goal"]["budget"]["turns"], 40, "goal: {goal}");
    assert_eq!(goal["goal"]["status"], "paused", "goal: {goal}");

    // And the budget enforcement continues across the restart: ten more
    // single-step turns land exactly on the 40-turn limit — only true when
    // the consumed 30 survived the restart (a reset counter would leave 10
    // of 40 unexhausted).
    for i in 0..10 {
        mock_two.push_text(&format!("resumed work {i}"));
        server_two
            .call_method(
                "message.send",
                json!({ "session_id": &session_id, "text": "go", "mode": "wait" }),
            )
            .await
            .unwrap();
    }
    assert_eq!(mock_two.chat_call_count(), 10);
    let resumed = server_two
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .expect("resumed session is live");
    assert_eq!(resumed.goal().used_turns(), 40);
    assert!(
        resumed.goal().is_budget_exhausted(),
        "40 of 40 turns must exhaust the budget after the resume"
    );

    // And the post-restart accounting was appended to the same log,
    // continuing the absolute totals from the restored base.
    let ops = read_wire_ops(&server_two, &session_id).await;
    let max_turns = ops
        .iter()
        .filter_map(|op| match op {
            WireOp::GoalUpdate { turns_used, .. } => *turns_used,
            _ => None,
        })
        .max();
    assert_eq!(max_turns, Some(40), "ops: {ops:?}");
}

/// should emit skill.activated when the model calls the Skill tool
#[tokio::test]
async fn should_emit_skill_activated_when_the_model_calls_the_skill_tool() {
    // Given a server whose session catalog carries a discovered skill and
    // a scripted LLM that invokes it
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_tool_use(vec![LlmToolCall {
        id: "call_1".to_string(),
        name: "Skill".to_string(),
        args: json!({"skill": "commit", "args": "-m \"fix bug\""}),
    }]);
    mock.push_text("Skill followed");
    let (server, tmp) = test_server(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))));
    let skill_dir = tmp.path().join("skills");
    let commit_skill = skill_dir.join("commit");
    std::fs::create_dir_all(&commit_skill).unwrap();
    std::fs::write(
        commit_skill.join("SKILL.md"),
        "---\ndescription: commit helper\n---\nRun the commit flow.",
    )
    .unwrap();
    let created = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let session_id = created["id"].as_str().unwrap().to_string();
    let session = server
        .manager
        .get_session(&mirri_core::SessionId::new(&session_id))
        .await
        .unwrap();
    session
        .skill_catalog()
        .discover(&skill_dir, mirri_core::SkillSource::Project)
        .unwrap();
    server
        .call_method(
            "setPermission",
            json!({ "sessionId": &session_id, "mode": "yolo" }),
        )
        .await
        .unwrap();

    // When a subscriber listens and a wait-mode message runs the turn
    let mut events = server.subscribe_events().await.unwrap();
    server
        .call_method(
            "message.send",
            json!({ "session_id": session_id, "text": "commit it" }),
        )
        .await
        .unwrap();

    // Then the subscriber observes event.skill.activated with the
    // model-tool trigger (distinct from the RPC path's `user-slash`) and
    // the model-supplied args.
    let event =
        next_event_where(&mut events, |n| n.method == "event.skill.activated", |_| {}).await;
    assert_eq!(event.params["skillName"], "commit");
    assert_eq!(event.params["trigger"], "model-tool");
    assert_eq!(event.params["skillSource"], "project");
    assert_eq!(event.params["args"], "-m \"fix bug\"");
    assert!(
        event.params["skillPath"]
            .as_str()
            .is_some_and(|p| p.contains("commit")),
        "skill path present: {}",
        event.params
    );
    assert!(
        event.params["activationId"]
            .as_str()
            .is_some_and(|id| !id.is_empty()),
        "activation id is minted: {}",
        event.params
    );
}

