#[tokio::test]
async fn should_return_a_bounded_snippet_window_around_the_first_hit() {
    // Given a message with a long body and the needle in the middle
    let (server, _tmp) = test_server(None);
    let session_id = create_search_session(&server, "Snippet source").await;
    let body = format!("{}needle{}", "filler ".repeat(60), " trailer".repeat(60));
    seed_search_history_message(
        &server,
        &session_id,
        mirri_core::ContextMessage::from_message(mirri_core::Message::user(body.clone())),
    )
    .await;

    // When the search runs
    let result = server
        .call_method("session.search", json!({ "query": "needle" }))
        .await
        .expect("search");
    let snippet = result["hits"][0]["snippet"].as_str().expect("snippet");

    // Then the snippet is a bounded window around the hit — the needle is
    // present, both ends are marked with an ellipsis, and the window stays
    // within ~2x80 chars of the hit
    assert!(snippet.contains("needle"), "snippet centers the hit");
    assert!(
        snippet.starts_with('…'),
        "snippet marks its head: {snippet}"
    );
    assert!(snippet.ends_with('…'), "snippet marks its tail: {snippet}");
    assert!(
        snippet.chars().count() <= 80 + 80 + "needle".len() + 2,
        "snippet is bounded to the window radius: {snippet}"
    );
    assert!(
        snippet.len() < body.len(),
        "snippet is a window, not the body"
    );
}

#[tokio::test]
async fn should_number_hits_with_the_zero_based_turn_ordinal_when_messages_match() {
    // Given a session whose history spans two turns
    let (server, _tmp) = test_server(None);
    let session_id = create_search_session(&server, "Turns").await;
    for message in [
        mirri_core::Message::user("first needle prompt"),
        mirri_core::Message::assistant("first reply"),
        mirri_core::Message::user("second needle prompt"),
        mirri_core::Message::assistant("second reply"),
    ] {
        seed_search_history_message(
            &server,
            &session_id,
            mirri_core::ContextMessage::from_message(message),
        )
        .await;
    }

    // When the search runs for the user-role needle
    let result = server
        .call_method(
            "session.search",
            json!({ "query": "needle", "role": "user" }),
        )
        .await
        .expect("search");

    // Then the hits carry the zero-based turn ordinals — the second user
    // message belongs to turn 1
    let hits = result["hits"].as_array().expect("hits");
    assert_eq!(hits.len(), 2);
    let turns: Vec<i64> = hits
        .iter()
        .map(|hit| hit["turn"].as_i64().expect("turn ordinal"))
        .collect();
    assert!(turns.contains(&0) && turns.contains(&1), "turns: {turns:?}");
}

