#[tokio::test]
async fn should_order_hits_by_time_desc_across_sessions_when_multiple_sessions_match() {
    // Given two sessions that both match, created in order so the second
    // is strictly newer
    let (server, _tmp) = test_server(None);
    let older = create_search_session(&server, "Older session").await;
    seed_search_history_message(
        &server,
        &older,
        mirri_core::ContextMessage::from_message(mirri_core::Message::user("shared needle older")),
    )
    .await;
    tokio::time::sleep(std::time::Duration::from_millis(10)).await;
    let newer = create_search_session(&server, "Newer session").await;
    seed_search_history_message(
        &server,
        &newer,
        mirri_core::ContextMessage::from_message(mirri_core::Message::user("shared needle newer")),
    )
    .await;

    // When the search runs
    let result = server
        .call_method("session.search", json!({ "query": "needle" }))
        .await
        .expect("search");
    let hits = result["hits"].as_array().expect("hits");

    // Then the newer session is hit first (time_desc) and both carry the
    // engine's bound workspace id
    assert_eq!(hits.len(), 2);
    assert_eq!(hits[0]["session_id"], newer, "newer session first");
    assert_eq!(hits[1]["session_id"], older, "older session second");
    let workspace_id = hits[0]["workspace_id"].as_str().expect("workspace id");
    assert!(
        !workspace_id.is_empty(),
        "hits carry the bound workspace id"
    );
    assert_eq!(hits[1]["workspace_id"], workspace_id);
    // And the hit times are the session updatedAt epoch milliseconds
    let t0 = hits[0]["time"].as_i64().expect("time");
    let t1 = hits[1]["time"].as_i64().expect("time");
    assert!(t0 >= t1, "hit times follow time_desc");
}

#[tokio::test]
async fn should_clamp_the_page_size_to_fifty_when_more_is_requested() {
    // Given a session with 60 matching messages (title deliberately does
    // not match, so the pages cover exactly the message docs)
    let (server, _tmp) = test_server(None);
    let session_id = create_search_session(&server, "Filler session").await;
    for i in 0..60 {
        seed_search_history_message(
            &server,
            &session_id,
            mirri_core::ContextMessage::from_message(mirri_core::Message::user(format!(
                "needle number {i}"
            ))),
        )
        .await;
    }

    // When the first page is requested with an oversized page size
    let first = server
        .call_method(
            "session.search",
            json!({ "query": "needle", "page_size": 100 }),
        )
        .await
        .expect("first page");

    // Then the page carries exactly 50 hits (the cap) and a next-page token
    assert_eq!(first["hits"].as_array().map(Vec::len), Some(50));
    let token = first["next_page_token"].as_str().expect("next page token");

    // When the second page is fetched with the token
    let second = server
        .call_method(
            "session.search",
            json!({ "query": "needle", "page_size": 100, "page_token": token }),
        )
        .await
        .expect("second page");

    // Then the remaining 10 hits return and no further page token does
    assert_eq!(second["hits"].as_array().map(Vec::len), Some(10));
    assert!(
        second.get("next_page_token").is_none(),
        "no token on the final page"
    );
}

#[tokio::test]
async fn should_answer_invalid_params_when_the_page_token_fingerprint_mismatches() {
    // Given a session with 3 matching messages and a fetched first page
    let (server, _tmp) = test_server(None);
    let session_id = create_search_session(&server, "Token guard").await;
    for i in 0..3 {
        seed_search_history_message(
            &server,
            &session_id,
            mirri_core::ContextMessage::from_message(mirri_core::Message::user(format!(
                "needle number {i}"
            ))),
        )
        .await;
    }
    let first = server
        .call_method(
            "session.search",
            json!({ "query": "needle", "page_size": 2 }),
        )
        .await
        .expect("first page");
    let token = first["next_page_token"]
        .as_str()
        .expect("token")
        .to_string();

    // When the same token is replayed with a different query
    let error = server
        .call_method(
            "session.search",
            json!({ "query": "other", "page_size": 2, "page_token": token }),
        )
        .await
        .expect_err("fingerprint mismatch is rejected");

    // Then the answer is invalid params (mid-pagination condition change)
    assert_invalid_params(&error, "fingerprint mismatch");

    // And a token that is not a valid cursor at all is rejected too
    let error = server
        .call_method(
            "session.search",
            json!({ "query": "needle", "page_token": "not-a-token" }),
        )
        .await
        .expect_err("garbage token rejected");
    assert_invalid_params(&error, "garbage token");
}

