#[tokio::test]
async fn should_find_messages_in_a_persisted_session_when_it_is_not_live() {
    // Given a scripted-LLM server whose session ran one turn and was closed
    let mock = Arc::new(ScriptedLlm::new());
    mock.push_text("the assistant mentions a needle too");
    let (server, _tmp) = test_server(Some(Arc::new(ScriptedLlmFactory::new(Arc::clone(&mock)))));
    let session_id = create_search_session(&server, "The needle vault").await;
    server
        .call_method(
            "message.send",
            json!({ "session_id": session_id, "text": "please mention the needle", "mode": "wait" }),
        )
        .await
        .expect("turn runs");
    server
        .call_method("session.close", json!({ "session_id": session_id }))
        .await
        .expect("session closes");
    assert!(
        server
            .session_manager()
            .get_session(&SessionId::new(&session_id))
            .await
            .is_none(),
        "the session is no longer live"
    );

    // When the search runs for the needle
    let result = server
        .call_method("session.search", json!({ "query": "needle" }))
        .await
        .expect("search over persisted sessions");

    // Then both the persisted user message and the assistant reply hit
    // (main-agent replay), with the title hit too
    let hits = result["hits"].as_array().expect("hits");
    let roles: Vec<&str> = hits
        .iter()
        .map(|hit| hit["role"].as_str().expect("role"))
        .collect();
    assert!(
        roles.contains(&"user") && roles.contains(&"assistant") && roles.contains(&"title"),
        "persisted user, assistant, and title docs all hit: {hits:?}"
    );
    for hit in hits {
        assert_eq!(hit["session_id"], session_id);
        assert_eq!(
            hit["agent_id"].as_str().expect("agent id"),
            if hit["role"] == "title" { "" } else { "main" }
        );
    }

    // And a second search re-reads the same state without side effects
    let again = server
        .call_method("session.search", json!({ "query": "needle" }))
        .await
        .expect("search is repeatable");
    assert_eq!(
        again["hits"].as_array().map(Vec::len),
        result["hits"].as_array().map(Vec::len),
        "the read-only scan is stable"
    );
}

// ---------------------------------------------------------------------------
// btw.start (P11a F-P8-1): the behind-the-wheel side-channel fork
// ---------------------------------------------------------------------------

/// Given a session whose main agent already carries context, When `btw.start`
/// forks it, Then the result is the new agent's id (the TS wire contract
/// `{agent_id}`, mirroring mirri-server's StartBtwHandler) — never the
/// error-shaped stub.
#[tokio::test]
async fn should_return_the_forked_agent_id_when_btw_start_forks_the_main_agent() {
    let (server, _tmp) = test_server(None);
    let created = server
        .call_method("session.create", json!({}))
        .await
        .expect("session.create must succeed");
    let session_id = created["id"].as_str().unwrap().to_string();

    let result = server
        .call_method("btw.start", json!({ "sessionId": session_id }))
        .await
        .expect("btw.start must succeed");

    let agent_id = result["agent_id"].as_str().expect("agent_id on the wire");
    assert!(!agent_id.is_empty(), "the forked agent id must be real");
    assert_ne!(agent_id, DEFAULT_MAIN_AGENT_ID, "the fork is a new agent");
    assert!(
        result.get("ok").is_none(),
        "the error-shaped stub keys must be gone"
    );

    // And the forked agent exists in the session with all tools vetoed
    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .expect("session stays live");
    let btw_agent = session
        .get_agent(&AgentId::new(agent_id))
        .await
        .expect("the btw agent is registered in the session");
    let enabled_tools = btw_agent
        .config()
        .read()
        .unwrap_or_else(|e| e.into_inner())
        .enabled_tools
        .clone();
    assert_eq!(
        enabled_tools,
        Some(Vec::new()),
        "the btw fork must run with every tool disabled"
    );
}

/// A minimal server-provided tool stand-in for the MCP registration race:
/// same registration surface `register_server_tools_to_sessions` drives
/// (`ToolManager::register_mcp_tool`), without wiring a real connection
/// manager.
struct LateMcpTool;

impl mirri_core::tool::Tool for LateMcpTool {
    fn name(&self) -> &str {
        "late-server__Probe"
    }

    fn description(&self) -> &str {
        "An MCP tool from a server that connected after the fork"
    }

    fn parameters(&self) -> &serde_json::Value {
        use std::sync::OnceLock;
        static SCHEMA: OnceLock<serde_json::Value> = OnceLock::new();
        SCHEMA.get_or_init(|| serde_json::json!({ "type": "object", "properties": {} }))
    }

    fn resolve_execution(
        &self,
        _input: serde_json::Value,
    ) -> EngineResult<mirri_core::tool::ToolExecution> {
        Ok(mirri_core::tool::ToolExecution::Runnable {
            plan: mirri_core::tool::ExecutionPlan {
                accesses: vec![],
                display: mirri_core::tool::ToolInputDisplay::Generic {
                    summary: "probe".to_string(),
                },
                approval_rule: "late-server__Probe".to_string(),
                stop_batch_after_this: false,
            },
            execute: Box::new(|_ctx| {
                Box::pin(async { mirri_core::tool::ToolResult::success("probed".to_string()) })
            }),
        })
    }
}

/// Given a live btw fork (all tools vetoed via `enabled_tools = Some([])`),
/// When an MCP server completes its connection and registers its tools into
/// every live agent — exactly what `register_server_tools_to_sessions` does
/// on the `Connected` transition — Then the btw agent's tool table stays
/// empty: the whitelist is authoritative at the table-rebuild choke point,
/// so a late registration cannot reopen the side channel's tools
/// (F-P11a-2; the TS kernel is immune via its runtime
/// `onBeforeExecuteTool` veto).
#[tokio::test]
async fn should_keep_the_btw_tool_table_empty_when_an_mcp_server_registers_late() {
    let (server, _tmp) = test_server(None);
    let created = server
        .call_method("session.create", json!({}))
        .await
        .expect("session.create must succeed");
    let session_id = created["id"].as_str().unwrap().to_string();

    let result = server
        .call_method("btw.start", json!({ "sessionId": session_id }))
        .await
        .expect("btw.start must succeed");
    let btw_id = result["agent_id"].as_str().unwrap().to_string();

    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .expect("session stays live");
    let btw_agent = session
        .get_agent(&AgentId::new(&btw_id))
        .await
        .expect("the btw agent is registered in the session");

    // The Connected transition's registration: server tools land in every
    // live agent's tool manager — the main agent and the btw fork both.
    for agent_id in session.list_agents().await {
        if let Some(agent) = session.get_agent(&agent_id).await {
            agent
                .tool_manager()
                .write()
                .register_mcp_tool("late-server".to_string(), Arc::new(LateMcpTool));
        }
    }

    let tool_table = {
        let tools = btw_agent.tool_manager();
        let tools_guard = tools.read();
        tools_guard.loop_tools()
    };
    assert!(
        tool_table.is_empty(),
        "the btw fork's tool table must stay empty after the late MCP registration, got: {:?}",
        tool_table
            .iter()
            .map(|d| d.name.as_str())
            .collect::<Vec<_>>()
    );

    // And the main agent (no explicit whitelist) does see the tool — the
    // fix must not starve unrestricted agents of MCP tools.
    let main_agent = session
        .get_agent(&AgentId::new(DEFAULT_MAIN_AGENT_ID))
        .await
        .expect("the main agent exists");
    let main_tools = main_agent.tool_manager();
    let main_guard = main_tools.read();
    let main_table = main_guard.loop_tools();
    assert!(
        main_table.iter().any(|d| d.name == "late-server__Probe"),
        "the main agent must still receive the late MCP tool"
    );
}

/// Given a main agent whose context memory already carries a user message,
/// When `btw.start` forks it, Then the child sees the parent's history (the
/// TS `fork('main')` semantics — the side channel answers from context) and
/// carries the side-question system reminder.
#[tokio::test]
async fn should_inherit_parent_context_and_the_side_question_reminder_when_btw_start_forks() {
    let (server, _tmp) = test_server(None);
    let created = server
        .call_method("session.create", json!({}))
        .await
        .expect("session.create must succeed");
    let session_id = created["id"].as_str().unwrap().to_string();

    // Seed the main agent's context with a user message the side channel
    // must be able to answer from.
    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .expect("session stays live");
    let main_agent = session
        .get_agent(&AgentId::new(DEFAULT_MAIN_AGENT_ID))
        .await
        .expect("the main agent exists");
    main_agent
        .context_memory()
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .append_user_message(
            vec![mirri_core::message::ContentPart::Text {
                text: "the launch code is 4-8-15".to_string(),
            }],
            mirri_core::origin::PromptOrigin::User,
        );

    let result = server
        .call_method("btw.start", json!({ "session_id": session_id }))
        .await
        .expect("btw.start must succeed");
    let btw_id = result["agent_id"].as_str().unwrap().to_string();

    let btw_agent = session
        .get_agent(&AgentId::new(&btw_id))
        .await
        .expect("the btw agent is registered in the session");
    let memory = btw_agent.context_memory();
    let guard = memory.lock().unwrap_or_else(|e| e.into_inner());
    let messages = guard.messages();
    assert!(
        messages.iter().any(|m| m.text_content().contains("4-8-15")),
        "the btw fork must see the main agent's context history"
    );
    assert!(
        guard.messages().iter().any(|m| m
            .text_content()
            .contains("side-channel conversation with the user")),
        "the btw fork must carry the side-question system reminder"
    );

    // And the main agent's memory is untouched by the fork
    let main_messages = main_agent.context_memory();
    let main_guard = main_messages.lock().unwrap_or_else(|e| e.into_inner());
    assert_eq!(
        main_guard.messages().len(),
        1,
        "forking must not mutate the source agent"
    );
}

