// ---------------------------------------------------------------------------
// session.addAdditionalDir (P11a F-P8-2): the workspace-local config
// ---------------------------------------------------------------------------

/// A throwaway workspace root that IS a project root (a `.git` marker
/// inside), with one existing subdirectory `extra` to add.
fn git_project_workspace() -> (tempfile::TempDir, std::path::PathBuf) {
    let tmp = tempfile::tempdir().expect("tempdir must be creatable");
    std::fs::create_dir(tmp.path().join(".git")).expect("create .git marker");
    std::fs::create_dir(tmp.path().join("extra")).expect("create the extra dir");
    let root = tmp.path().to_path_buf();
    (tmp, root)
}

/// A server bound to the given workspace root (no LLM — none needed).
fn server_for_workspace_root(root: &std::path::Path) -> EmbeddedServer {
    let workspace = Arc::new(WorkspaceScope::new(
        WorkspaceId::new("add-dir-ws"),
        root.to_path_buf(),
        WorkspaceScopeConfig::default(),
    ));
    let manager = Arc::new(SessionManager::new(workspace));
    // The create chain requires a resolvable model (spec 11 R4 — no
    // built-in fallback), so this bare server seeds the test default.
    EmbeddedServer::with_providers(manager, None, None, None, None, test_server_config(), None)
}

/// Given a git project workspace with an existing `extra` directory, When
/// `addAdditionalDir` persists it, Then the result reports the resolved
/// absolute dir, the project root, the local.toml config path, and the
/// file is written with the `workspace.additional_dir` key.
#[tokio::test]
async fn should_resolve_and_persist_an_additional_dir_when_the_local_toml_is_written() {
    let (_tmp, root) = git_project_workspace();
    let server = server_for_workspace_root(&root);
    let created = server
        .call_method("session.create", json!({}))
        .await
        .expect("session.create must succeed");
    let session_id = created["id"].as_str().unwrap().to_string();

    let result = server
        .call_method(
            "addAdditionalDir",
            json!({ "sessionId": session_id, "path": "extra", "persist": true }),
        )
        .await
        .expect("addAdditionalDir must succeed");

    let expected_dir = root.join("extra");
    assert_eq!(
        result["additionalDirs"],
        json!([expected_dir.to_str().unwrap()]),
        "the relative path must resolve against the project root"
    );
    assert_eq!(result["projectRoot"], root.to_str().unwrap());
    assert_eq!(
        result["configPath"],
        root.join(".mirri-code")
            .join("local.toml")
            .to_str()
            .unwrap()
    );
    assert_eq!(result["persisted"], true);

    // And the local.toml carries the persisted dir under the TS key
    let text =
        std::fs::read_to_string(root.join(".mirri-code").join("local.toml")).expect("local.toml");
    let parsed: toml::Value = toml::from_str(&text).expect("local.toml must parse");
    let dirs = parsed
        .get("workspace")
        .and_then(|w| w.get("additional_dir"))
        .and_then(|v| v.as_array())
        .expect("workspace.additional_dir array");
    assert_eq!(
        dirs,
        &vec![toml::Value::String(
            expected_dir.to_str().unwrap().to_string()
        )],
        "the persisted list must hold the resolved absolute dir"
    );
}

/// Given a persisted additional dir from an earlier session, When a NEW
/// session adds another dir, Then the result still lists both — the
/// workspace-local config survives the session (the resume-parity e2e).
#[tokio::test]
async fn should_keep_the_full_dir_list_when_a_new_session_adds_another_dir() {
    let (_tmp, root) = git_project_workspace();
    std::fs::create_dir(root.join("another")).expect("create the second dir");
    let server = server_for_workspace_root(&root);
    let first = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let first_id = first["id"].as_str().unwrap().to_string();
    server
        .call_method(
            "addAdditionalDir",
            json!({ "sessionId": first_id, "path": "extra", "persist": true }),
        )
        .await
        .expect("first addAdditionalDir must succeed");

    // A brand-new session on the same workspace reads the same local.toml.
    let second = server
        .call_method("session.create", json!({}))
        .await
        .unwrap();
    let second_id = second["id"].as_str().unwrap().to_string();
    let result = server
        .call_method(
            "addAdditionalDir",
            json!({ "sessionId": second_id, "path": "another", "persist": true }),
        )
        .await
        .expect("second addAdditionalDir must succeed");

    assert_eq!(
        result["additionalDirs"],
        json!([
            root.join("extra").to_str().unwrap(),
            root.join("another").to_str().unwrap(),
        ]),
        "the earlier persisted dir must survive into the new session's list"
    );
}

