// ---------------------------------------------------------------------------
// session.addAdditionalDir followups (P11f F-P11a-3b / F-P11a-4 / F-P11a-5)
// ---------------------------------------------------------------------------

/// A throwaway workspace root that IS a project root (a `.git` marker
/// inside), with one existing subdirectory `b` for the `..`-spelling test.
fn git_project_workspace_with_b() -> (tempfile::TempDir, std::path::PathBuf) {
    let tmp = tempfile::tempdir().expect("tempdir must be creatable");
    std::fs::create_dir(tmp.path().join(".git")).expect("create .git marker");
    std::fs::create_dir(tmp.path().join("b")).expect("create the b dir");
    let root = tmp.path().to_path_buf();
    (tmp, root)
}

/// A throwaway workspace root that is a SUBDIRECTORY of the project root
/// (the `.git` marker sits one level above the workspace) with an existing
/// `extra` dir under the workspace — the shape that separates "resolve
/// against the session cwd" from "resolve against the project root"
/// (F-P11a-4: the TS kernel resolves new inputs against the session cwd).
fn nested_project_workspace() -> (tempfile::TempDir, std::path::PathBuf) {
    let tmp = tempfile::tempdir().expect("tempdir must be creatable");
    std::fs::create_dir_all(tmp.path().join("repo").join(".git")).expect("create .git marker");
    std::fs::create_dir_all(tmp.path().join("repo").join("sub").join("extra"))
        .expect("create the extra dir");
    let root = tmp.path().join("repo").join("sub");
    (tmp, root)
}

/// Given a workspace root that sits one level below the git root, When a
/// relative dir is added, Then it resolves against the session cwd (the
/// workspace root) — NOT the project root — so `extra` lands at
/// `<workspace>/extra`, matching the TS `resolveAdditionalDir(kaos,
/// workDir, ...)` base (F-P11a-4).
#[tokio::test]
async fn should_resolve_a_relative_dir_against_the_session_cwd_when_the_workspace_sits_below_the_git_root()
 {
    let (_tmp, root) = nested_project_workspace();
    let server = server_for_workspace_root(&root);
    let created = server
        .call_method("session.create", json!({}))
        .await
        .expect("session.create must succeed");
    let session_id = created["id"].as_str().unwrap().to_string();

    let result = server
        .call_method(
            "addAdditionalDir",
            json!({ "sessionId": session_id, "path": "extra", "persist": true }),
        )
        .await
        .expect("a cwd-relative dir that exists must resolve");

    assert_eq!(
        result["additionalDirs"],
        json!([root.join("extra").to_str().unwrap()]),
        "the relative path must resolve against the session cwd, not the project root"
    );
}

/// Given an input that spells a `..` segment, When the dir is added, Then
/// the resolved (and persisted) path is lexically folded — `a/../b` reports
/// and persists as `<root>/b`, not `<root>/a/../b` (F-P11a-5: the TS
/// `normalize` resolves `..` without I/O).
#[tokio::test]
async fn should_normalize_dotdot_segments_when_resolving_an_additional_dir() {
    let (_tmp, root) = git_project_workspace_with_b();
    let server = server_for_workspace_root(&root);
    let created = server
        .call_method("session.create", json!({}))
        .await
        .expect("session.create must succeed");
    let session_id = created["id"].as_str().unwrap().to_string();

    let result = server
        .call_method(
            "addAdditionalDir",
            json!({ "sessionId": session_id, "path": "a/../b", "persist": true }),
        )
        .await
        .expect("the lexically folded dir exists and must resolve");

    let expected = root.join("b");
    assert_eq!(
        result["additionalDirs"],
        json!([expected.to_str().unwrap()]),
        "the `..` segment must fold away in the resolved dir"
    );
    let text =
        std::fs::read_to_string(root.join(".mirri-code").join("local.toml")).expect("local.toml");
    assert!(
        !text.contains(".."),
        "the persisted list must hold the folded spelling, got: {text}"
    );
}

/// Given a local.toml persisted with a `~`-prefixed dir, When another dir is
/// added, Then the persisted entry is read back through home expansion —
/// `~/x` resolves under `$HOME/x`, not `<projectRoot>/~/x` (F-P11a-5: the
/// TS `resolvePath` expands `~` for persisted dirs too).
#[tokio::test]
// The crate-wide home lock is a std Mutex held across the awaits on
// purpose: the pinned `$HOME` must survive the RPC that expands `~`,
// and each `#[tokio::test]` runs on its own (current-thread) runtime
// thread, so a waiter blocks its own thread while the holder — on
// another — finishes; no deadlock, only bounded serialization.
#[allow(clippy::await_holding_lock)]
async fn should_expand_the_home_dir_when_reading_a_persisted_additional_dir() {
    let (_tmp, root) = git_project_workspace();
    let home = tempfile::tempdir().expect("home tempdir must be creatable");
    std::fs::create_dir(home.path().join("x")).expect("create ~/x");
    std::fs::create_dir_all(root.join(".mirri-code")).expect("create config dir");
    std::fs::write(
        root.join(".mirri-code").join("local.toml"),
        "[workspace]\nadditional_dir = [\"~/x\"]\n",
    )
    .expect("write the persisted ~ entry");
    // The expansion reads $HOME at call time (mirrors the TS kaos.gethome()).
    // The crate-wide home lock serializes this pin against the other
    // HOME-reading tests — without it a concurrently running test that pins
    // $HOME (e.g. the bootstrap home-isolation tests) can clobber the value
    // between the write and the expansion read.
    let _home_lock = crate::bootstrap::test_env::home_lock();
    unsafe { std::env::set_var("HOME", home.path()) };

    let server = server_for_workspace_root(&root);
    let created = server
        .call_method("session.create", json!({}))
        .await
        .expect("session.create must succeed");
    let session_id = created["id"].as_str().unwrap().to_string();

    let result = server
        .call_method(
            "addAdditionalDir",
            json!({ "sessionId": session_id, "path": "extra", "persist": true }),
        )
        .await
        .expect("addAdditionalDir must succeed");

    assert_eq!(
        result["additionalDirs"],
        json!([
            home.path().join("x").to_str().unwrap(),
            root.join("extra").to_str().unwrap(),
        ]),
        "the persisted ~/x entry must expand under $HOME, and the new dir under the cwd"
    );
}

/// Given a session with a main agent, When `addAdditionalDir` persists a
/// dir, Then the main agent's context receives the
/// `<local-command-stdout>` notification naming the added path and the
/// config file it was saved to (the TS
/// `notifyAdditionalDirAdded` → `appendLocalCommandStdout` semantics —
/// main agent only, F-P11a-3b).
#[tokio::test]
async fn should_notify_the_main_agent_when_an_additional_dir_is_added() {
    let (_tmp, root) = git_project_workspace();
    let server = server_for_workspace_root(&root);
    let created = server
        .call_method("session.create", json!({}))
        .await
        .expect("session.create must succeed");
    let session_id = created["id"].as_str().unwrap().to_string();

    server
        .call_method(
            "addAdditionalDir",
            json!({ "sessionId": session_id, "path": "extra", "persist": true }),
        )
        .await
        .expect("addAdditionalDir must succeed");

    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .expect("session stays live");
    let main_agent = session
        .get_agent(&AgentId::new(DEFAULT_MAIN_AGENT_ID))
        .await
        .expect("the main agent exists");
    let memory = main_agent.context_memory();
    let guard = memory.lock().unwrap_or_else(|e| e.into_inner());
    let context = guard
        .messages()
        .iter()
        .map(|m| m.text_content())
        .collect::<String>();
    assert!(
        context.contains("<local-command-stdout>"),
        "the notification must be wrapped in the local-command-stdout tags, got: {context}"
    );
    assert!(
        context.contains("Added workspace directory:"),
        "the notification must open with the added-dir line, got: {context}"
    );
    assert!(
        context.contains("extra"),
        "the notification must name the added path, got: {context}"
    );
    assert!(
        context.contains("Saved to:"),
        "a persisted add must point at the config file, got: {context}"
    );
    assert!(
        context.contains(
            root.join(".mirri-code")
                .join("local.toml")
                .to_str()
                .unwrap()
        ),
        "the notification must name the local.toml path, got: {context}"
    );
}

/// Given a session-only add (`persist: false`), When `addAdditionalDir`
/// runs, Then the main agent's notification says the dir is for this
/// session only — no config file is named.
#[tokio::test]
async fn should_notify_the_main_agent_with_the_session_only_wording_when_persist_is_false() {
    let (_tmp, root) = git_project_workspace();
    let server = server_for_workspace_root(&root);
    let created = server
        .call_method("session.create", json!({}))
        .await
        .expect("session.create must succeed");
    let session_id = created["id"].as_str().unwrap().to_string();

    server
        .call_method(
            "addAdditionalDir",
            json!({ "sessionId": session_id, "path": "extra", "persist": false }),
        )
        .await
        .expect("addAdditionalDir must succeed");

    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .expect("session stays live");
    let main_agent = session
        .get_agent(&AgentId::new(DEFAULT_MAIN_AGENT_ID))
        .await
        .expect("the main agent exists");
    let memory = main_agent.context_memory();
    let guard = memory.lock().unwrap_or_else(|e| e.into_inner());
    let context = guard
        .messages()
        .iter()
        .map(|m| m.text_content())
        .collect::<String>();
    assert!(
        context.contains("For this session only"),
        "a non-persisted add must use the session-only wording, got: {context}"
    );
    assert!(
        !context.contains("Saved to:"),
        "a non-persisted add must not name a config file, got: {context}"
    );
}

// ---------------------------------------------------------------------------
// session.addAdditionalDir sandbox effect (P11f-2 F-P11a-3a): additional
// dirs become accessible to the session's file tools
// ---------------------------------------------------------------------------

/// Resolve a named builtin tool off an agent's tool manager.
fn agent_tool(agent: &mirri_core::AgentScope, name: &str) -> Arc<dyn mirri_core::Tool> {
    agent
        .tool_manager()
        .read()
        .find_tool(name)
        .unwrap_or_else(|| panic!("the '{name}' builtin tool must be registered"))
}

/// Given a Manual-mode session with no approval responder and no additional
/// dirs registered, When the Read tool is pointed at a file outside the
/// workspace root, Then the tool layer builds a runnable execution (outside
/// is no longer a tool-layer refusal) and the permission chain intercepts
/// it: the boundary policy asks with a grant_dir, and the manager blocks
/// because no approval mechanism is available (F-P11a-3a red line 1,
/// rewritten for plan D2 — sandbox enforcement moved from the tool layer to
/// the permission chain).
#[tokio::test]
async fn should_block_a_read_outside_the_workspace_when_permission_mode_is_manual_and_no_approval_responder_is_available()
 {
    let (_tmp, root) = git_project_workspace();
    let outside = tempfile::tempdir().expect("outside tempdir must be creatable");
    let outside_file = outside.path().join("secret.txt");
    std::fs::write(&outside_file, "s3cret").expect("write the outside file");
    let server = server_for_workspace_root(&root);
    let created = server
        .call_method("session.create", json!({}))
        .await
        .expect("session.create must succeed");
    let session_id = created["id"].as_str().unwrap().to_string();

    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .expect("session stays live");
    let main_agent = session
        .get_agent(&AgentId::new(DEFAULT_MAIN_AGENT_ID))
        .await
        .expect("the main agent exists");

    // Tool layer: an outside absolute path is no longer a tool error — it
    // yields a runnable execution (authorization is the chain's job now).
    let read_tool = agent_tool(&main_agent, "Read");
    let execution = read_tool
        .resolve_execution(json!({ "path": outside_file.to_string_lossy() }))
        .expect("resolve");
    let ToolExecution::Runnable { .. } = execution else {
        panic!("an outside absolute path must yield a runnable execution, not a tool-layer error");
    };

    // Permission chain: in Manual mode the boundary policy asks, carrying
    // the outside file's parent dir as the grant_dir.
    let args = json!({ "path": outside_file.to_string_lossy() });
    let display = mirri_core::ToolInputDisplay::Generic {
        summary: "read outside the workspace".to_string(),
    };
    let cancel = mirri_core::CancelToken::new();
    let ctx = mirri_core::PermissionPolicyContext {
        tool_name: "Read",
        tool_call_id: "call-outside-read",
        args: &args,
        approval_rule: "Read",
        display: &display,
        accesses: &[],
        mode: mirri_core::PermissionMode::Manual,
        rules: &[],
        session_approvals: &std::collections::HashSet::new(),
        cancel: &cancel,
    };
    let pm = main_agent.permission_manager();
    match pm.evaluate(&ctx) {
        mirri_core::PermissionPolicyResult::Ask { reason, grant_dir } => {
            assert_eq!(
                reason.as_deref(),
                Some("the path is outside the workspace sandbox")
            );
            assert_eq!(
                grant_dir.as_deref(),
                Some(outside.path().canonicalize().unwrap().as_path()),
                "the grant_dir must be the outside file's parent directory"
            );
        }
        other => panic!("a Manual-mode outside read must ask, got {other:?}"),
    }

    // With no approval responder the manager blocks instead of approving.
    assert!(
        matches!(
            pm.before_tool_call(&ctx),
            mirri_core::hooks::AuthorizeToolResult::Blocked { .. }
        ),
        "no approval mechanism available must block the outside read"
    );
}

/// A throwaway additional dir OUTSIDE the workspace root with one file in
/// it — the shape that proves the sandbox opens up for additional dirs
/// (a dir inside the root would pass the root-only check anyway).
fn additional_dir_outside_workspace() -> (tempfile::TempDir, std::path::PathBuf) {
    let extra = tempfile::tempdir().expect("extra tempdir must be creatable");
    std::fs::write(extra.path().join("note.txt"), "added dir content\n")
        .expect("write the extra-dir file");
    let dir = extra.path().to_path_buf();
    (extra, dir)
}

/// Given `addAdditionalDir` registered a dir outside the workspace, When the
/// Read tool reads a file inside it, Then the read goes through — the
/// additional dir is inside the sandbox (F-P11a-3a, the TS
/// `setAdditionalDirs` → `isWithinWorkspace` mirror).
#[tokio::test]
async fn should_let_the_read_tool_read_from_an_additional_dir_when_add_additional_dir_ran() {
    let (_tmp, root) = git_project_workspace();
    let (extra, extra_dir) = additional_dir_outside_workspace();
    let server = server_for_workspace_root(&root);
    let created = server
        .call_method("session.create", json!({}))
        .await
        .expect("session.create must succeed");
    let session_id = created["id"].as_str().unwrap().to_string();
    server
        .call_method(
            "addAdditionalDir",
            json!({
                "sessionId": session_id,
                "path": extra_dir.to_string_lossy(),
                "persist": true
            }),
        )
        .await
        .expect("addAdditionalDir must succeed");

    let session = server
        .session_manager()
        .get_session(&SessionId::new(&session_id))
        .await
        .expect("session stays live");
    let main_agent = session
        .get_agent(&AgentId::new(DEFAULT_MAIN_AGENT_ID))
        .await
        .expect("the main agent exists");
    let read_tool = agent_tool(&main_agent, "Read");
    let execution = read_tool
        .resolve_execution(json!({ "path": extra_dir.join("note.txt").to_string_lossy() }))
        .expect("resolve");
    let ToolExecution::Runnable { execute, .. } = execution else {
        panic!("expected a runnable execution for a file inside the additional dir");
    };
    let result = execute(mirri_core::tool::ExecutableToolContext {
        wait_registry: None,
        turn_id: "test".to_string(),
        tool_call_id: "call-1".to_string(),
        cancel: Default::default(),
        progress: mirri_core::tool::ToolProgressHandle::default(),
    })
    .await;
    assert!(
        !result.is_error,
        "the read inside the additional dir must pass"
    );
    match &result.output {
        mirri_core::ToolOutput::Text(text) => assert!(text.contains("added dir content")),
        other => panic!("expected text output, got {other:?}"),
    }
    drop(extra);
}

